; value for a graphic index, the actual start of the graphic data for each set
; is eight bytes further on than the address given here. For example, Graphic
; Set 03 has a start address here of 27278, however the UDG with an index of 1
; (which is the true start of the graphic data for Set 03) is at 27286. The
; address given here (27278) is actually an address in the previous data block
; at 27030.
