main:

; Jump to Start of Initialisation Code
;
; Used by the routines at 59543 and 63000.
  JP 34428                ; Jump to start of initialisation code

; Unused
  DEFB 190,133,173,233

; Index of Current Level
  DEFB 1

; Game Flags
;
; +-----+---------------------------------------------------------------------+
; | Bit | Effect                                                              |
; +-----+---------------------------------------------------------------------+
; | 0   | Drutt Mode Flag (Set = Drutt mode / Reset = Berk mode)              |
; | 1   | Characters Already Swapped Flag                                     |
; | 2   | "Berk Has Been Killed" Flag                                         |
; | 3   | "Reset Spiders to Initial State" Flag                               |
; | 4   | Level Exit Door Unlocked Flag                                       |
; | 5   | Update Scores and Display Flag (Reset = draw timer figures / Set =  |
; |     | calculate/update scores and display)                                |
; | 6   | Character Swap Pending Flag                                         |
; | 7   | Show Score Flag (Reset = draw Timer Figures / Set = Display Score / |
; |     | Hi Score)                                                           |
; +-----+---------------------------------------------------------------------+
  DEFB 0

; Cannon's (Level 4) Ammunition Counter
;
; Number of shots Cannon can fire before returning to its dormant state.
; Increases by 10 for each drip the Cannon catches.
  DEFB 0

; Current Time / Lives
  DEFB 16

; Score Data
  DEFW 0                  ; Timer Tick Counter / Score penalty (current level)
  DEFW 0                  ; Score (Current Level)
  DEFW 0                  ; Current Total Score

; Current Border Colour
  DEFB 1

; Index of Current Character's Current Room
  DEFB 0

; Control Input Bitmap
;
; +-----+-----------------------------------------------------+
; | Bit | Effect                                              |
; +-----+-----------------------------------------------------+
; | 0   | Right                                               |
; | 1   | Left                                                |
; | 2   | Forward (i.e. DOWN - makes Drutt swap depth levels) |
; | 3   | Back (i.e. UP - makes Drutt jump higher)            |
; | 4   | Berk / Drutt                                        |
; | 5   | Pause                                               |
; | 6   | Restart                                             |
; | 7   | Unused                                              |
; +-----+-----------------------------------------------------+
  DEFB 0

; Berk's Current Power
;
; +-------+----------------------------+
; | Value | Effect                     |
; +-------+----------------------------+
; | 0     | None                       |
; | 1     | Jumping (Level 1)          |
; | 2     | Jumping (Level 2)          |
; | 3     | Jumping (Level 4)          |
; | 4     | Flying (Level 1)           |
; | 5     | Flying (Level 3, 1)        |
; | 6     | Flying (Level 3, 2)        |
; | 7     | Flying (Level 4, 1)        |
; | 8     | Flying (Level 4, 2)        |
; | 9     | Immunity to Bubo (Level 2) |
; | 10    | Floating (Level 3)         |
; | 11    | Invisibility (Level 3)     |
; +-------+----------------------------+
  DEFB 0

; Interaction Data for Berk
  DEFB 0                  ; Class of entity currently held by Berk (e.g. Drutt
                          ; = 18), or zero for none
  DEFB 0                  ; y-coordinate minus one for top edge of coloured
                          ; creature slot with which Berk is interacting
  DEFB 0                  ; Number of times Berk has been killed by a spider on
                          ; Level 1

; Remaining Duration of Berk's Current Power
;
; For each game-cycle that a power is in use, the byte at 34224 is increased.
; When this reaches 16, it is reset to zero and the value at 34225 is decreased
; by one.
  DEFB 0                  ; Number of elapsed game-cycles in current group of
                          ; 16
  DEFB 0                  ; Number of groups of 16 game-cycles remaining

; Attribute of Current Character
;
; This is 1 (blue) for Berk, or 6 (yellow) for Drutt.
  DEFB 1

; Timer Figure Blink Duration Counter
  DEFB 0

; Data for Clawed Foot (Level 3)
;
; Location 34229 holds the index of the action performed by Clawed Foot after
; it picks Berk up. This value is incremented when the Clawed Foot reaches the
; top of its vertical range of travel while carrying Berk. If the incremented
; value exceeds six, then it is reset to one. After incrementing (and resetting
; if appropriate), the value is used to determine what the Clawed Foot does
; with Berk:
  DEFB 0                  ; Time (cycles) until Clawed Foot (Level 3) attacks
  DEFB 0                  ; Clawed Foot's Action Index

; Temporary Store for Room Dimension Data
;
; Contains an entry from one of the room dimension data blocks (at 43815,
; 44436, 45116 or 45860) for the current room of interest (see also 34262).
  DEFB 0,0,0,0,0

; Temporary Store for Width of Entity's Current Room
;
; This location holds the width of an entity's current room (in characters,
; plus + 99).
  DEFB 0

; Table of Data Addresses (Current Level)
  DEFW 99                 ; State Data for Simple Entities
  DEFW 99                 ; State Data for Complex Entities
  DEFW 99                 ; Address of Berk's state data
  DEFW 99                 ; Address of Drutt's state data
  DEFW 99                 ; Address of worm's state data
  DEFW 99                 ; Start address for reverse-order collision checks
  DEFW 99                 ; Room Dimension Data
  DEFW 99                 ; Horizontal Room Connectivity Map
  DEFW 99                 ; Unused Data Block (09)
  DEFW 99                 ; Vertical Room Connectivity Map

