  DEFW 45895              ; Vertical Room Connectivity Map (Level 4)

; Stack Space
  DEFB 78,79,87,32,73,83,32,84
  DEFB 72,69,32,87,73,78,84,69
  DEFB 82,32,79,70,32,79,85,82
  DEFB 32,68,73,83,67,79,78,84
  DEFB 69,78,84,32,77,65,68,69
  DEFB 32,71,76,79,82

; Unused
  DEFB 0,0

; Set Up Random Seed and Disable Interrupts
;
; Used by the routine at 34200.
  CALL 59831              ; Do nothing (see trivia)
  LD A,(23672)            ; Store the least significant byte of the system
                          ; variable FRAMES...
  LD (54219),A            ; ...at 54219 as the seed for the pseudo-random
                          ; number generator
  DI                      ; Disable interrupts

; Display Main Menu and Handle Main Game Loop
  LD SP,34426             ; Set Stack Pointer
  CALL 34695              ; Copy State Data for all resettable complex entities
                          ; into Table of Initial-State Data
  LD A,1                  ; Set current level to 1...
  LD (34207),A            ; ...
  CALL 46830              ; Display and handle Main Menu
  LD A,(34217)            ; Load current border colour into A
  OUT (254),A             ; Set border colour
  CALL 34864              ; Copy start addresses of current level's data blocks
                          ; to 34236 and clean up old data
  CALL 53887              ; Paint red areas outside accessible areas of current
                          ; character's current room
  CALL 47241              ; Reset Show Score Flag and draw timer figures bar
; Start of main loop
  CALL 53723              ; If Berk has been killed then reset his state, flash
                          ; screen and decrease time / lives
  CALL 35689              ; Update state of Berk and store current position in
                          ; script data
  CALL 51739              ; Update states of Drutt and worm and store current
                          ; positions in script data
  LD A,(34207)            ; If current level is not Level 1...
  CP 1                    ; ...
  JR NZ,34527             ; ...then skip ahead to 34527
; Level 1
  CALL 36791              ; Update states of all Level 1 entities
  LD IX,(34240)           ; Load IX with address of complex state data (current
                          ; level) for Berk
  BIT 2,(IX+10)           ; If "Back to Level 1" Flag is reset...
  JR Z,34557              ; ...then skip ahead to 34557
; Back to Level 1 Flag is set
  LD A,(43612)            ; If y-coordinate of Boni's bottom edge is not 121...
  CP 121                  ; ...
  JR NZ,34557             ; ...then skip ahead to 34557
  LD A,(43677)            ; If y-coordinate of Drutt's bottom edge is not
                          ; 121...
  CP 121                  ; ...
  JR NZ,34557             ; ...then skip ahead to 34557
  LD A,(43671)            ; If Drutt's room is not 1...
  CP 1                    ; ...
  JR NZ,34557             ; ...then skip ahead to 34557
  LD A,2                  ; Set depth of "Home Sweet Home" brickwork to 2...
  LD (43159),A            ; ...
  SET 3,(IX+10)           ; Set "All Home" Flag
  JR 34557                ; Skip ahead to 34557
  LD A,(34207)            ; If current level is not Level 2...
  CP 2                    ; ...
  JR NZ,34537             ; ...then skip ahead to 34537
; Level 2
  CALL 38009              ; Update states of all Level 2 entities
  LD A,(34207)            ; If current level is not Level 3...
  CP 3                    ; ...
  JR NZ,34547             ; ...then skip ahead to 34547
; Level 3
  CALL 39137              ; Update states of all Level 3 entities
  LD A,(34207)            ; If current level is not Level 4...
  CP 4                    ; ...
  JR NZ,34557             ; ...then skip ahead to 34557
; Level 4
  CALL 41211              ; Update states of all Level 4 entities
; All levels
  CALL 47893              ; Check for control input and store at 34219
  CALL 55525              ; Move all falling entities down by distances
                          ; appropriate to their current velocity factors
  CALL 34916              ; If Fire Pressed, or Character Swap Pending Flag
                          ; set, then swap characters
  CALL 53782              ; Set each value in Primary Display Buffer within
                          ; play area to zero
  CALL 45899              ; Populate Primary Display Buffer with layout data
                          ; for current character's current room
  CALL 54034              ; Draw contents of Primary Display Buffer to display
  CALL 59725              ; Play and clear pending sound (index as stored at
                          ; 34273)
  LD A,(34210)            ; Load remaining time / lives into A
  OR A                    ; If no time / lives are left...
  JR Z,34645              ; ...then jump to 34645
  LD A,(43603)            ; If "All Home" Flag is set...
  BIT 3,A                 ; ...
  JR NZ,34658             ; ...then skip ahead to 34658
  CALL 47363              ; Update eyes of a randomly selected timer figure,
                          ; increase Timer Tick Counter and process timer
                          ; figure blinking
  LD HL,34208             ; If Update Scores and Display Flag is reset...
  BIT 5,(HL)              ; ...
  JR Z,34606              ; ...then skip ahead to 34606
  RES 5,(HL)              ; Reset Update Scores and Display Flag
  CALL 47499              ; Update scores and display
  LD HL,61312             ; Point HL at Display Buffer 1
  LD DE,63424             ; Point DE at Display Buffer 2
  LD A,(34271)            ; Invert "Display Buffer 2 is Primary" Flag...
  XOR 1                   ; ...
  LD (34271),A            ; ...
  JR Z,34623              ; If "Display Buffer 2 is Primary" Flag is reset then
                          ; skip ahead to 34623 (Display Buffer 1 is Primary,
                          ; Display Buffer 2 is Secondary)
  EX DE,HL                ; Switch DE and HL (Display Buffer 1 is Secondary,
                          ; Display Buffer 2 is Primary)
  LD (34279),HL           ; Store address of Primary Display Buffer at 34279
  LD A,(34219)            ; Load A with control input
  BIT 6,A                 ; If Restart hasn't been pressed...
  JP Z,34466              ; ...then jump to 34466 (start of main loop)
; Restart has been pressed
  LD A,1                  ; Set sound 1 as pending if appropriate, then play
                          ; and clear pending sound...
  CALL 59722              ; ...
  CALL 34751              ; Reset all game data in preparation for new game
  JP 34438                ; Jump back to 34438 (return to Main Menu)
; No time/lives left
  CALL 47499              ; Update scores and display
  CALL 47185              ; Print "SORRY BERK,  BUT YOUR TIME IS UP" string
  LD A,1                  ; Set sound 1 as pending if appropriate, then play
                          ; and clear pending sound...
  CALL 59722              ; ...
  JR 34666                ; Skip ahead to 34666
; "All Home" Flag is set
  CALL 47213              ; Print "HOME SWEET HOME" string
  LD A,3                  ; Set sound 3 as pending if appropriate, then play
                          ; and clear pending sound...
  CALL 59722              ; ...
  CALL 47942              ; Wait for current key to be released and another to
                          ; be pressed, storing in A
  CALL 34751              ; Reset all game data in preparation for new game
  JP 34438                ; Jump back to 34438 (return to Main Menu)

; Pause
;
; Used by the routine at 53649. Input:  B  Repeat count for outer loop C
; Additional repeat count for inner loop
  PUSH BC                 ; Store BC
  LD B,10                 ; Set B to 10
  DEC BC                  ; Decrease BC
  LD A,B                  ; If BC is not zero...
  OR C                    ; ...
  JR NZ,34678             ; ...then loop back to 34678
  POP BC                  ; Restore BC
  DJNZ 34675              ; Loop back for next pass
  RET                     ; Return

; Table of Start Addresses of Levels' State Data for Complex Entities
  DEFW 43333              ; Level 1
  DEFW 43993              ; Level 2
  DEFW 44608              ; Level 3
  DEFW 45274              ; Level 4

; Copy State Data for all Resettable Complex Entities into Table of
; Initial-State Data for Complex Entities
;
; Used by the routine at 34438.
  LD IY,34687             ; Point IY at start of Table of Start Addresses of
                          ; Levels' State Data for Complex Entities
  LD DE,59821             ; Point DE at start of Table of Initial-State Data
                          ; for Complex Entities
  LD B,4                  ; Set B to 4 (as there are 4 levels)
  PUSH BC                 ; Store BC (B = remaining number of levels to
                          ; process)
  LD L,(IY+0)             ; Load start address of current level's complex state
                          ; data into HL...
  LD H,(IY+1)             ; ...
  INC IY                  ; Advance IY to next entry in list of addresses of
                          ; complex state data...
  INC IY                  ; ...
  PUSH HL                 ; Transfer start address of current level's complex
                          ; state data into IX...
  POP IX                  ; ...
  LD A,(IX+0)             ; If first byte in current complex state data entry
                          ; is 255 (End Marker)...
  CP 255                  ; ...
  JR Z,34747              ; ...then skip ahead to 34747
  LD A,(IX+10)            ; If entity's Can Be Reset Flag is reset...
  AND 128                 ; ...
  JR Z,34740              ; ...then advance IX by 13 bytes to next entry and
                          ; loop back to 34718
  PUSH IX                 ; Transfer start address of current entry in complex
                          ; state data into HL...
  POP HL                  ; ...
  LD BC,13                ; Load BC with 13 (as entries in complex state data
                          ; are 13 bytes wide)
  LDIR                    ; Copy current entry in complex state data into Table
                          ; of Initial-State Data for Complex Entities at 59821
  LD BC,13                ; Load BC with 13 (as entries in complex state data
                          ; are 13 bytes wide)
  ADD IX,BC               ; Advance IX to next entry in complex state data
  JR 34718                ; Loop back to 34718
  POP BC                  ; Restore BC (B = remaining number of levels to
                          ; process)
  DJNZ 34704              ; Decrease B and loop back to 34704 to process next
                          ; level
  RET                     ; Return

; Reset All Game Data in Preparation for New Game
;
; Used by the routine at 34438.
  LD IY,34687             ; Point IY at start of Table of Start Addresses of
                          ; Levels' State Data for Complex Entities
  LD HL,59821             ; Point HL at start of Table of Initial-State Data
                          ; for Complex Entities
  LD B,4                  ; Set B to 4 (as there are 4 levels)
  PUSH BC                 ; Store BC (B = remaining number of levels to
                          ; process)
  LD E,(IY+0)             ; Load start address of current level's complex state
                          ; data into DE...
  LD D,(IY+1)             ; ...
  INC IY                  ; Advance IY to next entry in list of addresses of
                          ; complex state data...
  INC IY                  ; ...
  PUSH DE                 ; Transfer start address of current level's complex
                          ; state data into IX...
  POP IX                  ; ...
  LD A,(IX+0)             ; If first byte in current complex state data entry
                          ; is 255 (End Marker)...
  CP 255                  ; ...
  JR Z,34803              ; ...then skip ahead to 34803
  LD A,(IX+10)            ; If entity's Can Be Reset Flag is reset...
  AND 128                 ; ...
  JR Z,34796              ; ...then advance IX by 13 bytes to next entry and
                          ; loop back to 34774
  PUSH IX                 ; Transfer start address of current entry in complex
                          ; state data into DE...
  POP DE                  ; ...
  LD BC,13                ; Load BC with 13 (as entries in complex state data
                          ; are 13 bytes wide)
  LDIR                    ; Copy current entry in Table of Initial-State Data
                          ; for Complex Entities at 59821 into complex state
                          ; data
  LD BC,13                ; Load BC with 13 (as entries in complex state data
                          ; are 13 bytes wide)
  ADD IX,BC               ; Advance IX to next entry in complex state data
  JR 34774                ; Loop back to 34774
  POP BC                  ; Restore BC (B = remaining number of levels to
                          ; process)
  DJNZ 34760              ; Decrease B and loop back to 34760 to process next
                          ; level
  LD HL,34298             ; Point HL at Joystick Mode Flag
  LD DE,34207             ; Point DE at store for current level number
  XOR A                   ; Set A to zero and reset Carry Flag
  SBC HL,DE               ; Subtract DE from HL to leave HL = 91
  LD B,L                  ; Load B with 91
  LD HL,34207             ; Point HL at store for current level number...
  LD (HL),A               ; ...and set 91 bytes from here onwards to zero...
  INC HL                  ; ...
  DJNZ 34819              ; ...
  LD A,16                 ; Set time / lives to 16...
  LD (34210),A            ; ...
  LD A,1                  ; Set current level to Level 1...
  LD (34207),A            ; ...
  CALL 36778              ; Initialise script data positions for Flying
                          ; Skeleton Creature and Bat (Level 1)
  CALL 38468              ; Reset current positions in apebeasts' script data
                          ; to initial values
  CALL 41354              ; Reset Skeleton to initial state
  CALL 51732              ; Reset Drutt to initial state
  LD A,1                  ; Set room of "Closed Trap Door" and impassable
                          ; marker to 1 (i.e. starting room)...
  LD (43188),A            ; ...
  LD (43450),A            ; ...
  LD (34226),A            ; Set attribute of current character to 1 (blue,
                          ; Berk)
  DEC A                   ; Set room of "Open Trap Door" and "Home Sweet Home"
                          ; brickwork to 0...
  LD (43437),A            ; ...i.e. remove from game...
  LD (43159),A            ; ...
  RET                     ; Return

; Copy Start Addresses of Current Level's Data Blocks to 34236 and Clean Up Old
; Data
;
; Used by the routines at 34438 and 36753.
  PUSH DE                 ; Store DE
  PUSH HL                 ; Store HL
  LD HL,(34244)           ; Load HL with address of complex state data (current
                          ; level) for worm
  LD (HL),0               ; Set worm's current room to zero
  LD A,(34207)            ; Load current level into A
  LD HL,34281             ; Point HL at position 20 bytes before start of list
                          ; of start addresses of level 1's data blocks
  LD BC,20                ; Set data length to 20, as there are 10 data blocks
                          ; per level (so 10 addresses)
  ADD HL,BC               ; Advance HL to start of data block address list for
                          ; next level
  DEC A                   ; Decrease level counter
  JR NZ,34880             ; Loop back if we have not reached data for required
                          ; level
; At this point, HL points to the start of the list of start addresses of the
; current level's data blocks
  LD DE,34236             ; Copy this level's data block start addresses to
                          ; 34236...
  LDIR                    ; ...
  LD B,9                  ; Clear Store for Script Instruction Loop Data...
  LD HL,34285             ; ...
  LD (HL),A               ; ...
  INC HL                  ; ...
  DJNZ 34894              ; ...
  POP HL                  ; Restore HL
  POP DE                  ; Restore DE
  RET                     ; Return

; Script Routine (48, 49) Return
;
; This script routine terminates the script data currently under execution
; until the next game cycle.
  RET                     ; Return

; Unused routine
;
; This routine floods the Attribute File with value 9 (Blue INK, Blue PAPER)
  LD HL,22528             ; Set all Attribute File contents to blue INK, blue
                          ; PAPER...
  LD DE,22529             ; ...
  LD (HL),9               ; ...
  LD BC,767               ; ...
  LDIR                    ; ...
  RET                     ; Return

; If Fire Pressed, or Character Swap Pending Flag Set, then Swap Characters
;
; Used by the routine at 34438.
  LD HL,34208             ; If Character Swap Pending Flag is reset...
  BIT 6,(HL)              ; ...
  JR Z,34927              ; ...then skip ahead to 34927
  RES 6,(HL)              ; Reset Character Swap Pending Flag
  JR 34944                ; Skip ahead to 34944
  LD A,(34219)            ; Load A with control input
  BIT 4,A                 ; If fire was pressed...
  JR NZ,34940             ; ...then skip ahead to 34940
  RES 1,(HL)              ; Reset Characters Already Swapped Flag
  CALL 53825              ; Copy room dimension data entry for current
                          ; character's current room to temporary store
                          ; location (34230)
  RET                     ; Return
; [Fire pressed]
  BIT 1,(HL)              ; If Characters Already Swapped Flag set (i.e. FIRE
                          ; hasn't been released since last swap)...
  JR NZ,34936             ; ...then jump back to 34936
  SET 1,(HL)              ; Set Characters Already Swapped Flag
  LD A,(HL)               ; Load Game Flags into A
  XOR 1                   ; Flip bit 7 (Berk / Drutt flag)...
  LD (HL),A               ; ...
  BIT 0,(HL)              ; If current character is now Berk (0)...
  JR Z,34958              ; ...then jump ahead to 34958
  LD A,6                  ; Load A with 6 (attribute for Drutt's timer
                          ; indicator figures)
  JR 34960                ; Skip ahead to 34960
  LD A,1                  ; Load A with 1 (attribute for Berk's timer indicator
                          ; figures)
  LD (34226),A            ; Set attribute of timer indicator figures to value
                          ; in A
  CALL 53887              ; Paint red areas outside accessible areas of current
                          ; character's current room
  LD HL,34208             ; If Show Score Flag is set...
  BIT 7,(HL)              ; ...
  JP NZ,47628             ; ...then print SCORE / TOTAL / HI-SC string in
                          ; current character's colours and return
  JP 47241                ; Reset Show Score Flag, draw timer figures bar and
                          ; return

; Script Data Berk Turning to Face Left
  DEFB 8,0                ; Set Must Process Current Script Data Flag
  DEFB 19,0               ; Move carried entity to Berk's left as he faces left
  DEFB 184,219            ; 56248 (Berk, stepping left, left foot out, arm and
                          ; eye animated)
  DEFB 193,219            ; 56257 (Berk, stepping left, left foot out and
                          ; forward, arm and eye animated)
; At this point, Berk has made the turn (i.e. already moved his feet)
  DEFB 13,0               ; Set Berk's Facing Left Flag, and reset his Facing
                          ; Into Screen and Facing Right flags
  DEFB 19,0               ; Move carried entity to Berk's left as he faces left
  DEFB 9,0                ; Reset Must Process Current Script Data Flag
  DEFB 202,219            ; 56266 (Berk, facing left, arm and eye animated)
  DEFB 1,0,169,136        ; Jump back to 34985

; Script Data Berk Turning to Face Right
  DEFB 8,0                ; Set Must Process Current Script Data Flag
  DEFB 20,0               ; Move carried entity to Berk's right as he faces
                          ; right
  DEFB 158,217            ; 55710 (Berk, stepping right, right foot out, arm
                          ; and eye animated)
  DEFB 146,217            ; 55698 (Berk, stepping right, right foot out and
                          ; forward, arm and eye animated)
; At this point, Berk has made the turn (i.e. already moved his feet)
  DEFB 14,0               ; Set Berk's Facing Right Flag, and reset his Facing
                          ; Into Screen and Facing Left flags
  DEFB 20,0               ; Move carried entity to Berk's right as he faces
                          ; right
  DEFB 9,0                ; Reset Must Process Current Script Data Flag
  DEFB 170,217            ; 55722 (Berk, facing right, arm and eye animated)
  DEFB 1,0,189,136        ; Jump back to 35005

; Script Data Berk Interacting with a Door Behind Him
  DEFB 8,0                ; Set Must Process Current Script Data Flag
  DEFB 6,0                ; Set Berk's Facing Into Screen Flag, and reset his
                          ; Facing Left and Facing Right flags
  DEFB 10,0               ; Reset Berk's Walking Left and Walking Right flags
  DEFB 22,0               ; Move carried entity behind Berk as he faces into
                          ; screen
  DEFB 84,224             ; 57428 (Berk facing into screen, holding something)
  DEFB 84,224             ; 57428 (Berk facing into screen, holding something)
  DEFB 59,0               ; Have Berk interact appropriately with a door behind
                          ; him
  DEFB 57,0               ; Cycle attributes (full-screen), clear display
                          ; buffers and paint red areas outside current room
  DEFB 23,0,5,0           ; Start loop (1) for 5 iterations
  DEFB 250,223            ; 57338 (Berk facing into screen, arms out to the
                          ; sides)
  DEFB 24,0               ; End loop (1)
  DEFB 1,0,41,137         ; Jump to 35113 (Berk facing into screen, ready to
                          ; respond to control input)

; Script Data Berk Interacting with a Door in Front of Him
  DEFB 8,0                ; Set Must Process Current Script Data Flag
  DEFB 7,0                ; Reset Berk's Facing Into Screen, Facing Left and
                          ; Facing Right flags
  DEFB 10,0               ; Reset Berk's Walking Left and Walking Right flags
  DEFB 21,0               ; Move carried entity in front of Berk as he faces
                          ; out of screen
  DEFB 226,222            ; 57058 (Berk, facing out of screen, holding
                          ; something, animated)
  DEFB 226,222            ; 57058 (Berk, facing out of screen, holding
                          ; something, animated)
  DEFB 58,0               ; Have Berk interact appropriately with a door in
                          ; front of him
  DEFB 57,0               ; Cycle attributes (full-screen), clear display
