  DEFB 2,0                ; Move Berk left two characters...
  DEFB 2,0                ; ...
  DEFB 62,0               ; Move Berk into room to the left, if appropriate
  DEFB 34,0               ; Move Berk up two characters...
  DEFB 34,0               ; ...
  DEFB 24,0               ; End loop (1)
  DEFB 23,0,4,0           ; Start loop (1) for 4 iterations
  DEFB 168,230            ; 59048 (Berk being thrown left)
  DEFB 2,0                ; Move Berk left two characters...
  DEFB 2,0                ; ...
  DEFB 35,0               ; Move Berk down two characters...
  DEFB 35,0               ; ...
  DEFB 24,0               ; End loop (1)
  DEFB 23,0,2,0           ; Start loop (1) for 2 iterations
  DEFB 32,231             ; 59168 (Floating / starting to fall, animated)
  DEFB 2,0                ; Move Berk left one character
  DEFB 35,0               ; Move Berk down two characters...
  DEFB 35,0               ; ...
  DEFB 24,0               ; End loop (1)
  DEFB 1,0,43,138         ; Jump to 35371 (Berk lying on floor stunned and
                          ; getting up)

; Change Direction Berk is Facing Depending Upon Relative Position of Drutt
;
; Used by the routine at 35735. Input:  IX  Address of complex state data
; (current level) for Berk
  LD A,(34218)            ; If Drutt's current room...
  CP (IX+0)               ; ...is not the same as Berk's current room...
  JP NZ,35786             ; ...then jump to 35786 (terminate Berk's flight, or
                          ; have him (turn to) face out of screen as
                          ; appropriate)
  LD A,(IX+11)            ; Reset Berk's Walking Right, Walking Left, Unused
                          ; (11,2) and Unused (11,3) flags...
  AND 240                 ; ...
  LD (IX+11),A            ; ...
  LD E,(IX+9)             ; Load Berk's Flags into E
  LD IY,(34242)           ; Load IY with address of complex state data (current
                          ; level) for Drutt
  LD A,(IY+7)             ; Load A with x-coordinate of Drutt's right side...
  INC A                   ; ...and increase by one
  CP (IX+5)               ; If x-coordinate of Berk's left side is greater than
                          ; this (i.e. Drutt is to the left of Berk)...
  JR C,35653              ; ...then skip ahead to 35653
  LD A,(IX+7)             ; Load A with x-coordinate of Berk's right side
  INC A                   ; Increase A by one
  CP (IY+5)               ; If x-coordinate of Drutt's left side is greater
                          ; than this (i.e. Drutt is to the right of Berk)...
  JR C,35670              ; ...then skip ahead to 35670
; Drutt is between Berk's left and right sides
  LD A,(IY+1)             ; If Drutt's depth is 1...
  CP 1                    ; ...
  JP Z,35642              ; ...then skip ahead to 35642
; Drutt is behind Berk
  LD A,E                  ; Load A with Berk's flags
  AND 14                  ; If Berk's Facing into Screen, Facing Left and
                          ; Facing Right flags are all reset...
  JP Z,35636              ; ...then skip ahead to 35636
; Drutt is behind Berk and at least one of Berk's Facing into Screen, Facing
; Left and Facing Right flags is set
  JP 35815                ; Point HL at script data for Berk facing into
                          ; screen, ready to respond to control input and
                          ; execute
; Drutt is behind Berk and Berk's Facing into Screen, Facing Left and Facing
; Right flags are all reset
  LD HL,35105             ; Point HL at script data for Berk turning (facing
                          ; out of screen to facing into screen)...
  JP 48098                ; ...and execute
; Drutt is in front of Berk
  BIT 1,E                 ; If Berk's Facing into Screen Flag is reset...
  JP Z,35821              ; ...then point HL at script data for Berk facing out
                          ; of screen, ready to respond to control input and
                          ; execute
; Drutt is in front of Berk and Berk's Facing into Screen Flag is set
  LD HL,35073             ; Point HL at script data for Berk turning (facing
                          ; into screen to facing out of screen)...
  JP 48098                ; ...and execute
; Drutt is to the left of Berk
  LD A,E                  ; Load A with Berk's flags
  AND 6                   ; If either of Berk's Facing into Screen or Facing
                          ; Left flags are set...
  JR NZ,35664             ; ...then skip ahead to 35664
; Drutt is to the left of Berk, and Berk's Facing into Screen and Facing Left
; flags are both reset
  LD HL,34977             ; Point HL at script data for Berk turning to face
                          ; left...
  JP 48098                ; ...and execute
; Drutt is to the left of Berk and either of Berk's Facing into Screen or
; Facing Left flags are set
  LD HL,34985             ; Point HL at script data for Berk facing left...
  JP 48098                ; ...and execute
; Drutt is to the right of Berk
  LD A,E                  ; Load A with Berk's flags
  AND 10                  ; If either of Berk's Facing into Screen or Facing
                          ; Right flags are set...
  JR NZ,35681             ; ...then skip ahead to 35681
; Drutt is to the right of Berk, and Berk's Facing into Screen and Facing Right
; flags are both reset
  LD HL,34997             ; Point HL at script data for Berk turning to face
                          ; right...
  JP 48098                ; ...and execute
; Drutt is to the right of Berk and either of Berk's Facing into Screen or
; Facing Right flags are set
  LD HL,35005             ; Point HL at script data for Berk facing right...
  JP 48098                ; ...and execute

; Current Position in Berk's Script Data
  DEFW 35081              ; Berk facing out of screen, ready to respond to
                          ; control input

; Update State of Berk and Store Current Position in Script Data
;
; Used by the routine at 34438.
  LD IX,(34240)           ; Load IX with address of complex state data (current
                          ; level) for Berk
  CALL 53848              ; Store room size data for Berk's current room
  BIT 5,(IX+9)            ; If Berk's "Do Not Update State" Flag is set...
  RET NZ                  ; ...then return
  LD HL,(35687)           ; Load current position in Berk's script data from
                          ; 35687 into HL...
  LD (34277),HL           ; ...and store at 34277 as position in script
                          ; currently running
  CALL 35735              ; Update state of Berk depending upon currently
                          ; selected character, control input and currently
                          ; active power
  LD HL,(34277)           ; Store address (current position in script data)
                          ; stored at 34277...
  LD (35687),HL           ; ...at 35687 as current position in Berk's script
                          ; data
  LD A,(34220)            ; If Berk's current power is not invisibility (level
                          ; 3)...
  CP 11                   ; ...
  RET NZ                  ; ...then return
; Current power is invisibility (Level 3)
  LD BC,50800             ; Load BC with address of blank graphic layout
                          ; data...
  LD (IX+2),C             ; ...and set this as Berk's current graphic layout
                          ; data address...
  LD (IX+3),B             ; ...
  CALL 48388              ; Decrease remaining time for current power and if
                          ; zero, exit this routine and run script data for
                          ; removal of power
  RET                     ; Return

; Update State of Berk Depending Upon Currently Selected Character, Control
; Input and Currently Active Power
;
; Used by the routine at 35689. Input:  IX  Address of complex state data
; (current level) for Berk
  BIT 7,(IX+9)            ; If Berk's Moving Upwards Flag (floating power) is
                          ; set...
  JP NZ,36542             ; ...then jump to 36542 (update state of Berk,
                          ; floating power active)
  BIT 0,(IX+9)            ; If Berk's Must Process Current Script Data Flag is
                          ; set...
  JP NZ,48096             ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  LD A,(34208)            ; If Drutt Mode Flag is set...
  BIT 0,A                 ; ...
  JP NZ,35577             ; ...then jump to 35577 (change direction Berk is
                          ; facing depending upon relative position of Drutt)
; Drutt Mode Flag is reset (i.e. Berk Mode)
  LD A,(34219)            ; Load A with control input
  BIT 0,A                 ; If right has been pressed...
  JP NZ,36214             ; ...then skip ahead to 36214 (move Berk right if
                          ; appropriate)
  BIT 1,A                 ; If left has been pressed...
  JP NZ,36137             ; ...then skip ahead to 36137 (move Berk left if
                          ; appropriate)
  CALL 54283              ; Move Berk into new room (left or right) if he is at
                          ; the edge of his current room
  LD A,(34219)            ; Load A with control input
  BIT 2,A                 ; If forward has been pressed...
  JP NZ,36036             ; ...then skip ahead to 36036 (update state of Berk,
                          ; forward pressed)
  BIT 3,A                 ; If back has been pressed...
  JP NZ,35827             ; ...then skip ahead to 35827
; At this point, no control has been pressed. This entry point is used by the
; routines at 35577, 36036 and 36116.
  BIT 6,(IX+9)            ; If Berk is not flying...
  JR Z,35802              ; ...then skip ahead to 35802
; Berk is flying
  RES 6,(IX+9)            ; Reset Berk's Is Flying Flag
  LD HL,35359             ; Point HL at script data for Berk starting to fall
                          ; downwards...
  JP 48098                ; ...and execute
; No control pressed and Berk not flying
  BIT 1,(IX+9)            ; If Berk's Facing Into Screen Flag is reset...
  JR Z,35821              ; ...then skip ahead to 35821
; No control pressed, Berk not flying and Berk's Facing Into Screen Flag is set
  BIT 3,(IX+11)           ; If Berk's Unused (11,3) Flag is reset...
  JP Z,48096              ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
; No control pressed, Berk not flying, Berk's Facing Into Screen and Unused
; (11,3) flags are set This entry point is used by the routine at 35577.
  LD HL,35113             ; Point HL at script data for Berk facing into
                          ; screen, ready to respond to control input...
  JP 48098                ; ...and execute
; No control pressed, Berk not flying and Berk's Facing Into Screen Flag is
; reset This entry point is used by the routine at 35577.
  LD HL,35081             ; Point HL at script data for Berk facing out of
                          ; screen, ready to respond to control input...
  JP 48098                ; ...and execute
; Back Pressed
  BIT 6,(IX+9)            ; If Berk is flying...
  JP NZ,48096             ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  CALL 36008              ; If Berk is holding an edible entity them make him
                          ; eat it, process appropriate script data and return
                          ; to calling routine
  DEC (IX+4)              ; Temporarily decrease y-coordinate of Berk's top
                          ; edge
  CALL 54890              ; Check entity at IX for collision with another
                          ; entity (in reverse order) at next depth level into
                          ; screen whose Interaction (11,7) Flag is set
  PUSH AF                 ; Store AF
  INC (IX+4)              ; Restore y-coordinate of Berk's top edge
  POP AF                  ; Restore AF
  JR C,35953              ; If no collision occurred, then skip ahead to 35953
  CP 33                   ; If collision was not with an entity of class 33
                          ; (door)...
  JR NZ,35870             ; ...then skip ahead 35870
; Collision with door
  CALL 36116              ; If Berk is not horizontally aligned with door then
                          ; move him closer and exit this routine
; Berk is now horizontally aligned with door
  CALL 36367              ; If Berk is neither facing into the screen nor
                          ; walking then exit this routine and have Berk turn
                          ; into screen
  LD (34256),IY           ; Store address of complex state data for door at
                          ; 34256
  LD HL,35017             ; Point HL at script data for Berk interacting with a
                          ; door behind him...
  JP 48098                ; ...and execute
; Collision with something other than door
  CP 22                   ; If collision was with an entity of class of 22 or
                          ; greater (can't be picked up)...
  JR NC,35924             ; ...then skip ahead to 35924
; Collision with entity that can be picked up
  BIT 4,(IX+9)            ; If Berk is already carrying something...
  JP NZ,35953             ; ...then skip ahead to 35953
  CALL 36116              ; If Berk is not horizontally aligned with entity
                          ; then move him closer and exit this routine
; Berk is now horizontally aligned with entity pointed to by IY
  CALL 36367              ; If Berk is neither facing into the screen nor
                          ; walking then exit this routine and have Berk turn
                          ; into screen
  LD (34256),IY           ; Store address of complex state data for entity at
                          ; 34256
  LD B,(IX+6)             ; Load B with y-coordinate of Berk's bottom edge...
  DEC B                   ; ...minus 1 (to take into account different depth)
  LD A,(IY+6)             ; Load A with y-coordinate of entity's bottom edge...
  CP (IX+4)               ; ...and if this is less than the y-coordinate of
                          ; Berk's top edge...
  JR C,35918              ; ...then skip ahead to 35918
; Entity is not above Berk
  CP B                    ; If entity's bottom edge is level with Berk's
                          ; (taking into account different depth)...
  JR Z,35912              ; ...then skip ahead to 35912
; Entity is above floor and below Berk's top edge
  LD HL,35163             ; Point HL at script data for Berk picking up an
                          ; entity that is above floor and below Berk's top
                          ; edge and behind him...
  JP 48098                ; ...and execute
; Entity is on floor behind Berk
  LD HL,35135             ; Point HL at script data for Berk picking up an
                          ; entity on floor behind him...
  JP 48098                ; ...and execute
; Entity is above Berk
  LD HL,35149             ; Point HL at script data for Berk picking up an
                          ; entity above and behind him...
  JP 48098                ; ...and execute
; Collision with something that can't be picked up
  CP 32                   ; If collision was not with entity of class 32
                          ; (coloured creatures' slots, Level 3)...
  JR NZ,35953             ; ...then skip ahead to 35953
; Collision with a coloured creature slot
  BIT 4,(IX+9)            ; If Berk is not carrying anything...
  JR Z,35953              ; ...then skip ahead to 35953
; Berk is carrying something
  CALL 36116              ; If Berk is not horizontally aligned with coloured
                          ; creature slot then move him closer and exit this
                          ; routine
; Berk is now horizontally aligned with coloured creature slot and carrying
; something
  CALL 36367              ; If Berk is neither facing into the screen nor
                          ; walking then exit this routine and have Berk turn
                          ; into screen
  LD A,(IY+4)             ; Load A with y-coordinate of top edge of coloured
                          ; creature slot... (see trivia)
  DEC A                   ; ...minus 1...
  LD (34222),A            ; ...and store at 34222
  LD HL,35235             ; Point HL at script data for Berk putting an entity
                          ; down above floor behind him...
  JP 48098                ; ...and execute
; No collision, collision with non-interactive entity or interaction conditions
; not met
  LD A,(34220)            ; If Berk has no current power...
  OR A                    ; ...
  JR Z,35969              ; ...then skip ahead to 35969
  CP 4                    ; If Berk's current power is 1-3 (jumping)...
  JP C,35995              ; ...then skip ahead to 35995
  CP 9                    ; If Berk's current power is 4-8 (flying)...
  JP C,35985              ; ...then skip ahead to 35985
; Berk has neither jumping nor flying power
  BIT 4,(IX+9)            ; If Berk is not carrying anything...
  JP Z,35786              ; ...then jump to 35786 (terminate Berk's flight, or
                          ; have him (turn to) face out of screen as
                          ; appropriate)
; Berk is carrying something
  CALL 36367              ; If Berk is neither facing into the screen nor
                          ; walking then exit this routine and have Berk turn
                          ; into screen
  LD HL,35219             ; Point HL at script data for Berk putting an entity
                          ; down on floor behind him...
  JP 48098                ; ...and execute
; Berk's current power is flying
  SET 6,(IX+9)            ; Set Berk's Is Flying Flag
  LD HL,35417             ; Point HL at script data for Berk starting to fly...
  JP 48098                ; ...and execute
; Berk's current power is jumping
  CALL 36296              ; Make Berk drop the entity he is holding and load IY
                          ; with its complex state data address
  LD (IX+12),129          ; Set Berk's Is Jumping Flag and set initial jump
                          ; velocity to 1
  LD HL,35441             ; Point HL at script data for Berk starting to jump
                          ; straight up...
  JP 48098                ; ...and execute

; Make Berk Eat the Entity He is Holding, if Edible, and Exit Calling Routine
;
; Used by the routine at 35735.
  LD A,(34221)            ; If Berk is not holding anything...
  OR A                    ; ...
  RET Z                   ; ...then return
  CP 12                   ; If class value of entity held by Berk is greater
                          ; than 12...
  RET NC                  ; ...then return
  POP BC                  ; Remove top value from stack (i.e. return address to
                          ; routine that called this routine)
  CALL 48710              ; Move carried entity in front of Berk as he faces
                          ; out of screen
  LD IY,(34260)           ; Load IY with address of complex state data for
                          ; entity held by Berk
  DEC (IY+4)              ; Move entity up one character to level of Berk's
                          ; mouth...
  DEC (IY+6)              ; ...
  LD HL,35493             ; Point HL at script data for Berk eating an
                          ; entity...
  JP 48098                ; ...and execute

; Update State of Berk (Forward Pressed)
;
; Used by the routine at 35735. Input:  IX  Address of complex state data
; (current level) for Berk
  BIT 1,(IX+9)            ; If Berk's Facing Into Screen Flag is reset...
  JP Z,36049              ; ...then skip ahead to 36049
; Berk's Facing Into Screen Flag is set
  LD HL,35073             ; Point HL at script data for Berk turning (facing
                          ; into screen to facing out of screen)...
  JP 48098                ; ...and execute
; Berk's Facing Into Screen Flag is reset
  LD DE,0                 ; Clear pointer to complex state data for entity
                          ; involved in last collision check...
  LD (34258),DE           ; ...
  CALL 54768              ; Check entity at IX for collision with another
                          ; entity at same depth whose Interaction (11,6) Flag
                          ; is set...
  JR C,36103              ; ...and if no collision occurred, then skip ahead to
                          ; 36103
; Collision occurred
  CP 33                   ; If collision was not with an entity of class 33
                          ; (door)...
  JR NZ,36078             ; ...then skip ahead to 36078
; Collision with door
  CALL 36116              ; If Berk is not horizontally aligned with door then
                          ; move him closer and exit this routine
; Berk is now horizontally aligned with door
  LD (34256),IY           ; Store address of door's complex state data at 34256
  LD HL,35045             ; Point HL at script data for Berk interacting with a
                          ; door in front of him...
  JP 48098                ; ...and execute
; Collision with something other than door
  BIT 4,(IX+9)            ; If Berk's Carrying Something Flag is set...
  JP NZ,35786             ; ...then jump to 35786 (terminate Berk's flight, or
                          ; have him (turn to) face out of screen as
                          ; appropriate)
  CP 22                   ; If collision was with an entity of class of 22 or
                          ; greater (can't be picked up)...
  JP NC,35786             ; ...then jump to 35786 (terminate Berk's flight, or
                          ; have him (turn to) face out of screen as
                          ; appropriate)
; At this point, Berk is not carrying anything, and the entity he is colliding
; with is one which can be picked up
  CALL 36116              ; If Berk is not horizontally aligned with entity at
                          ; IY then move him closer and exit this routine
; Berk is now horizontally aligned with entity pointed to by IY
  LD (34256),IY           ; Store address of entity's complex state data at
                          ; 34256
  LD HL,35187             ; Point HL at script data for Berk picking up an
                          ; entity on floor in front of him...
  JP 48098                ; ...and execute
; No collision occurred
  BIT 4,(IX+9)            ; If Berk is not carrying anything...
  JP Z,35786              ; ...then jump to 35786 (terminate Berk's flight, or
                          ; have him (turn to) face out of screen as
                          ; appropriate)
; Berk is carrying something
  LD HL,35205             ; Point HL at script data for Berk putting an entity
                          ; down on floor in front of him...
  JP 48098                ; ...and execute

; If Berk is Not Horizontally Aligned with Entity at IY then Move Berk Closer
; and Exit Calling Routine
;
; Used by the routines at 35735 and 36036. Input:  IX  Address of complex state
; data (current level) for Berk IY Address of complex state data for entity
; with which Berk has collided
  LD A,(IY+7)             ; Load A with width of entity at IY, minus 1...
  SUB (IY+5)              ; ...
  SRL A                   ; ...divide value by 2...
  SUB 2                   ; ...and subtract 2
  ADD A,(IY+5)            ; Add result to x-coordinate of entity's left edge
; At this point, A holds the x-coordinate of the middle of the entity at IY,
; minus two
  CP (IX+5)               ; If x-coordinate in A is the same as Berk's left
                          ; side x-coordinate...
  RET Z                   ; ...then return
  POP BC                  ; Remove top value from stack (i.e. return address to
                          ; routine that called this routine)
  JP NC,36214             ; If x-coordinate in A is the less than Berk's left
                          ; side x-coordinate then skip ahead to 36214
; This entry point is used by the routine at 35735. Attempt to move Berk left
  BIT 6,(IX+9)            ; If Berk is flying...
  JR NZ,36200             ; ...then skip ahead to 36200
; Attempt to move Berk left (not flying) (see bugs)
  RES 1,(IX+9)            ; Reset Berk's Facing Into Screen Flag
  CALL 54666              ; Check Berk for collision with another impassable /
                          ; pushable entity immediately to the left...
  JR NC,36171             ; ...and if a collision occurred, then skip ahead to
                          ; 36171
; No collision
  CALL 54348              ; Move Berk into room to the left, if appropriate...
  JP NC,35786             ; ...and if Berk can't enter new room then jump to
                          ; 35786 (terminate Berk's flight, or have him (turn
                          ; to) face out of screen as appropriate)
  BIT 1,(IX+11)           ; If Berk's Walking Left Flag is already set...
  JP NZ,48096             ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  LD HL,35263             ; Point HL at script data for Berk starting to walk
                          ; left...
  JP 48098                ; ...and execute
; Collision occurred with entity to the left
  CP 129                  ; If collision was not with entity of class 129
                          ; (causes other entities to start falling)...
  JR NZ,36184             ; ...then skip ahead to 36184
  CALL 36296              ; Make Berk drop the entity he is holding and load IY
                          ; with its complex state data address
  LD HL,35291             ; Point HL at script data for Berk starting to fall
                          ; to the left...
  JP 48098                ; ...and execute
  CP 22                   ; If collision was with an entity of class of less
                          ; than 22 (can be picked up)...
  JR C,36158              ; ...then jump back to 36158
  CP 50                   ; If collision was with entity of class 50 (causes
                          ; Drutt to swap depth levels)...
  JR Z,36158              ; ...then jump back to 36158
  CP 25                   ; If collision was with entity of class 25 (Green
                          ; Apebeast, Level 2)...
  CALL Z,53667            ; ...then set "Berk Has Been Killed" Flag
  JP 35786                ; Jump to 35786 (terminate Berk's flight, or have him
                          ; (turn to) face out of screen as appropriate)
; Attempt to move Berk left (flying)
  CALL 54666              ; Check Berk for collision with another impassable /
                          ; pushable entity immediately to the left...
  JP C,48096              ; ...and if a collision has not occurred, then jump
                          ; to 48096 (advance HL to next script instruction and
                          ; execute)
  CP 129                  ; If collision was with entity of class 129 (causes
                          ; other entities to start falling)...
  JP Z,48096              ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  JP 35786                ; Jump to 35786 (terminate Berk's flight, or have him
                          ; (turn to) face out of screen as appropriate)
; This entry point is used by the routine at 35735. Attempt to move Berk right
  BIT 6,(IX+9)            ; If Berk is flying...
  JP NZ,36282             ; ...then skip ahead to 36282
; Attempt to move Berk right (not flying) (see bugs)
  RES 1,(IX+9)            ; Reset Berk's Facing Into Screen Flag
  CALL 54569              ; Check Berk for collision with another impassable /
                          ; pushable entity immediately to the right...
  JR NC,36249             ; ...and if a collision occurred, then skip ahead to
                          ; 36249
; No collision
  CALL 54313              ; Move Berk into room to the right, if appropriate...
  JP NC,35786             ; ...and if Berk can't enter new room then jump to
                          ; 35786 (terminate Berk's flight, or have him (turn
                          ; to) face out of screen as appropriate)
  BIT 0,(IX+11)           ; If Berk's Walking Right Flag is already set...
  JP NZ,48096             ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  LD HL,35251             ; Point HL at script data for Berk starting to walk
                          ; right...
  JP 48098                ; ...and execute
; Collision occurred with entity to the right
  CP 129                  ; If collision was not with entity of class 129
                          ; (causes other entities to start falling)...
  JR NZ,36266             ; ...then skip ahead to 36266
  CALL 36296              ; Make Berk drop the entity he is holding and load IY
                          ; with its complex state data address
  LD IY,(34260)           ; Load IY with address of complex state data for
                          ; entity last held by Berk (see trivia)
  LD HL,35327             ; Point HL at script data for Berk starting to fall
                          ; to the right...
  JP 48098                ; ...and execute
  CP 22                   ; If collision was with an entity of class of less
                          ; than 22 (can be picked up)...
  JR C,36236              ; ...then jump back to 36236
  CP 50                   ; If collision was with entity of class 50 (causes
                          ; Drutt to swap depth levels)...
  JR Z,36236              ; ...then jump back to 36236
  CP 25                   ; If collision was with entity of class 25 (Green
                          ; Apebeast, Level 2)...
  CALL Z,53667            ; ...then set "Berk Has Been Killed" Flag
  JP 35786                ; Jump to 35786 (terminate Berk's flight, or have him
                          ; (turn to) face out of screen as appropriate)
; Attempt to move Berk right (flying)
  CALL 54569              ; Check Berk for collision with another impassable /
                          ; pushable entity immediately to the right...
  JP C,48096              ; ...and if a collision has not occurred, then jump
                          ; to 48096 (advance HL to next script instruction and
                          ; execute)
  CP 129                  ; If collision was with entity of class 129 (causes
                          ; other entities to start falling)...
  JP Z,48096              ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  JP 35786                ; Jump to 35786 (terminate Berk's flight, or have him
                          ; (turn to) face out of screen as appropriate)

; Make Berk Drop the Entity He is Holding and Load IY with its Complex State
; Data Address
;
; Used by the routines at 35735, 36116, 36390, 36638, 39151, 39278, 39776,
; 48920 and 53723. Input: IX  Address of complex state data (current level) for
; Berk Output: IY  Address of complex state data for entity dropped by Berk
  LD A,(34221)            ; If Berk is not holding anything...
  OR A                    ; ...
  RET Z                   ; ...then return
  XOR A                   ; Set class of entity held by Berk to zero (i.e.
                          ; nothing)...
  LD (34221),A            ; ...
  LD IY,(34260)           ; Load IY with address of complex state data for
                          ; entity last held by Berk
  LD (IY+12),2            ; Set this dropped entity's velocity factor to 2...
  RES 5,(IY+10)           ; ...reset its Is Being Carried Flag...
  SET 6,(IY+10)           ; ...and set its Can Fall Flag
  RES 4,(IX+9)            ; Reset Berk's Carrying Something Flag
  BIT 0,(IX+11)           ; If Berk's Walking Right Flag is reset...
  JR Z,36339              ; ...then skip ahead to 36339
  INC (IY+7)              ; Move dropped entity right one character...
  INC (IY+5)              ; ...
  JR 36351                ; Skip ahead to 36351
  BIT 1,(IX+11)           ; If Berk's Walking Left Flag is reset...
  JR Z,36351              ; ...then skip ahead to 36351
  DEC (IY+7)              ; Move dropped entity left one character...
  DEC (IY+5)              ; ...
  LD A,(IY+5)             ; If entity at IY has the x-coordinate of its left
                          ; side less than 100...
  CP 100                  ; ...
  JR C,36331              ; ...then move right until left x-coordinate is 100
  LD A,(34235)            ; Load A with width of current room (chars) + 99
  CP (IY+7)               ; If entity at IY has the x-coordinate of its right
                          ; side greater than the width of the current room...
  JR C,36345              ; ...then move right until left x-coordinate is less
                          ; than room width
  RET                     ; Return

; If Berk is Neither Facing into the Screen nor Walking then Exit Calling
; Routine and Have Berk Turn into Screen
;
; Used by the routine at 35735. Input:  IX  Address of complex state data
; (current level) for Berk
  BIT 1,(IX+9)            ; If Berk's Facing Into Screen Flag is set...
  RET NZ                  ; ...then return
  LD A,(IX+11)            ; If either of Berk's Walking Left or Walking Right
                          ; flags is set...
  AND 3                   ; ...
  RET NZ                  ; ...then return
  POP BC                  ; Remove top value from stack (i.e. return address to
                          ; routine that called this routine)
  LD HL,35105             ; Point HL at script data for Berk turning (facing
                          ; out of screen to facing into screen)...
  JP 48098                ; ...and execute

; Script Routine (59) Have Berk Interact Appropriately with a Door Behind Him
; Output: BC  Address of script data to execute upon arrival of new level
  LD BC,35113             ; Load BC with address of script data for Berk facing
                          ; into screen, ready to respond to control input
  JR 36393                ; Have Berk interact appropriately with a door

; Script Routine (58) Have Berk Interact Appropriately with a Door in Front of
; Him Input:  BC  (entry at 36393 only) Address of script data to execute upon
; arrival of new level
  LD BC,35081             ; Load BC with address of script data for Berk facing
                          ; out of screen, ready to respond to control input
; This entry point is used by the routine at 36385.
  LD (34266),BC           ; Store script data address in BC at 34266
  LD A,(34208)            ; Load E with Game Flags...
  LD E,A                  ; ...
  LD A,(34221)            ; Load A with class of entity currently held by
                          ; Berk...
  CP 17                   ; ... and if this is not 17 (Key)...
  JR NZ,36429             ; ...then skip ahead to 36429
; Berk is holding a key
  LD A,7                  ; Set door colour to 7 (white, i.e. unlocked)...
  LD (50712),A            ; ...
  CALL 36296              ; Make Berk drop the key and load IY with its complex
                          ; state data address
  LD (IY+1),0             ; Set depth of key to 0 (i.e. out of display)
  SET 4,E                 ; Set Level Exit Door Unlocked Flag...
  LD A,E                  ; ...
  LD (34208),A            ; ...
  JP 48096                ; Advance HL to next script instruction and execute
; Berk is not holding a key
  BIT 4,E                 ; If Level Exit Door Unlocked Flag is reset...
  JR Z,36462              ; ...then skip ahead to 36462
  LD D,A                  ; Load D with class of entity currently held by Berk
  LD A,(34207)            ; Set Zero Flag if current level is Level 4...
  CP 4                    ; ...
  LD A,D                  ; Load A with class of entity currently held by Berk
  JR NZ,36446             ; If Zero Flag is not set (i.e. we are not on Level
                          ; 4) then skip ahead to 36446
; Level 4
  CP 19                   ; Set Zero Flag if class of entity currently held by
                          ; Berk is 19 (Boni)
  JR 36448                ; Skip ahead to 36448
; Not Level 4
  CP 18                   ; Set Zero Flag if class of entity currently held by
                          ; Berk is 18 (Drutt)
  JR NZ,36462             ; If Zero Flag is not set (i.e. Berk is not holding
                          ; Drutt on Levels 1-3 or Boni on Level 4) then skip
                          ; ahead to 36462
; Berk is holding the correct character
  CALL 48417              ; Remove Berk's current power and reset sweet /
                          ; mushroom / edible eyes / sausage to its original
                          ; state
  CALL 36638              ; Advance to next level and if back to Level 1 then
                          ; exit this routine and make Berk start falling
; New level is not Level 1
  LD HL,(34266)           ; Load HL with script data address stored at 34266...
  JP 48098                ; ...and execute
; Door is locked or Berk is not holding the correct character
  CALL 36296              ; Make Berk drop the entity he is holding and load IY
                          ; with its complex state data address
  CALL 53667              ; Set "Berk Has Been Killed" Flag
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (56) Give Berk Power Corresponding to Entity Eaten Input:  IX
; Address of complex state data (current level) for Berk
  CALL 48417              ; Remove Berk's current power and reset sweet /
                          ; mushroom / edible eyes / sausage to its original
                          ; state
  LD A,(34221)            ; Set current power value to class of entity
                          ; currently held by Berk...
  LD (34220),A            ; ...
  XOR A                   ; Set class of entity held by Berk to zero (i.e.
                          ; none)...
  LD (34221),A            ; ...
  LD (34224),A            ; Set number of elapsed game-cycles in current block
                          ; to zero
  RES 4,(IX+9)            ; Reset Berk's Carrying Something Flag
  LD IY,(34260)           ; Load IY with address of complex state data for
                          ; entity last held by Berk...
  LD (IY+1),A             ; ...and set its depth to zero (i.e. outside room)
  LD A,(IY+10)            ; Initialise remaining duration of power to value
                          ; encoded entity's complex state data (bits 0-4)...
  AND 31                  ; ...
  LD (34225),A            ; ...
  LD A,(34220)            ; If Berk's current power is not floating (Level
                          ; 3)...
  CP 10                   ; ...
  JP NZ,48096             ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
; Power is floating
  LD (IX+12),12           ; Set distance Berk will be pushed by Drutt while
                          ; floating to 12
  SET 7,(IX+9)            ; Set Berk's Moving Upwards Flag
  LD (IX+11),240          ; Reset Berk's Walking Right, Walking Left, Unused
                          ; (11,2) and Unused (11,3) flags, and set his
                          ; Impassable Leftwards, Impassable Rightwards,
                          ; Interaction (11,6) and Interaction (11,7) flags
  SET 7,(IX+8)            ; Set bit 7 of Berk's class value (i.e. set "Spans
                          ; Full Depth" Flag)
  INC (IX+6)              ; Increase y-coordinate of Berk's bottom edge by two
                          ; characters...
  INC (IX+6)              ; ...
  LD HL,35515             ; Point HL at script data for Berk gaining floating
                          ; power...
  JP 48098                ; ...and execute

; Update State of Berk (Floating Power Active)
;
; Used by the routine at 35735. Input:  IX  Address of complex state data
; (current level) for Berk
  CALL 54768              ; Check entity at IX for collision with another
                          ; entity at same depth whose Interaction (11,6) Flag
                          ; is set...
  CP 130                  ; ...and if collision was with entity of class 130
                          ; (causes Berk and Drutt to bounce off or bang
                          ; head)...
  JR Z,36558              ; ...then skip ahead to 36558
; No collision with entity of class 130
  DEC (IX+4)              ; Move Berk up one character...
  DEC (IX+6)              ; ...
  CALL 55433              ; Change Berk's room up one if appropriate
  BIT 1,(IX+11)           ; If Berk's Walking Left Flag is set...
  JR NZ,36587             ; ...then skip ahead to 36587
  BIT 0,(IX+11)           ; If Berk's Walking Right Flag is set...
  JR NZ,36576             ; ...then skip ahead to 36576
  CALL 48388              ; Decrease remaining time for current power and if
                          ; zero, exit this routine and run script data for
                          ; removal of power
  JP 48096                ; Advance HL to next script instruction and execute
; Berk's Walking Right Flag is set (i.e. Drutt has pushed Berk right)
  INC (IX+5)              ; Move Berk's left and right sides right by one
                          ; character...
  INC (IX+7)              ; ...
  CALL 54313              ; Move Berk at IX into room to the right, if
                          ; appropriate
  JR 36596                ; Skip ahead to 36596
; Berk's Walking Left Flag is set (i.e. Drutt has pushed Berk left)
  DEC (IX+5)              ; Move Berk's left and right sides left by one
                          ; character...
  DEC (IX+7)              ; ...
  CALL 54348              ; Move Berk at IX into room to the left, if
                          ; appropriate
  DEC (IX+12)             ; Decrease remaining horizontal distance from Drutt's
                          ; push...
  JP NZ,48096             ; ...and if not zero then jump to 48096 (advance HL
                          ; to next script instruction and execute)
  LD A,1                  ; Set remaining power duration to 1...
  LD (34225),A            ; ...
  JP 48212                ; Reset Berk's Walking Left and Walking Right flags,
                          ; advance HL to next script instruction and execute

; Script Routine (57) Cycle Attributes (Full-Screen), Clear Display Buffers and
; Paint Red Areas Outside Current Room
  CALL 36616              ; Cycle attributes (full-screen), clear display
                          ; buffers and paint red areas outside current room
  JP 48096                ; Advance HL to next script instruction and execute

; Cycle Attributes (Full-Screen), Clear Display Buffers and Paint Red Areas
; Outside Current Room
;
; Used by the routines at 36610, 39584 and 39760.
  PUSH HL                 ; Store HL
  CALL 53581              ; Cycle Attributes (Full-Screen) and Clear Display
                          ; Buffers
  CALL 53887              ; Paint red areas outside accessible areas of current
                          ; character's current room
  POP HL                  ; Restore HL
  RET                     ; Return

; State Data for Drutt Upon Returning to Level 1
;
; After completing Level 4, the data here is written into Drutt's slot in Level
; 1's State Data for Complex Entities block (43333). This ensures that Drutt
; follows Berk and Boni through the final door.
  DEFB 10,1,193,204,30,119,30,119,18,0,192,192,2

; Advance to Next Level and if Back to Level 1 then Exit Calling Routine and
; Make Berk Start Falling
;
; Used by the routine at 36390.
  LD A,(34208)            ; Set Update Scores and Display Flag...
  SET 5,A                 ; ...
  LD (34208),A            ; ...
  LD IY,(34256)           ; Load IY with address of complex state data for Door
                          ; just interacted with
  LD A,(IY+9)             ; Load A with destination level from Door's state
                          ; data...
  LD (34207),A            ; ...and set current level to this value
  CP 1                    ; If destination level is not Level 1...
  JR NZ,36725             ; ...then skip ahead to 36725
; Destination level is Level 1 (i.e. Level 4 completed)
  CALL 36753              ; Load IX with address of Berk's complex state data
                          ; and set his horizontal position to match Level 1's
                          ; entry door
  SET 2,(IX+10)           ; Set "Back to Level 1" Flag
  LD (IX+0),10            ; Set Berk's room to 10
  LD (IX+4),103           ; Set y-coordinate of Berk's top edge to 103
  LD (IX+6),109           ; Set y-coordinate of Berk's bottom edge to 109
  LD IY,43606             ; Load IY with address of Boni's entry in Level 1's
                          ; State Data for Complex Entities...
  LD (34256),IY           ; ...and store at 34256
  CALL 48850              ; Have Berk hold Boni, and position him appropriately
                          ; between Berk's hands
  LD (IY+1),1             ; Set Boni's depth to 1
  LD (IY+0),10            ; Set Boni's room to 10
  CALL 36296              ; Make Berk drop the entity he is holding and load IY
                          ; with its complex state data address
  CALL 55516              ; Set Berk's Can Fall Flag and set his initial
                          ; velocity factor to 2
  CALL 36739              ; Lock Level 1's exit door and cycle attributes
                          ; (full-screen)
  POP BC                  ; Remove top value from stack (i.e. return address to
                          ; routine that called this routine)
  LD HL,36625             ; Overwrite Drutt's entry in Level 1's State Data for
                          ; Complex Entities with data at 36625...
  LD DE,43671             ; ...
  LD BC,13                ; ...
  LDIR                    ; ...
  LD HL,35359             ; Point HL at script data for Berk starting to fall
                          ; downwards...
  JP 48098                ; ...and execute
; Destination level is not Level 1
  CALL 36753              ; Set Berk's horizontal position to match Level 1's
                          ; entry door
  LD IY,(34242)           ; Load IY with address of current level's complex
                          ; state data for Drutt...
  LD (34256),IY           ; ...and store at 34256
  CALL 48850              ; Have Berk hold Drutt, and position him
                          ; appropriately between Berk's hands
  LD HL,34208             ; Reset Level Exit Door Unlocked Flag...
  RES 4,(HL)              ; ...
  LD A,5                  ; Set door colour to 5 (cyan, i.e. locked)...
  LD (50712),A            ; ...
  CALL 36616              ; Cycle attributes (full-screen), clear display
                          ; buffers and paint red areas outside current room
  RET                     ; Return

; Set Berk's Horizontal Position to Match Level 1's Entry Door
;
; Used by the routine at 36638.
  CALL 34864              ; Copy start addresses of current level's data blocks
                          ; to 34236 and clean up old data
  LD A,33                 ; Load IY with address of complex state data for
                          ; first entity that has class of 33 (Entry Door)...
  CALL 54019              ; ...
  LD IX,(34240)           ; Load IX with start address of current level's
                          ; complex state data for Berk
  LD A,(IY+5)             ; Load A with x-coordinate of left of Entry Door...
  INC A                   ; ...and add one
  LD (IX+5),A             ; Adjust Berk's horizontal position so that his left
                          ; side is at coordinate in A...
  ADD A,5                 ; ...and his right side is 5 characters to the right
                          ; of this...
  LD (IX+7),A             ; ...
  RET                     ; Return

; Initialise Script Data Positions for Flying Skeleton Creature and Bat (Level
; 1)
;
; Used by the routine at 34751.
  LD HL,36803             ; Load HL with start address of script data for
                          ; Boni's kidnap...
  LD (36801),HL           ; ...and store this as the current script data
                          ; position at 36801
  LD HL,37018             ; Load HL with start address of script data for Bat
                          ; (not attacking)...
  LD (37016),HL           ; ...and store this as the current script data
                          ; position at 37016
  RET                     ; Return

; Update States of All Level 1 Entities
;
; Used by the routine at 34438.
  CALL 36887              ; Execute script data for Boni's kidnap and handle
                          ; Trap Door opening and closing
  CALL 37062              ; Update state of Bat (Level 1) and store current
                          ; position in script data
  CALL 37586              ; Update states of the Spiders (Level 1) and store
                          ; current positions in script data
  RET                     ; Return

