  DEFB 114,200            ; 51314 (Flying Skeleton Creature, animated)
  DEFB 2,0                ; Move creature left one character
  DEFB 26,0               ; End loop (2)
  DEFB 25,0,10,0          ; Start loop (2) for 10 iterations
