  DEFB 26,0               ; End loop (2)
  DEFB 25,0,4,0           ; Start loop (2) for 4 iterations
  DEFB 114,200            ; 51314 (Flying Skeleton Creature, animated)
  DEFB 114,200            ; 51314 (Flying Skeleton Creature, animated)
  DEFB 114,200            ; 51314 (Flying Skeleton Creature, animated)
  DEFB 114,200            ; 51314 (Flying Skeleton Creature, animated)
  DEFB 34,0               ; Move creature up one character
