; Execute Script Data for Boni's Kidnap and Handle Trap Door Opening and
; Closing
;
; Used by the routine at 36791.
  LD IX,43619             ; Load IX with address of complex state data for
                          ; Flying Skeleton Creature
  LD A,(43628)            ; If Berk and Drutt Through Trap Door Flag is set...
  BIT 3,A                 ; ...
  RET NZ                  ; ...then return
  BIT 2,A                 ; If Trap Door Opened Flag is set...
  JR NZ,36966             ; ...then jump to 36966 (close the Trap Door if Berk
                          ; is not in room 1 and Drutt is in room 4)
  BIT 1,A                 ; If creature's Inactive Flag is set...
  JR NZ,36921             ; ...then jump to 36921 (open the Trap Door if Berk
                          ; is near the left side of the Trap Door room)
  LD HL,(36801)           ; Load current position in script data for Boni's
                          ; kidnap from 36801 into HL...
  LD (34277),HL           ; ...and store at 34277 as position in script
                          ; currently running
  CALL 36947              ; Advance HL to next script instruction and start
                          ; executing
  LD HL,(34277)           ; Store address (current position in script data)
                          ; stored at 34277...
  LD (36801),HL           ; ...at 36801 as current position in script data for
                          ; Boni's kidnap
  RET                     ; Return

; Open Trap Door if Berk is Near the Left Side of the Trap Door Room
;
; Used by the routine at 36887. Input:  IX  Address of complex state data for
; Flying Skeleton Creature (Level 1)
  LD IY,43593             ; Load IY with address of complex state data for Berk
                          ; (Level 1)
  LD A,(IY+5)             ; If x-coordinate of Berk's left side is 104 or
                          ; greater...
  CP 104                  ; ...
  RET NC                  ; ...then return
  SET 2,(IX+9)            ; Set Trap Door Opened Flag
  XOR A                   ; Set room of "Closed Trap Door" to 0 (i.e. remove
                          ; from Trap Door Room)...
  LD (43188),A            ; ...
  INC A                   ; Increase A to 1 (index of Trap Door Room)...
  LD (43437),A            ; ...and set this as the current room of "Open Trap
                          ; Door"...
  LD (43450),A            ; ...and marker (preventing Berk and Drutt passing
                          ; door lid)
  RET                     ; Return

; Advance HL to Next Script Instruction and Start Executing
;
; Used by the routine at 36887.
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (36) Remove Boni from Level 1
  XOR A                   ; Set Boni's room (Level 1) to zero...
  LD (43606),A            ; ...
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (37) Remove Flying Skeleton Creature from Level 1, and
; Terminate Script Processing Input:  IX Address of complex state data for an
; entity
  XOR A                   ; Set current room of Flying Skeleton Creature (Level
                          ; 1) to zero...
  LD (43619),A            ; ...
  SET 1,(IX+9)            ; Set Flying Skeleton Creature's Inactive Flag
  RET                     ; Return (i.e. terminate further script processing)

; Close the Trap Door if Berk is Not in Room 1 and Drutt is in Room 4 (Level 1)
;
; See bugs.
  LD A,(43593)            ; If Berk's current room (Level 1) is 1 (i.e. Trap
                          ; Door Room)...
  CP 1                    ; ...
  RET Z                   ; ...then return
  LD A,(43671)            ; If Drutt's current room is not 4 (room at bottom of
                          ; Trap Door Shaft)...
  CP 4                    ; ...
  RET NZ                  ; ...then return
  SET 3,(IX+9)            ; Set Berk and Drutt Through Trap Door Flag
  JR 36996                ; Close the Trap Door and return

; Script Routine (38) Close the Trap Door
  CALL 36996              ; Close the Trap Door
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (39) Open the Trap Door
  CALL 37004              ; Open the Trap Door
  JP 48096                ; Advance HL to next script instruction and execute

; Close the Trap Door
;
; Used by the routines at 36966 and 36984.
  LD A,1                  ; Set room of "Closed Trap Door" to 1 (i.e. Trap Door
                          ; Room)...
  LD (43188),A            ; ...
  DEC A                   ; Decrease A to zero
  JR 37009                ; Set room of "Open Trap Door" to 0

; Open the Trap Door
;
; Used by the routine at 36990.
  XOR A                   ; Set room of "Closed Trap Door" to 0 (i.e. remove
                          ; from Trap Door Room)...
  LD (43188),A            ; ...
  INC A                   ; Increase A to 1 (index of Trap Door Room)
; This entry point is used by the routine at 36996.
  LD (43437),A            ; Set value in A as the current room of "Open Trap
                          ; Door"...
  LD (43450),A            ; ...and marker (preventing Berk and Drutt passing
                          ; door lid)
  RET                     ; Return

