; Update State of Bat (Level 1) and Store Current Position in Script Data
;
; Used by the routine at 36791.
  LD IX,43463             ; Point IX at position data for Bat (Level 1)
  CALL 53848              ; Store room size data for Bat's room
  LD HL,(37016)           ; Load current position in Bat's script data from
                          ; 37016 into HL...
  LD (34277),HL           ; ...and store at 34277 as position in script
                          ; currently running
  CALL 37085              ; Update state of Bat
  LD HL,(34277)           ; Store address (current position in script data)
                          ; stored at 34277...
  LD (37016),HL           ; ...at 37016 as current position in Bat's script
                          ; data
  RET                     ; Return

; Update State of Bat (Level 1)
;
; Used by the routine at 37062. Input:  IX  (always 43463, entry in Level 1
; complex state data for Bat) HL Current position in Bat's script data
  CALL 54768              ; Check entity at IX for collision with another
                          ; entity at same depth whose Interaction (11,6) Flag
                          ; is set...
  JR C,37104              ; ...and if no collision occurred, then skip ahead to
                          ; 37104
  CP 31                   ; If collision was not with entity of class 31
                          ; (Berk)...
  JR NZ,37100             ; ...then skip ahead to 37100
  CALL 53667              ; Set "Berk Has Been Killed" Flag
  JP 48096                ; Advance HL to next script instruction and execute
  CP 18                   ; If collision was with entity of class 18 (Drutt)...
  JR Z,37111              ; ...then skip ahead to 37111
  CALL 54890              ; Check entity at IX for collision with another
                          ; entity (in reverse order) at next depth level into
                          ; screen whose Interaction (11,7) Flag is set...
  CP 18                   ; ...and if collision was not with entity of class 18
                          ; (Drutt)...
  JR NZ,37128             ; ...then skip ahead to 37128
  BIT 6,(IY+10)           ; If Drutt's Can Fall Flag is set...
  JR NZ,37128             ; ...then skip ahead to 37128
  SET 6,(IY+10)           ; Set Drutt's Can Fall Flag
  LD (IY+12),2            ; Set Drutt's Velocity Factor to 2
  JP 48096                ; Advance HL to next script instruction and execute
  BIT 0,(IX+9)            ; If Bat's Paralysed Flag is set...
  JP NZ,48096             ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  LD A,(34208)            ; If Drutt Mode Flag is set...
  BIT 0,A                 ; ...
  JR NZ,37148             ; ...then skip ahead to 37148
  LD IY,(34240)           ; Load IY with address of current level's complex
                          ; state data for Berk
  JR 37152                ; Skip ahead to 37152
  LD IY,(34242)           ; Load IY with address of current level's complex
                          ; state data for Drutt
; At this point, IY points to the complex state data entry for the current
; character.
  LD A,(IY+0)             ; If current character's current room is not the same
                          ; as the Bat's...
  CP (IX+0)               ; ...
  JP NZ,48096             ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  LD A,(IY+7)             ; If the current character's right side...
  CP (IX+5)               ; ...is to the left of the Bat's left side...
  JR C,37194              ; ...then skip ahead to 37194
  LD A,(IX+7)             ; If the Bat's right side...
  CP (IY+5)               ; ...is to the left of the current character's left
                          ; side...
  JR C,37183              ; ...then skip ahead to 37183
  LD HL,37024             ; Point HL at script data for Bat attacking...
  JP 48098                ; ...and execute
  LD A,(IX+7)             ; If the x-coordinate of the Bat's right side is less
                          ; than 130...
  CP 130                  ; ...
  JP C,48615              ; ...then move Bat right by one character
  JP 48096                ; Advance HL to next script instruction and execute
  LD A,101                ; If the x-coordinate of the Bat's left side is
                          ; greater than 101...
  CP (IX+5)               ; ...
  JP C,48660              ; ...then move Bat left by one character
  JP 48096                ; Advance HL to next script instruction and execute

