; Table of Current Positions in Spiders' Script Data
  DEFW 37792              ; Spider 1
  DEFW 37792              ; Spider 2
  DEFW 37792              ; Spider 3

; Update the States of the Spiders (Level 1) and Store Current Positions in
; Script Data
;
; Used by the routine at 36791.
  LD IX,43749             ; Load IX with address of complex state data for
                          ; Spider 1 (Level 1)
  LD IY,37580             ; Load IY with start address of Table of Current
                          ; Positions in Spiders' Script Data
  LD B,3                  ; Load B with 3 as there are 3 spiders
  LD L,(IY+0)             ; Load HL with current position in script data for
                          ; current spider...
  LD H,(IY+1)             ; ...
  LD (34277),HL           ; ...and store at 34277 as position in script
                          ; currently running
  PUSH IX                 ; Store IX
  PUSH IY                 ; Store IY
  PUSH BC                 ; Store BC
  CALL 37639              ; Update the state of the current spider (Level 1)
  POP BC                  ; Restore BC
  POP IY                  ; Restore IY
  POP IX                  ; Restore IX
  LD HL,(34277)           ; Store address (current position in script data for
                          ; current spider) stored at 34277...
  LD (IY+0),L             ; ...in table at 37580 as current position in this
                          ; spider's script data...
  LD (IY+1),H             ; ...
  INC IY                  ; Advance IY to next entry in table (i.e. position in
                          ; next spider's script data)...
  INC IY                  ; ...
  LD DE,13                ; Advance IX by 13 bytes (i.e. to entry for next
                          ; spider)...
  ADD IX,DE               ; ...
  DJNZ 37596              ; Decrease B (remaining number of spiders to process)
                          ; and loop back to 37596
  RET                     ; Return

; Update the State of a Spider (Level 1)
;
; Used by the routine at 37586. Input:  IX  Address of complex state data for a
; (Level 1) spider (43749, 43762 or 43775)
  LD A,(34208)            ; If "Reset Spiders to Initial State" Flag is
                          ; reset...
  BIT 3,A                 ; ...
  JR Z,37662              ; ...then skip ahead to 37662
  LD A,27                 ; Reset complex state data for right-hand spider to
                          ; that stored in Initial-State Table...
  CALL 53987              ; ...
  LD A,28                 ; Reset complex state data for middle spider to that
                          ; stored in Initial-State Table...
  CALL 53987              ; ...
  LD A,29                 ; Reset complex state data for left-hand spider to
                          ; that stored in Initial-State Table...
  CALL 53987              ; ...
  RET                     ; Return
  BIT 2,A                 ; If Berk Has Been Killed Flag is set...
  RET NZ                  ; ...then return
  CALL 54764              ; Check entity at IX for collision with another
                          ; entity at next depth level out of screen whose
                          ; Interaction (11,6) Flag is set...
  CP 31                   ; ...and if collision was not with entity of class 31
                          ; (Berk)...
  JR NZ,37685             ; ...then skip ahead to 37685
  CALL 53667              ; Set "Berk Has Been Killed" Flag
  LD A,(34223)            ; Increase count of number of times a spider has
                          ; killed Berk...
  INC A                   ; ...
  LD (34223),A            ; ...
  JP 48096                ; Advance HL to next script instruction and execute
  LD IY,(34240)           ; Load IY with address of current level's complex
                          ; state data for Berk
  BIT 0,(IX+9)            ; If spider's Must Process Current Script Data Flag
                          ; is set...
  JP NZ,48096             ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  LD A,(IX+0)             ; If the spider and Berk are in different rooms...
  CP (IY+0)               ; ...
  RET NZ                  ; ...then return
  LD A,(IX+7)             ; Load A with the x-coordinate of the spider's right
                          ; side...
  ADD A,4                 ; ...plus 4...
  CP (IY+5)               ; ...and if the x-coordinate of Berk's left side is
                          ; greater than this...
  RET C                   ; ...then return
  LD HL,37800             ; Point HL at script data for spider moving down...
  JP 48098                ; ...and execute

; Script Routine (41) Move Spider Up One Character and, if Home, Reset its
; Timer and Make it Wait Input:  IX Address of complex state data for an entity
; Output: HL  Address of next script instruction to execute
  LD A,(IX+6)             ; If y-coordinate of bottom of entity IX (spider) is
                          ; not 106...
  CP 106                  ; ...
  JP NZ,48541             ; ...then move entity up one character and return
  LD C,20                 ; Load C with 20
  LD A,(IX+8)             ; If entity class is not 27 (right-most spider, Level
                          ; 1)...
  CP 27                   ; ...
  JR NZ,37744             ; ...then skip ahead to 37744
; The following code affects the behaviour of the right-most spider depending
; upon how many times Berk has been killed by a spider. See (trivia) and
; (pokes).
  LD A,(34223)            ; Load number of times Berk has been killed by a
                          ; spider into A...
  SRL A                   ; ...and divide by four, discarding remainder...
  SRL A                   ; ...
  ADD A,C                 ; Add this value to C, in C...
  LD C,A                  ; ...
  LD (IX+12),C            ; Load spider's timer with this value
  LD HL,37792             ; Point HL at script data for spider waiting...
  JP 48098                ; ...and execute

; Script Routine (42) Decrease Remaining Time Until Spider Next Descends and if
; Zero, Start Descent Input:  IX Address of complex state data for an entity
; Output: HL  Address of next script instruction to execute
  BIT 0,(IX+9)            ; If spider's Must Process Current Script Data Flag
                          ; is reset...
  JP Z,48096              ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  LD A,(IX+12)            ; If Spider's timer is zero...
  OR A                    ; ...
  JR Z,37772              ; ...then skip ahead to 37772
  DEC (IX+12)             ; Decrease remaining time on spider's timer
  JP 48096                ; Advance HL to next script instruction and execute
  LD HL,37800             ; Point HL at script data for spider moving down...
  JP 48098                ; ...and execute

; Script Routine (40) Move Spider Down One Character, and if at Bottom, Advance
; it to Bounce / Climb Up Mode Input: IX  Address of complex state data for an
; entity Output: HL  Address of next script instruction to execute
  LD A,(IX+6)             ; If entity's bottom y-coordinate is less than 119...
  CP 119                  ; ...
  JP C,48567              ; ...then move entity down one character and process
                          ; next script data
  LD HL,37816             ; Point HL at script data for bounce / climb up
                          ; mode...
  JP 48098                ; ...and execute

