; Update States of All Level 2 Entities
;
; Used by the routine at 34438.
  CALL 38592              ; Update states of stalactites (Level 2)
  CALL 38480              ; Update states of apebeasts (Level 2) and store
                          ; current positions in script data
  CALL 38054              ; Update state of Bubo (Level 2) and store current
                          ; position in script data
  CALL 38219              ; Update state of Bubo's projectile
  RET                     ; Return

; Current Position in Bubo's Script Data
  DEFW 38024

; Script Data Bubo
  DEFB 9,0                ; Reset Must Process Current Script Data Flag
  DEFB 84,152             ; 38996 (Bubo, normal, animated)
  DEFB 1,0,136,148        ; Jump to 38024
; Firing
  DEFB 8,0                ; Set Must Process Current Script Data Flag
  DEFB 25,0,4,0           ; Start loop (2) for 4 iterations
  DEFB 126,152            ; 39038 (Bubo, pre/post firing)
  DEFB 26,0               ; End loop (2)
  DEFB 158,152            ; 39070 (Bubo, squashed, firing)
  DEFB 194,152            ; 39106 (Bubo, squashed, firing, with explosion)
  DEFB 61,0               ; Fire Bubo's projectile
  DEFB 126,152            ; 39038 (Bubo, pre/post firing)
  DEFB 1,0,136,148        ; Jump to 38024

; Update State of Bubo (Level 2) and Store Current Position in Script Data
;
; Used by the routine at 38009.
  LD IX,44227             ; Load IX with address of complex state data for Bubo
                          ; (Level 2)
  LD HL,(38022)           ; Load HL with current position in Bubo's script data
                          ; from 38022...
  LD (34277),HL           ; ...and store at 34277 as position in script
                          ; currently running
  CALL 38074              ; Update state of Bubo
  LD HL,(34277)           ; Store address (current position in script data)
                          ; stored at 34277...
  LD (38022),HL           ; ...at 38022 as current position in Bubo's script
                          ; data
  RET                     ; Return

; Update State of Bubo
;
; Used by the routine at 38054. Input:  IX  Address of complex state data for
; Bubo (Level 2)
  BIT 3,(IX+9)            ; If Bubo's Harmless Flag is set...
  JR NZ,38101             ; ...then skip ahead to 38101
  LD A,(34220)            ; If Berk's current power is not immunity to Bubo
                          ; (Level 2)...
  CP 9                    ; ...
  JR NZ,38093             ; ...then skip ahead to 38093
  SET 3,(IX+9)            ; Set Bubo's Harmless Flag
  JR 38101                ; Skip ahead to 38101
  CALL 54768              ; Check entity at IX for collision with another
                          ; entity at same depth whose Interaction (11,6) Flag
                          ; is set...
  CP 31                   ; ...and if collision was with entity of class 31
                          ; (Berk)...
  CALL Z,53667            ; ...then set "Berk Has Been Killed" Flag
  LD IY,44214             ; Load IY with address of complex state data for
                          ; Bubo's Projectile (Level 2)
  BIT 0,(IX+9)            ; If Bubo's Must Process Current Script Data Flag is
                          ; set (Bubo firing)...
  JP NZ,48096             ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  BIT 1,(IY+9)            ; If Projectile's Fired Flag is set...
  JP NZ,48096             ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  BIT 5,(IX+10)           ; If Bubo is not being carried...
  JR Z,38132              ; ...then skip ahead to 38132
  SET 2,(IX+9)            ; Set Bubo's Waiting to Fire Flag
  JP 48096                ; Advance HL to next script instruction and execute
; The code block below is only entered if Bubo's Must Process Current Script
; Data Flag is reset (i.e. he is not firing), the Projectile's Fired Flag is
; reset and Bubo is not being carried.
  LD A,(IX+1)             ; If Bubo has a depth of 2...
  CP 2                    ; ...
  JP Z,48096              ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  BIT 2,(IX+9)            ; If Bubo's Waiting to Fire Flag is set, i.e. he has
                          ; just been dropped...
  JR NZ,38155             ; ...then skip ahead to 38155 (make Bubo fire)
  LD A,60                 ; Load A with a random number, 0-59...
  CALL 54222              ; ...
  OR A                    ; ...and if this is not zero (59 in 60 chance)...
  JP NZ,48096             ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  RES 2,(IX+9)            ; Reset Bubo's Waiting to Fire Flag
  LD HL,38032             ; Point HL at script data for Bubo firing...
  JP 48098                ; ...and execute

; Script Routine (61) Fire Bubo's Projectile
;
; Note that Bubo normally can't fire when being carried (see instructions at
; 38119), however if he starts to fire immediately before being picked up, then
; his Being Carried Flag will be set by the time execution reaches this
; routine. Input:  IX  Address of complex state data for Bubo (Level 2) IY
; Address of complex state data for Bubo's projectile
  SET 1,(IY+9)            ; Set projectile's Fired Flag
  BIT 5,(IX+10)           ; If Bubo is being carried...
  JR NZ,38181             ; ...then skip ahead to 38181
  LD (IY+12),251          ; Set projectile's Velocity Factor to -5
  JR 38185                ; Skip ahead to 38185
  LD (IY+12),246          ; Set projectile's Velocity Factor to -10
  LD A,(IX+5)             ; Set projectile's x-coordinate to one more than
                          ; Bubo's...
  INC A                   ; ...
  LD (IY+5),A             ; ...
  LD (IY+7),A             ; ...
  LD A,(IX+4)             ; Set projectile's y-coordinate to be three less than
                          ; Bubo's...
  SUB 3                   ; ...
  LD (IY+4),A             ; ...
  LD (IY+6),A             ; ...
  LD A,(IX+0)             ; Set projectile's room to be same as Bubo's...
  LD (IY+0),A             ; ...
  LD (IY+1),1             ; Set projectile's depth to zero
  JP 48096                ; Advance HL to next script instruction and execute

; Update State of Bubo's Projectile
;
; Used by the routine at 38009.
  LD IX,44214             ; Load IX with address of complex state data for
                          ; Bubo's Projectile (Level 2)
  BIT 1,(IX+9)            ; If projectile's Fired Flag is reset...
  RET Z                   ; ...then return
  BIT 2,(IX+9)            ; If projectile's Has Hit Target Flag is reset...
  JR Z,38252              ; ...then update position of projectile and knock key
                          ; down if appropriate
  LD BC,39131             ; Point BC at graphic layout data for Bubo's
                          ; Projectile...
  LD (IX+2),C             ; ...and set this as the Graphic Lookup Address for
                          ; the projectile's complex state data entry...
  LD (IX+3),B             ; ...
  LD (IX+9),0             ; Reset projectile's Has Hit Target Flag and Fired
                          ; Flag
  LD (IX+1),0             ; Set projectile's depth to zero
  RET                     ; Return
  LD IY,44227             ; Point IY at complex state data for Bubo (Level 2)
  LD A,(IX+12)            ; If projectile's velocity factor is not zero...
  OR A                    ; ...
  JR NZ,38267             ; ...then skip ahead to 38267
  CALL 38377              ; Start level 2 key falling if Bubo's projectile is
                          ; in place below it
  JR 38361                ; Jump to 38361 (increase velocity and handle landing
                          ; if appropriate)
  BIT 7,A                 ; If bit 7 of projectile's velocity factor is set
                          ; (i.e. negative, moving upwards)...
  JR NZ,38336             ; ...then skip ahead to 38336
  CP 6                    ; If projectile's velocity factor is less than 6...
  JR C,38277              ; ...then skip ahead to 38277
  LD A,5                  ; Load A with 5 (terminal velocity)
  LD B,A                  ; Load B with velocity value
  PUSH BC                 ; Store BC (B = remaining velocity value)
  CALL 54768              ; Check entity at IX for collision with another
                          ; entity at same depth whose Interaction (11,6) Flag
                          ; is set...
  JR C,38328              ; ...and if no collision occurred, then skip ahead to
                          ; 38328
  CP 31                   ; If collision was not with entity of class 31
                          ; (Berk)...
  JR NZ,38293             ; ...then skip ahead to 38293
  CALL 53667              ; Set "Berk Has Been Killed" Flag
  JR 38328                ; Skip ahead to 38328
  CP 25                   ; If collision was not with entity of class 25 (Green
                          ; Apebeast, Level 2)...
  JR NZ,38328             ; ...then skip ahead to 38328
  LD A,(34218)            ; Load A with current character's current room...
  CP (IX+0)               ; ...and if this is not the same as the projectile's
                          ; room...
  JR NZ,38328             ; ...then skip ahead to 38328
  LD (IY+1),0             ; Set Ape Beast's depth to zero
  LD (IY+11),0            ; Reset Ape Beast's flags
  LD BC,51483             ; Point BC at graphic layout data for Explosion
                          ; (Bubo's Projectile / Fallen Drips, Level 4)...
  LD (IX+2),C             ; ...and set this as the Graphic Lookup Address for
                          ; the projectile's complex state data entry...
  LD (IX+3),B             ; ...
  SET 2,(IX+9)            ; Set projectile's Has Hit Target Flag
  POP BC                  ; Restore BC (B = current velocity factor)
  RET                     ; Return
  CALL 38756              ; Move projectile down one character
  POP BC                  ; Restore BC (B = current velocity factor)
  DJNZ 38278              ; Decrease remaining velocity value and loop back to
                          ; 38278 if not zero
  JR 38361                ; Skip ahead to 38361 (increase velocity and handle
                          ; landing if appropriate)
; Projectile moving upwards
  NEG                     ; Multiply projectile's velocity factor by -1
  CP 6                    ; If projectile's velocity factor is now less than
                          ; 6...
  JR C,38344              ; ...then skip ahead to 38344 (change projectile's
                          ; y-coordinate based upon velocity)
  LD A,5                  ; Load A with 5 (i.e. cap velocity magnitude at 5)
  NEG                     ; Multiply value in A by -1...
  LD E,A                  ; ...and load value (capped velocity) into E
  LD A,(IX+4)             ; Decrease projectile's y-coordinate by value in E...
  ADD A,E                 ; ...
  LD (IX+4),A             ; ...
  LD A,(IX+6)             ; ...
  ADD A,E                 ; ...
  LD (IX+6),A             ; ...
  LD A,(IX+4)             ; If projectile's y-coordinate is at least 124...
  CP 124                  ; ...
  JR NC,38372             ; ...then skip ahead to 38372 (reset projectile's
                          ; Fired Flag and return)
  INC (IX+12)             ; Increase projectile's velocity factor by one
  RET                     ; Return
  RES 1,(IX+9)            ; Reset projectile's Fired Flag
  RET                     ; Return

; Start Level 2 Key Falling if Bubo's Projectile is in Place Below it
;
; Used by the routine at 38219. Input:  IX  Address of complex state data for
; Bubo's projectile (Level 2)
  LD A,(IX+0)             ; If room of projectile is not 1...
  CP 1                    ; ...
  RET NZ                  ; ...then return
  LD A,(IX+5)             ; If projectile's left-side has an x-coordinate less
                          ; than 114...
  CP 114                  ; ...
  RET C                   ; ...then return
  CP 118                  ; If projectile's left-side has an x-coordinate of
                          ; 118 or more...
  RET NC                  ; ...then return
  LD IY,44240             ; Load IY with address of complex state data for Key
                          ; (Level 2)
  LD A,(IY+0)             ; If key's room is not 2...
  CP 2                    ; ...
  RET NZ                  ; ...then return
  BIT 6,(IY+10)           ; If key's Is Falling Flag is set...
  RET NZ                  ; ...then return
  SET 6,(IY+10)           ; Set key's Is Falling Flag
  LD (IY+12),2            ; Set key's velocity factor to 2
  RET                     ; Return

