; Update States of Apebeasts (Level 2) and Store Current Positions in Script
; Data
;
; Used by the routine at 38009.
  LD IX,44162             ; Load IX with address of complex state data for
                          ; Green Apebeast 1 (Level 2)
  LD IY,38424             ; Point IY at Table of Current Positions in
                          ; Apebeasts' Script Data
