  PUSH IY                 ; Store IY
  CALL 38540              ; Update the state of the current apebeast
  POP IY                  ; Restore IY
  POP IX                  ; Restore IX
  LD HL,(34277)           ; Store address (current position in script data for
                          ; current apebeast) stored at 34277...
  LD (IY+0),L             ; ...in table at 38424 as current position in this
                          ; apebeast's script data...
  LD (IY+1),H             ; ...
  INC IY                  ; Advance IY to next entry in table (i.e. position in
                          ; next apebeast's script data)...
  INC IY                  ; ...
  LD DE,13                ; Advance IX by 13 bytes (i.e. to entry for next
                          ; apebeast)...
  ADD IX,DE               ; ...
  LD A,(IX+8)             ; If class of this next entry is 25 (i.e.
                          ; Apebeast)...
  CP 25                   ; ...
  JR Z,38488              ; ...then loop back to 38488
  RET                     ; Return

; Update State of an Apebeast
;
; Used by the routine at 38480.
  CALL 54768              ; Check entity at IX for collision with another
                          ; entity at same depth whose Interaction (11,6) Flag
                          ; is set...
  JP C,48096              ; ...and if no collision occurred, then jump to 48096
                          ; (advance HL to next script instruction and execute)
  CP 31                   ; If collision was with entity of class 31 (Berk)...
  CALL Z,53667            ; ...then set "Berk Has Been Killed" Flag
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (60) Check Position of Apebeast and Turn If Appropriate Input:
; IX  Address of complex state data for an entity Output: HL  Address of next
; script instruction to execute
  BIT 0,(IX+11)           ; If Apebeast's Walking Right Flag is set...
  JR NZ,38575             ; ...then skip ahead to 38575
; Apebeast walking left
  LD A,(IX+12)            ; If minimum allowed x-coordinate of Apebeast...
  CP (IX+5)               ; ...is less than x-coordinate of left edge of
                          ; Apebeast...
  JP C,48096              ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  LD HL,38432             ; Point HL at script data for Apebeast walking
                          ; right...
  JP 48098                ; ...and execute
; Apebeast walking right
  LD A,(IX+12)            ; If minimum allowed x-coordinate of Apebeast...
  ADD A,13                ; ...plus 13...
  CP (IX+7)               ; ...is equal to or greater than x-coordinate of
                          ; right edge of Apebeast...
  JP NC,48096             ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  LD HL,38450             ; Point HL at script data for Apebeast walking
                          ; left...
  JP 48098                ; ...and execute

; Update States of Stalactites (Level 2)
;
; Used by the routine at 38009.
  LD IX,44305             ; Load IX with address of complex state data for
                          ; first of seven falling stalactites (Level 2)
  LD A,(IX+8)             ; If current entity class is not 34 (Stalactite,
                          ; Level 2)...
  CP 34                   ; ...
  RET NZ                  ; ...then return
  LD A,(IX+12)            ; If velocity factor of stalactite is not zero (i.e.
                          ; it is falling)...
  OR A                    ; ...
  JR NZ,38635             ; ...then skip ahead to 38635
  LD A,40                 ; Load A with a random number, 0-39...
  CALL 54222              ; ...
  OR A                    ; ...and if this is not zero (39 in 40 chance)...
  JP NZ,38748             ; ...then advance IX to next entry in complex state
                          ; data and loop back to 38596
  CALL 38756              ; Move stalactite down one character and load A with
                          ; new top y-coordinate
  LD A,(IX+4)             ; Load A with top y-coordinate of stalactite (see
                          ; trivia)
  CP 101                  ; If new top y-coordinate is not 101
  JP NZ,38748             ; ...then advance IX to next entry in complex state
                          ; data and loop back to 38596
  LD (IX+12),1            ; Set stalactite's velocity factor to 1
  JP 38748                ; Advance IX to next entry in complex state data and
                          ; loop back to 38596
  CP 1                    ; If velocity factor is not 1...
  JR NZ,38707             ; ...then check for collision with Berk killing him
                          ; if so, ensure stalactite is falling and update its
                          ; vertical position (38707)
  LD E,(IX+5)             ; Load E with x-coordinate of left of stalactite
  LD IY,(34240)           ; Load IY with address of current level's complex
                          ; state data for Berk
  LD A,(IY+0)             ; If Berk's current room is not the same as the
                          ; stalactite's...
  CP (IX+0)               ; ...
  JR NZ,38679             ; ...then skip ahead to 38679 to check Drutt's
                          ; position
  LD A,(IY+11)            ; If Berk's Walking Left Flag is set...
  BIT 1,A                 ; ...
  JR NZ,38673             ; ...then skip ahead to 38673
  BIT 0,A                 ; If Berk's Walking Right Flag is not set...
  JR Z,38679              ; ...then skip ahead to 38679 to check Drutt's
                          ; position
  LD A,(IY+7)             ; If Berk's right-side x-coordinate is the same as
                          ; the stalactite's left-side x-coordinate...
  CP E                    ; ...
  JR Z,38707              ; ...then check for collision with Berk killing him
                          ; if so, ensure stalactite is falling and update its
                          ; vertical position (38707)
  JR 38679                ; Skip ahead to 38679 to check Drutt's position
  LD A,(IY+5)             ; If Berk's left-side x-coordinate is the same as the
                          ; stalactite's left-side x-coordinate...
  CP E                    ; ...
  JR Z,38707              ; ...then check for collision with Berk killing him
                          ; if so, ensure stalactite is falling and update its
                          ; vertical position (38707)
  LD IY,44396             ; Load IY with address of complex state data for
                          ; Drutt (Level 2)
  LD A,(IY+0)             ; If Drutt's current room is not the same as the
                          ; stalactite's...
  CP (IX+0)               ; ...
  JR NZ,38699             ; ...then skip ahead to 38699
  LD A,(IY+5)             ; If Drutt's left-side x-coordinate is the same as
                          ; the stalactite's left-side x-coordinate...
  CP (IX+5)               ; ...
  JR Z,38707              ; ...then check for collision with Berk killing him
                          ; if so, ensure stalactite is falling and update its
                          ; vertical position (38707)
  LD A,200                ; Load A with a random number, 0-199...
  CALL 54222              ; ...
  OR A                    ; ...and if this is not zero (199 in 200 chance)...
  JR NZ,38748             ; ...then advance IX to next entry in complex state
                          ; data and loop back to 38596
  CALL 54768              ; Check entity at IX for collision with another
                          ; entity at same depth whose Interaction (11,6) Flag
                          ; is set...
  CP 31                   ; ...and if collision was not with entity of class 31
                          ; (Berk)...
  JR NZ,38718             ; ...then skip ahead to 38718 (start stalactite
                          ; falling)
  CALL 53667              ; Set "Berk Has Been Killed" Flag
  RET                     ; Return
  LD B,(IX+12)            ; Load B with stalactite's velocity factor...
  CALL 38756              ; ...and move stalactite down by this many
                          ; characters...
  DJNZ 38721              ; ...
  INC (IX+12)             ; Increase stalactite's velocity factor by one
  LD A,(IX+4)             ; If y-coordinate of top of stalactite is less than
                          ; 150...
  CP 150                  ; ...
  JR C,38748              ; ...then advance IX to next entry in complex state
                          ; data and loop back to 38596
  LD (IX+4),98            ; Move stalactite back to top of room...
  LD (IX+6),100           ; ...
  LD (IX+12),0            ; ...and set its velocity factor to zero
  LD BC,13                ; Advance IX by 13 bytes to move to next complex
                          ; state data entry...
  ADD IX,BC               ; ...
  JP 38596                ; ...and loop back to 38596 for next entity

; Move Entity at IX Down One Character
;
; Used by the routines at 38219 and 38592. Input:  IX  Address of complex state
; data for an entity Output: A New y-coordinate of entity's top
  INC (IX+4)              ; Increase y-coordinates of top and bottom of entity
                          ; by one character...
  INC (IX+6)              ; ...
  LD A,(IX+4)             ; Load new y-coordinate of entity's top into A
  RET                     ; Return

