; Update States of All Level 3 Entities
;
; Used by the routine at 34438.
  CALL 39776              ; Update state of Large Yellow Creature
  CALL 39601              ; Update states of coloured creatures
  CALL 39278              ; Update state of Clawed Foot
  CALL 39151              ; Update state of Hatch
  RET                     ; Return

; Hatch State Index (Level 3)
  DEFB 0

; Update State of Hatch (Level 3)
;
; Used by the routine at 39137.
  LD IX,(34240)           ; Load IX with address of current level's complex
                          ; state data for Berk
  LD HL,39150             ; If Hatch State Index is zero...
  LD A,(HL)               ; ...
  OR A                    ; ...
  JR Z,39176              ; ...then skip ahead to 39176
; Hatch State Index is not zero
  INC (HL)                ; Increase Hatch State Index
  CP 2                    ; If Hatch State Index is 2 (Berk was thrown 1 cycle
                          ; ago)...
  JR Z,39264              ; ...then skip ahead to 39264
  CP 10                   ; If Hatch State Index is 10 (Berk was thrown 9
                          ; cycles ago)...
  JR Z,39259              ; ...then skip ahead to 39259
  CP 11                   ; If Hatch State Index is 11 (Berk was thrown 10
                          ; cycles ago)...
  JR Z,39269              ; ...then skip ahead to 39269
  RET                     ; Return
; Hatch State Index is zero
  BIT 0,(IX+9)            ; If Berk's Must Process Current Script Data Flag is
                          ; set...
  RET NZ                  ; ...then return
  LD A,(IX+0)             ; If Berk's room is not 4 (Hatch Room)...
  CP 4                    ; ...
  RET NZ                  ; ...then return
  LD A,(IX+6)             ; If y-coordinate of Berk's bottom edge is not 121...
  CP 121                  ; ...
  RET NZ                  ; ...then return
  LD A,(IX+5)             ; If x-coordinate of Berk's left edge is less than
                          ; 109...
  CP 109                  ; ...
  RET C                   ; ...then return
  LD A,(IX+7)             ; If x-coordinate of Berk's right edge is 120 or
                          ; greater...
  CP 120                  ; ...
  RET NC                  ; ...then return
; At this point, Berk is standing on the hatch
  LD A,(34221)            ; If Berk is holding the weight...
  CP 12                   ; ...
  RET Z                   ; ...then return
  INC (HL)                ; Increase Hatch State Index to 1
  CALL 36296              ; Make Berk drop the entity he is holding and load IY
                          ; with its complex state data address
  LD A,(34220)            ; If Berk's current power is not invisibility (Level
                          ; 3)...
  CP 11                   ; ...
  JR NZ,39225             ; ...then skip ahead to 39225
  CALL 48417              ; Remove Berk's invisibility and reset corresponding
                          ; edible eyes to their original position
  LD B,4                  ; Move Berk up four characters...
  CALL 39442              ; ...
  DJNZ 39227              ; ...
  LD (IX+5),107           ; Set x-coordinate of Berk's left edge to 107
  LD (IX+7),112           ; Set x-coordinate of Berk's right edge to 112
  SET 0,(IX+9)            ; Set Berk's Must Process Current Script Data Flag
  LD HL,59048             ; Set Berk's graphic layout data address to 59048...
  LD (IX+2),L             ; ...(Berk being thrown left)...
  LD (IX+3),H             ; ...
  LD HL,35523             ; Set current position in Berk's script data to
                          ; 35523...
  LD (35687),HL           ; (Berk being thrown left by Hatch)
; Hatch State Index is 10 (Berk was thrown 9 cycles ago)
  LD HL,41115             ; Load HL with graphic layout data address of Hatch
                          ; half open with Bat (Animated)
  JR 39274                ; Skip ahead to 39274 (set Hatch's GLD address to
                          ; value in HL and return)
; Hatch State Index is 2 (Berk was thrown 1 cycle ago)
  LD HL,41099             ; Load HL with graphic layout data address of Hatch
                          ; fully open With Bat (Animated)
  JR 39274                ; Skip ahead to 39274 (set Hatch's GLD address to
                          ; value in HL and return)
; Hatch State Index is 11 (Berk was thrown 10 cycles ago)
  LD (HL),0               ; Set Hatch State Index to zero
  LD HL,41090             ; Load HL with graphic layout data address of Hatch
                          ; closed
  LD (44792),HL           ; Set Hatch's graphic layout data address to value in
                          ; HL
  RET                     ; Return

; Update State of Clawed Foot (Level 3)
;
; Used by the routine at 39137.
  LD A,(34228)            ; If Clawed Foot's Attack Timer is zero...
  OR A                    ; ...
  JR Z,39289              ; ...then skip ahead to 39289
  DEC A                   ; Decrease Clawed Foot's Attack Timer...
  LD (34228),A            ; ...
  RET                     ; Return
; Clawed Foot is attacking
  LD IY,44881             ; Load IY with address of complex state data for
                          ; Clawed Foot (Level 3)
  LD IX,(34240)           ; Load IX with address of current level's complex
                          ; state data for Berk
  CALL 53848              ; Store room size data for Berk's current room
  LD A,(44890)            ; Load A with Clawed Foot's flags...
  OR A                    ; ...and if any are set...
  JR NZ,39337             ; ...then skip ahead to 39337
; Clawed Foot attack not yet started
  LD A,(IY+0)             ; If the Clawed Foot's room...
  CP (IX+0)               ; ...is not the same as Berk's room...
  RET NZ                  ; ...then return
  LD A,(IX+11)            ; If Berk's Walking Left Flag or Walking Right Flag
                          ; is set...
  AND 3                   ; ...
  RET NZ                  ; ...then return
  LD A,(IX+5)             ; Set the Clawed Foot's left edge...
  INC A                   ; ...to be one character to the right of Berk's left
                          ; edge...
  LD (IY+5),A             ; ...
  ADD A,2                 ; Set the Clawed Foot's right edge...
  LD (IY+7),A             ; ...to be two characters to the right of its left
                          ; edge
  SET 1,(IY+9)            ; Set Clawed Foot's Moving Down Flag
  JR 39341                ; Skip ahead to 39341
; Clawed Foot attack underway
  BIT 1,A                 ; If Clawed Foot's Moving Down Flag is reset...
  JR Z,39420              ; ...then skip ahead to 39420
  LD B,3                  ; Load B with 3 (as the Clawed Foot moves down three
                          ; characters at time)
  INC (IY+4)              ; Advance Clawed Foot one character down...
  INC (IY+6)              ; ...
  LD A,(IY+6)             ; If y-coordinate of bottom edge of Clawed Foot is
                          ; 115...
  CP 115                  ; ...
  JR Z,39359              ; ...then skip ahead to 39359
  DJNZ 39343              ; Decrease remaining number of characters to move and
                          ; loop back to 39343 if not zero
  RET                     ; Return
; Clawed Foot attempting to grab Berk
  BIT 6,(IX+9)            ; If Berk is flying...
  JR NZ,39386             ; ...then skip ahead to 39386 (set Clawed Foot's
                          ; Moving Up Flag and return)
  BIT 6,(IX+10)           ; If Berk is falling...
  JR NZ,39386             ; ...then skip ahead to 39386 (set Clawed Foot's
                          ; Moving Up Flag and return)
  LD A,(IY+5)             ; If Clawed Foot's left edge...
  DEC A                   ; ...is one character to the right of Berk's left
                          ; edge...
  CP (IX+5)               ; ...
  JR Z,39391              ; ...then skip ahead to 39391
  DEC A                   ; If Clawed Foot's left edge...
  CP (IX+5)               ; ...is two characters to the right of Berk's left
                          ; edge...
  JR Z,39391              ; ...then skip ahead to 39391
; Berk is flying or falling, or Clawed Foot has missed
  LD (IY+9),4             ; Set Clawed Foot's Moving Up Flag
  RET                     ; Return
; Make Clawed Foot grab Berk (Clawed Foot is one or two characters to the right
; of Berk's left edge)
  LD BC,35515             ; Set current position in Berk's script data to...
  LD (35687),BC           ; ...Berk in floating position
  SET 0,(IX+9)            ; Set Berk's Must Process Current Script Data Flag
  LD A,12                 ; Set Clawed Foot's Moving Up Flag and Holding Berk
                          ; Flag...
  LD (IY+9),A             ; ...
  LD BC,40368             ; Set Clawed Foot's graphic layout data address to
                          ; point to 40368 (Reaching, Closed)...
  LD (IY+2),C             ; ...
  LD (IY+3),B             ; ...
  CALL 36296              ; Make Berk drop the entity he is holding and load IY
                          ; with its complex state data address
  RET                     ; Return
; Check Clawed Foot's Moving Up Flag
  BIT 2,A                 ; If Clawed Foot's Moving Up Flag is reset...
  JR Z,39532              ; ...then skip ahead to 39532
  DEC (IY+4)              ; Move Clawed Foot up one character...
  DEC (IY+6)              ; ...
  LD A,(IY+6)             ; If y-coordinate of bottom of Clawed Foot...
  CP 95                   ; ...is 95...
  JR Z,39449              ; ...then skip ahead to 39449
  BIT 3,(IY+9)            ; If Clawed Foot's Holding Berk Flag is reset...
  RET Z                   ; ...then return
; This entry point is used by the routine at 39151.
  DEC (IX+4)              ; Move entity at IX (Berk) up one character...
  DEC (IX+6)              ; ...
  RET                     ; Return
  BIT 3,(IY+9)            ; If Clawed Foot's Holding Berk Flag is reset...
  JR Z,39527              ; ...then skip ahead to 39527 (Reset Clawed Foot to
                          ; inactive state and return)
  LD A,(34229)            ; Increase Clawed Foot's Action Index...
  INC A                   ; ...
  LD (34229),A            ; ...
  CP 7                    ; ...and if less than 7...
  JR C,39470              ; ...then skip ahead to 39470
  LD A,1                  ; Set Clawed Foot's Action Index to 1...
  JR 39459                ; ...and jump to 39470 (via 39459)
  CP 3                    ; If Clawed Foot's Action Index is less than 3...
  JR C,39501              ; ...then skip ahead to 39501 (i.e. make clawed foot
                          ; release Berk, and return)
  CP 5                    ; If Clawed Foot's Action Index is less than 5...
  JR C,39482              ; ...then skip ahead to 39482
  LD E,112                ; Load E with 112 (prepare to set Clawed Foot's
                          ; destination x-coordinate)
  JR 39484                ; Skip ahead to 39484
  LD E,122                ; Load E with 122 (prepare to set Clawed Foot's
                          ; destination x-coordinate)
  LD (IX+12),E            ; Store destination x-coordinate in byte 12 of Berk's
                          ; complex state data
  BIT 0,A                 ; If Clawed Foot's Action Index is even...
  JR Z,39496              ; ...then skip ahead to 39496
  LD (IY+9),16            ; Set Clawed Foot's Move Left Flag
  RET                     ; Return
  LD (IY+9),32            ; Set Clawed Foot's Move Right Flag
  RET                     ; Return
; The instructions between 39501 and 39531 make the Clawed Foot release Berk.
  LD A,100                ; Set Clawed Foot's Attack Timer to 100...
  LD (34228),A            ; ...i.e. Clawed Foot will attack again in 100 cycles
  SET 6,(IX+10)           ; Set Berk's "Can Fall" flag
  LD (IX+12),2            ; Set Berk's velocity factor to 2
  LD BC,35359             ; Set current position in Berk's script data to...
  LD (35687),BC           ; ...Berk starting to fall downwards
  LD BC,40320             ; Set Clawed Foot's graphic layout data address to
                          ; point to 40320 (Reaching, Open)...
  CALL 39410              ; ...make Berk drop the entity he is holding and load
                          ; IY with its complex state data address
; Reset Clawed Foot to inactive state
  LD (IY+9),0             ; Reset Clawed Foot's Flags
  RET                     ; Return
; Check Clawed Foot's Moving Left Flag
  BIT 4,A                 ; If Clawed Foot's Move Left Flag is reset...
  JR Z,39552              ; ...then skip ahead to 39552
  DEC (IX+5)              ; Move Berk one character left...
  DEC (IX+7)              ; ...
  CALL 54348              ; Move Berk into room to the left, if appropriate
  LD A,(IX+0)             ; If Berk's room is 5 (room to the left of the
                          ; Coloured Creatures' Room)...
  CP 5                    ; ...then set Zero Flag
  JR 39569                ; Skip ahead to 39569
; Check Clawed Foot's Moving Right Flag
  BIT 5,A                 ; If Clawed Foot's Move Right Flag is reset...
  RET Z                   ; ...then return
  INC (IX+5)              ; Move Berk one character right...
  INC (IX+7)              ; ...
  CALL 54313              ; Move Berk into room to the right, if appropriate
  LD A,(IX+0)             ; If Berk's room is 7 (room to the right of the
                          ; Coloured Creatures' Room)...
  CP 7                    ; ...then set Zero Flag
  RET NZ                  ; If Zero Flag is not set (i.e. Berk is not in Room 5
                          ; or Room 7) then return
  LD A,(IX+12)            ; If the x-coordinate of Berk's left edge...
  CP (IX+5)               ; ...is not the same as the Clawed Foot's destination
                          ; x-coordinate...
  RET NZ                  ; ...then return
  LD IY,44881             ; Load IY with address of complex state data for
                          ; Clawed Foot (Level 3)
  JP 39501                ; Make Clawed Foot release Berk, and return

; Table of Coloured Creatures' Properties
;
; This data is used to periodically change the identities of the three coloured
; creatures. Upon switching, a random number (i.e. a "Sequence ID") between 0
; and 2 is generated. This Sequence ID is the index of the record, in the
; following table, whose data (entity class and graphic layout data address)
; will overwrite that of the first coloured creature at 44894, as defined in
; the complex state data table. The second and third creatures' data will be
; likewise overwritten by the data from the following two records,
; respectively. As three records are always used, starting with the record
; whose index matches the generated Sequence ID, there will always be one red,
; one yellow and one white creature.
  DEFB 13,62,157          ; Red Coloured Creature
  DEFB 14,77,157          ; Yellow Coloured Creature
  DEFB 15,92,157          ; White Coloured Creature
  DEFB 13,62,157          ; Red Coloured Creature
  DEFB 14,77,157          ; Yellow Coloured Creature

; Miscellaneous Data (Coloured Creatures)
  DEFB 0                  ; Creatures' current Sequence ID
  DEFB 0                  ; Cycles elapsed since last swap of creatures

; Update States of Coloured Creatures
;
; Used by the routine at 39137.
  LD A,(44903)            ; Load A with first coloured creature's flags
  BIT 2,A                 ; If Coloured Creatures' Reward Given Flag is set...
  RET NZ                  ; ...then return
  BIT 1,A                 ; If All Coloured Creatures Home Flag is set...
  JP NZ,39760             ; ...then present reward for getting coloured
                          ; creatures home, and return
  CALL 39699              ; Count coloured creatures in slots and return if all
                          ; are home
  LD A,L                  ; If all three coloured creatures are in slots...
  CP 3                    ; ...
  RET Z                   ; ...then return
  LD A,(34218)            ; If current character's current room is not 6
                          ; (coloured creatures' room)...
  CP 6                    ; ...
  RET NZ                  ; ...then return
  LD HL,39600             ; Increase cycles elapsed since last swap of
                          ; creatures...
  INC (HL)                ; ...
  LD A,(HL)               ; ...
  CP 100                  ; ...and if less than 100...
  RET C                   ; ...then return
  LD (HL),0               ; Set cycles elapsed since last swap of creatures to
                          ; zero
  CALL 36616              ; Cycle attributes (full-screen), clear display
                          ; buffers and paint red areas outside current room
  LD HL,39599             ; Point HL at current Sequence ID
  LD A,3                  ; Load A with a random number, 0-2...
  CALL 54222              ; ...
  CP (HL)                 ; ...and if this is the same as the current Sequence
                          ; ID...
  JR Z,39641              ; ...then jump back to 39641 to generate a new random
                          ; number
  LD (HL),A               ; Set new Sequence ID to generated number
  ADD A,A                 ; Load BC with three times Sequence ID...
  ADD A,(HL)              ; ...
  LD C,A                  ; ...
  LD B,0                  ; ...
  LD IY,39584             ; Load IY with start address of Table of Coloured
                          ; Creatures' Properties...
  ADD IY,BC               ; ...and add three times Sequence ID to get address
                          ; of first entry in new sequence
  LD IX,44894             ; Load IX with address of complex state data for
                          ; first coloured creature (Level 3)
  LD B,3                  ; Load B with 3 (as there are three coloured
                          ; creatures)
  LD A,(IY+0)             ; Set class of current coloured creature...
  LD (IX+8),A             ; ...
  LD A,(IY+1)             ; ...and address of graphic layout data...
  LD (IX+2),A             ; ...
  LD A,(IY+2)             ; ...
  LD (IX+3),A             ; ...to values in current record in Table of Coloured
                          ; Creatures' Properties
  INC IY                  ; Advance IY to next entry in properties table...
  INC IY                  ; ...
  INC IY                  ; ...
  LD DE,13                ; Advance IX to next coloured creature's
                          ; properties...
  ADD IX,DE               ; ...
  DJNZ 39667              ; Decrease remaining number of coloured creatures to
                          ; update and loop back to 39667 if not zero
  RET                     ; Return

; Count Coloured Creatures in Slots and Return if All Are Home
;
; Used by the routine at 39601. Output: H  Number of coloured creatures in
; correct slots L  Number of coloured creatures in slots
  LD IX,44894             ; Load IX with address of complex state data for
                          ; first coloured creature (Level 3)
  LD HL,0                 ; Load HL with zero
  LD B,3                  ; Load B with 3 (as there are 3 creatures)
  LD A,(IX+6)             ; If y-coordinate of bottom of current creature is
                          ; not 114...
  CP 114                  ; ...
  RET NZ                  ; ...then return
  INC L                   ; Increase L (number of creatures in slots)
  LD A,(IX+8)             ; If current entity class is not 13 (Red Coloured
                          ; Creature, Level 3)...
  CP 13                   ; ...
  JR NZ,39726             ; ...then skip ahead to 39726
  LD A,108                ; Load A with 108 (x-coordinate of left-most slot)
  JR 39736                ; Skip ahead to 39736
  CP 14                   ; If current entity class is not 14 (Yellow Coloured
                          ; Creature, Level 3)...
  JR NZ,39734             ; ...then skip ahead to 39734
  LD A,115                ; Load A with 115 (x-coordinate of middle slot)
  JR 39736                ; Skip ahead to 39736
  LD A,122                ; Load A with 122 (x-coordinate of right-most slot)
  CP (IX+5)               ; If x-coordinate of slot in A is not the same as
                          ; x-coordinate of current creature's left...
  JR NZ,39742             ; ...then skip ahead to 39742
  INC H                   ; Increase H (number of creatures at correct
                          ; x-coordinate for their respective coloured slots)
  LD DE,13                ; Advance IX to next entity...
  ADD IX,DE               ; ...
  DJNZ 39708              ; Loop back to 39708 for next creature
  LD A,H                  ; If H is not 3 (i.e. at least one creature not at
                          ; correct x-coordinates)...
  CP 3                    ; ...
  RET NZ                  ; ...then return
  LD A,2                  ; Set All Coloured Creatures Home Flag
  LD (44903),A            ; ...
  POP BC                  ; Return to routine that called the calling
                          ; routine...
  RET                     ; ...

; Present Reward for Getting Coloured Creatures Home
;
; Used by the routine at 39601.
  CALL 36616              ; Cycle attributes (full-screen), clear display
                          ; buffers and paint red areas outside current room
  LD IX,44972             ; Load IX with address of complex state data for
                          ; edible eyes (normally hidden off-screen)...
  CALL 55516              ; ...and set their "Can Fall" Flag and set initial
                          ; velocity factor to 2
  LD A,4                  ; Set Coloured Creatures' Reward Given Flag...
  LD (44903),A            ; ...
  RET                     ; Return

; Update State of Large Yellow Creature (Level 3)
;
; Used by the routine at 39137.
  LD IY,44868             ; Load IY with address of complex state data for
                          ; Large Yellow Creature (Level 3)
  LD IX,(34240)           ; Load IX with address of current level's complex
                          ; state data for Berk
  LD HL,44877             ; Load HL with address of Large Yellow Creature's
                          ; flags...
  LD A,(HL)               ; ...and load flags into A
  CP 2                    ; If creature is in "Rising From Floor" mode...
  JR Z,39831              ; ...then skip ahead to 39831
  CP 4                    ; If creature is in "Hunting" mode...
  JR Z,39845              ; ...then skip ahead to 39845
  CP 8                    ; If creature is in "Attacking" mode...
  JR Z,39918              ; ...then skip ahead to 39918
  CP 16                   ; If creature is in "Just Attacked" mode...
  JP Z,39934              ; ...then set creature's mode to "Returning Home",
                          ; set Berk's "Has Been Killed" Flag and return
  LD A,(IX+0)             ; If Berk's current room is not 3 (Yellow Creature's
                          ; Room)...
  CP 3                    ; ...
  JP NZ,39998             ; ...then set creature's mode to "Returning Home",
                          ; move one step closer to home and return
; "Returning Home" mode
  LD A,(IY+5)             ; If x-coordinate of creature's left side...
  CP (IX+5)               ; ...is the same as that of Berk's left side...
  JR Z,39828              ; ...then skip ahead to 39828
  INC A                   ; If x-coordinate of creature's left side...
  CP (IX+5)               ; ...is not one character to the right of Berk's left
                          ; side...
  JP NZ,39998             ; ...then set creature's mode to "Returning Home",
                          ; move one step closer to home and return
  LD A,2                  ; Set creature's mode to "Rising from Floor"...
  LD (HL),A               ; ...
; "Rising from Floor" mode
  CALL 39971              ; Move creature such that its left edge is up to two
                          ; characters closer to Berk's
  CALL 39961              ; Move creature up by two characters
  LD A,(IY+4)             ; If y-coordinate of creature's top...
  CP 108                  ; ...is 108 or greater...
  RET NC                  ; ...then return
  LD (HL),4               ; Set creature's mode to "Hunting"
; "Hunting" mode
  LD A,(IX+0)             ; If Berk's current room is not 3 (Yellow Creature's
                          ; Room)...
  CP 3                    ; ...
  JP NZ,39998             ; ...then set creature's mode to "Returning Home",
                          ; move one step closer to home and return
  LD A,(34220)            ; If Berk's current power is invisibility (Level
                          ; 3)...
  CP 11                   ; ...
  JR Z,39909              ; ...then skip ahead to 39909 ("confused" mode)
  LD A,(IX+4)             ; If y-coordinate of Berk's top...
  CP 103                  ; ...is less than 103...
  JR C,39909              ; ...then skip ahead to 39909 ("confused" mode)
  CALL 39971              ; Move creature such that its left edge is up to two
                          ; characters closer to Berk's
  LD A,(IY+4)             ; If creature's top...
  ADD A,4                 ; ...is four characters above Berk's top...
  CP (IX+4)               ; ...
  JR Z,39890              ; ...then skip ahead to 39890 (set "Attacking" mode)
  JR NC,39961             ; If creature's top is less than 4 characters above
                          ; Berk's top then move creature up by two characters
                          ; and return
  INC A                   ; If creature's top is five characters above Berk's
                          ; top...
  CP (IX+4)               ; ...
  JR Z,39890              ; ...then skip ahead to 39890 (set "Attacking" mode)
  JR C,39951              ; If creature's top is more than five characters
                          ; above Berk's top then move creature down two
                          ; characters and return
  LD (HL),8               ; Set creature's mode to "Attacking"
  LD (IY+1),1             ; Set creature's depth to 1
  SET 5,(IX+9)            ; Set Berk's "Do Not Update State" Flag
  LD BC,40442             ; Set graphic layout data address for creature to
                          ; 40442 (Large Yellow Creature with mouth open)...
  CALL 39944              ; ...
  JP 36296                ; Make Berk drop the entity he is holding, load IY
                          ; with its complex state data address and return
; "Confused" mode
  LD BC,40485             ; Set graphic layout data address for creature to
                          ; 40485 (Large Yellow Creature, animated,
                          ; confused)...
  CALL 39944              ; ...
  JP 40008                ; Move creature one step closer to x (left) = 113, y
                          ; (top) > 111 if not already there, and return
; "Attacking" mode
  CALL 39951              ; Move creature down two characters
  LD (IX+1),0             ; Set Berk's depth to zero
  LD (HL),16              ; Set creature's mode to "Just Attacked"
  LD BC,40451             ; Set graphic layout data address for creature to
                          ; 40451 (Large Yellow Creature with mouth closed)...
  JP 39944                ; ...and return

; Unused routine
  RET                     ; Return

; Set Large Yellow Creature's Mode to "Returning Home", and Set Berk's "Has
; Been Killed" Flag
;
; Used by the routine at 39776.
  CALL 53667              ; Set "Berk Has Been Killed" Flag
  RES 5,(IX+9)            ; Reset Berk's "Do Not Update State" Flag
  LD (HL),0               ; Set creature's mode to "Returning Home"
  RET                     ; Return

; Set Graphic Layout Data Address for Entity at IY to BC
;
; Used by the routine at 39776. Input:  BC  Graphic layout data address IY
; Address of complex state data for an entity
  LD (IY+2),C             ; Set graphic layout data address for entity to
                          ; address in BC...
  LD (IY+3),B             ; ...
  RET                     ; Return

; Move Entity at IY Down Two Characters
;
; Used by the routine at 39776. Input:  IY  Address of complex state data for
; an entity
  CALL 39954              ; Move entity at IY down one character
; This entry point is used by the routine at 40008.
  INC (IY+4)              ; Increase y-coordinates of entity's top and bottom
                          ; edges...
  INC (IY+6)              ; ...
  RET                     ; Return

; Move Entity at IY Up Two Characters
;
; Used by the routine at 39776. Input:  IY  Address of complex state data for
; an entity
  CALL 39964              ; Move entity at IY up one character
  DEC (IY+4)              ; Decrease y-coordinates of entity's top and bottom
                          ; edges...
  DEC (IY+6)              ; ...
  RET                     ; Return

; Move Entity IY Such that its Left Edge is Up to Two Characters Closer to
; Entity IX's
;
; Used by the routine at 39776. Input:  IX  Address of complex state data for
; Entity A IY  Address of complex state data for Entity B
  CALL 39975              ; Move Entity B one character closer (horizontally)
                          ; to Entity A...
  RET Z                   ; ...and if left edges now both at same x-coordinate
                          ; then return
; If entities' left edges are not at the same x-coordinate, then proceed into
; the code block below and move entity B by one additional character.
  LD A,(IX+5)             ; If x-coordinates of both entities' left edges are
                          ; the same...
  CP (IY+5)               ; ...
  RET Z                   ; ...then return
  JR C,39991              ; If Entity B's left edge is to the right of Entity
                          ; A's then move Entity B left by one character
  INC (IY+5)              ; Move Entity B right by one character...
  INC (IY+7)              ; ...
  RET                     ; Return
  DEC (IY+5)              ; Move Entity B left by one character...
  DEC (IY+7)              ; ...
  RET                     ; Return

; Set Large Yellow Creature's Mode to "Returning Home", Move One Step Closer to
; Home and Return
;
; Used by the routine at 39776. Input:  HL  Address of creature's flags IY
; Address of complex state data for creature
  LD (HL),0               ; Set creature's mode to "Returning Home"
  LD (IY+1),2             ; Set creature's depth to 2
  LD A,122                ; Move creature one step closer to x (Left) = 113, y
                          ; (Top) > 122...
  JR 40010                ; ...and return

; Move Entity at IY One Step Closer to Home Position
;
; This routine moves an entity (whose complex state data is pointed to by IY)
; one character left or right, if such a move would take the x-coordinate of
; that entity's left edge closer to a value of 113. The entity will also be
; moved down by one character if the y-coordinate of its top edge is less than
; or equal to 111 (or the input value in A if we are entering this routine via
; 40010). Input:  A  (Entry at 40010 only) Minimum allowed y-coordinate for
; entity's top edge IY  Address of complex state data for an entity
  LD A,111                ; Load A with 111 (minimum allowed y-coordinate)
; This entry point is used by the routine at 39998.
  CP (IY+4)               ; If y-coordinate of entity's top edge is greater
                          ; than value in A...
  JR C,40018              ; ...then skip ahead to 40018
  CALL 39954              ; Move entity at IY down one character
  LD A,(IY+5)             ; If x-coordinate of entity's left edge...
  CP 113                  ; ...is 113...
  RET Z                   ; ...then return
  JR C,40033              ; ...else if greater than 113 then skip ahead to
                          ; 40033
  DEC (IY+5)              ; Move entity left one character...
  DEC (IY+7)              ; ...
  RET                     ; Return
  INC (IY+5)              ; Move entity right one character...
  INC (IY+7)              ; ...
  RET                     ; Return

