; Reset Skeleton to Initial State
;
; Used by the routine at 34751.
  LD HL,41232             ; Set current position in Skeleton's script data...
  LD (41230),HL           ; ...to 41232 (Skeleton Idling)
  LD IX,41412             ; Load IX with address of Table of Addresses of
                          ; Attribute Data in Skeleton's GLD Blocks
  LD B,6                  ; Load B with 6 (as there are six blocks of graphic
                          ; layout data to modify)
  LD L,(IX+0)             ; Load HL with address of attribute data in current
                          ; block...
  LD H,(IX+1)             ; ...
  LD (HL),7               ; Set the attribute value to 7 (white)
  INC IX                  ; Advance IX to next address...
  INC IX                  ; ...
  DJNZ 41366              ; Decrease remaining number of blocks to modify and
                          ; loop back to 41366 if not zero
  RET                     ; Return

; Update State of Skeleton (Level 4) and Store Current Position in Script Data
;
; Used by the routine at 41211.
  LD IX,45404             ; Load IX with address of complex state data for
                          ; Skeleton (Level 4)
  BIT 2,(IX+9)            ; If Skeleton's Removed From Game Flag is set...
  RET NZ                  ; ...then return
  BIT 1,(IX+9)            ; If Skeleton's Is Dying Flag is set...
  JR NZ,41424             ; ...then update state of Skeleton (dying) and return
  LD HL,(41230)           ; Load current position in Skeleton's script data
                          ; from 41230 into HL...
  LD (34277),HL           ; ...and store at 34277 as position in script
                          ; currently running
  CALL 41498              ; Kill Berk if he collides with Skeleton
  LD HL,(34277)           ; Store address (current position in script data)
                          ; stored at 34277...
  LD (41230),HL           ; ...at 41230 as current position in Skeleton's
                          ; script data
  RET                     ; Return

; Table of Addresses of Attribute Data in Skeleton's Graphic Layout Data Blocks
;
; Each of the addresses in this table is of the "operand" of a "set attribute"
; instruction (i.e. 242) in the Skeleton's graphic layout data blocks. These
; are initially 7 (i.e. white). When the skeleton is killed, the routine at
; 41424 (instructions starting at 41473) decreases this attribute by one per
; game cycle. When the attribute values reach 1 (blue), the skeleton is removed
; from the game and replaced by Boni.
  DEFW 42911              ; (42910) Standing, Full, Animated
  DEFW 42947              ; (42946) Stepping Forward, Frame 1, Full, Animated
  DEFW 42988              ; (42987) Stepping Forward, Frame 2, Full, Animated
  DEFW 43023              ; (43022) Head, Animated
  DEFW 43062              ; (43061) Torso and Spear, Extended
  DEFW 43096              ; (43095) Torso and Spear, Retracted

; Update State of Skeleton (Dying)
;
; Used by the routine at 41381. Input:  IX  Address of complex state data for
; Skeleton (Level 4)
  LD A,(42911)            ; If current attribute in Skeleton's graphic layout
                          ; data is not 1...
  CP 1                    ; ...
  JR NZ,41473             ; ...then skip ahead to 41473
  LD (IX+1),0             ; Set Skeleton's room to 0
  LD IY,45417             ; Load IY with address of complex state data for Boni
                          ; (Level 4)
  LD A,(IX+4)             ; Set y-coordinate of Boni's top edge...
  LD (IY+4),A             ; ...to same as that of skeleton
  ADD A,3                 ; Set y-coordinate of Boni's bottom edge...
  LD (IY+6),A             ; ...to three characters below this
  LD A,(IX+5)             ; Set x-coordinate of Boni's left edge...
  LD (IY+5),A             ; ...to same as that of skeleton
  INC A                   ; Set x-coordinate of Boni's right edge...
  LD (IY+7),A             ; ...to one to the right of this
  LD (IY+1),1             ; Set Boni's depth to 1
  SET 6,(IY+10)           ; Set Boni's Can Fall Flag
  SET 2,(IX+9)            ; Set Skeleton's Removed From Game Flag
  RET                     ; Return
; Current attribute in Skeleton's graphic layout data is not 1
  LD IX,41412             ; Load IX with address of Table of Addresses of
                          ; Attribute Data in Skeleton's GLD Blocks
  LD B,6                  ; Load B with 6 (as there are six blocks of graphic
                          ; layout data to modify)
  LD L,(IX+0)             ; Load HL with address of attribute data in current
                          ; block...
  LD H,(IX+1)             ; ...
  DEC (HL)                ; Decrease the attribute value
  INC IX                  ; Advance IX to next address...
  INC IX                  ; ...
  DJNZ 41479              ; Decrease remaining number of blocks to modify and
                          ; loop back to 41479 if not zero
  LD A,11                 ; Set sound 11 as pending if appropriate, then play
                          ; and clear pending sound...
  CALL 59722              ; ...
  RET                     ; Return

; Kill Berk if He Collides with Skeleton
;
; See trivia Input:  IX  Address of complex state data for Skeleton (Level 4)
; (45404)
  CALL 54768              ; Check entity at IX for collision with another
                          ; entity at same depth whose Interaction (11,6) Flag
                          ; is set...
  JR C,41513              ; ...and if no collision occurred, then skip ahead to
                          ; 41513
  CP 31                   ; If collision was not with entity of class 31
                          ; (Berk)...
  JR NZ,41513             ; ...then skip ahead to 41513
  CALL 53667              ; Set "Berk Has Been Killed" Flag
  JP 48096                ; Advance HL to next script instruction and execute
; The instructions below do a "manual" check for a collision between the
; Skeleton and Berk. See trivia
  LD IY,(34240)           ; Load IY with address of current level's complex
                          ; state data for Berk
  LD A,(IY+0)             ; If Berk's current room is not 3 (Skeleton's
                          ; room)...
  CP 3                    ; ...
  JP NZ,48096             ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  LD A,(IX+5)             ; If x-coordinate of Skeleton's left edge...
  SUB 5                   ; ...is at least five characters to the right of
                          ; Berk's right edge...
  CP (IY+7)               ; ...
  JP NC,48096             ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  LD A,(IY+6)             ; If y-coordinate of Berk's bottom edge...
  CP 116                  ; ...is less than 116...
  JP C,48096              ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  CALL 53667              ; Set "Berk Has Been Killed" Flag
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (63) Have Skeleton Advance or Retreat Based Upon Positions of
; Berk and Fake Boni
;
; The skeleton will step forward once, and then step back, if Berk is close
; enough and Fake Boni is in a room to the right. If Fake Boni is in the
; Skeleton's room, or a room to the left of this, then the Skeleton will step
; forward repeatedly while Berk is close enough and will only back off when
; Berk moves out of range. The range is nine, so if the distance between Berk's
; right edge and the Skeleton's left edge is less than nine then the Skeleton
; will advance. A distance of nine or more will see the Skeleton retreat. Note
; that the calculated range is based upon the Skeleton's state data at 45404,
; in which the x-coordinates of his left and right edges do not match his
; apparent position or width graphically. Input:  IX  Address of complex state
; data for an entity Output: HL Address of next script instruction to execute
  LD IY,(34240)           ; Load IY with address of current level's complex
                          ; state data for Berk
  LD A,(IY+0)             ; If Berk's current room is 3 (Skeleton's room)...
  CP 3                    ; ...
  JR Z,41580              ; ...then jump to 41580
; Berk is not in Skeleton's room, or Fake Boni is in a room right of the
; Skeleton's room
  LD A,(IX+5)             ; If x-coordinate of Skeleton's left edge is at least
                          ; 128...
  CP 128                  ; ...
  JR NC,41574             ; ...then skip ahead to 41574
  LD HL,41318             ; Point HL at script data for Skeleton stepping back
                          ; (right)...
  JP 48098                ; ...and execute
  LD HL,41232             ; Point HL at script data for Skeleton Idling...
  JP 48098                ; ...and execute
; Berk is in Skeleton's room
  BIT 0,(IX+9)            ; If Skeleton's Must Process Current Script Data Flag
                          ; is reset...
  JR Z,41597              ; ...then skip ahead to 41597
  RES 0,(IX+9)            ; Reset Skeleton's Must Process Current Script Data
                          ; Flag
  LD A,(45430)            ; If Fake Boni is in a room with index of 4 or more
                          ; (room above Pit, or Pit)...
  CP 4                    ; ...
  JR NC,41561             ; ...then jump back to 41561 (move Skeleton back)
  LD A,(IX+5)             ; If x-coordinate of Skeleton's left edge...
  SUB 9                   ; ...is at least nine characters to the right of
                          ; Berk's right edge...
  CP (IY+7)               ; ...
  JR NC,41561             ; ...then jump back to 41561 (move Skeleton back)
  SET 0,(IX+9)            ; Set Skeleton's Must Process Current Script Data
                          ; Flag
  LD HL,41280             ; Point HL at script data for Skeleton stepping
                          ; forward (left)...
  JP 48098                ; ...and execute

; Script Routine (64) Set Random (1 to 10) Number of Iterations in Following
; Loop Script Instruction
  LD A,10                 ; Load A with a random number, 1-10...
  CALL 54222              ; ...
  INC A                   ; ...
  PUSH HL                 ; Store HL (current position in script data)
  LD BC,4                 ; Advance HL by four bytes...
  ADD HL,BC               ; ...to number of iterations in next (loop)
                          ; instruction...
  LD (HL),A               ; ...and set number of iterations to number generated
  POP HL                  ; Restore HL (current position in script data)
  JP 48096                ; Advance HL to next script instruction and execute

; Update State of Ghost
;
; Used by the routine at 41211.
  LD IX,45794             ; Load IX with address of complex state data for
                          ; Ghost (Level 4)
  CALL 54768              ; Check entity at IX for collision with another
                          ; entity at same depth whose Interaction (11,6) Flag
                          ; is set...
  CP 31                   ; ...and if collision was not with entity of class 31
                          ; (Berk)...
  JR NZ,41653             ; ...then skip ahead to 41653
; If collision was with Berk, then IY will point to Berk's complex state data
  BIT 6,(IY+9)            ; If Berk is not flying...
  JR Z,41653              ; ...then skip ahead to 41653
  CALL 53667              ; Set "Berk Has Been Killed" Flag
  LD A,(34218)            ; Load E with current character's current room
                          ; index...
  LD E,A                  ; ...
  LD A,(IX+0)             ; Load A with Ghost's current room index
  LD C,(IX+4)             ; Load C with y-coordinate of Ghost's top edge
  LD B,(IX+6)             ; Load B with y-coordinate of Ghost's bottom edge
  BIT 0,(IX+9)            ; If Ghost's Moving Upwards Flag is set...
  JR NZ,41716             ; ...then skip ahead to 41716
  CP 4                    ; If Ghost's current room is 4 (room above pit)...
  JR Z,41687              ; ...then skip ahead to 41687
  LD A,B                  ; If y-coordinate of Ghost's bottom edge...
  CP 119                  ; ...is not 119...
  JP NZ,42360             ; ...then move Ghost down one character and return
  SET 0,(IX+9)            ; Set Ghost's Moving Upwards Flag
  RET                     ; Return
; Ghost's current room is 4 (room above pit)
  CP E                    ; If current character is in the same room as the
                          ; Ghost...
  JR Z,41703              ; ...then skip ahead to 41703
  LD A,B                  ; If y-coordinate of Ghost's bottom edge...
  CP 119                  ; ...is not 119...
  JP NZ,42360             ; ...then move Ghost down one character and return
  INC (IX+0)              ; Increase index of Ghost's current room (to 5, pit)
  LD A,94                 ; Position Ghost such that the y-coordinate of its
                          ; top edge is 115...
  JR 41758                ; ...and return
; Current character and Ghost in same room (room above pit)
  LD A,C                  ; If y-coordinate of Ghost's top edge...
  CP 121                  ; ...is not 121...
  JP NZ,42360             ; ...then move Ghost down one character and return
  INC (IX+0)              ; Increase index of Ghost's current room (to 5, pit)
  LD A,100                ; Position Ghost such that the y-coordinate of its
                          ; top edge is 100...
  JR 41758                ; ...and return
; Ghost's Moving Upwards Flag is set
  CP 5                    ; If Ghost's current room is 5 (pit)...
  JR Z,41731              ; ...then skip ahead to 41731
  LD A,C                  ; If y-coordinate of Ghost's top edge...
  CP 101                  ; ...is not 101...
  JP NZ,42374             ; ...then move Ghost up one character and return
  RES 0,(IX+9)            ; Reset Ghost's Moving Upwards Flag (i.e. moving
                          ; downwards)
  RET                     ; Return
; Ghost's current room is 5 (pit)
  CP E                    ; If current character is in the same room as the
                          ; Ghost...
  JR Z,41747              ; ...then skip ahead to 41747
  LD A,C                  ; If y-coordinate of Ghost's top edge...
  CP 101                  ; ...is not 101...
  JP NZ,42374             ; ...then move Ghost up one character and return
  DEC (IX+0)              ; Decrease index of Ghost's current room (to 4, room
                          ; above pit)
  LD A,121                ; Position Ghost such that the y-coordinate of its
                          ; top edge is 121...
  JR 41758                ; ...and return
; Current character and Ghost in same room (pit)
  LD A,B                  ; If y-coordinate of Ghost's bottom edge...
  CP 100                  ; ...is not 100...
  JP NZ,42374             ; ...then move Ghost up one character and return
  DEC (IX+0)              ; Decrease index of Ghost's current room (to 4, room
                          ; above pit)
  LD A,115                ; Prepare to set y-coordinate of Ghost's top edge to
                          ; 115
  LD (IX+4),A             ; Set y-coordinate of Ghost's top edge to value in A
  ADD A,6                 ; Add 6 to value in A (as Ghost is 6 characters
                          ; tall)...
  LD (IX+6),A             ; ...and set y-coordinate of Ghost's bottom edge to
                          ; value in A
  RET                     ; Return

; Update State of Cannon and Projectile
;
; Used by the routine at 41211.
  CALL 41961              ; Update State of Cannon's Projectile
  LD IX,45508             ; Load IX with address of complex state data for
                          ; Cannon (Level 4)
  BIT 2,(IX+9)            ; If Cannon's Just Loaded Flag is reset...
  JR Z,41805              ; ...then skip ahead to 41805
  DEC (IX+12)             ; Decrease Cannon's Fire Timer...
  JR Z,41791              ; ...and if now zero then skip ahead to 41791
  LD BC,42519             ; Set Cannon's graphic layout data address to point
                          ; to graphic layout data for Cannon (Rocking) and
                          ; return...
  JP 42512                ; ...
  RES 2,(IX+9)            ; Reset Cannon's Just Loaded Flag
  LD (IX+12),50           ; Set Cannon's Fire Timer to 50
  LD BC,42530             ; Set Cannon's graphic layout data address to point
                          ; to graphic layout data for Cannon (Dormant) and
                          ; return...
  JP 42512                ; ...
; Cannon's Just Loaded Flag is reset, so Cannon has finished its rocking phase.
  LD A,(34209)            ; If Cannon has no ammunition...
  OR A                    ; ...
  JR Z,41799              ; ...then jump to 41799 (Cannon dormant)
  BIT 5,(IX+10)           ; If Cannon has its Is Being Carried Flag set...
  JR NZ,41799             ; ...then jump to 41799 (Cannon dormant)
  LD IY,(34240)           ; Load IY with address of current level's complex
                          ; state data for Berk
  LD A,(IX+0)             ; If Berk's current room is the same as the Cannon's
                          ; room...
  CP (IY+0)               ; ...
  JR Z,41833              ; ...then skip ahead to 41833
  JR C,41860              ; If index of Berk's current room is greater than the
                          ; index of the Cannon's room then skip ahead to 41860
  JR 41871                ; Skip ahead to 41871
; Berk and Cannon in same room
  LD A,(IX+7)             ; If x-coordinate of Cannon's right side is smaller
                          ; than x-coordinate of Berk's left side (i.e. Cannon
                          ; is to left of Berk)...
  CP (IY+5)               ; ...
  JR C,41860              ; ...then skip ahead to 41860
  LD A,(IY+7)             ; If x-coordinate of Berk's right side is smaller
                          ; than x-coordinate of Cannon's left side (i.e.
                          ; Cannon is to right of Berk)...
  CP (IX+5)               ; ...
  JR C,41871              ; ...then skip ahead to 41871
; Berk and Cannon overlapping horizontally
  LD E,1                  ; Load E with 1 (as Projectile will appear one
                          ; character to the right of the Cannon's coordinate
                          ; position)
  LD (IX+9),0             ; Prepare to set Projectile's state to zero (fired
                          ; vertically)
  LD BC,42530             ; Load BC with graphic layout data address for Cannon
                          ; (Upright)
  JR 41880                ; Skip ahead to 41880
; Berk is to the right of the Cannon
  LD (IX+9),1             ; Prepare to set Projectile's state to 1 (fired left)
  LD E,2                  ; Load E with 2 (as Projectile will appear two
                          ; characters to the right of the Cannon's coordinate
                          ; position)
  LD BC,42556             ; Load BC with graphic layout data address for Cannon
                          ; (Tilted Right)
  JR 41880                ; Skip ahead to 41880
; Berk is to the left of the Cannon
  LD (IX+9),2             ; Prepare to set Projectile's state to 2 (fired
                          ; right)
  LD BC,42594             ; Load BC with graphic layout data address for Cannon
                          ; (Tilted Left)
  LD E,0                  ; Load E with 0 (as Projectile will appear at the
                          ; same x-coordinate as in the Cannon's coordinate
                          ; position)
  CALL 42512              ; Set Cannon's graphic layout data address to value
                          ; in BC
  LD A,(IX+1)             ; If Cannon's depth is 2...
  CP 2                    ; ...
  RET Z                   ; ...then return (Cannon won't fire if it is placed
                          ; behind Berk)
  LD A,(IX+12)            ; If Cannon's Fire Timer is at zero...
  OR A                    ; ...
  JR Z,41899              ; ...then skip ahead to 41899
  DEC (IX+12)             ; Decrease Cannon's Fire Timer
  RET                     ; Return
; Cannon's Fire Timer is at zero
  LD HL,34209             ; Decrease ammunition level of Cannon (Level 4) by
                          ; one...
  DEC (HL)                ; ...
  LD (IX+12),50           ; Set Cannon's Fire Timer to 50
  LD IY,45599             ; Load IY with address of complex state data for
                          ; Cannon's Projectile
  LD A,(IX+5)             ; Set x-coordinate of Projectile's left and right
                          ; sides to E plus x-coordinate of Cannon's left
                          ; side...
  ADD A,E                 ; ...
  LD (IY+5),A             ; ...
  LD (IY+7),A             ; ...
  LD A,(IX+4)             ; Set y-coordinates of top and bottom of Projectile
                          ; to be one less than Cannon's top y-coordinate...
  DEC A                   ; ...
  LD (IY+4),A             ; ...
  LD (IY+6),A             ; ...
  LD A,(IX+0)             ; Set Projectile's room to same as Cannon's Room...
  LD (IY+0),A             ; ...
  LD (IY+1),1             ; Set Projectile's depth to 1
  LD A,(IX+9)             ; Set Projectile's state to value prepared
                          ; previously...
  LD (IY+9),A             ; ...
  LD (IY+12),251          ; Set Projectile's y-velocity to -5
  LD BC,51483             ; Set Projectile's graphic layout data address to
                          ; that for Explosion (Bubo's Projectile / fallen
                          ; drips, Level 4)...
  LD (IY+2),C             ; ...as Projectile is launched from Cannon in an
                          ; explosion...
  LD (IY+3),B             ; ...
  RET                     ; Return

; Update State of Cannon's Projectile
;
; Used by the routine at 41767.
  LD IX,45599             ; Load IX with address of complex state data for
                          ; Cannon's Projectile
  LD A,(IX+1)             ; If Projectile's depth is zero...
  OR A                    ; ...
  RET Z                   ; ...then return
  LD BC,49699             ; Set Projectile's graphic layout data address to
                          ; that of drip stage 8, disconnected and falling
                          ; (ball)...
  CALL 42512              ; ...
  LD A,(IX+9)             ; If Projectile's state is zero (fired vertically)...
  OR A                    ; ...
  JR Z,42015              ; ...then skip ahead to 42015
  CP 8                    ; If Projectile's state is not 8 (finished)...
  JR NZ,41991             ; ...then skip ahead to 41991
  LD (IX+1),0             ; Set Projectile's depth to 0
  RET                     ; Return
  CP 2                    ; If Projectile's state is not 2 (fired right)...
  JR NZ,42006             ; ...then skip ahead to 42006
; Projectile flying left
  CALL 42447              ; Move entity left two characters...
  CALL 42447              ; ...
  CALL 54348              ; Move entity at IX into room to the left, if
                          ; appropriate
  JR 42015                ; Skip ahead to 42015
; Projectile flying right
  CALL 42505              ; Move entity right two characters...
  CALL 42505              ; ...
  CALL 54313              ; Move entity at IX into room to the right, if
                          ; appropriate
; Update Projectile's vertical velocity
  LD A,(IX+12)            ; Load Projectile's velocity into A and E...
  LD E,A                  ; ...
  ADD A,(IX+4)            ; Add velocity to y-coordinates of top and bottom of
                          ; projectile...
  LD (IX+4),A             ; ...
  LD (IX+6),A             ; ...
  INC (IX+12)             ; Increase velocity by one (initially negative so
                          ; will accelerate downwards)
  LD A,E                  ; If velocity (before increase) was not 5...
  CP 5                    ; ...i.e. projectile has not yet fallen back to
                          ; floor-level...
  RET NZ                  ; ...then return
  LD (IX+9),8             ; Set Projectile's state to 8 (finished)
  LD BC,51483             ; Set Projectile's graphic layout data address to
                          ; that of explosion (Bubo's Projectile / fallen
                          ; drips, Level 4)...
  CALL 42512              ; ...
  CALL 54768              ; Check entity at IX for collision with another
                          ; entity at same depth whose Interaction (11,6) Flag
                          ; is set...
  RET C                   ; ...and if no collision occurred, then return
  CP 36                   ; If collision was not with entity of class 36
                          ; (skeleton, Level 4)...
  JR NZ,42058             ; ...then skip ahead to 42058
  LD HL,45413             ; Set Skeleton's Is Dying Flag...
  SET 1,(HL)              ; ...
  CP 31                   ; If collision was with entity of class 31 (Berk)...
  CALL Z,53667            ; ...then set "Berk Has Been Killed" Flag
  RET                     ; Return

; Update States of Drips (Level 4)
;
; Used by the routine at 41211.
  LD IX,45521             ; Load IX with address of complex state data for
                          ; first drip (Level 4)
  LD B,6                  ; Load B with 6 (as there are 6 drips to process)
  PUSH BC                 ; Store BC (B = Remaining number of drips to process)
  LD A,(IX+12)            ; If current drip's velocity factor is not zero...
  OR A                    ; ...
  JR NZ,42128             ; ...then skip ahead to 42128 (handle drip's fall)
  LD A,(IX+9)             ; If current drip's stage is not 8...
  CP 8                    ; ...
  JR NZ,42092             ; ...then skip ahead to 42092
  LD A,(IX+8)             ; Reset current drip's complex state data to values
                          ; stored in Table of Initial-State Data...
  CALL 53994              ; ...
  JR 42119                ; Advance IX to next entry in complex state data and
                          ; loop back to 42070
  CP 7                    ; If drip's stage is not 7...
  JR NZ,42102             ; ...then skip ahead to 42102
  LD (IX+12),1            ; Set current drip's velocity factor to 1
  JR 42119                ; Advance IX to next entry in complex state data and
                          ; loop back to 42070
  LD C,A                  ; Load drip's stage into C
  LD A,15                 ; Load A with a random number, 0-14...
  CALL 54222              ; ...
  OR A                    ; If A is not zero (14 in 15 chance)...
  JR NZ,42119             ; ...then advance IX to next entry in complex state
                          ; data and loop back to 42070
  LD A,C                  ; Load drip's stage back into A...
  INC A                   ; ...and add one
  LD (IX+9),A             ; Store updated drip stage value
  CALL 42251              ; Set drip's graphic layout data pointer to stage A
                          ; graphic
  LD DE,13                ; Load DE with 13 (as entries are 13 bytes wide)
  ADD IX,DE               ; Advance IX to next drip's complex state data
  POP BC                  ; Restore BC (B = Remaining number of drips to
                          ; process)
  DJNZ 42070              ; Loop back to 42070
  RET                     ; Return
; Drip's velocity factor is not zero
  INC (IX+12)             ; Increase drip's velocity factor
  LD (IX+1),1             ; Set drip's depth to 1
  LD IY,45508             ; Load IY with address of complex state data for
                          ; Cannon (Level 4)
  LD B,A                  ; Load B with drip's velocity factor
  LD A,(IY+0)             ; Load Cannon's current room
  CP (IX+0)               ; If Cannon is in a different room to the drip...
  JR NZ,42190             ; ...then skip ahead to 42190
  LD A,(IY+1)             ; If Cannon's depth is not 1...
  CP 1                    ; ...
  JR NZ,42190             ; ...then skip ahead to 42190
  LD A,(IY+5)             ; If x-coordinate of Cannon's left side...
  INC A                   ; ...plus one...
  CP (IX+5)               ; ...is not the same as the x-coordinate of the
                          ; drip's left side...
  JR NZ,42190             ; ...then skip ahead to 42190
  LD A,(IY+4)             ; If y-coordinate of top Cannon's top...
  CP (IX+4)               ; ...is not the same as the y-coordinate of the
                          ; drip's top...
  JR NZ,42215             ; ...then skip ahead to 42215
  LD A,(34209)            ; Increase Cannon's ammunition level by 10...
  ADD A,10                ; ...
  LD (34209),A            ; ...
  SET 2,(IY+9)            ; Set Cannon's Just Loaded Flag
  LD (IY+12),20           ; Set Cannon's Fire Timer to 20
  JR 42084                ; Reset current drip's state and loop back to 42070
                          ; for next drip
  CALL 54768              ; Check entity at IX for collision with another
                          ; entity at same depth whose Interaction (11,6) Flag
                          ; is set...
  CP 31                   ; ...and if collision was not with entity of class 31
                          ; (Berk)...
  JR NZ,42215             ; ...then skip ahead to 42215
  CALL 53667              ; Set "Berk Has Been Killed" Flag
  LD A,8                  ; Set drip's graphical stage to 8 (exploding on
                          ; contact)...
  LD (IX+9),A             ; ...and also set drip's stage to 8...
  CALL 42251              ; ...
  LD (IX+12),0            ; Set drip's velocity factor to zero
  JP 42119                ; Advance IX to next entry in complex state data and
                          ; loop back to 42070
  LD A,(IX+4)             ; If y-coordinate of top of drip is 120...
  CP 120                  ; ...
  JR Z,42200              ; ...then loop back to 42200 (make drip explode and
                          ; process next drip)
  INC (IX+4)              ; Move drip down one character...
  INC (IX+6)              ; ...
  DJNZ 42140              ; Decrease B (velocity factor) and loop back to 42140
                          ; if not zero
  JP 42119                ; Advance IX to next entry in complex state data and
                          ; loop back to 42070

; Addresses of Graphic Layout Data for Drips (Level 4)
;
; Used by the routine at 42251.
  DEFW 50800              ; Stage 0 - Blank
  DEFW 49600              ; Stage 1 - Green drip forming
  DEFW 49615              ; Stage 2 - Red drip enlarging
  DEFW 49630              ; Stage 3 - Magenta drip enlarging
  DEFW 49645              ; Stage 4 - Cyan drip enlarging
  DEFW 49663              ; Stage 5 - Yellow drip full size
  DEFW 49681              ; Stage 6 - Yellow drip extended
  DEFW 49699              ; Stage 7 - Drip disconnected and falling
  DEFW 51483              ; Stage 8 - Drip exploding on contact

; Set a Drip's (Level 4) Stage to A
;
; Used by the routine at 42064. Input:  A  Index of drip state (0-8) IX
; Address of complex state data for a drip (level 4)
  ADD A,A                 ; Double index of drip state...
  LD C,A                  ; ...and load into BC...
  LD B,0                  ; ...
  LD HL,42233             ; Point HL at start of table of Addresses of Graphic
                          ; Layout Data for Drips (Level 4)
  ADD HL,BC               ; Add BC to HL as offset
  LD C,(HL)               ; Load address (of graphic layout data) at this
                          ; location into BC...
  INC HL                  ; ...
  LD B,(HL)               ; ...
  CALL 42512              ; Set drip's graphic layout data address to BC
  RET                     ; Return

; Update State of Flying Skeleton Creature (Level 4)
;
; Used by the routine at 41211.
  LD IX,45482             ; Load IX with address of complex state data for
                          ; Flying Skeleton Creature (Level 4)
  CALL 54768              ; Check entity at IX for collision with another
                          ; entity at same depth whose Interaction (11,6) Flag
                          ; is set...
  CP 31                   ; ...and if collision was not with entity of class 31
                          ; (Berk)...
  JR NZ,42285             ; ...then skip ahead to 42285
  LD A,(45401)            ; If Berk's Can Fall Flag is reset...
  BIT 6,A                 ; ...
  CALL Z,53667            ; ...then set "Berk Has Been Killed" Flag
  LD HL,45491             ; Load HL with address of Flying Skeleton Creature's
                          ; flags
  BIT 0,(HL)              ; If creature's Horizontal Direction Flag is set
                          ; (moving left)...
  JR NZ,42320             ; ...then skip ahead to 42320
; Horizontal Direction Flag reset (moving right)
  LD A,(IX+0)             ; If creature's room is not 4 (Fake Boni's Room)...
  CP 4                    ; ...
  JR NZ,42309             ; ...then skip ahead to 42309
  LD A,(IX+7)             ; If x-coordinate of creature's right edge is less
                          ; than 126...
  CP 126                  ; ...
  JR C,42309              ; ...then skip ahead to 42309
  SET 0,(HL)              ; Set creature's Horizontal Direction Flag (moving
                          ; left)
  RET                     ; Return
  INC (IX+5)              ; Move creature right one character...
  INC (IX+7)              ; ...
  CALL 54313              ; ...and move into room to the right, if appropriate
  JR 42346                ; Skip ahead to 42346
; Horizontal Direction Flag set (moving left)
  LD A,(IX+0)             ; If creature's room is not 1 (Door Room)...
  CP 1                    ; ...
  JR NZ,42337             ; ...then skip ahead to 42337
  LD A,(IX+5)             ; If x-coordinate of creature's left edge is at least
                          ; 108...
  CP 108                  ; ...
  JR NC,42337             ; ...then skip ahead to 42337
  RES 0,(HL)              ; Reset creature's Horizontal Direction Flag (moving
                          ; right)
  RET                     ; Return
  DEC (IX+5)              ; Move creature left one character...
  DEC (IX+7)              ; ...
  CALL 54348              ; ...and move into room to the left, if appropriate
  LD A,(IX+4)             ; Load A with y-coordinate of creature's top edge
  BIT 1,(HL)              ; If creature's Vertical Direction Flag is set
                          ; (moving up)...
  JR NZ,42367             ; ...then skip ahead to 42367
; Vertical Direction Flag reset, moving down
  CP 108                  ; If y-coordinate of creature's top edge is not
                          ; 108...
  JR NZ,42360             ; ...then skip ahead to 42360
  SET 1,(HL)              ; Set creature's Vertical Direction Flag (moving up)
  RET                     ; Return
; This entry point is used by the routine at 41633.
  INC (IX+4)              ; Move creature down one character...
  INC (IX+6)              ; ...
  RET                     ; Return
; Vertical Direction Flag set, moving up
  CP 100                  ; If y-coordinate of creature's top edge is not
                          ; 100...
  JR NZ,42374             ; ...then skip ahead to 42374
  RES 1,(HL)              ; Reset creature's Vertical Direction Flag (moving
                          ; down)
  RET                     ; Return
; This entry point is used by the routine at 41633.
  DEC (IX+4)              ; Move creature up one character...
  DEC (IX+6)              ; ...
  RET                     ; Return

; Update State of Snake (Level 4)
;
; Used by the routine at 41211.
  LD IX,45495             ; Point IX at start of state data for Snake (Level 4)
  LD IY,(34240)           ; Load IY with address of current level's complex
                          ; state data for Berk
  LD HL,45507             ; Load HL with address of Snake's Attack Progress
                          ; Index
  LD A,(HL)               ; If Snake's Attack Progress Index is not zero...
  OR A                    ; ...
  JR NZ,42415             ; ...then skip ahead to 42415
; Snake's Attack Progress Index is zero
  LD A,(IY+0)             ; If Berk's room is not 5 (Snake's room)...
  CP 5                    ; ...
  RET NZ                  ; ...then return
  BIT 7,(IY+12)           ; If Berk's Is Jumping Flag is set...
  JR NZ,42413             ; ...then skip ahead to 42413
  BIT 0,(IY+9)            ; If Snake's Must Process Current Script Data Flag is
                          ; set...
  RET NZ                  ; ...then return
  INC (HL)                ; Increase Snake's Attack Progress Index
  RET                     ; Return
; Snake's Attack Progress Index is not zero
  CP 8                    ; If Snake's Attack Progress Index is less than 8...
  JR C,42454              ; ...then jump to 42454 (Snake moving right)
  CP 15                   ; If Snake's Attack Progress Index is less than 15...
  JR C,42459              ; ...then jump to 42459 (Snake preparing to pounce)
  CP 17                   ; If Snake's Attack Progress Index is less than 17...
  JR C,42461              ; ...then jump to 42461 (Snake pouncing)
  JR Z,42480              ; If Snake's Attack Progress Index is 17 then jump to
                          ; 42480 (Snake finished pouncing)
; Snake's Attack Progress Index is greater than 17
  LD (HL),20              ; Set Snake's Attack Progress Index to 20
  LD BC,42648             ; Set Snake's graphic layout data address to 42648...
  CALL 42512              ; ...(Snake, mouth closed, with animated tongue)
  LD A,(IX+5)             ; If x-coordinate of Snake's left edge is not 83...
  CP 83                   ; ...
  JR NZ,42447             ; ...then move Snake left one character and return
  LD (HL),0               ; Set Snake's Attack Progress Index to 0
  RET                     ; Return
; This entry point is used by the routine at 41961.
  DEC (IX+5)              ; Decrease x-coordinates of left and right edges of
                          ; entity at IX by one...
  DEC (IX+7)              ; ...
  RET                     ; Return
; Snake's Attack Progress Index is less than 8
  INC (HL)                ; Increase Snake's Attack Progress Index
  CALL 42505              ; Move Snake right one character
  RET                     ; Return
; Snake's Attack Progress Index is 8 or more, but less than 15
  INC (HL)                ; Increase Snake's Attack Progress Index
  RET                     ; Return
; Snake's Attack Progress Index is 15 or more, but less than 17
  LD A,(IY+6)             ; If the y-coordinate of Berk's bottom edge is less
                          ; than 116...
  CP 116                  ; ...
  JR C,42429              ; ...then jump back to 42429
  CALL 42486              ; Open Snake's mouth and set Berk Has Been Killed
                          ; Flag if Snake and Berk have collided
  LD B,4                  ; Move Snake right four characters...
  CALL 42505              ; ...
  DJNZ 42473              ; ...
  INC (HL)                ; Increase Snake's Attack Progress Index
  RET                     ; Return
; Snake's Attack Progress Index is 17
  CALL 42486              ; Open Snake's mouth and set Berk Has Been Killed
                          ; Flag if Snake and Berk have collided
  LD (HL),20              ; Set Snake's Attack Progress Index to 20
  RET                     ; Return

; Open Snake's Mouth and Set Berk Has Been Killed Flag if Snake and Berk Have
; Collided
;
; Used by the routine at 42381. Input:  HL  Address of Snake's Attack Progress
; Index IX  Address of complex state data for Snake (Level 4)
  LD BC,42703             ; Set Snake's graphic layout data address to 42703...
  CALL 42512              ; ...(Snake, mouth open, attacking)
  CALL 54768              ; Check entity at IX for collision with another
                          ; entity at same depth whose Interaction (11,6) Flag
                          ; is set...
  CP 31                   ; ...and if collision was not with entity of class 31
                          ; (Berk)...
  RET NZ                  ; ...then return
  POP BC                  ; Remove top value from stack (i.e. return address to
                          ; routine that called this routine)
  LD (HL),18              ; Set Snake's Attack Progress Index to 18
  CALL 53667              ; Set "Berk Has Been Killed" Flag
  RET                     ; Return

; Move Entity at IX Right One Character
;
; Used by the routines at 41961 and 42381.
  INC (IX+7)              ; Increase x-coordinates of left and right edges of
                          ; entity at IX by one...
  INC (IX+5)              ; ...
  RET                     ; Return

; Set Graphic Layout Data Address for Entity at IX to BC
;
; Used by the routines at 41767, 41961, 42251, 42381 and 42486. Input:  BC
; Holds address of graphic layout data
  LD (IX+2),C             ; Set current entity's graphic layout data address to
                          ; BC...
  LD (IX+3),B             ; ...
  RET                     ; Return

; Graphic Layout Data Cannon (Level 4) Loaded (Animated)
  DEFB 243,0,4            ; Increase current state value n (initially 0), up to
                          ; maximum of 4, resetting to zero if maximum reached
                          ; and jump to n-th address in following list:
  DEFB 34,166             ; 42530 (Cannon, straight)
  DEFB 60,166             ; 42556 (Cannon, tilted right)
  DEFB 34,166             ; 42530 (Cannon, straight)
  DEFB 98,166             ; 42594 (Cannon, tilted left)
; Straight
  DEFB 244,12             ; Set current graphic set to 12
