; Populate Primary Display Buffer with Layout Data for Current Character's
; Current Room
;
; Used by the routine at 34438.
  LD HL,(34279)           ; Modify instruction at 46045 with address of Primary
                          ; Display Buffer...
  LD (46046),HL           ; ...
  LD A,(34230)            ; Load C with depth of current character's current
                          ; room...
  LD C,A                  ; ...
  LD A,(34218)            ; Load B with index of current character's current
                          ; room...
  LD B,A                  ; ...
  LD D,0                  ; Load D with zero
; Start drawing simple entities
  LD IX,(34236)           ; Load IX with start address of current level's
                          ; simple state data
  LD E,6                  ; Load DE with 6 (as simple state data entries are 6
                          ; bytes wide)
  LD A,(IX+0)             ; Load first byte of current simple state data entry
                          ; into A
  CP 255                  ; If this is 255 (end marker for complex state
                          ; data)...
  JR Z,45961              ; ...then skip ahead to 45961
  CP 254                  ; If it is not 254 (end marker for level's simple
                          ; state data)...
  JR NZ,45939             ; ...then skip ahead to 45939
; At this point, we have passed the end marker for the simple state data block
; and are now at the start of the complex state data block whose entries are 13
; bytes wide.
  LD E,13                 ; Load DE with 13
  INC IX                  ; Advance IX to start of complex state data block
  LD A,(IX+0)             ; Load A with entity's room index
; At this point, A holds the index of the room to which the simple or complex
; entity belongs
  CP B                    ; If entity's room is not the same as the current
                          ; character's current room...
  JR NZ,45957             ; ...then skip ahead to 45957
  LD A,C                  ; If entity's depth is not the same as current depth
                          ; in C...
  CP (IX+1)               ; ...
  JR NZ,45957             ; ...then skip ahead to 45957
  EXX                     ; Switch registers
  PUSH IX                 ; Store IX (pointer to current entry in
                          ; simple/complex state data)
  CALL 45965              ; Load Primary Display Buffer with graphic layout
                          ; data for current entity
  POP IX                  ; Restore IX (pointer to current entry in
                          ; simple/complex state data)
  EXX                     ; Switch registers
  ADD IX,DE               ; Advance IX to next entity's state data
  JR 45921                ; Loop back to 45921
  DEC C                   ; Decrease current depth (i.e. closer to screen)
  JR NZ,45915             ; If depth is not zero (i.e. still depth levels to
                          ; process) then loop back to 45915
  RET                     ; Return

; Populate Primary Display Buffer with Graphic Layout Data for Entity Whose
; Simple / Complex State Data is at Address in IX
;
; Used by the routine at 45899. Input:  IX  Address of complex state data for
; an entity IX  (Entry at 45999, 46001 or 46003 only) Address of graphic layout
; data to draw B  (Entry at 45999, 46001 or 46003 only) 0 if current position
; in Display Buffer needs to be recalculated. 1 otherwise.
  LD E,(IX+2)             ; Load DE with address of graphic layout data for
                          ; entity...
  LD D,(IX+3)             ; ...
  LD A,(34233)            ; Load A with y-coordinate of top edge of current
                          ; character's current room...
  ADD A,(IX+4)            ; ...add y-coordinate of graphic element to draw as
                          ; offset...
  SUB 100                 ; ...subtract 100...
  LD L,A                  ; ...and load into L
  LD A,(34231)            ; Load A with x-coordinate of left edge of current
                          ; character's current room...
  ADD A,(IX+5)            ; ...add x-coordinate of graphic element to draw as
                          ; offset...
  SUB 100                 ; ...subtract 100...
  LD H,A                  ; ...and load into H
  LD (34281),HL           ; Store x- and y-coordinates at 34281
  PUSH DE                 ; Transfer address of graphic layout data in
                          ; simple/complex state data from DE...
  POP IX                  ; ...into IX
  LD B,0                  ; Reset Do Not Recalculate Display Buffer Address
                          ; Flag, as address not yet calculated
  JR 46003                ; Jump to 46003 (read / process data at address in
                          ; IX)
; This entry point is used by the routines at 46427, 46442, 46460 and 46599.
  INC IX                  ; Advance IX by one byte
; This entry point is used by the routines at 46284, 46295 and 46306.
  INC IX                  ; Advance IX by one byte
; This entry point is used by the routines at 46317, 46347, 46363, 46460,
; 46481, 46495, 46611, 46628, 46647 and 46664.
  LD A,(IX+0)             ; If first byte of graphic layout data entry is at
                          ; least 236...
  CP 236                  ; ...i.e. IX points to an instruction...
  JP NC,46218             ; ...then jump to appropriate graphic layout routine
; At this point, the graphic layout data pointed to by IX is graphical data,
; not an instruction. We only draw the graphics if they lie within the display
; area (i.e. have x- and y-coordinates less than 32 and 24 respectively, see
; trivia).
  LD A,H                  ; If x-coordinate of graphic to draw is 32 or more...
  CP 32                   ; ...
  JP NC,46151             ; ...then skip ahead to 46151
  LD A,L                  ; If y-coordinate of graphic to draw is 24 or more...
  CP 24                   ; ...
  JP NC,46151             ; ...then skip ahead to 46151
  PUSH HL                 ; Store HL (H = x-coordinate to draw to, L =
                          ; y-coordinate to draw to)
  DEC B                   ; Decrease value of Don't Recalculate Display Buffer
                          ; Address Flag
  JP Z,46051              ; If B is zero (i.e. we don't need to recalculate
                          ; current position in display buffer), then skip
                          ; ahead to 46051
; If B was 1, then we need to load DE with the address of the current position
; in the Primary Display Buffer.
  LD A,H                  ; Load C with three times entity's x-coordinate...
  ADD A,A                 ; ...
  ADD A,H                 ; ...
  LD C,A                  ; ...
  LD A,L                  ; Load DE with double entity's y-coordinate...
  ADD A,A                 ; ...
  LD E,A                  ; ...
  LD D,0                  ; ...
  LD B,D                  ; Set B to zero (BC now holds three times
                          ; x-coordinate)
  LD HL,46170             ; Point HL at start of Table of Multiples of 96
  ADD HL,DE               ; Add double y-coordinate as offset
  LD E,(HL)               ; Load DE with corresponding multiple of 96...
  INC HL                  ; ...
  LD D,(HL)               ; ...
; The operand of the instruction at 46045 represents the address of the Primary
; Display Buffer. This is modified by the instruction at 45902.
  LD HL,0                 ; Load HL with start address of Primary Display
                          ; Buffer
  ADD HL,DE               ; Move HL to position in Primary Display Buffer
                          ; corresponding to x- and y-coordinates of entity...
  ADD HL,BC               ; ...
  EX DE,HL                ; Switch DE (now points to position in Primary
                          ; Display Buffer for current entity) and HL
  LD A,(DE)               ; Load A with Graphic Set Index plus one from this
                          ; entry in Primary Display Buffer...
  INC A                   ; ...and if value is now zero (i.e. old value was 255
                          ; corresponding to a block outside dimensions of
                          ; room)...
  JP Z,46150              ; ...then skip ahead to 46150
  LD A,(34268)            ; Load current Graphic Set Index into this location
                          ; in Primary Display Buffer...
  LD (DE),A               ; ...
  INC DE                  ; Advance to Graphic Index in current character
                          ; block's entry in Primary Display Buffer
  LD A,(IX+0)             ; Load Graphic Index into current Display Buffer
                          ; location...
  LD (DE),A               ; ...
  INC DE                  ; Advance to next byte in current character block's
                          ; display buffer entry (Attribute)
  LD A,(34270)            ; Load Current Attribute into A...
  OR A                    ; ...and if not zero...
  JR NZ,46077             ; ...then skip ahead to 46077
; Current Attribute is zero (i.e. not set) so DE points to attribute data
  INC IX                  ; Advance IX to next byte in graphic layout data
                          ; (attribute)...
  LD A,(IX+0)             ; ...and load into A
; At this point, A holds an attribute value either from the graphic layout
; data, or the Current Attribute as stored at 34270. This attribute is to be
; applied to the current display buffer location. IX (current position in
; graphic layout data) is pointing to either the graphic index (if the Current
; Attribute at 34270 is set) or the attribute data (if the Current Attribute is
; not set). In either case, IX+1 is the address of the Cursor Shift byte. Bit 7
; of the Cursor Shift byte is the Override Attribute Flag.
  BIT 7,(IX+1)            ; If bit 7 (Override Attribute Flag) is set...
  JP NZ,46111             ; ...then skip ahead to 46111
; Override Attribute Flag reset
  LD L,A                  ; Load L with attribute value
  AND 56                  ; Check PAPER bits
  LD A,L                  ; Restore attribute value to A
  JP NZ,46111             ; If PAPER is not zero (i.e. black) then skip ahead
                          ; to 46111
; The instructions between 46091 and 46110 (inclusive) are executed only when
; the PAPER component of the attribute in A (and L) is black. If the Preserve
; INK Flag is reset in the attribute value loaded (at 46098) from the Display
; Buffer, then the instruction at 46107 will leave the reset (i.e. black) PAPER
; bits in A. If the Preserve INK Flag is set, then the instructions between
; 46104 and 46106 (inclusive) will shift the bits used for INK into the PAPER
; positions and this PAPER colour (originally INK colour) will be preserved
; when the instruction at 46107 is executed.
  AND 192                 ; Reset all bits except Preserve INK and Mirror flags
  LD B,A                  ; Load B with Preserve INK and Mirror flags
  LD A,L                  ; Restore attribute value to A
  AND 63                  ; Reset bits Preserve INK and Mirror flags
  LD C,A                  ; Load C with INK and PAPER bits of attribute value
  LD A,(DE)               ; Load value currently in Display Buffer into A...
  BIT 6,A                 ; ...and if Preserve INK Flag is reset...
  JP Z,46107              ; ...then skip ahead to 46107
; Preserve INK Flag set in Display Buffer
  ADD A,A                 ; Shift INK bits into PAPER bits...
  ADD A,A                 ; ...
  ADD A,A                 ; ...
  AND 56                  ; Reset all except PAPER bits
  OR B                    ; (Re)set Preserve INK and Mirror flags as stored in
                          ; B previously
  OR C                    ; Set INK bits as stored in C previously (PAPER was
                          ; black)
  LD (DE),A               ; Load attribute in A into Display Buffer
  POP HL                  ; Restore HL (H = x-coordinate to draw to, L =
                          ; y-coordinate to draw to)
; Read Cursor Shift byte. Bits 0-6 of this byte control where the cursor to
; write to Primary Display Buffer is moved to after writing the current
; character block. A value of 33 advances the cursor right by one character. A
; value, n, less than 33 moves the cursor down a character row, and left by
; 33-(n+1) characters. A value greater than 33 moves the cursor right by
; (n+1)-33 characters. Bit 7 is the Override Attribute Flag.
  LD A,(IX+1)             ; Load A with Cursor Shift byte...
  CP 255                  ; ...and if this is 255 (End Marker)...
  JP Z,46418              ; ...then jump to 46418 (load HL with stored
                          ; coordinates from 34281 and return from drawing)
  AND 127                 ; Reset bit 7 (Override Attribute Flag)
  SUB 33                  ; Subtract 33, and if remaining value is 0 (i.e.
                          ; original value was 33)...
  JP Z,46140              ; ...then skip ahead to 46140...
  JP NC,46132             ; ...else, if value was greater than 33 then skip
                          ; ahead to 46132
; Cursor Shift byte was less than 33 (move the cursor down a character row, and
; left by 33-(n+1) characters)
  INC L                   ; Increase y-coordinate
  INC A                   ; Increase A (x-coordinate offset) and add to
                          ; x-coordinate...
  ADD A,H                 ; ...
  LD H,A                  ; ...
  LD B,0                  ; Prepare to recalculate Display Buffer address as
                          ; change in coordinates is non-trivial
  JP 45999                ; Advance graphic layout data pointer by two bytes
                          ; and read / process next data
; Cursor Shift byte was 33 (move the cursor right by one character)
  INC DE                  ; Advance pointer to start of next entry in Primary
                          ; Display Buffer
  INC H                   ; Increase x-coordinate by one
  JP Z,46135              ; If x-coordinate is zero then jump back to 46135
                          ; (see trivia)
  LD B,1                  ; Prepare to skip over recalculation of Display
                          ; Buffer address as we moved right one character
  JP 45999                ; Advance graphic layout data pointer by two bytes
                          ; and read / process next data
; First byte in Primary Display Buffer entry for current position is 255 (i.e.
; outside dimensions of room)
  POP HL                  ; Restore HL (H = x-coordinate to draw to, L =
                          ; y-coordinate to draw to)
  LD A,(34270)            ; Load Current Attribute into A...
  OR A                    ; ...and if not zero...
  JP NZ,46160             ; ...then skip ahead to 46160
  INC IX                  ; Advance IX to next byte in graphic layout data
                          ; (attribute)
  LD A,(IX+1)             ; Load A with Cursor Shift byte...
  AND 127                 ; Reset bit 7 (Override Attribute Flag)
  SUB 33                  ; Subtract 33...
  JP 46128                ; ...and jump back to 46128 to update current drawing
                          ; position

; Table of Multiples of 96
;
; Used in calculating position in Display Buffer data for a given y-coordinate
; (as Display Buffer data is 3 bytes per character block, so 1 character row's
; worth of data is 3 x 32 = 96 bytes
  DEFW 0
  DEFW 96
  DEFW 192
  DEFW 288
  DEFW 384
  DEFW 480
  DEFW 576
  DEFW 672
  DEFW 768
  DEFW 864
  DEFW 960
  DEFW 1056
  DEFW 1152
  DEFW 1248
  DEFW 1344
  DEFW 1440
  DEFW 1536
  DEFW 1632
  DEFW 1728
  DEFW 1824
  DEFW 1920
  DEFW 2016
  DEFW 2112
  DEFW 2208

; Jump to Appropriate Graphic Layout Routine
;
; Used by the routine at 45965. Input:  A  Index of graphic layout data
; instruction IX  Address of current graphic layout data instruction
  INC IX                  ; Advance IX to first parameter byte in graphic
                          ; layout data
  SUB 236                 ; Subtract 236 to get zero-based index of required
                          ; instruction
  ADD A,A                 ; Load double index of graphic layout data
                          ; instruction into BC...
  LD C,A                  ; ...
  LD B,0                  ; ...
  PUSH HL                 ; Store HL
  LD HL,46244             ; Point HL at start of Table of Addresses of Graphic
                          ; Layout Data Handling Routines
  ADD HL,BC               ; Add doubled instruction index as offset to HL to
                          ; point to address of required routine
  LD A,(HL)               ; Modify JP instruction at 46241 with this address...
  LD (46242),A            ; ...
  INC HL                  ; ...
  LD A,(HL)               ; ...
  LD (46243),A            ; ...
  POP HL                  ; Restore HL
; The operand of the instruction at 46241 represents the addresses of the
; required graphic layout data handling routine. This is modified by the
; instruction at 46232.
  JP 0                    ; Jump to appropriate instruction handling routine

; Table of Addresses of Graphic Layout Data Handling Routines
;
; Graphic layout data is stored in the form of encoded instructions. Generally
; an instruction is simply to display a graphic of given index with a given
; attribute and then to advance the position of the drawing "cursor". If the
; first byte (normally the graphic index) is 236 or greater, however, then we
; are dealing with a special instruction; the values 236 and above can be
; considered to be opcodes. These opcodes correspond to calls/jumps to routines
; at addresses stored in this table. The opcodes all take different
; combinations of parameters.
  DEFW 46317              ; (236)
  DEFW 46284              ; (237)
  DEFW 46611              ; (238)
  DEFW 46628              ; (239)
  DEFW 46647              ; (240)
  DEFW 46664              ; (241)
  DEFW 46295              ; (242)
  DEFW 46559              ; (243)
  DEFW 46306              ; (244)
  DEFW 46347              ; (245)
  DEFW 46363              ; (246)
  DEFW 46577              ; (247)
  DEFW 46481              ; (248)
  DEFW 46495              ; (249)
  DEFW 46427              ; (250)
  DEFW 46460              ; (251)
  DEFW 46599              ; (252)
  DEFW 46594              ; (253)
  DEFW 46442              ; (254)
  DEFW 46418              ; (255)

; Graphic Layout Routine (237) Set New Pending Sound Input:  IX  Address of
; first parameter in current graphic layout data instruction Output: B  Do Not
; Recalculate Display Buffer Address Flag (0)
  LD A,(IX+0)             ; Load current byte of graphic layout data into A
  CALL 59613              ; Set pending sound index to A if it is currently
                          ; zero, or lower priority
  LD B,0                  ; Prepare to recalculate Display Buffer address
  JP 46001                ; Advance graphic layout data pointer by one byte and
                          ; read / process next data

; Graphic Layout Routine (242) Set Current Attribute Input:  IX  Address of
; first parameter in current graphic layout data instruction Output: B  Do Not
; Recalculate Display Buffer Address Flag (0)
  LD A,(IX+0)             ; Load current byte of graphic layout data...
  LD (34270),A            ; ...and set as current Attribute
  LD B,0                  ; Prepare to recalculate Display Buffer address
  JP 46001                ; Advance graphic layout data pointer by one byte and
                          ; read / process next data

; Graphic Layout Routine (244) Set Current Graphic Set Index Input:  IX
; Address of first parameter in current graphic layout data instruction Output:
; B  Do Not Recalculate Display Buffer Address Flag (0)
  LD A,(IX+0)             ; Load current byte of graphic layout data...
  LD (34268),A            ; ...and set as current Graphic Set Index
  LD B,0                  ; Prepare to recalculate Display Buffer address
  JP 46001                ; Advance graphic layout data pointer by one byte and
                          ; read / process next data

; Graphic Layout Routine (236) Set Graphic Index in Next Instruction to Value
; Randomly Selected from List
;
; Read Current Byte (n, random number cap), generate random number m (1 to n
; inclusive) and copy the m-th byte in following list into position after end
; of list bytes (i.e. the graphic index field of the next graphic layout data
; entry), then advance current position to this location. Input:  IX  Address
; of first parameter in current graphic layout data instruction Output: B  Do
; Not Recalculate Display Buffer Address Flag (0) IX  Address of next graphic
; layout data instruction to process
  PUSH IX                 ; Store current position in graphic layout data
  LD A,(IX+0)             ; Load current byte (Random Number Cap) from graphic
                          ; layout data into A...
  LD E,A                  ; ...and copy into E
  CALL 54222              ; Load BC with a random number, 1-A...
  INC A                   ; ...
  LD C,A                  ; ...
  LD B,0                  ; ...
  ADD IX,BC               ; Advance IX by number of bytes stored in BC
  LD A,(IX+0)             ; Load byte at this location into A
  POP IX                  ; Restore previous position in graphic layout data
  LD C,E                  ; Load Random Number Cap into BC...
  INC C                   ; ...and add one
  ADD IX,BC               ; Advance IX by this number of bytes
  LD (IX+0),A             ; Store byte previously read at current position
  JP 46003                ; Read / process data at address in IX

; Graphic Layout Routine (245) Decrease Timer Value, and if Zero, Reset and
; Write Random Graphic Index from List into Next Instruction
;
; Decrease timer value (1st parameter). If now zero, then reset timer to value
; in 2nd parameter, then load one of the n (3rd parameter) following values
; chosen at random into the Graphic Index field of the next instruction. Input:
; IX  Address of first parameter in current graphic layout data instruction
; Output: B  Do Not Recalculate Display Buffer Address Flag (0) IX  Address of
; next graphic layout data instruction to process
  LD B,0                  ; Prepare to recalculate Display Buffer address
  DEC (IX+0)              ; Decrease timer value
  JR NZ,46370             ; If timer is not zero, then advance IX to start of
                          ; next instruction and process
  CALL 46385              ; Reset timer to maximum, advance IX to start of next
                          ; instruction and set value here (graphic index) to
                          ; random value from sequence of data following
                          ; previous instruction...
  LD (IX+0),E             ; ...
  JP 46003                ; Read / process data at address in IX

; Graphic Layout Routine (246) Decrease Timer Value, and if Zero, Reset and
; Write Random Attribute from List into Next Instruction
;
; Decrease timer value (1st parameter). If now zero, then reset timer to value
; in 2nd parameter, then load one of the n (3rd parameter) following values
; chosen at random into the Attribute field of the next instruction. Input: IX
; Address of first parameter in current graphic layout data instruction Output:
; B  Do Not Recalculate Display Buffer Address Flag (0) IX  Address of next
; graphic layout data instruction to process
  LD B,0                  ; Prepare to recalculate Display Buffer address
  DEC (IX+0)              ; Decrease timer value
  JR Z,46376              ; If timer is zero, then reset timer, advance to next
                          ; instruction and set that instruction's attribute to
                          ; random value from sequence
; This entry point is used by the routine at 46347.
  CALL 46409              ; Advance to next instruction and process...
  JP 46003                ; ...
  CALL 46385              ; Reset timer to maximum, advance IX to start of next
                          ; instruction and set second value here (attribute)
                          ; to random value from sequence of data following
                          ; previous instruction...
  LD (IX+1),E             ; ...
  JP 46003                ; Read / process data at address in IX

; Reset Timer to Initial Value then Load E with Random Value from Sequence (in
; Graphic Layout Data)
;
; Used by the routines at 46347 and 46363. Input:  B  Always zero IX  Current
; address in graphic layout data
  LD A,(IX+1)             ; Set current timer value to maximum...
  LD (IX+0),A             ; ...
  LD A,(IX+2)             ; Load A with number of states
  CALL 54222              ; Set C to a random number between 3 and (number of
                          ; states + 2)...
  ADD A,3                 ; ...
  LD C,A                  ; ...
  PUSH IX                 ; Store IX (current position in graphic layout data)
  ADD IX,BC               ; Advance IX by C bytes (BC = C, as B = 0)
  LD E,(IX+0)             ; Load E with value at this position
  POP IX                  ; Restore IX (old position in graphic layout data)
; This entry point is used by the routine at 46363.
  LD A,(IX+2)             ; Advance IX by number of states + 3 bytes to arrive
                          ; at start of next data...
  ADD A,3                 ; ...
  LD C,A                  ; ...
  ADD IX,BC               ; ...
  RET                     ; Return

; Graphic Layout Routine (255) Load HL with Stored Coordinates from 34281 and
; Return from Drawing
;
; Note that when returning from another block of graphic layout data, the
; Current Attribute stored at 34270 (and set in the called block) is not
; preserved. Upon returning, the Current Attribute value is cleared. Output: B
; Do Not Recalculate Display Buffer Address Flag (0) H  Current x-coordinate L
; Current y-coordinate
  XOR A                   ; Set Current Attribute to zero...
  LD (34270),A            ; ...
  LD HL,(34281)           ; Load HL with base x- and y-coordinates
  LD B,A                  ; Set B to zero
  RET                     ; Return

; Graphic Layout Routine (250) Adjust x- and y-Coordinates for Drawing Without
; Storing
;
; Read following two bytes in graphic layout data and adjust y- and
; x-coordinates by these amounts respectively, without storing. These new
; coordinates will be lost on the next draw operation, being overwritten by the
; values stored at 34281. Input:  IX  Address of first parameter in current
; graphic layout data instruction Output: B  Do Not Recalculate Display Buffer
; Address Flag (0)
  LD A,(IX+0)             ; Read delta-y into A...
  ADD A,L                 ; ...and adjust y-coordinate by this amount...
  LD L,A                  ; ...
  LD A,(IX+1)             ; Read delta-x into A...
  ADD A,H                 ; ...and adjust x-coordinate by this amount...
  LD H,A                  ; ...
  LD B,0                  ; Prepare to recalculate Display Buffer address
  JP 45999                ; Advance graphic layout data pointer by two bytes
                          ; and read / process next data

; Graphic Layout Routine (254) Adjust x- and y-Coordinates for Drawing and Set
; as New Base Coordinates
;
; Read following two bytes in graphic layout data and adjust y- and
; x-coordinates by these amounts respectively, storing at 34281 as base
; coordinates. These new coordinates will be used as the starting position on
; the next draw operation. Input:  H  Current x-coordinate L  Current
; y-coordinate IX  Address of first parameter in current graphic layout data
; instruction Output: B  Do Not Recalculate Display Buffer Address Flag (0)
  LD A,(IX+0)             ; Read delta-y into A...
  ADD A,L                 ; ...and adjust y-coordinate by this amount...
  LD L,A                  ; ...
  LD A,(IX+1)             ; Read delta-x into A...
  ADD A,H                 ; ...and adjust x-coordinate by this amount...
  LD H,A                  ; ...
  LD (34281),HL           ; Store new coordinates at 34281
  LD B,0                  ; Prepare to recalculate Display Buffer address
  JP 45999                ; Advance graphic layout data pointer by two bytes
                          ; and read / process next data

; Graphic Layout Routine (251) Process Graphic Layout Data at Following Address
; and Return When Complete
;
; Functionally equivalent to "CALL" instruction. Read current WORD (address)
; from graphic layout data, load graphic layout data at that address into
; Primary Display Buffer and return to previous position. Upon returning (via
; routine at 46418 when a 255 is encountered), the position of the cursor (i.e.
; the value in HL) is reset to the base coordinates as stored at 34281 - see
; instruction at 46422. Input:  IX  Address of first parameter in current
; graphic layout data instruction Output: B  Do Not Recalculate Display Buffer
; Address Flag (0)
  LD C,(IX+0)             ; Load BC with destination graphic layout data
                          ; address...
  LD B,(IX+1)             ; ...
  PUSH IX                 ; Store IX (current position in graphic layout data)
  PUSH BC                 ; Transfer address just read into BC into IX...
  POP IX                  ; ...
  CALL 46003              ; Load graphic layout data from this new location
                          ; into Primary Display Buffer (recursive call)
  POP IX                  ; Restore IX (previously stored position in graphic
                          ; layout data)
  LD B,0                  ; Prepare to recalculate Display Buffer address
  JP 45999                ; Advance graphic layout data pointer by two bytes
                          ; and read / process next data

; Graphic Layout Routine (248) Jump to Graphic Layout Data Address
;
; Read current WORD (address) from graphic layout data and move graphic layout
; data Pointer to this address. Input: IX  Address of first parameter in
; current graphic layout data instruction Output: B  Do Not Recalculate Display
; Buffer Address Flag (0) IX  Address of next graphic layout data instruction
; to process
  LD C,(IX+0)             ; Load next two bytes as a WORD into IX...
  LD B,(IX+1)             ; ...
  PUSH BC                 ; ...
  POP IX                  ; ...
  LD B,0                  ; Prepare to recalculate Display Buffer address
  JP 46003                ; Read / process data at address in IX

; Graphic Layout Routine (249) Jump to Time-Weighted, Randomly Selected Graphic
; Layout Data Address in List Input: IX  Address of first parameter in current
; graphic layout data instruction Output: B  Do Not Recalculate Display Buffer
; Address Flag (0) IX  Address of next graphic layout data instruction to
; process
  PUSH IX                 ; Store IX (pointer to first parameter in graphic
                          ; layout data)
  LD A,(IX+1)             ; Load A with current state number
  ADD A,A                 ; Multiply A by four and add two...
  ADD A,A                 ; ...to give number of bytes of data to skip over...
  ADD A,2                 ; ...
  LD C,A                  ; Load BC with value in A...
  LD B,0                  ; ...
  ADD IX,BC               ; ...and add to IX to advance to start of data for
                          ; current state
  DEC (IX+0)              ; Decrease the timer value for this state...
  JR NZ,46544             ; ...and if not zero, skip ahead to 46544
  POP IX                  ; Restore (pointer to first parameter in graphic
                          ; layout data)
  LD A,(IX+0)             ; Load A with random number...
  CALL 54222              ; ...from zero to one less than number of states...
  LD (IX+1),A             ; ...and set this as the index of the current state
  ADD A,A                 ; Multiply A by four and add two...
  ADD A,A                 ; ...to give number of bytes of data to skip over...
  ADD A,2                 ; ...
  LD C,A                  ; Load BC with value in A
  ADD IX,BC               ; Advance IX to start of data for (new) current state
  LD A,(IX+1)             ; Load A with random number...
  CALL 54222              ; ...from one to maximum timer value for state...
  INC A                   ; ...
  LD (IX+0),A             ; ...and set as current timer value for this state
  JR 46545                ; Skip ahead to 46545
  POP BC                  ; Restore BC (graphic layout data position, was
                          ; previously in IX)
  LD C,(IX+2)             ; Load IX with graphic layout data address...
  LD B,(IX+3)             ; ...in current state's data...
  PUSH BC                 ; ...
  POP IX                  ; ...
  LD B,0                  ; Prepare to recalculate Display Buffer address
  JP 46003                ; Read / process data at address in IX

; Graphic Layout Routine (243) Increment Index, n, and Jump to n-th Address in
; Following List
;
; Read first parameter (n) from graphic layout data, increment (resetting to
; zero if it is equal to the length of the list of addresses as specified by
; the second parameter) and jump to n-th address. Input:  IX  Address of first
; parameter in current graphic layout data instruction Output: A  Number of
; bytes in graphic layout data to skip over
  LD A,(IX+0)             ; Load current byte of graphic layout data into A
  INC A                   ; Increase by one
  CP (IX+1)               ; If following byte (cap value) is greater than
                          ; current byte...
  JR C,46569              ; ...then skip ahead to 46569
  XOR A                   ; Reset current value to zero as cap value reached
  LD (IX+0),A             ; Load current value back into current position in
                          ; graphic layout data
  ADD A,A                 ; Load double current value + 2 (as we're skipping
                          ; over first two bytes and subsequent data are WORD
                          ; addresses) into A...
  ADD A,2                 ; ...
  JR 46586                ; Jump to 46586

; Graphic Layout Routine (247) Jump to Randomly Selected Graphic Layout Data
; Address from List
;
; Read current byte value (n) from graphic layout data, generate random number
; m (0 - n-1) then jump to address in m-th WORD after current position. Input:
; A  (Entry at 46585) Number of words in graphic layout data to skip over A
; (Entry at 46586) Number of bytes in graphic layout data to skip over IX
; Address of first parameter in current graphic layout data instruction Output:
; IX  Address of next graphic layout data instruction to process
  LD A,(IX+0)             ; Load current byte of graphic layout data into A
  INC IX                  ; Advance pointer to next byte
  CALL 54222              ; Load A with a random number between 0 and (A-1)
; This entry point is used by the routine at 46594.
  ADD A,A                 ; Double the number
; This entry point is used by the routine at 46559.
  LD C,A                  ; Load BC with offset value in A...
  LD B,0                  ; ...
  ADD IX,BC               ; Advance IX by offset value
  JP 46481                ; Jump to 46481 (set current position in graphic
                          ; layout data to value of WORD at this address)

; Graphic Layout Routine (253) Jump to Graphic Layout Data Address Selected
; from List, Based Upon Width of Berk's Carried Entity Output: A  Number of
; words in graphic layout data to skip over
  LD A,(34272)            ; Load A with width of entity (characters) carried by
                          ; Berk, minus 1
  JR 46585                ; Set current position in graphic layout data to
                          ; value of A-th word in list

; Unused routine
;
; Graphic layout routine (252): if Berk is holding nothing then jump to
; address. Input:IX Address of first parameter in current graphic layout data
; instruction Output:B Do Not Recalculate Display Buffer Address Flag (0)
  LD A,(34221)            ; If Berk is not holding anything...
  OR A                    ; ...
  JP Z,46481              ; ...then jump to 46481 (set current position in
                          ; graphic layout data to value of WORD at this
                          ; address)
  LD B,0                  ; Prepare to recalculate Display Buffer address
  JP 45999                ; Advance graphic layout data pointer by two bytes
                          ; and read / process next data

; Graphic Layout Routine (238) Start Loop (1 / 2)
;
; Start a loop in graphic layout data. The parameter is the repeat count. The
; current value of the repeat counter is stored at 34274 and the address of the
; next instruction (i.e. the first instruction that is processed in each loop)
; is stored at 34294. Input:  IX  Address of first parameter in current graphic
; layout data instruction Output: B  Do Not Recalculate Display Buffer Address
; Flag (0) IX  Address of next graphic layout data instruction to process
  LD A,(IX+0)             ; Load current byte of graphic layout data...
  LD (34274),A            ; ...into 34274 (repeat counter)
  INC IX                  ; Advance IX to next position in graphic layout
                          ; data...
  LD (34294),IX           ; ...and store at 34294
  LD B,0                  ; Prepare to recalculate Display Buffer address
  JP 46003                ; Read / process data at address in IX

; Graphic Layout Routine (239) End Loop (1 / 2) Output: B  Do Not Recalculate
; Display Buffer Address Flag (0) IX Address of next graphic layout data
; instruction to process
  LD A,(34274)            ; Decrement repeat counter...
  DEC A                   ; ...
  LD (34274),A            ; ...
  LD B,0                  ; Prepare to recalculate Display Buffer address
  JP Z,46003              ; If repeat counter is zero, then exit loop and
                          ; process subsequent bytes...
  LD IX,(34294)           ; ...else, restore stored position in graphic layout
                          ; data (start of loop)...
  JP 46003                ; ...and continue processing data from this point

; Graphic Layout Routine (240) Start Loop (2 / 2)
;
; Start a loop in graphic layout data. The parameter is the repeat count. The
; current value of the repeat counter is stored at 34275 and the address of the
; next instruction (i.e. the first instruction that is processed in each loop)
; is stored at 34296. Input:  IX  Address of first parameter in current graphic
; layout data instruction Output: B  Do Not Recalculate Display Buffer Address
; Flag (0) IX  Address of next graphic layout data instruction to process
  LD A,(IX+0)             ; Load current byte of graphic layout data...
  LD (34275),A            ; ...into 34275 (repeat counter)
  INC IX                  ; Advance IX to next position in graphic layout
                          ; data...
  LD (34296),IX           ; ...and store at 34296
  LD B,0                  ; Prepare to recalculate Display Buffer address
  JP 46003                ; Read / process data at address in IX

; Graphic Layout Routine (241) End Loop (2 / 2) Output: B  Do Not Recalculate
; Display Buffer Address Flag (0) IX Address of next graphic layout data
; instruction to process
  LD A,(34275)            ; Decrement repeat counter...
  DEC A                   ; ...
  LD (34275),A            ; ...
  LD B,0                  ; Prepare to recalculate Display Buffer address
  JP Z,46003              ; If repeat counter is zero, then exit loop and
                          ; process subsequent bytes...
  LD IX,(34296)           ; ...else, restore stored position in graphic layout
                          ; data (start of loop)...
  JP 46003                ; ...and continue processing data from this point

; Current Keyboard Controls
  DEFM "X"                ; Right
  DEFM "Z"                ; Left
  DEFM "A"                ; Forward
  DEFM "Q"                ; Back
  DEFM "C"                ; Berk / Drutt
  DEFM "P"                ; Pause
  DEFM "R"                ; Restart

; Table of Attribute File Addresses for Main Menu Strings
  DEFW 22666              ; "S   START   "
  DEFW 22762              ; "K NEW KEYS  "
  DEFW 22851              ; "J +KEMPSTON "
  DEFW 22947              ; "   RIGHT    "
  DEFW 23043              ; "   LEFT     "
  DEFW 23139              ; "   FORWARD  "
  DEFW 22865              ; "   BACK     "
  DEFW 22961              ; "   BERK/DRUT"
  DEFW 23057              ; "   PAUSE    "
  DEFW 23153              ; "   RESTART  "

; Table of Main Menu Strings
  DEFM "S   START   "
  DEFM "K NEW KEYS  "
  DEFM "J +KEMPSTON "
  DEFM "   RIGHT    "
  DEFM "   LEFT     "
  DEFM "   FORWARD  "
  DEFM "   BACK     "
  DEFM "   BERK/DRUT"     ; (see bugs)
  DEFM "   PAUSE    "
  DEFM "   RESTART  "

; Display and Handle Main Menu
;
; Used by the routine at 34438.
  LD A,1                  ; Load A with 1 (blue)
  LD (34217),A            ; Store at 34217 and...
  OUT (254),A             ; ...set border to this value (blue)
  LD A,9                  ; Fill top 22 rows of Attribute File with blue PAPER
                          ; & blue INK...
  CALL 53649              ; ...
  CALL 47140              ; Print "THROUGH the TRAPDOOR" string
  CALL 47628              ; Print SCORE / TOTAL / HI-SC string in current
                          ; character's colours
  LD IX,46690             ; Point IX at Table of Attribute File Addresses for
                          ; Main Menu Strings
  LD IY,46710             ; Point IY at start of Table of Main Menu Strings
  LD A,112                ; Load A with 112 (black INK on yellow PAPER)
  LD (34269),A            ; Store at 34269
  LD B,10                 ; Load B with 10 as there are 10 strings to print
                          ; (loop counter)
  PUSH BC                 ; Store BC (B = remaining number of strings to print)
  LD L,(IX+0)             ; Load Attribute File address at which to print text
                          ; into HL...
  LD H,(IX+1)             ; ...
  LD B,12                 ; Load B with 12 as there are 12 characters to print
                          ; (loop counter)
  PUSH BC                 ; Store BC (B = number of remaining characters to
                          ; print)
  LD E,(IY+0)             ; Load E with text character to print
  CALL 47682              ; Print double-height text character in E
  INC IY                  ; Advance IY to next character in text to print
  INC HL                  ; Advance to next Attribute File location
  POP BC                  ; Restore BC (B = number of remaining characters to
                          ; print)
  DJNZ 46872              ; Loop back for next character
  INC IX                  ; Advance IX to next entry in list of Attribute File
                          ; addresses to print to...
  INC IX                  ; ...
  POP BC                  ; Restore BC (B = remaining number of strings to
                          ; print)
  DJNZ 46863              ; Loop back for next string
  CALL 46946              ; Draw Joystick "J" (Main Menu) in colour depending
                          ; upon Joystick Mode
  LD A,114                ; Load A with the attribute value for red INK, yellow
                          ; PAPER, BRIGHT
  CALL 47084              ; Print keyboard controls on main menu
; This entry point is used by the routine at 46968.
  CALL 47955              ; Wait for key-press, store pressed key code in A and
                          ; play Main Menu Sound
  CP 83                   ; If pressed key was not 83 (S)...
  JR NZ,46915             ; ...then skip ahead to 46915
  LD A,2                  ; Set current border colour to red...
  LD (34217),A            ; ...
  OUT (254),A             ; ...
  RET                     ; Return
  CP 74                   ; If pressed key was not 74 (J)...
  JR NZ,46968             ; ...then jump to 46968 (if "K" pressed then redefine
                          ; controls)
  LD A,(34298)            ; If we are in Joystick Mode...
  OR A                    ; ...
  JR NZ,46937             ; ...then skip ahead to 46937
  CALL 47043              ; If Kempston Interface not present, or Kempston
                          ; Joystick moved / fire pressed...
  JR C,46900              ; ...then jump to 46900
  LD A,1                  ; Set Joystick Mode to On...
  LD (34298),A            ; ...(see trivia)
  JR 46938                ; Skip ahead to 46938
  DEC A                   ; Set Joystick Mode to Off...
  LD (34298),A            ; ...
  CALL 46946              ; Draw Joystick "J" (Main Menu) in colour depending
                          ; upon Joystick Mode
  JR 46900                ; Loop back to 46900

; Draw Joystick "J" (Main Menu) in Colour Depending Upon Joystick Mode
;
; Used by the routine at 46830.
  LD A,(34298)            ; If Joystick Mode Flag is set...
  OR A                    ; ...
  JR NZ,46956             ; ...then skip ahead to 46956
  LD A,112                ; Load A with attribute value for black INK, yellow
                          ; PAPER, BRIGHT
  JR 46958                ; Skip ahead to 46958
  LD A,114                ; Load A with attribute value for red INK, yellow
                          ; PAPER, BRIGHT
  LD E,74                 ; Load E with 74 (index for character "J")
  LD IX,46694             ; Point IX at entry for "J +KEMPSTON " in table of
                          ; Attribute File addresses at which to print menu
                          ; strings
  CALL 47071              ; Set attribute to A and location to (IX) and print
                          ; double-height character in E
  RET                     ; Return

; If "K" Pressed then Redefine Controls
;
; Used by the routine at 46830. Input:  A  ASCII code of pressed key
  CP 75                   ; If pressed key was not 75 (K)...
  JR NZ,46900             ; ...then jump to Main Menu handling routine at 46900
  LD B,7                  ; Load B with 7 (as there are seven controls to
                          ; define)
  LD HL,46683             ; Point HL at start of Table of Current Keyboard
                          ; Controls
  LD (HL),63              ; Set current entry in table to 63 (ASCII code for
                          ; "?")
  INC HL                  ; Advance HL to next entry
  DJNZ 46977              ; Decrease remaining number of controls to change and
                          ; loop back to 46977 if not zero
  LD A,112                ; Load A with the attribute value for black INK,
                          ; yellow PAPER, BRIGHT
  CALL 47084              ; Print keyboard controls on main menu
  LD IY,46683             ; Point IY at Table of Current Keyboard Controls
  LD IX,46696             ; Point IX at entry for "   RIGHT    " text in table
                          ; of Attribute File addresses at which to print for
                          ; main menu
  LD B,7                  ; Load B with 7 (as there are seven controls to
                          ; define)
  PUSH BC                 ; Store BC (remaining number of controls to define)
  LD A,198                ; Load A with 198 (yellow INK, black PAPER, BRIGHT,
                          ; FLASH)
  LD E,32                 ; Load E with 32 (" ")
  CALL 47071              ; Set attribute to A and location to (IX) and print
                          ; double-height character in E
  CALL 47955              ; Wait for key-press, store pressed key code in A and
                          ; play Main Menu Sound
  CALL 47060              ; If key pressed matches a direction, or the Berk /
                          ; Drutt key...
  JR Z,47005              ; ...then loop back to 47005
  LD E,A                  ; Load keycode of pressed control into E...
  LD (IY+0),E             ; ...and store in Table of Current Keyboard Controls
  INC IY                  ; Advance IY to next control
  LD A,113                ; Load A with 113 (blue INK, yellow PAPER, BRIGHT)
  CALL 47071              ; Set attribute to A and location to (IX) and print
                          ; double-height character in E
  INC IX                  ; Advance IX to next entry in table of Attribute File
                          ; addresses...
  INC IX                  ; ...
  POP BC                  ; Restore BC (remaining number of controls to define)
  DJNZ 46997              ; Decrease remaining number of controls to define and
                          ; loop back to 46997 if not zero
  XOR A                   ; Switch Joystick Mode to Off...
  LD (34298),A            ; ...
  LD A,114                ; Load A with the attribute value for red INK, yellow
                          ; PAPER, BRIGHT
  CALL 47084              ; Print keyboard controls on main menu
  JP 46900                ; Jump to Main Menu handling routine at 46900

; Set Carry Flag if Kempston Interface not Present, or Kempston Joystick Moved
; / Fire Pressed
;
; Used by the routine at 46830. Output: F  Carry Flag set if Kempston Interface
; not present, Kempston Joystick moved or fire pressed, reset otherwise
  LD B,0                  ; Set B to zero (to repeat check loop 256 times)
  IN A,(31)               ; Read value from Port 31 into A (Kempston Interface)
  OR A                    ; If retrieved value is not zero (i.e. Kempston
                          ; Interface not present, or Kempston Joystick not
                          ; centred / fire button pressed)...
  JR NZ,47053             ; ...then skip ahead to 47053
  DJNZ 47045              ; Decrease B (loop counter) and loop back to 47045 to
                          ; check Kempston status again if counter not zero
  RET                     ; Return
  LD A,6                  ; Set sound 6 as pending if appropriate, then play
                          ; and clear pending sound...
  CALL 59722              ; ...
  SCF                     ; Set Carry Flag
  RET                     ; Return

; Set Zero Flag if Key Whose Index is in A Matches a Direction, or the Berk /
; Drutt Key
;
; Used by the routine at 46968. Input:  A  Index of pressed key Output: F  Zero
; Flag set if input key index matches an entry in table at 46683, reset
; otherwise HL  Address of matching entry in table at 46683 (if match found)
  LD HL,46683             ; Point HL at Table of Current Keyboard Controls
  LD B,5                  ; Load B with 5 (as we are checking the first five
                          ; defined keys, see bugs)
  CP (HL)                 ; If character code at current HL position matches
                          ; the key we are checking...
  RET Z                   ; ...then return with Zero Flag set
  INC HL                  ; Advance HL to next character in keyboard controls
                          ; table
  DJNZ 47065              ; Loop back to 47065 to check next control
  RET                     ; Return

; Set Attribute and Location and Print Double-Height Character in E
;
; Used by the routines at 46946 and 46968. Input:  A  Attribute for character
; to print E  Character to print IX Points to memory location holding Attribute
; File address at which to print character
  LD (34269),A            ; Set text printing attribute to value in A
  LD L,(IX+0)             ; Load Attribute File address to print character to
                          ; into HL...
  LD H,(IX+1)             ; ...
  CALL 47682              ; Print double-height text character in E
  RET                     ; Return

; Print Keyboard Controls on Main Menu
;
; Used by the routines at 46830 and 46968. Input:  A  Attribute for printing
; text
  LD (34269),A            ; Set attribute for printing text
  LD IX,46696             ; Point IX at entry for "   RIGHT    " text in table
                          ; of Attribute File addresses at which to print
  LD IY,46683             ; Point IY at Table of Current Keyboard Controls
  LD B,7                  ; Load B with 7, as there are 7 keyboard controls
                          ; (loop counter)
  PUSH BC                 ; Store BC (B = number of remaining control keys)
  LD L,(IX+0)             ; Load HL with Attribute File address at which to
                          ; print character...
  LD H,(IX+1)             ; ...
  LD E,(IY+0)             ; Load E with character to print (current keyboard
                          ; control)
  CALL 47682              ; Print double-height text character in E
  INC IY                  ; Advance IY to next keyboard control
  INC IX                  ; Advance IX to next entry in list of Attribute File
                          ; addresses...
  INC IX                  ; ...
  POP BC                  ; Restore BC (B = number of remaining control keys)
  DJNZ 47097              ; Loop back to 47097 for next keyboard control
  RET                     ; Return

; "THROUGH the TRAPDOOR" String
  DEFM "THROUGH the TRAPDOOR"

; Print "THROUGH the TRAPDOOR" String
;
; Used by the routine at 46830.
  LD B,20                 ; Load B with 20 (length of string to print)
  LD HL,22566             ; Point HL at position to start printing text in
                          ; Attribute File
  LD A,79                 ; Load A with 79, for blue PAPER, white INK, BRIGHT
  LD IX,47120             ; Point IX to text to print
  JR 47224                ; Print the text and return

; "SORRY BERK,  BUT YOUR TIME IS UP" String
  DEFM "SORRY BERK,  BUT YOUR TIME IS UP"

; Print "SORRY BERK,  BUT YOUR TIME IS UP" String
;
; Used by the routine at 34438.
  LD B,32                 ; Load B with 32 (length of string to print)
  LD A,199                ; Load A with 199, for black PAPER, white INK,
                          ; BRIGHT, FLASH
  LD IX,47153             ; Point IX to text to print
  LD HL,23232             ; Point HL at position at which to start printing
                          ; text in Attribute File (start of second-last row)
  JR 47224                ; Print the text and return

; "HOME SWEET HOME" String
  DEFM "HOME SWEET HOME"

; Print "HOME SWEET HOME" String
;
; Used by the routine at 34438.
  LD B,15                 ; Set string length to 15
  LD A,68                 ; Set attribute to green INK on black PAPER, BRIGHT
  LD IX,47198             ; Point IX at "HOME SWEET HOME" text
  LD HL,22792             ; Point HL at Attribute File address at which to
                          ; print text
; This entry point is used by the routines at 47140 and 47185.
  LD (34269),A            ; Store attribute at 34269
  PUSH BC                 ; Store BC (B=remaining length of text)
  LD E,(IX+0)             ; Load character of text to print into E
  CALL 47682              ; Print double-height text character in E
  INC IX                  ; Advance IX to next text character to print
  INC HL                  ; Advance HL to next Attribute File address at which
                          ; to print
  POP BC                  ; Restore BC (B = remaining length of text)
  DJNZ 47227              ; Decrease remaining length of text by one and repeat
                          ; loop for next character
  RET                     ; Return

; Reset Show Score Flag and Draw Timer Figures Bar
;
; Used by the routines at 34438, 34916 and 47468.
  LD A,(34208)            ; Reset Show Score Flag...
  RES 7,A                 ; ...
  LD (34208),A            ; ...
  LD IX,23232             ; Point IX to start of second-last row of Attribute
                          ; File
  LD A,(34210)            ; Load remaining time / lives into A...
  OR A                    ; ...and if zero...
  JR Z,47267              ; ...then skip ahead 47267
  LD B,A                  ; Load number of lives into B
  PUSH BC                 ; Store BC (B = remaining number of pairs of open
                          ; eyes to draw)
  CALL 47315              ; If Show Score Flag reset then draw pair of Timer
                          ; Figure eyes (open, random frame) at Attribute File
                          ; address in IX and advance by two bytes
  POP BC                  ; Restore BC (B = remaining number of pairs of open
                          ; eyes to draw)
  DJNZ 47260              ; Decrease B (remaining number of pairs of open eyes
                          ; to draw) and loop back to 47260 if not zero
  LD A,(34210)            ; Load remaining time / lives into E...
  LD E,A                  ; ...
  LD A,16                 ; Load A with number of lives lost by subtracting E
                          ; from 16...
  SUB E                   ; ...
  JR Z,47284              ; If zero, then skip ahead to 47284
  LD B,A                  ; Load number of lost lives into B as counter for
                          ; loop
  PUSH BC                 ; Store BC (B = remaining number of pairs of closed
                          ; eyes to draw)
  CALL 47302              ; If Show Score Flag reset then draw pair of Timer
                          ; Figure eyes (closed) at Attribute File address in
                          ; IX and advance by two bytes
  POP BC                  ; Restore BC (B = remaining number of pairs of closed
                          ; eyes to draw)
  DJNZ 47277              ; Decrease B (remaining number of pairs of open eyes
                          ; to draw) and loop back to 47277 if not zero
  LD C,27                 ; Set graphic index to 27 (timer figures' bodies)
  LD A,(34226)            ; Load attribute of current character into A
  LD B,16                 ; Load B with 16 (as 16 timer figures' bodies to
                          ; draw)
  PUSH BC                 ; Store B (remaining number of timer figure bodies to
                          ; draw)
  CALL 47333              ; Draw left half of timer figure's body and invert
                          ; mirror flag on attribute
  CALL 47333              ; Draw right half of timer figure's body
  POP BC                  ; Restore B (remaining number of timer figure bodies
                          ; to draw)
  DJNZ 47291              ; Decrease B and loop back to 47291
  RET                     ; Return

; If Show Score Flag Reset then Draw Pair of Timer Figure Eyes (Closed) at
; Attribute File Address IX and Advance IX by Two Bytes
;
; Used by the routines at 47241 and 47363. Input:  IX  Pointer to a location in
; Attribute File
  CALL 47355              ; If Show Score Flag is set then return, else proceed
                          ; ahead to 47305
  LD A,(34226)            ; Load A with the attribute of the current character
  LD C,28                 ; Load C with 28 (graphic index of timer figures'
                          ; closed eyes)
  CALL 47333              ; Draw the left (closed) eye at Attribute File
                          ; address in IX and advance IX by one byte
  JR 47333                ; Draw the right (closed) eye at Attribute File
                          ; address in IX, advance IX by one byte and return

; If Show Score Flag Reset then Draw Pair of Timer Figure Eyes (Open, Random
; Frame) at Attribute File Address IX and Advance IX by Two Bytes
;
; Used by the routines at 47241, 47363 and 47431. Input:  IX  Attribute File
; address at which to draw pair of eyes Output: IX  Attribute File address two
; bytes on from initial IX
  CALL 47355              ; If Show Score Flag is set then return, else proceed
                          ; ahead to 47318
  CALL 47323              ; Draw Timer Figure's left eye (random frame) at
                          ; Attribute File address in IX and advance IX by one
                          ; byte
  JR 47333                ; Draw Timer Figure's right eye (same frame as
                          ; above), advance IX by one byte then return

; Draw a Timer Figure's Eye (Random Frame) at Attribute File Address in IX and
; Advance IX by One Byte
;
; Used by the routine at 47315. Input:  IX  (Entry at 47323 and 47333) Pointer
; to a location in Attribute File A  (Entry at 47333 only) Attribute C  (Entry
; at 47333 only) Graphic Index (e.g. 27 for timer figures' bodies) Output: A
; Attribute (including inverted mirror flag) IX  Pointer to next location in
; Attribute File
  LD A,5                  ; Load A with a random number, 0-4...
  CALL 54222              ; ...
  ADD A,29                ; Add 29 (as 29 is the index of the first of five eye
                          ; direction graphics) in C...
  LD C,A                  ; ...
  LD A,7                  ; Set attribute for timer indicator figures' eyes to
                          ; white INK on black PAPER
; This entry point is used by the routines at 47241, 47302 and 47315.
  LD B,4                  ; Set Graphic Set Index to 4
  PUSH AF                 ; Store AF (A = attribute)
  PUSH BC                 ; Store BC (B = graphic set index, C = graphic index)
  CALL 54144              ; Draw a graphic character block to display
  POP BC                  ; Restore BC (B = graphic set index, C = graphic
                          ; index)
  LD A,C                  ; Load Graphic Index into A
  CP 32                   ; If graphic index is less than 32 (i.e. we're not
                          ; dealing with #32 - eyes looking right or #33 - eyes
                          ; looking left and don't need to cancel inversion at
                          ; 47350)...
  JR C,47348              ; ...then skip ahead to 47348
  XOR 1                   ; Add or subtract 1 if Graphic Index is 32 or 33
                          ; respectively (Timer Figures' Eyes looking right or
                          ; left respectively) to cancel out inversion at 47350
  LD C,A                  ; Load Graphic Index into C
  POP AF                  ; Restore AF (A = attribute)
  XOR 128                 ; Flip mirror flag to prepare to draw mirror image of
                          ; just-drawn character block
  INC IX                  ; Advance IX to next byte in Attribute File
  RET                     ; Return

; If Show Score Flag is Reset then Return to Calling Routine, else Return to
; Routine that Called Calling Routine
;
; Used by the routines at 47302 and 47315.
  LD A,(34208)            ; If Show Score Flag is reset...
  BIT 7,A                 ; ...
  RET Z                   ; ...then return
  POP BC                  ; Remove return address from stack...
  RET                     ; ...and return to routine that called the calling
                          ; routine

; Update Eyes of a Randomly Selected Timer Figure, Increase Timer Tick Counter
; and Process Timer Figure Blinking
;
; Used by the routine at 34438.
  CALL 47431              ; Select a remaining Timer Figure at random and
                          ; update its eyes to a random (open-eyed) frame
  CALL 47468              ; Increase Timer Tick Counter and reduce remaining
                          ; time if Counter > 767
  LD A,(34227)            ; If Blink Duration Counter is zero...
  OR A                    ; ...
  JR Z,47388              ; ...then skip ahead to 47388
  DEC A                   ; Decrease Blink Duration Counter by one...
  LD (34227),A            ; ...
  OR A                    ; If decreased Blink Duration Counter is not zero...
  RET NZ                  ; ...then return
  LD IX,(34264)           ; Restore Attribute File address of eyes of currently
                          ; blinking timer figure into IX
  JP 47315                ; If Show Score Flag reset then draw pair of Timer
                          ; Figure eyes (open, random frame) at Attribute File
                          ; address IX, advance IX by two bytes then return
; Make a randomly chosen timer figure blink
  LD A,10                 ; Load A with a random number, 0-9...
  CALL 54222              ; ...
  OR A                    ; If A is not zero (9 in 10 chance)...
  RET NZ                  ; ...then return
  LD A,(34210)            ; Load remaining time / lives into A
  CP 2                    ; If less than two time / lives remain...
  RET C                   ; ...then return
  CALL 54222              ; Load A with a random number, 0-(x-1) (where x is
                          ; remaining time / lives)
  ADD A,A                 ; Double A...
  LD C,A                  ; ...and load into BC...
  LD B,0                  ; ...
  LD IX,23232             ; Point IX to start of second-last row of Attribute
                          ; File
  ADD IX,BC               ; Add BC as offset to IX (i.e. point to a random
                          ; "awake" timer figure)
  LD (34264),IX           ; Store Attribute File address of eyes of currently
                          ; blinking timer figure at 34264
  CALL 47302              ; If Show Score Flag reset then draw pair of Timer
                          ; Figure eyes (closed) at Attribute File address IX
                          ; and advance IX by two bytes
  LD A,10                 ; Set Blink Duration Counter to a random number,
                          ; 1-9...
  CALL 54222              ; ...
  INC A                   ; ...
  LD (34227),A            ; ...
  RET                     ; Return

; Select a Remaining Timer Figure at Random and Update its Eyes to a Random
; (Open-Eyed) Frame
;
; Used by the routine at 47363.
  LD A,(34210)            ; Load remaining time / lives into A...
  OR A                    ; ...and if none remain...
  RET Z                   ; ...then return
  LD E,A                  ; Load remaining time / lives into E
  LD A,18                 ; Load A with 18 minus remaining time / lives (i.e.
                          ; number in range 2 to 18)...
  SUB E                   ; ...
; As the value of x (Remaining Time / Lives) decreases, the probability that a
; randomly generated number between 0 and (18-x) is 2 or more increases. This
; probability is used to ensure that the rate at which each timer figure is
; updated remains roughly constant.
  CALL 54222              ; Load A with a random number, 0-(17 minus remaining
                          ; time / lives)
  CP 2                    ; If generated number is 2 or more...
  RET NC                  ; ...then return
  LD IX,23232             ; Point IX to start of second-last row of Attribute
                          ; File
  LD A,E                  ; Load remaining time / lives into A
; If remaining time / lives is one, then there is only one Timer Figure to
; update
  CP 1                    ; If this is 1...
  JP Z,47315              ; ...then jump to 47315 (If Show Score Flag reset
                          ; then draw pair of Timer Figure eyes and return)
; Otherwise, randomly select one of the remaining Timer Figures to update
  CALL 54222              ; Load A with random number between 0 and (x-1) where
                          ; x is remaining time / lives
  ADD A,A                 ; Double A...
  LD C,A                  ; ...and load into BC...
  LD B,0                  ; ...
  ADD IX,BC               ; Add BC as offset to IX (i.e. advance IX to point to
                          ; left eye of randomly chosen Timer Figure)
  JP 47315                ; If Show Score Flag reset then draw pair of Timer
                          ; Figure eyes (open, random frame) at Attribute File
                          ; address IX, advance IX by two bytes then return

; Increase Timer Tick Counter and Reduce Remaining Time if Counter > 767
;
; Used by the routine at 47363.
  LD HL,(34211)           ; Increase Timer Tick Counter by one...
  INC HL                  ; ...
  LD (34211),HL           ; ...
  LD A,H                  ; If Timer Tick Counter is less than 768 (i.e. 3 x
                          ; 256)...
  CP 3                    ; ...
  RET C                   ; ...then return
  LD HL,0                 ; Reset Timer Tick Counter to zero...
  LD (34211),HL           ; ...
; This entry point is used by the routine at 53723.
  LD A,(34210)            ; If no time / lives remain...
  OR A                    ; ...
  JP Z,47241              ; ...then reset Show Score Flag, draw timer figures
                          ; bar and return
  DEC A                   ; Decrease current time / lives by one...
  LD (34210),A            ; ...
  JP 47241                ; Reset Show Score Flag, and draw timer figures bar
                          ; and return

; Update Scores and Display
;
; Used by the routine at 34438.
  LD HL,34208             ; Set Show Score Flag...
  SET 7,(HL)              ; ...
  LD HL,0                 ; Set HL to zero
  LD A,(34210)            ; If no time / lives remain...
  OR A                    ; ...
  JR Z,47526              ; ...then skip ahead to 47526
  LD B,A                  ; Load HL with 1000 x current remaining time /
                          ; lives...
  LD DE,1000              ; ...
  ADD HL,DE               ; ...
  DJNZ 47517              ; ...
  LD DE,(34211)           ; Subtract value of Timer Tick Counter (i.e. Score
                          ; Penalty) from current level's score...
  SBC HL,DE               ; ...
  LD (34213),HL           ; Set score for current level
  LD DE,(34215)           ; Load DE with current total score
  ADD HL,DE               ; Add score for current level to total score...
  LD (34215),HL           ; ...and store
  LD DE,(34299)           ; Load current high score into DE
  SBC HL,DE               ; Subtract high score from current total score...
  JR C,47551              ; ...and if this is less than zero (i.e. high score
                          ; is higher than current total score) then skip ahead
                          ; to 47551
  LD HL,(34215)           ; Load current total score into HL...
  LD (34299),HL           ; ...and store as new high score
  LD A,16                 ; Set time / lives to 16...
  LD (34210),A            ; ...
  LD IY,47596             ; Point IY at "numeric (score)" part of string at
                          ; 47589
  LD HL,(34213)           ; Load HL with current score...
  CALL 47741              ; ...and convert to string at IY
  LD IY,47609             ; Point IY at "numeric (total)" part of string at
                          ; 47589
  LD HL,(34215)           ; Load HL with current total score...
  CALL 47741              ; ...and convert to string at IY
  LD IY,47622             ; Point IY at "numeric (high score)" part of string
                          ; at 47589
  LD HL,(34299)           ; Load HL with current high score...
  CALL 47741              ; ...and convert to string at IY
  JP 47628                ; Print SCORE / TOTAL / HI-SC string in current
                          ; character's colours and return

; Score / Total / High Score String
  DEFM 42,"SCORE",35,"00000",42," TOTAL",35,"00000",42," HI-SC",35,"00999",36

; Print Score / Total / High Score String in Current Character's Colours
;
; Used by the routines at 34916, 46830 and 47499.
  LD IY,47589             ; Point IY at SCORE / TOTAL / HI-SC text
  LD HL,23232             ; Set Attribute File address at which to print text
                          ; to start of second-last character row
  LD A,(IY+0)             ; Load a character from the string into A
  CP 36                   ; If the character is 36 (end marker)...
  RET Z                   ; ...then return
  CP 42                   ; If character is not 42 ("set attribute to current
                          ; character's colours" marker)...
  JR NZ,47660             ; ...then skip ahead to 47660
  LD A,(34226)            ; Load current character's attribute into A (blue for
                          ; Berk, yellow for Drutt)
  CP 1                    ; If blue (Berk)...
  JR Z,47656              ; ...then skip ahead to 47656
  LD A,112                ; Load A with value for black INK, yellow PAPER,
                          ; BRIGHT (Drutt's colours)
  JR 47666                ; Skip ahead to 47666
  LD A,79                 ; Load A with value for white INK, blue PAPER, BRIGHT
                          ; (Berk's colours)
  JR 47666                ; Skip ahead to 47666
  CP 35                   ; If character is not 35 ("set attribute to standard"
                          ; marker)...
  JR NZ,47673             ; ...then skip ahead to 47673
  LD A,71                 ; Load A with value for white INK, black PAPER,
                          ; BRIGHT
  LD (34269),A            ; Store this value as the attribute to print text
  INC IY                  ; Advance IY to next character in string to print
  JR 47635                ; Loop back to 47635 for next character
  LD E,A                  ; Load character to print into E
  CALL 47682              ; Print double-height text character in E
  INC HL                  ; Advance HL to next Attribute File address
  INC IY                  ; Advance IY to next character to process
  JR 47635                ; Loop back to 47635 for next character

; Print a Double-Height Text Character
;
; Used by the routines at 46830, 47071, 47084, 47213 and 47628. Input:  HL
; Attribute File address at which to print character E  Character to print
  LD BC,32                ; Load BC with 32 (width of a row in Attribute File)
  PUSH HL                 ; Store HL (Attribute File address at which to print
                          ; character)
  LD D,0                  ; Set D to zero
  EX DE,HL                ; Swap DE (now Attribute File address at which to
                          ; print character) and HL (now H = 0, L = character
                          ; to print)
  ADD HL,HL               ; Multiply index of character to print by eight in
                          ; HL, as each character's graphic data is eight bytes
                          ; long...
  ADD HL,HL               ; ...
  ADD HL,HL               ; ...
  LD DE,15360             ; Add eight times character index to 15360 in HL, to
                          ; point to graphic of character in ROM...
  ADD HL,DE               ; ...
  EX DE,HL                ; Swap DE (now points to graphic of character in ROM)
                          ; and HL (now 15360)
  POP HL                  ; Restore HL (Attribute File address at which to
                          ; print character)
  CALL 47709              ; Print top half of a double-height text character
  ADD HL,BC               ; Add BC to HL to advance down a character row
  CALL 47709              ; Print bottom half of a double-height text character
  AND A                   ; Reset Carry Flag
  SBC HL,BC               ; Subtract 32 from HL to restore to value it had upon
                          ; starting this routine
  RET                     ; Return

; Print Half of a Double-Height Text Character
;
; The most significant byte of the Attribute File address starts off as 88 for
; the top third of the screen. In the middle third it becomes 89 and in the
; lower third it reaches 90. The most significant byte of the Display File
; address (for the top pixel row of each character row) is 64 in the top third,
; 72 in the middle third and 80 in the lower third. Generally speaking,
; therefore, the most significant byte in the Display File address increases by
; eight for every increase of one in the attribute address most significant
; byte, so multiplying the latter by eight (giving 192, 200 or 208, values roll
; over 255-0 boundary with excess truncated) would put it on the same scale as
; the former (64, 72 or 80). Input:  DE  15360 + 8 x character index [+4 for
; second run-through] (i.e. points to ROM graphic data for the character of
; interest) HL  Attribute File address at which to print character
  PUSH HL                 ; Store HL
  PUSH BC                 ; Store BC
  LD A,(34269)            ; Load stored attribute into A
  LD (HL),A               ; Write this to Attribute File
  LD A,H                  ; Multiply the most significant byte (MSB) of the
                          ; Attribute File address by eight...
  ADD A,A                 ; ...to put it on the same scale as the MSB of the
                          ; Display File address MSB (see notes)...
  ADD A,A                 ; ...
  ADD A,A                 ; ...
  AND 91                  ; Drop the most significant bit to point to the
                          ; correct location in Display File
  LD H,A                  ; Load back into HL (L is unaffected, as it should
                          ; be)
  LD B,4                  ; Set B to 4 (loop counter)
  LD A,(DE)               ; Load a byte from the graphic data into C...
  LD C,A                  ; ...
  SRL C                   ; Shift bitmap data left one pixel in C
  OR C                    ; Merge this into bitmap data already in A to give a
                          ; "bold" typeface appearance
  AND 127                 ; Drop the leftmost bit to prevent one character
                          ; touching the next (space between letters)
  LD (HL),A               ; Load the bitmap data into two consecutive rows to
                          ; provide double-height (2 chars) text...
  INC H                   ; ...
  LD (HL),A               ; ...
  INC H                   ; ...
  INC DE                  ; Advance to next byte of graphic data
  DJNZ 47724              ; Repeat for next row of graphic data
  POP BC                  ; Restore BC
  POP HL                  ; Restore HL
  RET                     ; Return

; Convert Number in HL to String at IY
;
; Used by the routine at 47499. Input:  HL  A number to convert to string IY  A
; location in memory to store a number converted to a string
  LD DE,10000             ; Convert the ten thousands to a character...
  CALL 47772              ; ...
  LD DE,1000              ; Convert the thousands to a character...
  CALL 47772              ; ...
  LD DE,100               ; Convert the hundreds to a character...
  CALL 47772              ; ...
  LD DE,10                ; Convert the tens to a character...
  CALL 47772              ; ...
  LD A,L                  ; Load remainder (units) into L
  ADD A,48                ; Add as offset to 48 (ASCII code for "0")
  LD (IY+0),A             ; Load ASCII character code into units position in
                          ; string
  RET                     ; Return

; Convert a Digit of Numeric Data to its String Equivalent
;
; Used by the routine at 47741. Input:  DE  Current power of ten HL  A number
; to convert to string IY  A location in memory to store a current digit
; converted to a string
  LD (IY+0),47            ; Set character in string to "/" (character
                          ; immediately before "0")
  AND A                   ; Reset Carry Flag
  INC (IY+0)              ; Advance character at current string position to
                          ; next numeric character up
  SBC HL,DE               ; Subtract current power of ten from number to
                          ; convert
  JR NC,47777             ; If number to convert has not dropped below 0 (i.e.
                          ; we have not yet subtracted too many of the current
                          ; power of ten) then loop back to 47777
  ADD HL,DE               ; We have subtracted one too many of the current
                          ; power of ten, so add it back to make the remainder
                          ; positive
  INC IY                  ; Advance to next character in the string as we are
                          ; finished dealing with the current power of ten
  RET                     ; Return

; Read Keyboard and Load Pressed Key Character into A
;
; Used by the routines at 47893 and 47942. Output: A  Index of the key that was
; pressed
  EXX                     ; Swap registers
  LD BC,65278             ; Load B and C with 254
  LD HL,47853             ; Point HL at list of return values
  IN A,(C)                ; Read from port 254 into A (i.e. read keyboard) [IN
                          ; 65278 reads the half row CAPS SHIFT to V]
  SET 0,A                 ; Set bit 0 of A (i.e. clear pressing of CAPS SHIFT)
  AND 31                  ; Strip out all but the five bits representing key
                          ; presses
  XOR 31                  ; Invert all of the lowest five bits
  JR NZ,47843             ; If this value is non-zero, then a key has been
                          ; pressed, so skip ahead to 47843
  LD DE,5                 ; Advance HL by five characters in list of return
                          ; values string...
  ADD HL,DE               ; ...
  LD E,6                  ; Load E with 6 as there are 6 keyboard half-rows to
                          ; test (loop counter)
  RLC B                   ; With each loop, change BC from 65278 -> 65022 ->
                          ; 64510 -> 63486 -> 61438 -> 57342 -> 49150
  IN A,(C)                ; Read from port 254 into A (i.e. read keyboard)
  AND 31                  ; Strip out all but the five bits representing key
                          ; presses
  XOR 31                  ; Invert all of the lowest five bits
  JR NZ,47843             ; If this value is non-zero, then a key has been
                          ; pressed, so skip ahead to 47843
  INC HL                  ; Advance HL by five characters in list of return
                          ; values string...
  INC HL                  ; ...
  INC HL                  ; ...
  INC HL                  ; ...
  INC HL                  ; ...
  DEC E                   ; Decrease number of remaining keyboard half-rows to
                          ; check
  JR NZ,47811             ; If there are any more half rows to check then loop
                          ; back to 47811
  RLC B                   ; Set BC to 32766 for final keyboard half-row
  IN A,(C)                ; Read from port 254 into A (i.e. read keyboard)
  SET 1,A                 ; Set bit 1 of A (i.e. clear pressing of SYMBOL
                          ; SHIFT)
  AND 31                  ; Strip out all but the five bits representing key
                          ; presses
  XOR 31                  ; Invert all of the lowest five bits
  JR NZ,47843             ; If this value is non-zero, then a key has been
                          ; pressed, so skip ahead to 47843
  EXX                     ; Swap registers
  RET                     ; Return [no key pressed]
  SRL A                   ; Shift bits right
  JR C,47850              ; If carry flag is set, then this is the key that was
                          ; pressed, so skip ahead to 47850
  INC HL                  ; Advance HL to check next character
  JR 47843                ; Loop back to 47843
  LD A,(HL)               ; Load current character in list of return values
                          ; string into A as this is the key that was pressed
  EXX                     ; Swap registers
  RET                     ; Return [key pressed]

; Return Values from Keyboard Reading Routine
  DEFM "cZXCVASDFGQWERT1234509876POIUYeLKJH yMNB"

; Check for Control Key Press and Store at 34219
;
; Used by the routine at 34438.
  XOR A                   ; Clear previously stored control input...
  LD (34219),A            ; ...
  CALL 47788              ; Read keyboard and load character of pressed key
                          ; into A
  OR A                    ; If no key was pressed...
  JR Z,47930              ; ...then read joystick input and return
  LD E,1                  ; Set least significant bit of E as we are testing
                          ; the first keyboard control first
  LD B,7                  ; Set B to 7 as there are 7 keyboard controls to
                          ; check (loop counter)
  LD HL,46683             ; Point HL at Table of Current Keyboard Controls
  CP (HL)                 ; If pressed key is the same as the current keyboard
                          ; control...
  JR Z,47921              ; ...then skip ahead to 47921
  INC HL                  ; Advance HL to next keyboard control
  SLA E                   ; Shift E left
  DJNZ 47910              ; Loop back to 47910 for next keyboard control
  XOR A                   ; Set A to zero
  JR 47926                ; Skip ahead to 47926
  LD A,E                  ; Load input bitmap into A (bit that is set
                          ; represents the control that has been pressed)
  BIT 5,A                 ; If bit 5 is set (i.e. Berk / Drutt key has been
                          ; pressed)...
  JR NZ,47942             ; ...then jump to 47942 (Wait for current key to be
                          ; released and another to be pressed, storing in A)
                          ; and return
; This entry point is used by the routine at 47930.
  LD (34219),A            ; Store control input at 34219
  RET                     ; Return

; If Joystick Mode is On, then Read Joystick Input
;
; Used by the routine at 47893.
  LD A,(34298)            ; If Joystick Mode is Off...
  OR A                    ; ...
  RET Z                   ; ...then return
  IN A,(31)               ; Read state of Kempston joystick into A
  AND 31                  ; If joystick input is non-zero...
  JR NZ,47926             ; ...then jump to 47926
  RET                     ; Return

; Wait for Current Key to Be Released and Another to Be Pressed, Storing in A
;
; Used by the routines at 34438, 47893 and 47955.
  CALL 47788              ; Read keyboard and load character of pressed key
                          ; into A
  OR A                    ; If a key is pressed...
  JR NZ,47942             ; ...then loop back to 47942
  CALL 47788              ; Read keyboard and load character of pressed key
                          ; into A
  OR A                    ; If a key is not pressed...
  JR Z,47948              ; ...then loop back to 47948
  RET                     ; Return

; Wait for Key-Press, Store Pressed Key Code in A and Play Main Menu Sound
;
; Used by the routines at 46830 and 46968. Output: A  code of pressed key
  CALL 47942              ; Wait for current key to be released and another to
                          ; be pressed, storing in A
  PUSH AF                 ; Store AF (A = last pressed key)
  LD A,2                  ; Set sound 2 as pending if appropriate, then play
                          ; and clear pending sound...
  CALL 59722              ; ...
  POP AF                  ; Restore AF (A = last pressed key)
  RET                     ; Return

