; Advance HL to Next Script Instruction and Execute
;
; Used by the routines at 35735, 36116, 36390, 36471, 36542, 36610, 36947,
; 36950, 36984, 36990, 37085, 37639, 37753, 38074, 38165, 38540, 38554, 41498,
; 41617, 48133, 48142, 48148, 48158, 48220, 48246, 48260, 48267, 48274, 48307,
; 48336, 48365, 48487, 48567, 48593, 48641, 48686, 48692, 48698, 48704, 48920,
; 49010, 51765, 52029, 52038, 52047, 52142, 52243, 52309, 52860, 52870, 52889
; and 52967. Input:  IX  (Entry at 48096 and 48098) Address of complex state
; data for an entity Output: HL  Current position in script data
  INC HL                  ; Advance Script Data Pointer by two bytes...
  INC HL                  ; ...
; This entry point is used by the routines at 35577, 35735, 36008, 36036,
; 36116, 36367, 36390, 36471, 36638, 37085, 37639, 37718, 37753, 37778, 38074,
; 38554, 41550, 48285, 48295, 48307, 48324, 48336, 48353, 48365, 48388, 48934,
; 48976, 49010, 51765, 51779, 51904, 51924, 51944, 51954, 51960, 52053, 52148,
; 52243, 52908, 52914, 52967 and 53083.
  INC HL                  ; Advance Script Data Pointer by one byte
  LD A,(HL)               ; Load byte at this location into A
  DEC HL                  ; Move HL back one byte
  OR A                    ; If byte loaded into A was zero (i.e. a script
                          ; instruction)...
  JR Z,48117              ; ...then skip ahead to 48117
; HL pointing to a graphic layout data address, rather than a script
; instruction
  LD (34277),HL           ; Store address in HL at 34277 as position in script
                          ; currently running
  LD A,(HL)               ; Load word at location HL into Graphic Layout
                          ; Address in current entity's complex state data
                          ; entry (IX)...
  LD (IX+2),A             ; ...
  INC HL                  ; ...
  LD A,(HL)               ; ...
  LD (IX+3),A             ; ...
  RET                     ; Return
; HL pointing to a script instruction
  LD A,(HL)               ; Load script "instruction" into A
  PUSH HL                 ; Store HL (pointer to current position in script
                          ; data)
  LD HL,47966             ; Point HL at Table of Script Routine Start Addresses
  ADD A,A                 ; Load double index of script instruction into BC...
  LD C,A                  ; ...
  LD B,0                  ; ...
  ADD HL,BC               ; ...and add as offset in HL to point to start
                          ; address of required script routine
  LD C,(HL)               ; Load address at this location into BC...
  INC HL                  ; ...
  LD B,(HL)               ; ...
  POP HL                  ; Restore HL (pointer to current position in script
                          ; data)
  PUSH BC                 ; Push address in BC onto stack...
  RET                     ; ...and RET to this address

; Script Routine (04) If Current Character and Target Entity are in the Same
; Room then Set Pending Sound Input:  HL Current position in script data IX
; Address of complex state data for an entity
  INC HL                  ; Advance HL to parameter (sound index)...
  INC HL                  ; ...
  LD A,(HL)               ; Load A with sound index
  CALL 59601              ; If current character is in same room as target
                          ; entity at IX then set pending sound to A
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (62) Move Entity at IX into Room to the Left, if Appropriate
  CALL 54348              ; Move entity at IX into room to the left, if
                          ; appropriate
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (16) Have Berk Hold an Entity, and Position it Appropriately
; Between his Hands
  CALL 48850              ; Have Berk hold an entity, and position it
                          ; appropriately between his hands
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (17) Have Berk Put Down an Entity in Front of Him, if
; Appropriate Output: D  Depth offset for entity being put down
  LD D,0                  ; Load D with depth offset of 0 (as Berk is putting
                          ; down an entity in front of him)
  JR 48160                ; Have Berk put down an entity, if appropriate

; Script Routine (18) Have Berk Put Down an Entity Behind Him, if Appropriate
; Input:  D  (Entry at 48160 only) Depth offset for entity being put down IX
; Address of complex state data (current level) for Berk
  LD D,255                ; Load D with depth offset of -1 (as Berk is putting
                          ; down an entity behind him)
; This entry point is used by the routine at 48154.
  BIT 4,(IX+9)            ; If Berk's Carrying Something Flag is reset...
  RET Z                   ; ...then return
; Berk is carrying something
  RES 4,(IX+9)            ; Reset Berk's Carrying Something Flag
  XOR A                   ; Set class of entity held by Berk to zero (i.e.
                          ; nothing)...
  LD (34221),A            ; ...
  LD IY,(34260)           ; Load IY with address of complex state data for
                          ; entity last held by Berk...
  RES 5,(IY+10)           ; ...and reset its Is Being Carried Flag
  LD A,(IY+6)             ; Load E with height of entity minus one...
  SUB (IY+4)              ; ...
  LD E,A                  ; ...
  LD A,(34222)            ; Load A with y-coordinate minus one of top edge of
                          ; coloured creature slot Berk is interacting with...
  OR A                    ; ...and if this is not zero...
  JR NZ,48198             ; ...then skip ahead to 48198
; Value at 34222 is zero (i.e. Berk not interacting with a coloured creature
; slot on Level 3)
  LD A,(IX+6)             ; Load A with y-coordinate of Berk's bottom edge...
  ADD A,D                 ; ...plus depth offset...
; At this point, A holds either the y-coordinate of Berk's bottom edge plus
; depth offset, or the y-coordinate minus one of the top edge of (actually the
; y-coordinate of the bottom of the space within) a coloured creature slot on
; Level 3. This value in A is the y-coordinate that the carried entity's bottom
; edge will take on when that entity is put down.
  LD (IY+6),A             ; Set the y-coordinate of the bottom edge of the
                          ; put-down entity to value in A
  SUB E                   ; Set the y-coordinate of the top edge of the
                          ; put-down entity...
  LD (IY+4),A             ; ...to that of the bottom edge, minus the height as
                          ; appropriate
  XOR A                   ; Set value at 34222 to zero...
  LD (34222),A            ; ...as Berk is not (any longer) interacting with a
                          ; coloured creature slot on Level 3
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (10) Reset Walking Left and Walking Right Flags
;
; Used by the routine at 36542. Output: E  Combination of flags to (re)set
  LD E,0                  ; Reset Entity Walking Left and Entity Walking Right
                          ; flags...
  JR 48222                ; ...and advance HL to next script instruction and
                          ; execute

; Script Routine (12) Reset Walking Left Flag and Set Walking Right Flag
; Output: E  Combination of flags to (re)set
  LD E,1                  ; Set Entity Walking Right Flag, reset Entity Walking
                          ; Left Flag...
  JR 48222                ; ...and advance HL to next script instruction and
                          ; execute

; Script Routine (11) Set Walking Left Flag and Reset Walking Right Flag Input:
; E  (Entry at 48222 only) Combination of flags to (re)set IX  Address of
; complex state data for an entity
  LD E,2                  ; Prepare to set Entity Walking Left Flag and reset
                          ; Entity Walking Right Flag
; This entry point is used by the routines at 48212 and 48216.
  LD A,(IX+11)            ; (Re)set Walking Left and Walking Right flags as
                          ; prepared in E...
  AND 240                 ; ...and reset Unused (11,2) and Unused (11,3)
                          ; flags...
  ADD A,E                 ; ...
  LD (IX+11),A            ; ...
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (07) Reset Berk's Facing Into Screen, Facing Left and Facing
; Right Flags Output: B  Combination of flags to (re)set
  LD B,0                  ; Reset Berk's Facing Into Screen, Facing Left and
                          ; Facing Right flags...
  JR 48248                ; ...and advance HL to next script instruction and
                          ; execute

; Script Routine (06) Set Berk's Facing Into Screen Flag, and Reset his Facing
; Left and Facing Right Flags Output: B Combination of flags to (re)set
  LD B,2                  ; Set Berk's Facing Into Screen Flag, and reset his
                          ; Facing Left and Facing Right flags...
  JR 48248                ; ...and advance HL to next script instruction and
                          ; execute

; Script Routine (13) Set Berk's Facing Left Flag, and Reset his Facing Into
; Screen and Facing Right Flags Output: B Combination of flags to (re)set
  LD B,4                  ; Set Berk's Facing Left Flag, and reset his Facing
                          ; Into Screen and Facing Right flags...
  JR 48248                ; ...and advance HL to next script instruction and
                          ; execute

; Script Routine (14) Set Berk's Facing Right Flag, and Reset his Facing Into
; Screen and Facing Left Flags Input:  B (Entry at 48248 only) Combination of
; flags to (re)set IX  Address of complex state data (current level) for Berk
  LD B,8                  ; Prepare to set Berk's Facing Right Flag, and reset
                          ; his Facing Into Screen and Facing Left flags
; This entry point is used by the routines at 48234, 48238 and 48242.
  LD A,(IX+9)             ; Load A with Berk's flags...
  AND 241                 ; ...clearing Facing Into Screen, Facing Left and
                          ; Facing Right flags
  ADD A,B                 ; Combine with flags in B...
  LD (IX+9),A             ; ...and store
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (09) Reset Must Process Current Script Data Flag for Entity at
; IX Input:  IX  Address of complex state data for an entity
  RES 0,(IX+9)            ; Reset Must Process Current Script Data Flag
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (08) Set Must Process Current Script Data Flag for Entity at
; IX Input:  IX  Address of complex state data for an entity
  SET 0,(IX+9)            ; Set Must Process Current Script Data Flag
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (15) Jump to New Address if Berk Is Carrying Something Input:
; HL  Current position in script data IX  Address of complex state data for an
; entity
  INC HL                  ; Advance HL to parameter for current instruction...
  INC HL                  ; ...
  BIT 4,(IX+9)            ; If Berk is carrying an entity...
  JR NZ,48287             ; ...then read parameter address into HL and execute
                          ; next script instruction at that address
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (01) Load HL (Script Data Pointer) with New Address
;
; Functionality analogous to JP instruction. Input:  HL  Address in script data
; Output: HL  New address in script data
  INC HL                  ; Advance Script Data Pointer by two bytes...
  INC HL                  ; ...
; This entry point is used by the routine at 48274.
  LD C,(HL)               ; Read WORD at this location into HL...
  INC HL                  ; ...(i.e. update Script Data Pointer to this
                          ; address)...
  LD B,(HL)               ; ...
  PUSH BC                 ; ...
  POP HL                  ; ...
  JP 48098                ; ...and execute script instruction at this location

; Script Routine (23) Start Loop (1 / 3)
;
; Start a loop in script data. The first of the following two bytes is the
; repeat count and the second is disregarded. The current value of the repeat
; counter is stored at 34285 and the address of the next instruction (i.e. the
; first instruction that is processed in each loop) is stored at 34285. Output:
; HL  Address of next script instruction to execute
  CALL 48382              ; Load A with script instruction parameter, and
                          ; advance HL to next instruction
  LD (34285),A            ; Store repeat count at 34285
  LD (34286),HL           ; Store address to return to (i.e. first instruction
                          ; in loop) at 34285...
  JP 48098                ; ...and execute script instruction at this location

; Script Routine (24) End Loop (1 / 3) Output: HL  Address of next script
; instruction to execute
  LD A,(34285)            ; Load A with current repeat count
  OR A                    ; If repeat count is zero...
  JP Z,48096              ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  DEC A                   ; Decrease repeat count...
  LD (34285),A            ; ...and store
  LD HL,(34286)           ; Load HL with address of first instruction in
                          ; loop...
  JP 48098                ; ...and execute script instruction at this location

; Script Routine (25) Start Loop (2 / 3)
;
; Start a loop in script data. The first of the following two bytes is the
; repeat count and the second is disregarded. The current value of the repeat
; counter is stored at 34288 and the address of the next instruction (i.e. the
; first instruction that is processed in each loop) is stored at 34288. Output:
; HL  Address of next script instruction to execute
  CALL 48382              ; Load A with script instruction parameter, and
                          ; advance HL to next instruction
  LD (34288),A            ; Store repeat count at 34288
  LD (34289),HL           ; Store address to return to (i.e. first instruction
                          ; in loop) at 34288...
  JP 48098                ; ...and execute script instruction at this location

; Script Routine (26) End Loop (2 / 3) Output: HL  Address of next script
; instruction to execute
  LD A,(34288)            ; Load A with current repeat count
  OR A                    ; If repeat count is zero...
  JP Z,48096              ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  DEC A                   ; Decrease repeat count...
  LD (34288),A            ; ...and store
  LD HL,(34289)           ; Load HL with address of first instruction in
                          ; loop...
  JP 48098                ; ...and execute script instruction at this location

; Script Routine (27) Start Loop (3 / 3)
;
; Start a loop in script data. The first of the following two bytes is the
; repeat count and the second is disregarded. The current value of the repeat
; counter is stored at 34291 and the address of the next instruction (i.e. the
; first instruction that is processed in each loop) is stored at 34291. Output:
; HL  Address of next script instruction to execute
  CALL 48382              ; Load A with script instruction parameter, and
                          ; advance HL to next instruction
  LD (34291),A            ; Store repeat count at 34291
  LD (34292),HL           ; Store address to return to (i.e. first instruction
                          ; in loop) at 34291...
  JP 48098                ; ...and execute script instruction at this location

; Script Routine (28) End Loop (3 / 3) Output: HL  Address of next script
; instruction to execute
  LD A,(34291)            ; Load A with current repeat count
  OR A                    ; If repeat count is zero...
  JP Z,48096              ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  DEC A                   ; Decrease repeat count...
  LD (34291),A            ; ...and store
  LD HL,(34292)           ; Load HL with address of first instruction in
                          ; loop...
  JP 48098                ; ...and execute script instruction at this location

; Load A with Script Instruction Parameter then Advance HL to Next Instruction
;
; Used by the routines at 48295, 48324 and 48353.
  INC HL                  ; Advance HL by two bytes, beyond end of current
                          ; instruction...
  INC HL                  ; ...
  LD A,(HL)               ; Load value here into A
  INC HL                  ; Advance HL by two more bytes to start of next
                          ; instruction...
  INC HL                  ; ...
  RET                     ; Return

; Decrease Remaining Time for Current Power and if Zero, Exit Calling Routine
; and Run Script Data for Removal of Power
;
; Used by the routines at 35689, 36542 and 48487.
  LD DE,(34224)           ; Load remaining power time into DE
  LD A,E                  ; Increase E (number of game-cycles power has been in
                          ; use in current block)...
  INC A                   ; ...
  LD E,A                  ; ...
  CP 15                   ; If 16 game-cycles of power use have not yet
                          ; elapsed...
  JR NZ,48402             ; ...then skip ahead to 48402
  LD E,0                  ; Reset number of game-cycles power has been in use
                          ; to zero...
  DEC D                   ; ...and decrease remaining number of 16-game-cycles
  LD (34224),DE           ; Store updated remaining power time...
  RET NZ                  ; ...and return if this is not zero
  POP BC                  ; Remove top value from stack (i.e. return address to
                          ; routine that called this routine)
  CALL 48417              ; Remove Berk's current power and reset sweet /
                          ; mushroom / edible eyes / sausage to its original
                          ; position
  LD HL,35275             ; Point HL at script data for Berk's power
                          ; expiring...
  JP 48098                ; ...and execute

; Remove Berk's Current Power and Reset Sweet / Mushroom / Edible Eyes /
; Sausage to its Original Position
;
; Used by the routines at 36390, 36471, 39151 and 48388.
  LD A,(34220)            ; If Berk has no current power...
  OR A                    ; ...
  RET Z                   ; ...then return
  PUSH IX                 ; Store IX
  CP 6                    ; If Berk's current power is not 6 (flying, level 3,
                          ; 2)...
  JR NZ,48445             ; ...then skip ahead to 48445
  LD A,13                 ; Reset complex state data for Red Coloured Creature
                          ; to that stored in Initial-State Table...
  CALL 53987              ; ...
  LD A,14                 ; Reset complex state data for Yellow Coloured
                          ; Creature to that stored in Initial-State Table...
  CALL 53987              ; ...
  LD A,15                 ; Reset complex state data for White Coloured
                          ; Creature to that stored in Initial-State Table...
  CALL 53987              ; ...
  JR 48474                ; Skip ahead to 48474
  CP 10                   ; If Berk's current power is not 10 (floating)...
  JR NZ,48474             ; ...then skip ahead to 48474
  LD IX,(34240)           ; Load IX with address of current level's complex
                          ; state data for Berk
  RES 7,(IX+9)            ; Reset Berk's Moving Upwards Flag
  LD (IX+11),192          ; Reset Berk's Walking Right, Walking Left, Unused
                          ; (11,2), Unused (11,3), Impassable Leftwards and
                          ; Impassable Rightwards flags and set his Interaction
                          ; (11,6) and Interaction (11,7) flags
  RES 7,(IX+8)            ; Reset bit 7 of Berk's class value (change from 159
                          ; to 31)
  DEC (IX+6)              ; Decrease Berk's bottom y-coordinate by two...
  DEC (IX+6)              ; ...
  CALL 55516              ; Set Berk's Can Fall Flag and set his initial
                          ; velocity factor to 2
  LD A,(34220)            ; Reset complex state data for entity responsible for
                          ; Berk's current power to that stored in
                          ; Initial-State Table...
  CALL 53987              ; ...
  XOR A                   ; Clear Berk's current power...
  LD (34220),A            ; ...
  POP IX                  ; Restore IX
  RET                     ; Return

; Script Routine (32) Update Berk's Position and State (Flying) Depending Upon
; Control Input
;
; See pokes Input:  IX  (Entry at 48487 only) Address of complex state data
; (current level) for Berk IX  (Entry at 48541 only) Address of complex state
; data for an entity Output: HL  Address of next script instruction to execute
  CALL 48388              ; Decrease remaining time for current power and if
                          ; zero, exit this routine and run script data for
                          ; removal of power
  CALL 54768              ; Check entity at IX for collision with another
                          ; entity at same depth whose Interaction (11,6) Flag
                          ; is set...
  CP 130                  ; ...and if collision was not with entity of class
                          ; 130 (causes Berk and Drutt to bounce off or bang
                          ; head)...
  JR NZ,48507             ; ...then skip ahead to 48507
  RES 6,(IX+9)            ; Reset entity's Is Flying Flag
  LD HL,35359             ; Load HL with script data address for Berk starting
                          ; to fall downwards
  JP 48096                ; Advance HL to next script instruction and execute
  LD A,(IX+6)             ; If y-coordinate of Berk's bottom edge is 121 or
                          ; greater...
  CP 121                  ; ...
  JR NC,48527             ; ...then skip ahead to 48527
  LD A,(34219)            ; Load A with control input
  BIT 0,A                 ; If right pressed...
  JP NZ,48593             ; ...then move Berk right one character, and into new
                          ; room if appropriate
  BIT 1,A                 ; If left pressed...
  JP NZ,48641             ; ...then move Berk left one character, and into new
                          ; room if appropriate
  LD A,(IX+6)             ; If y-coordinate of Berk's bottom edge is less than
                          ; 98...
  CP 98                   ; ...
  JP C,48096              ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  CALL 55433              ; Change Berk's room up one if appropriate
  CALL 48710              ; Move carried entity in front of Berk as he faces
                          ; out of screen
; This entry point is used by the routine at 37718. It is also the start of the
; routine triggered by instruction 34 in script data.
  DEC (IX+4)              ; Decrease y-coordinates of entity's top and bottom
                          ; edges by one character...
  DEC (IX+6)              ; ...
  BIT 4,(IX+9)            ; If entity is Berk and his Carrying Something Flag
                          ; is reset...
  JP Z,48096              ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  LD IY,(34260)           ; Load IY with address of complex state data for
                          ; entity held by Berk...
  DEC (IY+4)              ; ...and decrease its top and bottom y-coordinates by
                          ; one character...
  DEC (IY+6)              ; ...
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (35) Move Entity at IX (and if Berk, Carried Entity) Down One
; Character
;
; Used by the routine at 37778. Input:  IX  Address of complex state data for
; an entity
  INC (IX+4)              ; Increase y-coordinates of entity's top and bottom
                          ; edges by one character...
  INC (IX+6)              ; ...
  BIT 4,(IX+9)            ; If entity is Berk and his Carrying Something Flag
                          ; is reset...
  JP Z,48096              ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  LD IY,(34260)           ; Load IY with address of complex state data for
                          ; entity held by Berk...
  INC (IY+4)              ; ...and increase its top and bottom y-coordinates by
                          ; one character...
  INC (IY+6)              ; ...
  JP 48096                ; Advance HL to next script instruction and execute

; Move Entity Right One Character, and Into New Room if Appropriate
;
; Used by the routine at 48487. Input:  IX  (Entry at 48593 only) Address of
; complex state data (current level) for Berk IX  (Entry at 48615 only) Address
; of complex state data for an entity
  LD A,(34235)            ; Load E with width of current room (chars) + 99...
  LD E,A                  ; ...
  LD A,(IX+7)             ; If x-coordinate of Berk's right side is less than
                          ; x-coordinate of right of current room...
  CP E                    ; ...
  JR C,48615              ; ...then skip ahead to 48615 (move Berk right by one
                          ; character
  CALL 54505              ; Load B with index of room to right of current
                          ; character's current room...
  JP Z,48096              ; ...and if there is no room to the right, then jump
                          ; to 48096 (advance HL to next script instruction and
                          ; execute)
  CALL 54383              ; Move Berk into room to right of its current room
                          ; and update position of carried entity if moving
                          ; entity is Berk
  CALL 48710              ; Move carried entity in front of Berk as he faces
                          ; out of screen
; This entry point is used by the routine at 37085. It is also the start of the
; routine triggered by instruction 03 in script data.
  INC (IX+5)              ; Increase x-coordinates of entity's left and right
                          ; edges by one character...
  INC (IX+7)              ; ...
  BIT 4,(IX+9)            ; If entity is Berk and his Carrying Something Flag
                          ; is reset...
  JP Z,48096              ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  LD IY,(34260)           ; Load IY with address of complex state data for
                          ; entity held by Berk...
  INC (IY+5)              ; ...and increase its left and right x-coordinates by
                          ; one character...
  INC (IY+7)              ; ...
  JP 48096                ; Advance HL to next script instruction and execute

; Move Entity Left One Character, and Into New Room if Appropriate
;
; Used by the routine at 48487. Input:  IX  (Entry at 48641 only) Address of
; complex state data (current level) for Berk IX  (Entry at 48660 only) Address
; of complex state data for an entity
  LD A,100                ; If Berk's left-side x-coordinate is greater than
                          ; 100 (x-coordinate of left side of room)...
  CP (IX+5)               ; ...
  JR C,48660              ; ...then skip ahead to 48660 (move Berk left by one
                          ; character)
  CALL 54539              ; Load B with index of room to left of entity's
                          ; current room...
  JP Z,48096              ; ...and if there is no room to the left, then jump
                          ; to 48096 (advance HL to next script instruction and
                          ; execute)
  CALL 54419              ; Move Berk into room to left of its current room and
                          ; update position of carried entity if moving entity
                          ; is Berk
  CALL 48710              ; Move carried entity in front of Berk as he faces
                          ; out of screen
; This entry point is used by the routine at 37085. It is also the start of the
; routine triggered by instruction 02 in script data.
  DEC (IX+5)              ; Decrease x-coordinates of entity's left and right
                          ; edges by one character...
  DEC (IX+7)              ; ...
  BIT 4,(IX+9)            ; If entity is Berk and his Carrying Something Flag
                          ; is reset...
  JP Z,48096              ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  LD IY,(34260)           ; Load IY with address of complex state data for
                          ; entity held by Berk...
  DEC (IY+5)              ; ...and decrease its left and right x-coordinates by
                          ; one character...
  DEC (IY+7)              ; ...
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (22) Move Carried Entity Behind Berk as he Faces Into Screen
  CALL 48715              ; Move carried entity behind Berk as he faces into
                          ; screen
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (21) Move Carried Entity in Front of Berk as he Faces Out of
; Screen
  CALL 48710              ; Move carried entity in front of Berk as he faces
                          ; out of screen
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (19) Move Carried Entity to Berk's Left as he Faces Left
  CALL 48738              ; Move carried entity to Berk's left as he faces left
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (20) Move Carried Entity to Berk's Right as he Faces Right
  CALL 48727              ; Move carried entity to Berk's right as he faces
                          ; right
  JP 48096                ; Advance HL to next script instruction and execute

; Move Carried Entity in Front of Berk as he Faces Out of Screen
;
; Used by the routines at 36008, 48487, 48593, 48641 and 48692.
  CALL 48760              ; If Berk is carrying an entity then load A with its
                          ; width minus one divided by two and D with Berk's
                          ; depth, else return
  JR 48719                ; Move carried entity into horizontal position
                          ; appropriate to its width (see notes in routine at
                          ; 48850) and return

; Move Carried Entity Behind Berk as he Faces into Screen
;
; Used by the routine at 48686.
  CALL 48760              ; If Berk is carrying an entity then load A with its
                          ; width minus one divided by two and D with Berk's
                          ; depth, else return
  INC D                   ; Increase the depth (as carried entity has moved
                          ; deeper into the screen)
; This entry point is used by the routine at 48710.
  XOR 1                   ; Move carried entity into horizontal position
                          ; appropriate to its width (see notes in routine at
                          ; 48850)...
  INC A                   ; ...
  ADD A,(IX+5)            ; ...
  JR 48749                ; Set carried entity's horizontal position and depth
                          ; and return

; Move Carried Entity to Berk's Right as he Faces Right
;
; Used by the routines at 48704 and 54383.
  CALL 48760              ; If Berk is carrying an entity then load A with its
                          ; width minus one divided by two and D with Berk's
                          ; depth, else return
  INC D                   ; Increase the depth (as carried entity has moved
                          ; deeper into the screen)
  NEG                     ; Subtract width of carried entity minus one divided
                          ; by two...
  ADD A,(IX+7)            ; ...from Berk's right-side x-coordinate and load
                          ; into A
  JR 48749                ; Set carried entity's calculated horizontal position
                          ; and depth and return

; Move Carried Entity to Berk's Left as he Faces Left
;
; Used by the routines at 48698 and 54419. Input:  IY  Address of complex state
; data for an entity carried by Berk
  CALL 48760              ; If Berk is carrying an entity then load A with its
                          ; width minus one divided by two and D with Berk's
                          ; depth, else return
  ADD A,A                 ; Double A to give width minus one... (see bugs)
  INC A                   ; ...and add one to get width of entity
  NEG                     ; Subtract width of carried entity...
  ADD A,(IX+5)            ; ...from Berk's left-side x-coordinate and load into
                          ; A
  INC D                   ; Increase the depth (as carried entity has moved
                          ; deeper into the screen)
; This entry point is used by the routines at 48715 and 48727.
  LD (IY+5),A             ; Set carried entity's horizontal position and
                          ; depth...
  ADD A,E                 ; ...
  LD (IY+7),A             ; ...
  LD (IY+1),D             ; ...
  RET                     ; Return

; Load A, D and E with Positional Data for a Carried Entity or Return
;
; Used by the routines at 48710, 48715, 48727 and 48738. Input:  IX  Address of
; complex state data for an entity Output: A  Width of carried entity
; (characters) minus 1, divided by two D  Depth of entity at IX (Berk) E Width
; of carried entity (characters) minus 1 IY  Address of complex state data for
; entity held by Berk
  BIT 4,(IX+9)            ; If entity IX is Berk and his Carrying Something
                          ; Flag is set...
  JR NZ,48768             ; ...then skip ahead to 48768
  POP BC                  ; Pop top value (return address) off stack...
  RET                     ; ...and return to routine that called the calling
                          ; routine
  LD IY,(34260)           ; Load IY with address of complex state data for
                          ; entity held by Berk
  LD A,(IX+0)             ; Set this entity's room to be same as Berk's...
  LD (IY+0),A             ; ...
  CALL 48897              ; Move carried entity into vertical position
                          ; appropriate to its height
  LD A,(34272)            ; Load A and E with width of entity (characters)
                          ; carried by Berk, minus 1...
  LD E,A                  ; ...
  SRL A                   ; Divide A by two, removing remainder
  LD D,(IX+1)             ; Load carried entity's depth into D
  RET                     ; Return

; Unused routine
;
; Assuming that IX and IY contain the addresses of two entities' complex state
; data, this routine will position the entity at IX such that it is
; horizontally centred with respect to, and B characters below the entity at
; IY. Input: IX  Address of complex state data for Entity 1 (assumed) IY
; Address of complex state data for Entity 2 (assumed) B  Vertical offset
; (assumed)
  LD A,(IX+6)             ; Load C with height of Entity 1 minus one...
  SUB (IX+4)              ; ...
  LD C,A                  ; ...
  LD A,(IY+6)             ; Load A with y-coordinate of bottom edge of Entity 2
                          ; plus B...
  ADD A,B                 ; ...
  LD (IX+6),A             ; Set y-coordinate of bottom edge of Entity 1 to A
  SUB C                   ; Update y-coordinate of top edge of Entity 1
                          ; accordingly...
  LD (IX+4),A             ; ...
  LD A,(IX+7)             ; Load B with width of Entity 1 minus one...
  SUB (IX+5)              ; ...
  LD B,A                  ; ...
  SRL A                   ; Load C with half of width of Entity 1 minus one...
  LD C,A                  ; ...
  LD A,(IY+7)             ; Load A with half of width of Entity 2 minus one...
  SUB (IY+5)              ; ...
  SRL A                   ; ...
  ADD A,(IY+5)            ; ...and add x-coordinate of left edge of Entity 2
; At this point, A holds the x-coordinate of the mid-point of Entity 2
  SUB C                   ; Subtract half of width of Entity 1 minus one...
  LD (IX+5),A             ; ...and set as x-coordinate of left edge of Entity 1
  ADD A,B                 ; Update x-coordinate of right edge of entity 2
                          ; accordingly...
  LD (IX+7),A             ; ...
  LD A,(IX+8)             ; If Entity 1 is not Berk...
  CP 31                   ; ...
  RET NZ                  ; ...then return
  PUSH HL                 ; Store HL
  CALL 53887              ; Paint red areas outside accessible areas of current
                          ; character's current room
  POP HL                  ; Restore HL
  RET                     ; Return

; Have Berk Hold an Entity, and Position it Appropriately Between his Hands
;
; The instruction blocks 48872-48894 and 48897-48916 move the entity that Berk
; is carrying into position (i.e. between Berk's hands), at a horizontal or
; vertical position appropriate to the height / width of that entity. These
; instructions result in the following x- or y-coordinates (left or top of
; carried entity relative to left or top of carrier, i.e. Berk): Input:  IX
; Address of complex state data (current level) for Berk IY  (entry at 48897)
; Address of complex state data for an entity carried by Berk Output: IY
; Address of complex state data for entity held by Berk
  LD IY,(34256)           ; Load IY with address of complex state data for
                          ; entity to be held by Berk...
  LD (34260),IY           ; ...and store at 34260 as address of state data for
                          ; entity held by Berk
  SET 5,(IY+10)           ; Set the entity's Is Being Carried Flag
  SET 4,(IX+9)            ; Set Berk's Carrying Something Flag
  LD A,(IY+8)             ; Set class of entity held by Berk to be this
                          ; entity's class...
  LD (34221),A            ; ...
  LD A,(IY+7)             ; Load A with the width of the entity, minus 1...
  SUB (IY+5)              ; ...
  LD (34272),A            ; ...and store at 34272
  LD E,A                  ; Load E with width of entity, minus 1
  SRL A                   ; Move entity defined at IY into horizontal position
                          ; appropriate to its height (see notes above)...
  XOR 1                   ; ...
  INC A                   ; ...
  ADD A,(IX+5)            ; ...
  LD (IY+5),A             ; ...
  ADD A,E                 ; ...
  LD (IY+7),A             ; ...
; This entry point is used by the routine at 48760.
  LD A,(IY+6)             ; Move entity defined at IY into vertical position
                          ; appropriate to its height (see notes above)...
  SUB (IY+4)              ; ...
  LD E,A                  ; ...
  SRL A                   ; ...
  XOR 1                   ; ...
  INC A                   ; ...
  ADD A,(IX+4)            ; ...
  LD (IY+4),A             ; ...
  ADD A,E                 ; ...
  LD (IY+6),A             ; ...
  RET                     ; Return

; Script Routine (29) Make Berk Start Falling, and Drop his Carried Entity if
; Appropriate Input:  IX  Address of complex state data for an entity
  LD (IX+12),2            ; Set Berk's initial velocity factor to 2
  SET 6,(IX+10)           ; Set Berk's "Can Fall" flag
  CALL 36296              ; Make Berk drop the entity he is holding and load IY
                          ; with its complex state data address
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (30) Check Berk's Fall Velocity, and React to Landing
;
; See trivia and pokes Input:  IX  Address of complex state data (current
; level) for Berk Output: HL  Address of next script instruction to execute
  BIT 6,(IX+10)           ; If Berk's "Can Fall" Flag is reset (i.e. Berk has
                          ; landed)...
  JR Z,48958              ; ...then skip ahead to 48958
  BIT 3,(IX+12)           ; If bit 3 of Berk's velocity factor is set (i.e.
                          ; Berk has a velocity factor of 8)...
  JR NZ,48952             ; ...then skip ahead to 48952
  LD HL,35363             ; Load HL with address of script data for Berk
                          ; starting to fall...
  JP 48098                ; ...and execute
  LD HL,35367             ; Point HL at script data for Berk falling rapidly
                          ; (horizontal, arms outstretched)...
  JP 48098                ; ...and execute
  BIT 3,(IX+12)           ; If bit 3 of Berk's velocity factor is set (i.e.
                          ; Berk has a velocity factor of 8)...
  JR NZ,48970             ; ...then skip ahead to 48970
  LD HL,35457             ; Point HL at script data for Berk landing (after
                          ; jump)
  JP 48098                ; ...and execute
  LD HL,35371             ; Point HL at script data for Berk lying on floor
                          ; stunned and getting up
  JP 48098                ; ...and execute

; Script Routine (31) React to Berk's Landing
;
; See trivia Input:  IX  Address of complex state data for an entity Output: HL
; Address of next script instruction to execute
  BIT 3,(IX+12)           ; If bit 3 of Berk's velocity factor is set (i.e.
                          ; Berk has a velocity factor of 8)...
  JR NZ,48988             ; ...then skip ahead to 48988
  LD HL,35457             ; Point HL at script data for Berk landing (after
                          ; jump)
  JP 48098                ; ...and execute
  LD HL,35371             ; Point HL at script data for Berk lying on floor
                          ; stunned and getting up
  JP 48098                ; ...and execute

; Table of Addresses of Berk's Jump Script Data
  DEFW 35441              ; (1) - Berk starting to jump straight up
  DEFW 35447              ; (2) - Unused
  DEFW 35457              ; (3) - Berk landing (after jump)
  DEFW 35469              ; (4) - Berk jumping left
  DEFW 35481              ; (5) - Berk jumping right
  DEFW 35283              ; (6) - Berk banging head
  DEFW 35339              ; (7) - Berk falling to the right
  DEFW 35303              ; (8) - Berk falling to the left

; Script Routine (33) Advance Berk's Jump and Select Next Phase if Current
; Phase Complete Output: HL  Address of next script instruction to execute
  CALL 55041              ; Handle Berk's jump, and load A with Jump State
                          ; Index as appropriate...
  LD A,E                  ; ...
  OR A                    ; If Jump State Index is zero...
  JP Z,48096              ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  DEC A                   ; Decrease Jump State Index
  LD DE,48994             ; Load DE with start address of Table of Addresses of
                          ; Berk's Jump Script Data
  CALL 53814              ; Advance DE by 2xA Bytes, load WORD at this location
                          ; into HL...
  EX DE,HL                ; ...
  JP 48098                ; ...and execute script instruction at this location

