; Reset Drutt to Initial State
;
; Used by the routine at 34751.
  LD HL,51524             ; Set current position in Drutt's script data...
  LD (51518),HL           ; ...to 51524 (Drutt facing out of screen)
  RET                     ; Return

; Update States of Drutt and Worm and Store Current Positions in Script Data
;
; Used by the routine at 34438.
  CALL 52837              ; Update state of Worm and store current position in
                          ; script data
  LD IX,(34242)           ; Load IX with address of current level's complex
                          ; state data for Drutt
  CALL 53848              ; Store room size data for Drutt's current room
  LD HL,(51518)           ; Load current position in Drutt's script data from
                          ; 51518 into HL...
  LD (34277),HL           ; ...and store at 34277 as position in script
                          ; currently running
  CALL 51765              ; Update state of Drutt
  LD HL,(34277)           ; Store address (current position in script data)
                          ; stored at 34277...
  LD (51518),HL           ; ...at 51518 as current position in Drutt's script
                          ; data
  RET                     ; Return

; Update State of Drutt
;
; If Drutt is being carried or falling, then he should be prevented from doing
; anything. This is accomplished by constantly resetting his current script
; data position to be 51520. This does nothing except redraw Drutt. Input: IX
; Address of complex state data (current level) for Drutt Output: HL  Address
; of next script instruction to execute
  LD A,(IX+10)            ; If both Drutt's Being Carried and Can Fall flags
                          ; are reset...
  AND 96                  ; ...
  JP Z,48096              ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  LD HL,51520             ; Point HL at script data for Drutt facing out of
                          ; screen (falling)...
  JP 48098                ; ...and execute

; Script Routine (43) Select Next Action for Drutt Depending Upon Control Input
; Input:  IX  Address of complex state data (current level) for Drutt Output:
; HL  Address of next script instruction to execute
  CALL 54768              ; Check Drutt for collision with another entity at
                          ; same depth whose Interaction (11,6) Flag is set...
  CP 129                  ; ...and if collision was not with entity of class
                          ; 129 (causes other entities to start falling)...
  JR NZ,51792             ; ...then skip ahead to 51792
  CALL 55516              ; Set Drutt's Can Fall Flag and initial velocity
                          ; factor to 2
  JP 52038                ; Move Drutt down one character, advance HL to next
                          ; script instruction and execute
  LD IY,(34244)           ; Load IY with address of current level's complex
                          ; state data for worm
  LD A,(34208)            ; If Drutt Mode Flag is reset...
  BIT 0,A                 ; ...
  JR Z,51841              ; ...then skip ahead to 51841
; Drutt Mode Flag is set (i.e. Drutt Mode)
  SET 1,(IX+9)            ; Set Drutt's Under Player Control Flag
  LD A,(34219)            ; Load A with control input
  BIT 0,A                 ; If right has been pressed...
  JR NZ,51904             ; ...then randomly select script data for rightward
                          ; hop of size three or four, and execute
  BIT 1,A                 ; If left has been pressed...
  JR NZ,51924             ; ...then randomly select script data for leftward
                          ; hop of size three or four, and execute
  BIT 2,A                 ; If forward has been pressed...
  JP NZ,51954             ; ...then point HL at script data for Drutt swapping
                          ; depth levels and execute
  BIT 3,A                 ; If back has been pressed...
  JP NZ,51944             ; ...then jump to 51944 (start Drutt jumping)
; At this point, no control has been pressed, so Drutt is effectively not under
; player control
  RES 1,(IX+9)            ; Reset Drutt's Under Player Control Flag
  LD A,(IY+1)             ; If worm's depth is zero (i.e. not in play area)...
  OR A                    ; ...
  JR Z,51875              ; ...then randomly select an action for Drutt and
                          ; execute
  JP 51960                ; Move Drutt closer to the worm and eat it if close
                          ; enough
; Drutt Mode Flag is reset (i.e. Berk Mode)
  RES 1,(IX+9)            ; Reset Drutt's Under Player Control Flag
  LD A,(IY+1)             ; If worm's depth is not zero (i.e. is in play
                          ; area)...
  OR A                    ; ...
  JP NZ,51960             ; ...then move Drutt closer to the worm and eat it if
                          ; close enough
  LD IY,(34240)           ; Load IY with address of current level's complex
                          ; state data for Berk
  LD A,(IY+0)             ; If Drutt is in the same room as Berk...
  CP (IX+0)               ; ...
  JR Z,51875              ; ...then randomly select an action for Drutt and
                          ; execute
; The following code will make Drutt move closer to the target (a worm, or Berk
; if in Berk Mode) if the target's room is directly to the left or right of
; Drutt's room (i.e. no vertical separation). Otherwise, Drutt will perform a
; random action. This entry point is used by the routine at 51960.
  CALL 53194              ; Load A with value indicating which direction room A
                          ; lies relative to Drutt's current room
  CP 1                    ; If target room is to the right...
  JR Z,51904              ; ...then randomly select script data for rightward
                          ; hop of size three or four, and execute
  CP 2                    ; If target room is to the left...
  JR Z,51924              ; ...then randomly select script data for leftward
                          ; hop of size three or four, and execute
; This entry point is used by the routine at 51960.
  LD A,7                  ; Load A with a random number, 0-6...
  CALL 54222              ; ...
  LD DE,51890             ; Point DE at Table of Addresses of Script Data for
                          ; Drutt's Actions...
  CALL 53814              ; ...and load DE with entry of index A in this table
  EX DE,HL                ; Switch DE and HL (now contains address of randomly
                          ; selected script data)
  JP 48098                ; Execute script data at address in HL

; Table of Addresses of Script Data for Drutt's Actions
;
; When Drutt is neither under player control nor seeking a target (a worm or
; Berk) then his actions are determined by randomly selecting a script data
; address from this table and executing. There is:
  DEFW 51538              ; Move Drutt and any pushed entity right by a hop of
                          ; size four
  DEFW 51608              ; Move Drutt and any pushed entity left by a hop of
                          ; size three
  DEFW 51630              ; Drutt swapping depth levels
  DEFW 51524              ; Drutt facing out of screen
  DEFW 51524              ; Drutt facing out of screen
  DEFW 51524              ; Drutt facing out of screen
  DEFW 51524              ; Drutt facing out of screen

; Randomly Select Script Data for Rightward Hop of Size Three or Four, and
; Execute
;
; Used by the routine at 51779.
  LD A,2                  ; Load A with a random number, 0-1...
  CALL 54222              ; ...
  OR A                    ; ...and if this is zero (1 in 2 chance)...
  JR Z,51918              ; ...then skip ahead to 51918
  LD HL,51538             ; Point HL at script data for moving Drutt and any
                          ; pushed entity right by a hop of size four...
  JP 48098                ; ...and execute
  LD HL,51562             ; Point HL at script data for moving Drutt and any
                          ; pushed entity right by a hop of size three...
  JP 48098                ; ...and execute

; Randomly Select Script Data for Leftward Hop of Size Three or Four, and
; Execute
;
; Used by the routine at 51779.
  LD A,2                  ; Load A with a random number, 0-1...
  CALL 54222              ; ...
  OR A                    ; ...and if this is zero (1 in 2 chance)...
  JR Z,51938              ; ...then skip ahead to 51938
  LD HL,51584             ; Point HL at script data for moving Drutt and any
                          ; pushed entity left by a hop of size four...
  JP 48098                ; ...and execute
  LD HL,51608             ; Point HL at script data for moving Drutt and any
                          ; pushed entity left by a hop of size three...
  JP 48098                ; ...and execute

; Start Drutt Jumping
;
; Used by the routine at 51779.
  LD (IX+12),130          ; Set Drutt's Is Jumping Flag and set initial Jump
                          ; Velocity to 2
  LD HL,51674             ; Point HL at script data for Drutt starting to jump
                          ; straight up...
  JP 48098                ; ...and execute

; Point HL at Script Data for Drutt Swapping Depth Levels and Execute
;
; Used by the routine at 51779.
  LD HL,51630             ; Point HL at script data for Drutt swapping depth
                          ; levels...
  JP 48098                ; ...and execute

; Move Drutt Closer to the Worm and Eat it if Close Enough
;
; Used by the routine at 51779. Input:  IX  Address of complex state data
; (current level) for Drutt IY  Address of complex state data (current level)
; for Worm
  LD A,(IY+0)             ; If Drutt and worm are not in the same room...
  CP (IX+0)               ; ...
  JP NZ,51864             ; ...then move Drutt closer to worm if appropriate,
                          ; otherwise make Drutt perform random action
  LD A,(IX+5)             ; If Drutt's left edge...
  CP (IY+5)               ; ...is to the left of the worm's...
  JR C,52017              ; ...then skip ahead to 52017
  LD A,(IY+7)             ; If worm's right edge...
  CP (IX+5)               ; ...is to the left of Drutt's left edge...
  JR C,52023              ; ...then skip ahead to 52023
  LD A,(IX+4)             ; If y-coordinate of Drutt's top edge...
  CP 120                  ; ...is less than 120...
  JP C,51875              ; ...then randomly select an action for Drutt and
                          ; execute
  LD A,(IY+1)             ; If worm's depth is the same as Drutt's...
  CP (IX+1)               ; ...
  JR Z,52007              ; ...then skip ahead to 52007
; Drutt and worm in same room, at different depth and same x-coordinate
  LD HL,51630             ; Point HL at script data for Drutt swapping depth
                          ; levels...
  JP 48098                ; ...and execute
; Drutt and worm in same room, at same depth and same x-coordinate
  LD (IY+1),0             ; Set worm's depth to zero (i.e. remove from play)
  LD HL,51706             ; Point HL at script data for Drutt eating a worm...
  JP 48098                ; ...and execute
; Drutt's left edge to left of worm's
  LD HL,51538             ; Point HL at script data for moving Drutt and any
                          ; pushed entity right by a hop of size four...
  JP 48098                ; ...and execute
; Worm's right edge to left of Drutt's left edge
  LD HL,51584             ; Point HL at script data for moving Drutt and any
                          ; pushed entity left by a hop of size four...
  JP 48098                ; ...and execute

; Script Routine (44) Move Entity Up One Character
;
; Used by the routine at 48026. Input:  IX  Address of complex state data for
; an entity
  DEC (IX+4)              ; Move entity up one character...
  DEC (IX+6)              ; ...
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (45) Move Entity Down One Character
;
; Used by the routine at 51779. Input:  IX  Address of complex state data for
; an entity
  INC (IX+4)              ; Move entity down one character...
  INC (IX+6)              ; ...
  JP 48096                ; Advance HL to next script instruction and execute

; Script Routine (46) Move Drutt, or Entity he is Pushing Left One Character
; and Start Pushed Entity Falling if Appropriate
  CALL 52053              ; Move Drutt, or entity he is pushing left one
                          ; character and start pushed entity falling if
                          ; appropriate
  JP 48096                ; Advance HL to next script instruction and execute

; Move Drutt, or Entity he is Pushing Left One Character and Start Pushed
; Entity Falling if Appropriate
;
; Drutt will only push other entities when he is under player control. If he is
; not, then he will just pass through pushable entities. Input:  IX  Address of
; complex state data (current level) for Drutt
  CALL 54666              ; Check entity at IX for collision with another
                          ; impassable / pushable entity immediately to the
                          ; left...
  JR C,52087              ; ...and if a collision has not occurred, then skip
                          ; ahead to 52087
; At this point, a collision has occurred, so IY points to the complex state
; data entry of the entity with which Drutt has collided
  CP 22                   ; If collision was with an entity of class of 22 or
                          ; greater (can't be picked up)...
  JR NC,52076             ; ...then skip ahead to 52076
  BIT 1,(IX+9)            ; If Drutt's Under Player Control Flag is reset...
  JR Z,52087              ; ...then skip ahead to 52087 (move Drutt left
                          ; without pushing anything)
  PUSH IX                 ; Store IX (address of current level's complex state
                          ; data for Drutt)
  CALL 52098              ; Advance position of entity pushed left by Drutt
  POP IX                  ; Restore IX (address of current level's complex
                          ; state data for Drutt)
  RET                     ; Return
; Collision with entity of class 22 or greater
  CP 129                  ; If collision was with entity of class 129 (causes
                          ; other entities to start falling)...
  JR Z,52087              ; ...then skip ahead to 52087
; At this point, the entity to Drutt's left is neither passable nor pushable.
  POP BC                  ; Remove top value from stack (i.e. return address to
                          ; routine that called this routine)
  LD HL,51630             ; Point HL at script data for Drutt swapping depth
                          ; levels...
  JP 48098                ; ...and execute
; No collision, not under player control or collision with entity of class 129
  CALL 54348              ; Move Drutt into room to the left, if appropriate...
  RET NC                  ; ...and if Drutt can't enter new room then return
  DEC (IX+5)              ; Move Drutt left one character...
  DEC (IX+7)              ; ...
  RET                     ; Return

; Advance Position of Entity Pushed Left by Drutt
;
; Used by the routine at 52053. Input:  IY  Address of complex state data for
; entity pushed by Drutt
  PUSH IY                 ; Transfer address of complex state data for pushed
                          ; entity from IY...
  POP IX                  ; ...to IX
  CALL 54666              ; Check pushed entity for collision with another
                          ; impassable / pushable entity immediately to the
                          ; left...
  JR C,52112              ; ...and if a collision has not occurred, then skip
                          ; ahead to 52112
  CP 129                  ; If collision was with entity of class 129 (causes
                          ; other entities to start falling)...
  JR Z,52134              ; ...then skip ahead to 52134
  RET                     ; Return (as Drutt can't push two entities)
; No knock-on collision
  LD A,(IX+5)             ; If x-coordinate of left edge of pushed entity is at
                          ; least 103...
  CP 103                  ; ...i.e. not yet at left edge of room...
  JR NC,52127             ; ...then skip ahead to 52127
  CALL 54539              ; Load B with index of room to left of current
                          ; character's current room...
  RET Z                   ; ...and if there is no room to the left then return
  CALL 54348              ; Move pushed entity into room to the left, if
                          ; appropriate...
  RET NC                  ; ...and if pushed entity can't enter new room then
                          ; return
  DEC (IX+5)              ; Move pushed entity left one character...
  DEC (IX+7)              ; ...
  RET                     ; Return
  CALL 55516              ; Set Can Fall Flag and set initial velocity factor
                          ; of 2 for pushed entity
  CALL 52127              ; Move pushed entity left two characters...
  JR 52127                ; ...and return

; Script Routine (47) Move Drutt, or Entity he is Pushing Right One Character
; and Start Pushed Entity Falling if Appropriate
  CALL 52148              ; Move Drutt, or entity he is pushing right one
                          ; character and start pushed entity falling if
                          ; appropriate
  JP 48096                ; Advance HL to next script instruction and execute

; Move Drutt, or Entity he is Pushing Right One Character and Start Pushed
; Entity Falling if Appropriate
;
; Drutt will only push other entities when he is under player control. If he is
; not, then he will just pass through pushable entities. Input:  IX  Address of
; complex state data (current level) for Drutt
  CALL 54569              ; Check Drutt for collision with another impassable /
                          ; pushable entity immediately to the right...
  JR C,52182              ; ...and if a collision has not occurred, then skip
                          ; ahead to 52182
; At this point, a collision has occurred, so IY points to the complex state
; data entry of the entity with which Drutt has collided
  CP 22                   ; If collision was with an entity of class 22 or
                          ; greater (can't be picked up)...
  JR NC,52171             ; ...then skip ahead to 52171
  BIT 1,(IX+9)            ; If Drutt's Under Player Control Flag is reset...
  JR Z,52182              ; ...then skip ahead to 52182 (move Drutt right
                          ; without pushing anything)
  PUSH IX                 ; Store IX (address of current level's complex state
                          ; data for Drutt)
  CALL 52193              ; Advance position of entity pushed right by Drutt
  POP IX                  ; Restore IX (address of current level's complex
                          ; state data for Drutt)
  RET                     ; Return
; Collision with entity of class 22 or greater
  CP 129                  ; If collision was with entity of class 129 (causes
                          ; other entities to start falling)...
  JR Z,52182              ; ...then skip ahead to 52182
; At this point, the entity to Drutt's right is neither passable nor pushable.
  POP BC                  ; Remove top value from stack (i.e. return address to
                          ; routine that called this routine)
  LD HL,51630             ; Point HL at script data for Drutt swapping depth
                          ; levels...
  JP 48098                ; ...and execute
; No collision, not under player control or collision with entity of class 129
  CALL 54313              ; Move Drutt into room to the right, if
                          ; appropriate...
  RET NC                  ; ...and if Drutt can't enter new room then return
  INC (IX+5)              ; Move Drutt right one character...
  INC (IX+7)              ; ...
  RET                     ; Return

; Advance Position of Entity Pushed Right by Drutt
;
; Used by the routine at 52148. Input:  IY  Address of complex state data for
; entity pushed by Drutt
  PUSH IY                 ; Transfer address of complex state data for pushed
                          ; entity from IY...
  POP IX                  ; ...to IX
  CALL 54569              ; Check pushed entity for collision with another
                          ; impassable / pushable entity immediately to the
                          ; right...
  JR C,52207              ; ...and if a collision has not occurred, then skip
                          ; ahead to 52207
  CP 129                  ; If collision was with entity of class 129 (causes
                          ; other entities to start falling)...
  JR Z,52235              ; ...then skip ahead to 52235
  RET                     ; Return (as Drutt can't push two entities)
; No knock-on collision
  LD A,(34235)            ; Load E with width of current room (chars) + 99...
  SUB 2                   ; ...minus 2...
  LD E,A                  ; ...
  LD A,(IX+7)             ; ...and if x-coordinate of right edge of pushed
                          ; entity is less than this...
  CP E                    ; ...i.e. not yet at right edge of room...
  JR C,52227              ; ...then skip ahead to 52227
  CALL 54505              ; Load B with index of room to right of current
                          ; character's current room...
  RET Z                   ; ...and if there is no room to the right then return
  CALL 54313              ; Move pushed entity into room to the right, if
                          ; appropriate...
  RET NC                  ; ...and if pushed entity can't enter new room then
                          ; return
  INC (IX+5)              ; Move pushed entity right one character...
  INC (IX+7)              ; ...
  XOR A                   ; Load A with zero (see trivia)
  RET                     ; Return
  CALL 55516              ; Set Can Fall Flag and set initial velocity factor
                          ; of 2 for pushed entity
  CALL 52227              ; Move pushed entity right two characters...
  JR 52227                ; ...and return

; Script Routine (50) Advance Drutt's Jump and Select Next Phase if Current
; Phase Complete
;
; The CALL at 52243 will be RETurned from if Drutt's Is Jumping Flag is reset.
; Otherwise, E will be loaded with Drutt's jump state index (see 55041).
; Output: HL  Address of next script instruction to execute
  CALL 55023              ; Handle Drutt's jump, and load A with Jump State
                          ; Index as appropriate
  LD A,E                  ; If jump state index is zero...
  OR A                    ; ...
  JP Z,48096              ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  CP 1                    ; If jump state index is 1...
  JR Z,52259              ; ...then skip ahead to 52259
  CP 2                    ; If jump state index is not 2...
  JR NZ,52265             ; ...then skip ahead to 52265
; Jump state index is 1 (landed on floor / platform and Back (control input)
; bit set) or 2 (unused)
  LD HL,51674             ; Point HL at script data for Drutt starting to jump
                          ; straight up...
  JP 48098                ; ...and execute
; Jump state index is not 2
  CP 3                    ; If jump state index is not 3...
  JR NZ,52275             ; ...then skip ahead to 52275
; Jump state index is 3 (Drutt's jump velocity less than 4, and back not
; pressed, i.e. terminate jumping)
  LD HL,51524             ; Point HL at script data for Drutt facing out of
                          ; screen...
  JP 48098                ; ...and execute
; Jump state index is not 3
  CP 4                    ; If jump state index is not 4...
  JR NZ,52285             ; ...then skip ahead to 52285
; Jump state index is 4 (bounced off an obstruction to the right or Left
; (control input) Bit set)
  LD HL,51686             ; Point HL at script data for Drutt Jumping Left...
  JP 48098                ; ...and execute
; Jump state index is not 4
  CP 5                    ; If jump state index is not 5...
  JR NZ,52295             ; ...then skip ahead to 52295
; Jump state index is 5 (bounced off an obstruction to the left or Right
; (control input) Bit set)
  LD HL,51696             ; Point HL at script data for Drutt Jumping Right...
  JP 48098                ; ...and execute
; Jump state index is not 5
  CP 6                    ; If jump state index is not 6...
  JP NZ,48096             ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
; Jump state index is 6 (Drutt has banged his head on something above him)
  CALL 55516              ; Set Drutt's Can Fall Flag and set initial velocity
                          ; factor of 2
  LD HL,51520             ; Point HL at script data for Drutt facing out of
                          ; screen (falling)...
  JP 48098                ; ...and execute

; Script Routine (51) Swap Drutt's Current Depth Level if Possible
  CALL 52315              ; Swap Drutt's current depth level if possible
  JP 48096                ; Advance HL to next script instruction and execute

; Swap Drutt's Current Depth Level if Possible
;
; Used by the routine at 52309. Input:  IX  Address of complex state data
; (current level) for Drutt
  LD A,(IX+1)             ; If Drutt's depth is not 1...
  CP 1                    ; ...
  JR NZ,52351             ; ...then skip ahead to 52351
; Drutt's depth is 1
  LD A,(34230)            ; If Drutt's current depth is the same as number of
                          ; available depth levels in current room...
  CP (IX+1)               ; ...i.e. room has depth of 1...
  RET Z                   ; ...then return (as there is no other depth level
                          ; for Drutt to move to)
; The following collision check is usually only satisfied by Berk. This
; prevents Drutt from jumping back a depth level while in front of (at same
; depth level as) Berk.
  CALL 54878              ; Check Drutt for collision with another entity (only
                          ; those defined before, and in reverse order) at same
                          ; depth level whose Interaction (11,7) Flag is set...
  RET NC                  ; ...and if a collision occurred, then return
; The following collision check prevents Drutt from jumping back when there is
; an obstruction (e.g. the brick columns in the pit room, level 1) behind him.
  CALL 54890              ; Check Drutt for collision with another entity (in
                          ; reverse order) at next depth level into screen
                          ; whose Interaction (11,7) Flag is set...
  JR C,52341              ; ...and if no collision occurred, then skip ahead to
                          ; 52341
  CP 22                   ; If collision was with an entity of class of 22 or
                          ; greater (can't be picked up)...
  RET NC                  ; ...then return
  INC (IX+1)              ; Increase Drutt's depth (i.e. move backward away
                          ; from screen)
  DEC (IX+4)              ; Decrease Drutt's top and bottom y-coordinates...
  DEC (IX+6)              ; ...
  RET                     ; Return
; Drutt's depth is not 1
  LD A,(IX+1)             ; If Drutt's current depth is 1... (see trivia)
  CP 1                    ; ...
  RET Z                   ; ...then return
; The following collision check prevents Drutt from jumping forward a depth
; level while in behind an obstruction (e.g. Berk).
  CALL 54764              ; Check Drutt for collision with another entity at
                          ; next depth level out of screen whose Interaction
                          ; (11,6) Flag is set...
  RET NC                  ; ...and if a collision occurred, then return
  DEC (IX+1)              ; Decrease Drutt's depth (i.e. move forward towards
                          ; screen)
  INC (IX+4)              ; Increase Drutt's top and bottom y-coordinates...
  INC (IX+6)              ; ...
  RET                     ; Return

