                          ; 52726 into HL...
  LD (34277),HL           ; ...and store at 34277 as position in script
                          ; currently running
  CALL 52860              ; Update state of worm
  LD HL,(34277)           ; Store address (current position in script data)
                          ; stored at 34277...
  LD (52726),HL           ; ...at 52726 as current position in worm's script
                          ; data
  RET                     ; Return

; Update State of Worm
;
; Used by the routine at 52837. Input:  IX  Address of complex state data
; (current level) for Worm
