  JP 48096                ; ...otherwise advance HL to next script instruction
                          ; and execute

; Script Routine (53) Move Worm Left if Possible, Otherwise Choose New
; Direction Input:  IX  Address of complex state data for an entity
  CALL 54666              ; Check worm for collision with another impassable /
                          ; pushable entity immediately to the left...
  JR NC,52908             ; ...and if a collision occurred, then have worm
                          ; choose new direction
  CALL 54348              ; Move worm into room to the left, if appropriate...
  JR NC,52908             ; ...and if worm can't enter new room then have worm
                          ; choose new direction
  DEC (IX+5)              ; Move worm left one character...
  DEC (IX+7)              ; ...
  JP 48096                ; Advance HL to next script instruction and execute

