; Script Routine (55) Choose New Direction and Start Crawling (Worm) Input:  IX
; Address of complex state data for an entity
  CALL 53057              ; Increase Worm's Age and, if it has expired, set its
                          ; depth to zero and return
  LD A,20                 ; Load A with a random number, 5-24...
  CALL 54222              ; ...
  ADD A,5                 ; ...
  LD (IX+12),A            ; ...and set worm's Time Until Direction Change to
                          ; this value
  LD A,2                  ; Load A with a random number, 0-1...
  CALL 54222              ; ...
  OR A                    ; ...and if zero (1 in 2 chance)...
  JR NZ,52951             ; ...then skip ahead to 52951
; Have worm move left
  CALL 54666              ; Check worm for collision with another impassable /
                          ; pushable entity immediately to the left...
  JR NC,52961             ; ...and if a collision occurred, then start worm
                          ; crawling right
  CALL 54348              ; Move worm into room to the left, if appropriate...
  JR NC,52961             ; ...and if worm can't enter new room then start worm
                          ; crawling right
  LD HL,52765             ; Point HL at script data for worm, crawling left...
  JP 48098                ; ...and execute
; Have worm move right
  CALL 54569              ; Check worm for collision with another impassable /
                          ; pushable entity immediately to the right...
  JR NC,52945             ; ...and if a collision occurred, then start worm
                          ; crawling left
  CALL 54313              ; Move worm into room to the right, if appropriate...
  JR NC,52945             ; ...and if worm can't enter new room then start worm
                          ; crawling left
  LD HL,52781             ; Point HL at script data for worm, crawling right...
  JP 48098                ; ...and execute

; Script Routine (52) Increase Worm's Age and Decrease Time Until Direction
; Change, or React to Drutt's Presence
;
; When both Drutt and the worm are in the same room, and the worm is alerted to
; Drutt's presence, then the worm will take on its alarmed appearance and start
; fleeing in the direction away from Drutt. As long as Drutt remains in the
; same room as the worm, and within the "alerting" distance, the worm will
; continue fleeing in the same direction, and its Time Until Direction Change
; will be frozen. Input:  IX  Address of complex state data for an entity
; Output: HL  Address of next script instruction to execute
  CALL 53057              ; Increase Worm's Age and, if it has expired, set its
                          ; depth to zero and return
  LD IY,(34242)           ; Load IY with address of current level's complex
                          ; state data for Drutt
  LD A,(IX+0)             ; If Drutt and the worm are in the same room...
  CP (IY+0)               ; ...
  JR Z,53004              ; ...then skip ahead to 53004
; Drutt and worm in different rooms, so countdown to next direction change
; resumes as worm out of danger
  RES 1,(IX+9)            ; Reset In Danger Flag
  LD A,(IX+12)            ; If worm's Time Until Direction Change is zero...
  OR A                    ; ...
  JR Z,52998              ; ...then skip ahead to 52998 (have worm choose new
                          ; direction)
  DEC (IX+12)             ; Decrease worm's Time Until Direction Change
  JP 48096                ; Advance HL to next script instruction and execute
  LD HL,52747             ; Point HL at script data for worm, choosing next
                          ; direction...
  JP 48098                ; ...and execute
; Drutt and worm in same room, so worm potentially in danger
  LD A,(IX+5)             ; Load A with x-coordinate of worm's left edge...
  INC A                   ; ...plus one...
  SUB (IY+5)              ; ...minus x-coordinate of Drutt's left edge
  JR C,53034              ; If negative then skip ahead to 53034
  CP 10                   ; If worm's left edge is 9 characters or more to the
                          ; right of Drutt's...
  JR NC,52982             ; ...then jump back to 52982
  BIT 1,(IX+9)            ; If In Danger Flag is set...
  JP NZ,48096             ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  SET 1,(IX+9)            ; Set In Danger Flag
  LD HL,52817             ; Point HL at script data for worm, fleeing right...
  JP 48098                ; ...and execute
; Drutt's left edge more than one character to the right of worm's left edge
  NEG                     ; If worm's left edge is 11 characters or more to the
                          ; left of Drutt's...
  CP 10                   ; ...
  JR NC,52982             ; ...then jump back to 52982
  BIT 1,(IX+9)            ; If In Danger Flag is set...
  JP NZ,48096             ; ...then jump to 48096 (advance HL to next script
                          ; instruction and execute)
  SET 1,(IX+9)            ; Set In Danger Flag
  LD HL,52797             ; Point HL at script data for worm, fleeing left...
  JP 48098                ; ...and execute

; Increase Worm's Age and Set its Depth to Zero if it has Expired
;
; Used by the routines at 52914 and 52967. Input:  IX  Address of complex state
; data (current level) for Worm
  LD A,(52728)            ; Increase current Worm Age value...
  INC A                   ; ...
  LD (52728),A            ; ...
  BIT 7,A                 ; If Worm Age is less than 128...
  RET Z                   ; ...then return
  LD A,(34218)            ; If current character's room...
  CP (IX+0)               ; ...is the same as the worm's...
  RET Z                   ; ...then return
  XOR A                   ; Set the worm's depth to zero...
  LD (IX+1),A             ; ...
  LD (52728),A            ; Reset Worm Age to zero
  POP BC                  ; Remove top value from stack (return address in
                          ; calling routine)
  RET                     ; Return (to routine that called the calling routine)

; Attempt to Spawn a New Worm
;
; Used by the routine at 52860. Input:  IX  Address of complex state data
; (current level) for Worm
  LD A,60                 ; Load A with a random number, 0-59...
  CALL 54222              ; ...
  OR A                    ; If random number is not zero (59 in 60 chance)...
  RET NZ                  ; ...then return
  LD A,(34218)            ; Set worm's current room to same as current
                          ; character's...
  LD (IX+0),A             ; ...
  CALL 53848              ; Store room size data for worm's current room
  LD A,(34235)            ; Load A with width of current room (chars) + 99...
  SUB 100                 ; ...and subtract 100 to get x-coordinate
                          ; (zero-based) of right side of the room
  CALL 54222              ; Load A with a random x-coordinate within current
                          ; room
  ADD A,100               ; Add 100 to restore coordinate system
  LD (IX+5),A             ; Set this as the worm's left x-coordinate
  ADD A,2                 ; Add two to this...
  LD (IX+7),A             ; ...and set as the worm's right x-coordinate
  LD A,2                  ; Load A with a random number, 1-2...
  CALL 54222              ; ...
  INC A                   ; ...
  LD (IX+1),A             ; ...and assign the worm this depth
  LD A,124                ; Load A with 124 (y-coordinate of character row
                          ; below bottom of room)
  SUB (IX+1)              ; Subtract worm's depth value to get its bottom
                          ; y-coordinate...
  LD (IX+6),A             ; ...and assign
  PUSH AF                 ; Store AF (A = bottom y-coordinate of worm)
  LD (IX+4),121           ; Set worm's top y-coordinate to 121
  CALL 54768              ; Check entity at IX for collision with another
                          ; entity at same depth whose Interaction (11,6) Flag
                          ; is set
  POP BC                  ; Store AF (B = bottom y-coordinate of worm)
  JR NC,53154             ; If a collision occurred then set worm's depth to
                          ; zero and return
  LD (IX+4),B             ; Set worm's top y-coordinate to same as its bottom
                          ; y-coordinate
  LD HL,52735             ; Point HL at script data for worm rising from
                          ; floor...
  JP 48098                ; ...and execute
  LD (IX+1),0             ; Set worm's depth to zero
  RET                     ; Return

; Pathfinding Data Table
;
; When built, this table has a header and a main data block. The header is
; three bytes long and contains the values:
  DEFB 0,0,0
  DEFB 0,0
  DEFB 0,0
  DEFB 0,0
  DEFB 0,0
  DEFB 0

; Unused
  DEFB 0,0,0,0,0,0,0,0
  DEFB 0,0,0,0,0,0,0,0
  DEFB 0,0,100,100,100,100,100

; Load A with Value Indicating Which Direction Room A Lies Relative to Room in
; State Data at IX
;
; Direction index value in A denotes which direction (left or right), e.g.
; Drutt, has to travel to reach the target room: Input:  A  Target room index
; (e.g. Berk's room or worm's room) IX  Address of complex state data (current
; level) for Drutt Output: A  Direction index
  PUSH HL                 ; Store HL
  PUSH IX                 ; Store IX
  LD E,A                  ; Load E with target room index
  LD A,(IX+0)             ; Load D with Drutt's current room...
  LD D,A                  ; ...
  LD HL,53159             ; Set first two bytes of header to 255 (Start
                          ; Marker)...
  LD (HL),255             ; ...
  INC HL                  ; ...
  LD (HL),255             ; ...
  INC HL                  ; Set third byte of header to index of Drutt's
                          ; current room...
  LD (HL),A               ; ...
  INC HL                  ; Advance HL to first byte of first entry
  CALL 54542              ; Load B with index of room to left of Drutt's
                          ; current room...
  JR Z,53228              ; ...and if there is no such room then skip ahead to
                          ; 53228
  LD A,E                  ; If room to left of Drutt's current room is the
                          ; target room...
  CP B                    ; ...then set Zero Flag
  LD A,2                  ; Load A with 2 ("go left")
  JP Z,53336              ; If Zero Flag is set (room to left is target room)
                          ; then restore registers and return
  CALL 53309              ; Add entry to Pathfinding Data Table stating room to
                          ; left of Drutt is to the left
  CALL 54508              ; Load B with index of room to right of Drutt's
                          ; room...
  JR Z,53243              ; ...and if there is no such room then skip ahead to
                          ; 53243
  LD A,E                  ; If room to right of Drutt's current room is the
                          ; target room...
  CP B                    ; ...then set Zero Flag
  LD A,1                  ; Load A with 1 ("go right")
  JP Z,53336              ; If Zero Flag is set (room to right is target room)
                          ; then restore registers and return
  CALL 53309              ; Add entry to Pathfinding Data Table stating room to
                          ; right of Drutt is to the right
; Now the Pathfinding Data Table has a header and zero, one or two records,
; depending upon the horizontal connectivity of Drutt's current room.
  LD IX,53162             ; Load IX with address of first entry in Pathfinding
                          ; Data Table
  LD D,(IX+1)             ; Load D with index of room from current entry in
                          ; Pathfinding Data Table
  CALL 54542              ; Load B with index of room to left of room D...
  JR Z,53271              ; ...and if there is no such room then skip ahead to
                          ; 53271
  LD A,E                  ; If room to left of room D is the target room...
  CP B                    ; ...
  JP Z,53333              ; ...then load A with direction index for room D,
                          ; restore registers and return
  CALL 53317              ; If room B already has an entry in Pathfinding Data
                          ; Table...
  JR Z,53271              ; ...then skip ahead to 53271
  LD A,(IX+0)             ; Load A with current entry's direction index (room B
                          ; must lie in same direction as room D)
  CALL 53309              ; Add entry to Pathfinding Data Table for room B
                          ; lying in direction A
  CALL 54508              ; Load B with index of room to right of room D...
  JR Z,53292              ; ...and if there is no such room then skip ahead to
                          ; 53292
  LD A,E                  ; If room to right of room D is the target room...
  CP B                    ; ...
  JP Z,53333              ; ...then load A with direction index for room D,
                          ; restore registers and return
  CALL 53317              ; If room B already has an entry in Pathfinding Data
                          ; Table...
  JR Z,53292              ; ...then skip ahead to 53292
  LD A,(IX+0)             ; Load A with current entry's direction index (room B
                          ; must lie in same direction as room D)
  CALL 53309              ; Add entry to Pathfinding Data Table for room B
                          ; lying in direction A
  INC IX                  ; Advance IX by two bytes to next entry in
                          ; Pathfinding Data Table...
  INC IX                  ; ...
  LD A,(IX+0)             ; If byte at this location is not 255 (End Marker)...
  CP 255                  ; ...
  JP NZ,53247             ; ...then loop back to 53247
; At this point, the search has checked all rooms and not found the target
; room.
  POP IX                  ; Restore IX
  POP HL                  ; Restore HL
  XOR A                   ; Set A to zero
  RET                     ; Return

; Add Entry to Pathfinding Data Table for Room B in Direction A
;
; B contains the room the pathfinding routine is currently looking at, and A
; contains a value that denotes which direction this room lies in relative to
; Drutt's current room. Input:  A  Direction index (1 or 2) B  Index of room
; being examined HL  Current address of end of Pathfinding Data Table
  LD (HL),A               ; Store direction index
  INC HL                  ; Advance by one byte
  LD A,B                  ; Store index of room being examined...
  LD (HL),A               ; ...
  INC HL                  ; Advance by one byte
  LD (HL),255             ; Store 255 (End Marker)
  RET                     ; Return

; Set Zero Flag if Room B Has an Entry in Pathfinding Data Table, Otherwise
; Reset
;
; Used by the routine at 53194. Input:  HL  Address of end of Pathfinding Data
; Table B  Index of room to check table for Output: F  (Zero Flag) Set if room
; B is already stored in Pathfinding Data Table, reset otherwise
  PUSH HL                 ; Store HL (address of end of Pathfinding Data Table)
  DEC HL                  ; Move HL back to previous entry's room index...
  LD A,(HL)               ; ...load into A...
  CP 255                  ; ...and if this is 255 (Start Marker, so room B not
                          ; found)...
  JR Z,53330              ; ...then skip ahead to 53330
  DEC HL                  ; Move HL back to entry's direction index
  CP B                    ; If room to search for not the same as current
                          ; entry's room...
  JR NZ,53318             ; ...then loop back to 53318 to test next entry
; At this point, the room we're looking for (in B) is already stored in the
; Pathfinding Data Table and the Zero Flag is set.
  POP HL                  ; Restore HL (address of end of Pathfinding Data
                          ; Table)
  RET                     ; Return
  POP HL                  ; Restore HL (address of end of Pathfinding Data
                          ; Table)
  DEC A                   ; Reset Zero Flag
  RET                     ; Return

; Load A with Direction Index in Pathfinding Data Table entry at Address in IX,
; Restore Registers and Return
;
; Used by the routine at 53194. Input:  IX  Address of an entry in Pathfinding
; Data Table
  LD A,(IX+0)             ; Load A with direction index for entry at IX
; This entry point is used by the routine at 53194.
  POP IX                  ; Restore IX
  POP HL                  ; Restore HL
  RET                     ; Return

; Graphic Layout Data Worm Looking ahead, animated
  DEFB 244,7              ; Set current graphic set to 7
  DEFB 250,254,1          ; Change cursor's x- and y-coordinates by +1 and -2
                          ; characters respectively
  DEFB 251,57,209         ; Process graphic layout data at 53561 and upon
                          ; returning, move cursor to base coordinates
  DEFB 250,255,1          ; Change cursor's x- and y-coordinates by +1 and -1
                          ; characters respectively
  DEFB 3,3,32,4,3,33
  DEFB 255                ; End Marker
; Looking left, normal
