  DEFB 250,255,1          ; Change cursor's x- and y-coordinates by +1 and -1
                          ; characters respectively
  DEFB 6,131,33,5,135,31
  DEFB 4,3,33
  DEFB 255                ; End Marker
; Looking left, alarmed
  DEFB 244,7              ; Set current graphic set to 7
  DEFB 250,255,0          ; Change cursor's x- and y-coordinates by 0 and -1
                          ; characters respectively
  DEFB 7,7,33,6,3,32
  DEFB 4,3,33
  DEFB 255                ; End Marker
; Looking right, alarmed
  DEFB 244,7              ; Set current graphic set to 7
  DEFB 250,255,1          ; Change cursor's x- and y-coordinates by +1 and -1
                          ; characters respectively
  DEFB 6,131,33,7,135,31
  DEFB 4,3,33
  DEFB 255                ; End Marker
; Unused
  DEFB 244,7              ; Set current graphic set to 7
  DEFB 250,254,1          ; Change cursor's x- and y-coordinates by +1 and -2
                          ; characters respectively
  DEFB 1,7,32,3,3,32
  DEFB 8,3,32,9,3,33
  DEFB 255                ; End Marker
; Unused
  DEFB 244,7              ; Set current graphic set to 7
  DEFB 250,254,1          ; Change cursor's x- and y-coordinates by +1 and -2
                          ; characters respectively
  DEFB 1,7,32,3,3,31
  DEFB 9,131,33,8,131,33
  DEFB 255                ; End Marker
; Crawling Left, Alarmed (Frame 1 / 2)
  DEFB 244,7              ; Set current graphic set to 7
  DEFB 7,7,33
  DEFB 248,219,208        ; Jump to 53464
; Crawling Left (Frame 1 / 2)
  DEFB 244,7              ; Set current graphic set to 7
  DEFB 5,7,33,10,3,33
  DEFB 10,3,33,9,3,33
  DEFB 255                ; End Marker
; Crawling Left (Frame 2 / 2)
  DEFB 244,7              ; Set current graphic set to 7
  DEFB 5,7,33,11,3,33
  DEFB 9,3,33
  DEFB 255                ; End Marker
; Crawling Left, Alarmed (Frame 2 / 2)
  DEFB 244,7              ; Set current graphic set to 7
  DEFB 7,7,33,11,3,33
  DEFB 9,3,33
  DEFB 255                ; End Marker
; Crawling Right (Frame 2 / 2)
  DEFB 244,7              ; Set current graphic set to 7
  DEFB 9,131,33,11,131,33
  DEFB 5,135,33
  DEFB 255                ; End Marker
; Worm Crawling Right, Alarmed (Frame 2 / 2)
  DEFB 244,7              ; Set current graphic set to 7
  DEFB 9,131,33,11,131,33
  DEFB 7,135,33
  DEFB 255                ; End Marker
; Crawling Right (Frame 1 / 2)
  DEFB 244,7              ; Set current graphic set to 7
  DEFB 250,0,255          ; Change cursor's x- and y-coordinates by -1 and 0
                          ; characters respectively
  DEFB 9,131,33,10,131,33
  DEFB 10,131,33,5,135,33
  DEFB 255                ; End Marker
; Crawling Right, Alarmed (Frame 1 / 2)
  DEFB 244,7              ; Set current graphic set to 7
  DEFB 250,0,255          ; Change cursor's x- and y-coordinates by -1 and 0
                          ; characters respectively
  DEFB 9,131,33,10,131,33
  DEFB 10,131,33,7,135,33
  DEFB 255                ; End Marker
; Eyes, looking ahead, animated
  DEFB 247,3              ; Jump to one of the 3 addresses in the following
                          ; list, chosen at random:
  DEFB 65,209             ; 53569 (eyes, looking ahead, open)
  DEFB 65,209             ; 53569 (eyes, looking ahead, open)
  DEFB 69,209             ; 53573 (eyes, looking ahead, closed)
; Eyes, looking ahead, open
  DEFB 1,7,33
  DEFB 255                ; End Marker
; Eyes, looking ahead, closed
  DEFB 2,3,33
  DEFB 255                ; End Marker

; Cycle Attributes (Long, Full-Screen) and Clear Display Buffers
;
; Used by the routine at 53723.
  LD B,21                 ; Set repeat counter to 21
  JR 53583                ; Flash screen when Berk is "killed"

; Cycle Attributes (Short, Full-Screen) and Clear Display Buffers
;
; Used by the routine at 36616.
  LD B,7                  ; Set repeat counter to 7
; This entry point is used by the routine at 53577.
  PUSH BC                 ; Store BC (B = remaining number of iterations
                          ; required)
  LD HL,22528             ; Point HL at start of Attribute File
  LD BC,704               ; Set BC to 704 (i.e. gap between start of Attribute
                          ; File and start of second-last row (timer figures))
  LD A,(HL)               ; Load current attribute at memory location HL into A
  AND 7                   ; Strip out other components to leave only INK
                          ; component
  JR Z,53602              ; If value is zero (black INK) then skip ahead to
                          ; 53602
  INC A                   ; Increase INK value to next colour
  AND 7                   ; Strip out other components to leave only INK
                          ; component
  JR NZ,53602             ; If value is not zero (black INK) then skip ahead to
                          ; 53602
  LD A,1                  ; INK value was zero, so set now to blue INK
  LD E,A                  ; Load new INK value into E
  LD A,(HL)               ; Load current attribute at memory location HL into A
  AND 56                  ; Strip out other components to leave only PAPER
                          ; component
  JR Z,53616              ; If black PAPER, then skip ahead to 53616
  ADD A,8                 ; Increase to next PAPER colour
  AND 56                  ; Strip out other components to leave only PAPER
                          ; component
  JR NZ,53616             ; If PAPER component is not black then skip ahead to
                          ; 53616
  LD A,8                  ; PAPER value was zero, so set now to blue PAPER
  OR E                    ; Add INK component back in
  OR 64                   ; Set BRIGHT flag
  LD (HL),A               ; Paint new attribute back to current position in
                          ; Attribute File
  AND 16                  ; Set / reset speaker bit
  OR 2                    ; Set RED bit to maintain red border
  OUT (254),A             ; Set border and set / reset speaker state
  INC HL                  ; Advance to next byte of Attribute File
  DEC BC                  ; Decrease remaining number of character blocks to
                          ; process
  LD A,B                  ; If number of remaining character blocks is not
                          ; zero...
  OR C                    ; ...
  JR NZ,53590             ; ...then loop back to 53590
  POP BC                  ; Restore BC (B = remaining number of iterations
                          ; required)
  DJNZ 53583              ; Loop back for next iteration
; This entry point is used by the routine at 53887.
  LD HL,61312             ; Clear Display Buffers 1 and 2...
  LD BC,4224              ; ...
  LD (HL),0               ; ...
  LD D,H                  ; ...
  LD E,L                  ; ...
  INC DE                  ; ...
  LDIR                    ; ...
  RET                     ; Return

; Fill Top 22 Rows of Attribute File with Attribute Value in A
;
; Used by the routines at 46830 and 53723. Input:  A  Attribute
  LD HL,22528             ; Point HL at start of Attribute File
  LD E,L                  ; Point DE one byte after this...
  LD D,H                  ; ...
  INC DE                  ; ...
  LD BC,703               ; Set counter to 703, as we are filling 704
                          ; characters (32*22)
  LD (HL),A               ; Set first byte to A...
  LDIR                    ; ...and repeat for remaining 703 bytes
  LD B,3                  ; Pause for three iterations...
  CALL 34675              ; ...
  RET                     ; Return

; Set "Berk Has Been Killed" Flag
;
; Used by the routines at 36116, 36390, 37085, 37639, 38074, 38219, 38540,
; 38592, 39934, 41498, 41633, 41961, 42064, 42266 and 42486.
  LD A,(34208)            ; Set "Berk Has Been Killed" Flag...
  SET 2,A                 ; ...
  LD (34208),A            ; ...
  RET                     ; Return

; Table of Berk's Reset Complex State Data Addresses
;
; Addresses of complex state data reverted to by Berk after he is "killed"
  DEFW 53684              ; Level 1
  DEFW 53710              ; Level 2
  DEFW 53697              ; Level 3
  DEFW 53710              ; Level 4

; Berk's Reset Complex State Data
;
; Complex state data reverted to by Berk after he is "killed"
  DEFB 4,1,103,231,85,113,91,118,31,1,192,192,10 ; Level 1
  DEFB 1,1,103,231,85,107,91,112,31,1,192,192,10 ; Level 3
  DEFB 1,1,103,231,85,113,91,118,31,1,192,192,10 ; Levels 2 & 4

; If Berk Has Been Killed then Reset his Position and State, Flash Screen and
; Decrease Time / Lives
;
; Used by the routine at 34438.
  LD HL,34208             ; Point HL at Game Flags
  RES 3,(HL)              ; Reset "Reset Spiders to Initial State" Flag
  BIT 2,(HL)              ; If "Berk Has Been Killed" Flag is not set...
  RET Z                   ; ...then return
  RES 2,(HL)              ; Reset "Berk Has Been Killed" Flag
  SET 3,(HL)              ; Set "Reset Spiders to Initial State" Flag
  LD IX,(34240)           ; Load IX with address of current level's complex
                          ; state data for Berk
  CALL 36296              ; Make Berk drop the entity he is holding and load IY
                          ; with its complex state data address
  LD DE,53674             ; Point DE at location two bytes (1 WORD) before
                          ; start of Table of Addresses of Berk Reset Data
  LD A,(34207)            ; Load current level number into A
  CALL 53814              ; Load DE with that level's address (from table at
                          ; 53676) for complex state data to revert Berk to
                          ; after he is killed
  EX DE,HL                ; Swap HL (now address of complex state data to
                          ; revert to) and DE
  LD DE,(34240)           ; Load DE with address of current level's complex
                          ; state data for Berk
  LD BC,13                ; Overwrite Berk's current complex state data...
  LDIR                    ; ...with reset data from table at 53684 for current
                          ; level
  LD HL,35363             ; Load HL with address of script data for Berk
                          ; starting to fall...
  LD (35687),HL           ; ...and store at 35687 (as current position in
                          ; Berk's script data)
  CALL 53577              ; Cycle attributes (long, full-screen) and clear
                          ; display buffers
  LD A,127                ; Fill top 22 rows of Attribute File with white PAPER
                          ; and white INK, BRIGHT...
  CALL 53649              ; ...
  CALL 53887              ; Paint red areas outside accessible areas of current
                          ; character's current room
  CALL 47485              ; Decrease current time / lives by one if greater
                          ; than zero and redraw Timer Figures
  RET                     ; Return

; Set Each Value in Primary Display Buffer Within Play Area to Zero
;
; Used by the routine at 34438.
  LD HL,(34279)           ; Load HL with start address of Primary Display
                          ; Buffer
  LD BC,704               ; Set BC to 704, as there are 704 entries in a
                          ; Display Buffer
  LD DE,3                 ; Load DE with 3 as each entry in the Display Buffer
                          ; is three bytes wide
  LD A,(HL)               ; Read first byte in Display Buffer...
  INC A                   ; ...and add one
  JP Z,53806              ; If value is now zero (i.e. was previously 255 and
                          ; therefore outside normal play area), then skip
                          ; ahead to 53806
  XOR A                   ; Set all values in current entry to zero...
  LD (HL),A               ; ...
  INC HL                  ; ...
  LD (HL),A               ; ...
  INC HL                  ; ...
  LD (HL),A               ; ...
  INC HL                  ; ...
  JP 53807                ; Skip ahead to 53807
  ADD HL,DE               ; Advance current position in Display Buffer to next
                          ; entry
  DEC BC                  ; Decrease remaining number of entries to process
  LD A,B                  ; If remaining number of entries is not zero...
  OR C                    ; ...
  JP NZ,53791             ; ...then loop back to 53791
  RET                     ; Return

; Advance DE by 2xA Bytes and Load WORD at this Location into DE
;
; Used by the routines at 49010, 51779 and 53723. Input:  A  Index DE  Base
; address Output: DE  WORD value at DE (input) + 2 x A (input)
  PUSH HL                 ; Store HL
  ADD A,A                 ; Load HL with double index...
  LD L,A                  ; ...
  LD H,0                  ; ...
  ADD HL,DE               ; Add HL to DE as offset, in HL
  LD E,(HL)               ; Load address at HL into DE...
  INC HL                  ; ...
  LD D,(HL)               ; ...
  POP HL                  ; Restore HL
  RET                     ; Return

; Copy Room Dimension Data Entry for Current Character / Entity's Current Room
; to Temporary Store Location (34230)
;
; Used by the routines at 34916 and 53887. Input:  IX  (Entry at 53848 only)
; Address of complex state data for an entity
  LD A,(34208)            ; If Drutt Mode Flag is reset (Berk Mode)...
  BIT 0,A                 ; ...
  JR Z,53838              ; ...then skip ahead to 53838
  LD IX,(34242)           ; Load IX with address of current level's complex
                          ; state data for Drutt
  JR 53842                ; Skip ahead to 53842
  LD IX,(34240)           ; Load IX with address of current level's complex
                          ; state data for Berk
  LD A,(IX+0)             ; Store current character's current room at 34218...
  LD (34218),A            ; ...
; This entry point is used by the routines at 35689, 37062, 39278, 51739,
; 52837, 53083, 54480 and 55525.
  LD A,(IX+0)             ; Load entity's current room into A
  DEC A                   ; Subtract 1...
  LD E,A                  ; ...and multiply by 5...
  ADD A,A                 ; ...
  ADD A,A                 ; ...
  ADD A,E                 ; ...
  LD C,A                  ; Load into BC...
  LD B,0                  ; ...
  LD HL,(34248)           ; Load start address of current level's room
                          ; dimension data into HL...
  ADD HL,BC               ; ...and add BC as offset
  LD (34262),HL           ; Store HL at 34262
  LD C,5                  ; Set BC to 5 (as entries are 5 bytes wide)
  LD DE,34230             ; Copy data entry in room dimension data for entity's
                          ; current room to 34230...
  LDIR                    ; ...
  LD A,(34231)            ; Load position (chars) of left side of current room
                          ; into E...
  LD E,A                  ; ...
  LD A,(34232)            ; Subtract position (chars) of right side of current
                          ; room in A...
  SUB E                   ; ...
  ADD A,100               ; ...and add 100
  LD (34235),A            ; Store value (width of current room + 99) at 34235
  RET                     ; Return

; Paint Red Areas Outside Accessible Areas of Current Character's Current Room
;
; Used by the routines at 34438, 34916, 36616, 48791, 53723 and 54456.
  CALL 53825              ; Copy room dimension data entry for current
                          ; character's current room to temporary store
                          ; location (34230)
  PUSH IX                 ; Store IX
  CALL 53635              ; Clear Display Buffers 1 & 2
  EXX                     ; Switch registers
  LD HL,61312             ; Point HL at Display Buffer 1
  LD DE,63424             ; Point DE at Display Buffer 2
  EXX                     ; Switch registers
  LD HL,(34231)           ; For current character's current room, set H =
                          ; room's right edge position and L = room's left edge
                          ; position (chars)
  LD DE,(34233)           ; For current character's current room, set D =
                          ; room's bottom edge position and E = room's top edge
                          ; position (chars)
  LD IX,22528             ; Point IX at first byte of Attribute File
  LD B,0                  ; Set initial y-coordinate (characters) to zero
  LD A,B                  ; Load A with current y-coordinate
  CP E                    ; If y-coordinate of top of room is greater than
                          ; current y-coordinate...
  JR C,53950              ; ...then skip ahead to 53950
  LD A,D                  ; Load A with y-coordinate of bottom of room
  CP B                    ; If y-coordinate of bottom of room is less than
                          ; current y-coordinate...
  JR C,53950              ; ...then skip ahead to 53950
  LD C,0                  ; Set initial x-coordinate to zero
  LD A,C                  ; Load A with current x-coordinate
  CP L                    ; If x-coordinate of left of room is greater than
                          ; current x-coordinate...
  JR C,53940              ; ...then skip ahead to 53940
  LD A,H                  ; Load A with x-coordinate of right of room
  CP C                    ; If x-coordinate of right of room is less than
                          ; current x-coordinate...
  JR C,53940              ; ...then skip ahead to 53940
  EXX                     ; Switch registers
  CALL 53977              ; Advance pointers in Display Buffers and Attribute
                          ; File address to next character
  JR 53943                ; Skip ahead to 53943
; Current x-coordinate, C, is outside range of x-coordinates spanned by room
  CALL 53968              ; Print red cell to current Attribute File position
                          ; (outside play area) and mark as unused in Display
                          ; Buffers
  INC C                   ; Advance C by one (move right one character)
  BIT 5,C                 ; If bit 5 is not set (x-coordinate has not reached
                          ; 32)...
  JR Z,53926              ; ...then loop back to 53926
  JR 53959                ; Skip ahead to 53959
; Current y-coordinate, B, is outside range of y-coordinates spanned by room
  PUSH BC                 ; Store BC (B = current y-coordinate, C = current
                          ; x-coordinate)
  LD B,32                 ; Load counter with 32 (as there are 32 characters
                          ; per row)
  CALL 53968              ; Print red cell to current Attribute File position
                          ; (outside play area) and mark as unused in Display
                          ; Buffers
  DJNZ 53953              ; Loop back to 53953 for next character block
  POP BC                  ; Restore BC (B = current y-coordinate, C = current
                          ; x-coordinate)
  INC B                   ; Increase current y-coordinate by one
  LD A,B                  ; If y-coordinate has not reached 22...
  CP 22                   ; ...
  JR NZ,53916             ; ...then loop back to 53916
  POP IX                  ; Restore IX
  RET                     ; Return

; Print Red Cell to Current Attribute File Position (Outside Play Area) and
; Mark as Unused in Display Buffers
;
; Used by the routine at 53887. Input:  IX  Address of start of Attribute File
; (22528) HL'  Current position in display buffer 1 (at 61312) DE'  Current
; position in display buffer 2 (at 63424)
  LD (IX+0),18            ; Set attribute to red INK, red PAPER
  EXX                     ; Switch registers
  LD A,255                ; Load 255 into current positions in Display Buffers
                          ; 1 and 2...
  LD (HL),A               ; ...
  LD (DE),A               ; ...
; This entry point is used by the routine at 53887.
  INC HL                  ; Advance display buffer 1 pointer by three bytes to
                          ; next entry...
  INC HL                  ; ...
  INC HL                  ; ...
  INC DE                  ; Advance display buffer 2 pointer by three bytes to
                          ; next entry...
  INC DE                  ; ...
  INC DE                  ; ...
  EXX                     ; Switch registers
  INC IX                  ; Advance IX to next byte in Attribute File
  RET                     ; Return

; Reset Complex State Data for First Entity of Class A to that Stored in
; Initial-State Table at 59821
;
; Used by the routines at 37639 and 48417. Input:  A  Entity class value IX
; (Entry at 53994 only) Address of complex state data for an entity
  CALL 54019              ; Load IX with address of complex state data for
                          ; first entry in current level that has class A...
  PUSH IY                 ; ...
  POP IX                  ; ...
; This entry point is used by the routine at 42064.
  LD IY,59821             ; Point IY at start of Table of Initial-State Data
                          ; for Complex Entities
  CALL 54023              ; Advance IY to first entry in copied complex state
                          ; data that has class A
  PUSH IX                 ; Store IX (address of entry in complex state data to
                          ; overwrite)
  LD B,E                  ; Load B with 13 (DE set to 13 in routine at 54019)
  LD A,(IY+0)             ; Overwrite IX data entry with IY data...
  LD (IX+0),A             ; ...
  INC IX                  ; ...
  INC IY                  ; ...
  DJNZ 54004              ; ...
  POP IX                  ; Restore IX (address of entry in complex state data
                          ; just overwritten)
  RET                     ; Return

; Point IY at First Entry in Current Level's Complex State Data that has Class
; A
;
; Used by the routines at 36753 and 53987. Input:  A  Value of an entity class
; Output: IY  Address of complex state data for first entity of class A
  LD IY,(34238)           ; Load start address of current level's complex state
                          ; data into IY
; This entry point is used by the routine at 53987.
  LD DE,13                ; Load DE with 13 (as entries in complex state data
                          ; are 13 bytes wide)
  CP (IY+8)               ; If current IY entity has class A...
  RET Z                   ; ...then return
  ADD IY,DE               ; Advance to entry for next entity
  JR 54026                ; Loop back to 54026

; Draw Contents of Primary Display Buffer to Display
;
; If either the graphic index, or the graphic set index for the current entry
; in the Primary Display Buffer is zero, then only the attribute from that
; entry is rendered; the currently displayed bitmap data (from the previous
; frame) is preserved.
  LD IX,22528             ; Point IX at first byte of Attribute File
  LD HL,61312             ; Point HL at Display Buffer 1
  LD DE,63424             ; Point DE at Display Buffer 2
  LD A,(34271)            ; If "Display Buffer 2 is Primary" Flag is reset...
  OR A                    ; ...i.e. Display Buffer 1 is Primary...
  JP Z,54052              ; ...then skip ahead to 54052
  EX DE,HL                ; Switch DE and HL (Display Buffer 1 is Secondary,
                          ; Display Buffer 2 is Primary)
  PUSH DE                 ; Copy address of Secondary Display Buffer into IY...
  POP IY                  ; ...
  LD A,(HL)               ; Read Graphic Set Index from Primary Display Buffer
                          ; into A
  INC HL                  ; Advance HL to next byte (Graphic Index) in Primary
                          ; Display Buffer
  OR A                    ; If Graphic Set Index is zero...
  JP Z,54130              ; ...then skip ahead to 54130
  CP 255                  ; If Graphic Set Index is 255 (character block
                          ; outside room's dimensions)...
  JP Z,54140              ; ...then skip ahead to 54140
  LD B,A                  ; Transfer Graphic Set Index into B
  LD E,0                  ; Set E to zero
  CP (IY+0)               ; If Graphic Set Index in Primary Display Buffer
                          ; entry is different to Graphic Set Index in
                          ; Secondary Display Buffer entry...
  JP NZ,54076             ; ...then skip ahead to 54076
  INC E                   ; Increase E
  LD A,(HL)               ; Load Graphic Index from Primary Display Buffer
  OR A                    ; If Graphic Index is zero...
  JP Z,54130              ; ...then skip ahead to 54130
  LD C,A                  ; Transfer Graphic Index into C
  CP (IY+1)               ; If Graphic Index in Primary Display Buffer is
                          ; different to Graphic Index in Secondary Display
                          ; Buffer...
  JP NZ,54089             ; ...then skip ahead to 54089
  INC E                   ; Increase E
  INC HL                  ; Advance HL to third byte (attribute) in Primary
                          ; Display Buffer entry
  LD A,(HL)               ; Read attribute from Primary Display Buffer
  CP (IY+2)               ; If attribute in Display Buffer entry A is different
                          ; to attribute in Secondary Display Buffer entry...
  JP NZ,54102             ; ...then skip ahead to 54102
  BIT 1,E                 ; If E is 2 (i.e. both Graphic Set Index and Graphic
                          ; Index are the same)...
  JP NZ,54107             ; ...then skip ahead to 54107, over drawing
                          ; instructions (no need to redraw what is already
                          ; there)
  PUSH HL                 ; Store HL (pointer to current position in Primary
                          ; Display Buffer)
  CALL 54144              ; Draw a graphic character block to display
  POP HL                  ; Restore HL (pointer to current position in Primary
                          ; Display Buffer)
  INC HL                  ; Advance HL to next byte in Primary Display Buffer
                          ; (start of next entry)
  INC IX                  ; Advance IX to next byte in Attribute File
  PUSH IX                 ; Copy current Attribute File address from IX to
                          ; DE...
  POP DE                  ; ...
  LD A,E                  ; If current Attribute File address is not at the
                          ; start of the seventh row of a third of the display
                          ; (i.e. row 7, 15 or 23)...
  CP 192                  ; ...
  JR NZ,54122             ; ...then skip ahead to 54122
  LD A,D                  ; If current Attribute File address is 23232 (256*90
                          ; + 192, i.e. at start of second last display
                          ; character row)...
  CP 90                   ; ...
  RET Z                   ; ...then return, as only timer figures appear in
                          ; last two rows
  LD DE,3                 ; Advance current position in Secondary Display
                          ; Buffer by 3 bytes...
  ADD IY,DE               ; ...
  JP 54055                ; Loop back to 54055
  INC HL                  ; Advance HL to third byte (attribute) in Primary
                          ; Display Buffer entry
  LD A,(HL)               ; Load attribute into A
  SET 6,A                 ; Set BRIGHT flag
  LD (IX+0),A             ; Place attribute at current position in Attribute
                          ; File
  JP 54107                ; Loop back to 54107
  INC HL                  ; Advance HL to third byte (attribute) in Primary
                          ; Display Buffer entry
  JP 54107                ; Loop back to 54107

; Draw a Graphic Character Block to Display
;
; This routine uses the same technique as seen in the routine at 47709 to
; convert from an Attribute File address to a Display File address. See the
; notes in 47709 for more details. Input:  A  Attribute value (bit 7 is
; "mirror" flag, rather than FLASH) B  Graphic set index C  Graphic index IX
; Address in Attribute File
  SET 6,A                 ; Set Bright Flag
  LD (IX+0),A             ; Load attribute value into current Attribute File
                          ; address
  XOR A                   ; Load graphic set index into HL..
  LD L,B                  ; ...
  LD H,A                  ; ...
  ADD HL,HL               ; Double (as start address entries in table at 27000
                          ; are two bytes wide)...
  LD DE,27000             ; ...and add as offset to 27000 (in HL)...
  ADD HL,DE               ; ...
  LD E,(HL)               ; Load start address for this graphic set into DE...
  INC HL                  ; ...
  LD D,(HL)               ; ...
  LD L,C                  ; Load graphic index into HL...
  LD H,A                  ; ...
  ADD HL,HL               ; Multiply by eight, as graphic blocks are eight
                          ; bytes long...
  ADD HL,HL               ; ...
  ADD HL,HL               ; ...
  ADD HL,DE               ; Add to address of start of this graphic set as an
                          ; offset in HL
  EX DE,HL                ; Swap DE (now points to required graphic data) and
                          ; HL (now address of start of graphic set from table
                          ; at 27000)
  PUSH IX                 ; Switch Attribute File address into HL...
  POP HL                  ; ...
  LD A,H                  ; Multiply the most significant byte (MSB) of the
                          ; Attribute File address by eight...
  ADD A,A                 ; ...to put it on the same scale as the MSB of the
                          ; Display File address MSB (see notes)...
  ADD A,A                 ; ...
  ADD A,A                 ; ...
  AND 91                  ; Drop the most significant bit to point to the
                          ; correct location in Display File
  LD H,A                  ; Load back into HL (L is unaffected, as it should
                          ; be)
  EX DE,HL                ; Switch DE (now Display File address) and HL (now
                          ; pointer to graphic data)
  BIT 7,(IX+0)            ; If mirror flag is set for Attribute File at current
                          ; location...
  JP NZ,54194             ; ...then skip to 54194 to draw mirrored version
  LD B,8                  ; Set counter to 8 rows
  LD A,(HL)               ; Read byte from graphic data...
  LD (DE),A               ; ...and load into Display File
  INC D                   ; Move down one pixel row in Display File
  INC HL                  ; Advance to next byte of graphic data
  DJNZ 54187              ; Loop back for next row of pixels
  RET                     ; Return

; Draw Mirrored Graphic Character Block to Display File
;
; Used by the routine at 54144. Input:  HL  Address of bitmap data to draw IX
; Address in Attribute File
  RES 7,(IX+0)            ; Reset Bit 7 (Mirror Flag, shared with FLASH flag so
                          ; would cause graphic to flash)
  LD B,8                  ; Set counter to 8 rows
  PUSH BC                 ; Store BC (B = current counter value)
  LD A,(HL)               ; Read byte from graphic data...
  PUSH HL                 ; Store HL (pointer to graphic data)
  LD HL,27030             ; Point HL at mirror graphic lookup table
  LD C,A                  ; Load graphic "value" into BC...
  LD B,0                  ; ...
  ADD HL,BC               ; ...and add to HL as offset
  LD A,(HL)               ; Read byte at this location (mirror image of graphic
                          ; data read by instruction at 54201)
  POP HL                  ; Restore HL (pointer to graphic data)
  LD (DE),A               ; Load (mirrored) graphic data into Display File
  INC D                   ; Move down one pixel row in Display File
  INC HL                  ; Advance to next byte of graphic data
  POP BC                  ; Restore BC (B = current counter value)
  DJNZ 54200              ; Loop back for next row of pixels
  RET                     ; Return

; Data for Pseudo-Random Number Generator
  DEFW 0                  ; Seed
  DEFB 0                  ; Temporary store for range value

; Load A with a Pseudo-Random Number Between 0 and the Higher of 2 and A
; (Input)
;
; This routine uses a linear congruential generator to generate a new
; pseudo-random number based upon a seed value. The seed value is stored at
; 54219, is initially set to the value in the least significant byte of the
; system variable FRAMES, and subsequently set to the previously generated
; pseudo-random number. On entering this routine, the A register holds the
; range for the random number (e.g. 5 means this routine will generate a random
; number in the range 0-4 inclusive). A range of less than 2 is not allowed, so
; if A is less than this then it will be set to 2. Input:  A  Range Output: A
; Generated random number
  CP 2                    ; If range is less than 2...
  JP NC,54229             ; ...then set range to 2...
  LD A,2                  ; ...
  LD (54221),A            ; Store range at 54211
  PUSH HL                 ; Store HL
  PUSH DE                 ; Store DE
  PUSH BC                 ; Store BC
  LD DE,(54219)           ; Load DE with seed
  LD H,E                  ; Load least significant byte of random seed into H
  LD L,253                ; Set L to 253
  LD A,D                  ; Load most significant byte (MSB) of random seed
                          ; into A
; At this point, the three registers A, H and L encode a 24-bit number whose
; value is (256 * seed + 253)
  OR A                    ; Reset carry flag
  SBC HL,DE               ; Subtract seed from HL...
  SBC A,0                 ; ...and decrement A if Carry Flag is set
  SBC HL,DE               ; Subtract seed from HL...
  SBC A,0                 ; ...and decrement A if Carry Flag is set
; At this point, the three registers A, H and L encode a 24-bit number whose
; value is (254 * seed + 253)
  LD E,A                  ; Calculate (AHL mod 65,537)...
  LD D,0                  ; ...loading result into HL...
  SBC HL,DE               ; ...
  JP NC,54261             ; ...and if this is negative...
  INC HL                  ; ...then add one (as zero in HL can represent both
                          ; zero and 65,536)
  LD (54219),HL           ; Store HL (new seed) at 54219
; At this point, HL contains a new pseudo-random 16-bit number
  PUSH HL                 ; Copy 16-bit pseudo-random number from HL into DE...
  POP DE                  ; ...
  LD A,(54221)            ; Load A with range as stored previously
  DEC A                   ; Decrease range by 1 to get maximum value as we want
                          ; the output to range from 0 to (A-1)...
  LD B,A                  ; ...and load into B (loop counter)
; In the following loop we are obtaining the number of times that 65,536 goes
; into RANGE x DE. In other words, (RANGE x DE) is divided by 65,536 and the
; integer part of the result is loaded into A. A is therefore limited to values
; between zero, and the value A had on entering this routine minus one,
; inclusive.
  XOR A                   ; Set A to zero
  ADD HL,DE               ; Add DE to HL
  JP NC,54277             ; If DE has not crossed the 65,535 - 0 boundary then
                          ; skip ahead to 54277
  INC A                   ; Increase A (count of number of times DE rolls over
                          ; from 65,535 to 0)
  DJNZ 54272              ; Decrease B and loop back to 54272
  POP BC                  ; Restore BC
  POP DE                  ; Restore DE
  POP HL                  ; Restore HL
  RET                     ; Return

; Move Entity at IX into New Room (Left or Right) if it is at the Edge of its
; Current Room
;
; Used by the routines at 35735 and 55041. Input:  IX  Address of complex state
; data for an entity
  LD A,(34235)            ; Load A with width of current room (chars) + 97...
  DEC A                   ; ...
  DEC A                   ; ...
  CP (IX+5)               ; If x-coordinate of left side (+100) of entity is
                          ; greater than this...
  JR C,54306              ; ...then skip ahead to 54306
  LD A,(IX+7)             ; If x-coordinate of right side (+100) of entity is
                          ; not less than 102...
  CP 102                  ; ...
  RET NC                  ; ...then return
  CALL 54539              ; Load B with index of room to left of entity's
                          ; current room
  CALL 54419              ; Move entity at IX into room to left of its current
                          ; room and update position of carried entity if
                          ; moving entity is Berk
  RET                     ; Return
  CALL 54505              ; Load B with index of room to right of current
                          ; character's current room
  CALL 54383              ; Move entity at IX into room to right of its current
                          ; room and update position of carried entity if
                          ; moving entity is Berk
  RET                     ; Return

; Move Entity at IX into Room to the Right, If Appropriate
;
; This routine moves an entity (e.g. Berk or Drutt) into the next room to the
; right, if there is one, in a way that is consistent with the point of view of
; the currently selected character. For example, if Berk is the selected
; character and he moves into a new room, he does so as soon as his leading
; side (left or right) crosses the edge of the screen. He essentially
; disappears immediately from his old room. However from Drutt's point of view,
; Berk should move across the boundary smoothly and not just vanish as soon as
; his leading side crosses the boundary. This routine (along with its
; counterpart at 54348) ensures that this happens correctly. Input:  IX
; Address of complex state data for an entity Output: A  Zero if no room exists
; to the right, otherwise, x-coordinate of character's appropriate edge F
; (Carry Flag) Set if entity is not at edge of current room, or has moved into
; new room and has not collided. Reset otherwise (i.e. can't enter new room).
  LD A,(34235)            ; Load C with width of entity's current room (chars)
                          ; + 99...
  LD C,A                  ; ...
  LD A,(34208)            ; If Drutt Mode Flag is reset (Berk Mode)...
  BIT 0,A                 ; ...
  JR Z,54329              ; ...then skip ahead to 54329
  LD A,(IX+5)             ; Load A with x-coordinate of Drutt's left edge
  JR 54332                ; Skip ahead to 54332
  LD A,(IX+7)             ; Load A with x-coordinate of Berk's right edge
  CP C                    ; If x-coordinate of room's right edge is greater
                          ; than x-coordinate in A...
  RET C                   ; ...then return
  CALL 54505              ; Load B with index of room to right of current
                          ; character's current room
  JR Z,54381              ; If there is no room to the right, then jump to
                          ; 54381
  CALL 54383              ; Move entity at IX into room to right of its current
                          ; room and update position of carried entity if
                          ; moving entity is Berk
  CALL 54569              ; Check entity at IX for collision with another
                          ; impassable / pushable entity immediately to the
                          ; right...
  JR NC,54381             ; ...and if a collision occurred, then jump to 54381
  RET                     ; Return

; Move Entity at IX into Room to the Left, If Appropriate
;
; This routine moves an entity (e.g. Berk or Drutt) into the next room to the
; right, if there is one, in a way that is consistent with the point of view of
; the currently selected character. For example, if Berk is the selected
; character and he moves into a new room, he does so as soon as his leading
; edge (left or right) crosses the edge of the screen. He essentially
; disappears immediately from his old room. However from Drutt's point of view,
; Berk should move across the boundary smoothly and not just vanish as soon as
; his leading edge crosses the boundary. This routine (along with its
; counterpart at 54313) ensures that this happens correctly. Input:  IX
; Address of complex state data for an entity Output: A  Zero if no room exists
; to the left, otherwise, x-coordinate of character's appropriate edge F
; (Carry Flag) Set if entity is not at edge of current room, or has moved into
; new room and has not collided. Reset otherwise (i.e. can't enter new room).
  LD A,(34208)            ; If Drutt Mode Flag is reset (Berk Mode)...
  BIT 0,A                 ; ...
  JR Z,54363              ; ...then skip ahead to 54363
  LD A,100                ; If x-coordinate of Drutt's right edge is greater
                          ; than 100 (x-coordinate of left-edge of room)...
  CP (IX+7)               ; ...
  RET C                   ; ...then return
  JR 54369                ; Skip ahead to 54369
  LD A,100                ; If x-coordinate of Berk's left edge is greater than
                          ; 100 (x-coordinate of left-edge of room)...
  CP (IX+5)               ; ...
  RET C                   ; ...then return
  CALL 54539              ; Load B with index of room to left of entity's
                          ; current room
  JR Z,54381              ; If there is no room to the left, then jump to 54381
  CALL 54419              ; Move entity at IX into room to left of its current
                          ; room and update position of carried entity if
                          ; moving entity is Berk
  CALL 54666              ; Set Carry Flag if entity at IX has not collided
                          ; with another impassable / pushable entity
                          ; immediately to the left, reset otherwise
  RET                     ; Return
; This entry point is used by the routine at 54313.
  XOR A                   ; Set A to zero
  RET                     ; Return

; Move Entity at IX into Room to Right of its Current Room and Update Position
; of Carried Entity if Moving Entity is Berk
;
; Used by the routines at 48593, 54283 and 54313. Input:  IX  Address of
; complex state data for an entity
  CALL 54398              ; Set character's position to be left-hand side of
                          ; new room to right
  CALL 54456              ; Paint red areas outside current character's room if
                          ; IX points to current character's complex state data
  BIT 7,(IX+9)            ; If entity is Berk and his Moving Upwards Flag
                          ; (floating) is set...
  RET NZ                  ; ...then return
  CALL 48727              ; If entity is Berk then move carried entity to
                          ; Berk's right as he faces right
  RET                     ; Return

; Set Entity's Position to be Left-Hand Side of New Room to Right
;
; Used by the routine at 54383. Input:  B  Index of destination room IX
; Address of complex state data for an entity
  LD A,(34235)            ; Load D with i.e. x-coordinate of right edge of room
                          ; (width of current room (chars) + 99) minus
                          ; x-coordinate of right-edge of current character...
  SUB (IX+7)              ; ...(i.e. [negative] distance by which entity's
                          ; right edge is to the right of right edge of
                          ; room)...
  LD D,A                  ; ...
  CALL 54480              ; Set room of entity to B, store room size data for
                          ; new room and load E with entity's width minus one
  LD A,99                 ; Load A with x-coordinate of left edge of current
                          ; (new) room
  SUB D                   ; Subtract D (negative)...
  LD (IX+7),A             ; ...and set as new x-coordinate of entity's right
                          ; edge
  SUB E                   ; Subtract (width - 1) of entity...
  LD (IX+5),A             ; ...and set this as x-coordinate of entity's left
                          ; edge
  RET                     ; Return

; Move Entity at IX into Room to Left of its Current Room and Update Position
; of Carried Entity if Moving Entity is Berk
;
; Used by the routines at 48641, 54283 and 54348.
  CALL 54434              ; Set entity's position to be right-hand side of new
                          ; room to left
  CALL 54456              ; Paint red areas outside current character's room if
                          ; IX points to current character's complex state data
  BIT 7,(IX+9)            ; If entity is Berk and his Moving Upwards Flag
                          ; (floating) is set...
  RET NZ                  ; ...then return
  CALL 48738              ; If entity is Berk then move carried entity to
                          ; Berk's left as he faces left
  RET                     ; Return

; Set Entity's Position to be Right-Hand Side of New Room to Left
;
; Used by the routine at 54419. Input:  B  Index of destination room IX
; Address of complex state data for an entity
  LD A,100                ; Load D with x-coordinate of left edge of room minus
                          ; x-coordinate of left edge of current entity...
  SUB (IX+5)              ; ...(i.e. distance by which entity's left edge is to
                          ; the left of left edge of room)...
  LD D,A                  ; ...
  CALL 54480              ; Set room of entity to B, store room size data for
                          ; new room and load E with entity's width minus one
  LD A,(34235)            ; Load A with width of current (new) room (chars) +
                          ; 99
  SUB D                   ; Subtract D...
  INC A                   ; ...and add one to get x-coordinate of entity's left
                          ; edge in new room
  LD (IX+5),A             ; Set entity's left edge to this position
  ADD A,E                 ; Add (width - 1) of entity...
  LD (IX+7),A             ; ...and set this as x-coordinate of entity's right
                          ; edge
  RET                     ; Return

; Paint Red Areas Outside Current Character's Room if IX Points to Current
; Character's Complex State Data
;
; Used by the routines at 54383, 54419, 55433 and 55616. Input:  IX  Address of
; complex state data for an entity
  LD A,(34208)            ; Set Zero Flag if Drutt Mode Flag is reset...
  BIT 0,A                 ; ...
  LD A,(IX+8)             ; Load Entity Class Value of entity at IX into A
  JR NZ,54471             ; If Zero Flag is reset (i.e. Drutt Mode) then skip
                          ; ahead to 54471
  CP 31                   ; If Entity Class is 31 (i.e. Berk)...
  JR Z,54474              ; ...then paint red areas outside accessible areas of
                          ; current character's current room and return
  RET                     ; Return
  CP 18                   ; If Entity Class is not 18 (i.e. Drutt)...
  RET NZ                  ; ...then return
  PUSH HL                 ; Store HL
  CALL 53887              ; Paint red areas outside accessible areas of current
                          ; character's current room
  POP HL                  ; Restore HL
  RET                     ; Return

; Set Room of Entity at IX to B, Store Room Size Data for New Room and Load E
; with Entity's Width Minus One
;
; Used by the routines at 54398, 54434, 55433 and 55616. Input:  B  Destination
; room index IX  Address of complex state data for an entity Output: E
; Entity's width, minus one (characters)
  LD A,B                  ; Set entity's current room to be destination room...
  LD (IX+0),A             ; ...
  PUSH HL                 ; Store HL
  PUSH DE                 ; Store DE
  CALL 53848              ; Store room size data for entity's current room
  POP DE                  ; Restore DE
  POP HL                  ; Restore HL
  LD A,(IX+7)             ; Load A with x-coordinate of entity's right...
  SUB (IX+5)              ; ...subtract x-coordinate of entity's left...
  LD E,A                  ; ...and load result (entity's width minus one) into
                          ; E
  RET                     ; Return

; Unused routine
;
; This routine is not used. It is assumed, since this routine flows into the
; routine at 54505, that this unused routine was also intended to deal with
; room connectivity. As there are routines to deal with vertical and horizontal
; (left-right) connectivity, it is possible that this routine was originally
; intended to handle horizontal (forward-back) connectivity.
  LD IY,(34252)           ; Load IY with address of Unused Data Block (09)
  JR 54512                ; Load B with index of room, as related to room of
                          ; index D via data in Unused Data Block (09)

; Load B with Index of Room to Right of an Entity's Current Room
;
; Used by the routines at 48593, 52193, 54283 and 54313. Input:  IX  Address of
; complex state data for an entity IY  (entry at 54512 only) An entry in a room
; connectivity table D  (entry at 54508 and 54512 only) Index of base room for
; check Output: B  Index of room found if there is one, undefined otherwise F
; Zero Flag set if there is no room to the right, reset otherwise
  LD D,(IX+0)             ; Load current room of entity pointed to by IX into D
; This entry point is used by the routine at 53194.
  LD IY,(34250)           ; Load start address of current level's Horizontal
                          ; Room Connectivity Data into IY
; This entry point is used by the routine at 54499.
  LD A,(IY+0)             ; Load first byte (left room index) of current entry
                          ; into A
  CP 255                  ; If byte is 255 (i.e. the End Marker)...
  RET Z                   ; ...then return
  CP D                    ; If byte is not the same as the room index in D...
  JR NZ,54527             ; ...then skip ahead to 54527
  LD B,(IY+1)             ; Load second byte (right room index) of current
                          ; entry into B
  CP 255                  ; Reset zero flag (as current room cannot be 255)
  RET                     ; Return
  INC IY                  ; Advance by two bytes to the next entry...
  INC IY                  ; ...
  JR 54512                ; Loop back to 54512

; Unused routine
;
; This routine is not used. It is assumed, since this routine flows into the
; routine at 54539, that this unused routine was also intended to deal with
; room connectivity. As there are routines to deal with vertical and horizontal
; (left-right) connectivity, it is possible that this routine was originally
; intended to handle horizontal (forward-back) connectivity.
  LD IY,(34252)           ; Load IY with address of Unused Data Block (09)
  JR 54546                ; Load B with index of room, as related to room of
                          ; index D via data in Unused Data Block (09)

; Load B with Index of Room to Left of an Entity's Current Room
;
; Used by the routines at 48641, 52098, 54283 and 54348. Input:  IX  Address of
; complex state data for an entity IY  (entry at 54546 only) An entry in a room
; connectivity table D  (entry at 54542 and 54546 only) Index of base room for
; check Output: B  Index of room found if there is one, undefined otherwise F
; Zero Flag set if there is no room to the left, reset otherwise
  LD D,(IX+0)             ; Load current room of entity pointed to by IX into D
; This entry point is used by the routine at 53194.
  LD IY,(34250)           ; Load start address of current level's Horizontal
                          ; Room Connectivity Data into IY
; This entry point is used by the routine at 54533.
  INC IY                  ; Advance by one byte to second byte (right room
                          ; index) of first entry
  LD A,(IY+0)             ; Load second byte (right room index) of current
                          ; entry into A
  CP 255                  ; If byte is 255 (i.e. the End Marker)...
  RET Z                   ; ...then return
  CP D                    ; If byte is not the same as the room index in D...
  JR NZ,54563             ; ...then skip ahead to 54563
  LD B,(IY-1)             ; Load first byte (left room index) of current entry
                          ; into B
  CP 255                  ; Reset zero flag (as current room cannot be 255)
  RET                     ; Return
  INC IY                  ; Advance by two bytes to the next entry...
  INC IY                  ; ...
  JR 54548                ; Loop back to 54548

; Check Entity at IX for Collision With Another (Impassable / Pushable) Entity
; Immediately to the Right
;
; Used by the routines at 36116, 52148, 52193, 52889, 52914, 54313 and 55041.
; Input:  IX  Address of complex state data for an entity Output: F  Carry Flag
; set if no entity found, reset otherwise A  Class of entity, if found,
; otherwise 255 IY  Address of complex state data for colliding entity
  LD DE,13                ; Load DE with 13 (as entries in complex state data
                          ; are 13 bytes wide)
  LD IY,(34238)           ; Load start address of current level's complex state
                          ; data into IY
  LD A,(IY+0)             ; Load A with room index for current IY entity
  CP 255                  ; If this is not 255 (i.e. End Marker)...
  JR NZ,54585             ; ...then skip ahead to 54585
  SCF                     ; Set Carry Flag
  RET                     ; Return
  LD A,(IX+0)             ; If room of entity at IX is not the same as room of
                          ; entity at IY...
  CP (IY+0)               ; ...
  JR NZ,54662             ; ...then advance IY to next entity
  BIT 5,(IY+10)           ; If current entity at IY has its Is Being Carried
                          ; Flag set...
  JP NZ,54662             ; ...then advance IY to next entity
  LD A,(IY+8)             ; If current entity at IY has a class which is the
                          ; same as the entity at IX...
  CP (IX+8)               ; ...
  JR Z,54662              ; ...then advance IY to next entity
  BIT 7,A                 ; If entity at IY has its "Spans Full Depth" Flag is
                          ; set...
  JR NZ,54620             ; ...then skip over depth check to 54620
  LD A,(IY+1)             ; If entity at IY has a depth which is not the same
                          ; as the depth of the entity at IX...
  CP (IX+1)               ; ...
  JR NZ,54662             ; ...then advance IY to next entity
  LD A,(IY+11)            ; If entity at IY has its "Impassable / Pushable
                          ; Rightwards" Flag reset...
  AND 32                  ; ...
  JP Z,54662              ; ...then advance IY to next entity
  LD A,(IX+7)             ; If the right side of entity at IX...
  INC A                   ; ...
  CP (IY+5)               ; ...is not immediately to the left of the left side
                          ; of the entity at IY...
  JR NZ,54662             ; ...then advance IY to next entity
  LD A,(IX+6)             ; If the bottom of the entity at IX...
  CP (IY+4)               ; ...is above the top of the entity at IY...
  JR C,54662              ; ...then advance IY to next entity
  LD A,(IY+6)             ; If the bottom of the entity at IY...
  CP (IX+4)               ; ...is above the top of the entity at IX...
  JR C,54662              ; ...then advance IY to next entity
  XOR A                   ; Set A to zero to reset Carry Flag
  LD (34258),IY           ; Store pointer to current entity at 34258
  LD A,(IY+8)             ; Load A with class of entity at IY
  RET                     ; Return
  ADD IY,DE               ; Advance IY pointer to next entity in complex state
                          ; data block
  JR 54576                ; Loop back to 54576

; Check Entity at IX for Collision With Another (Impassable / Pushable) Entity
; Immediately to the Left
;
; Used by the routines at 36116, 52053, 52098, 52870, 52914, 54348 and 55041.
; Input:  IX  Address of complex state data for an entity Output: F  Carry Flag
; set if no entity found, reset otherwise A  Class of entity, if found,
; otherwise 255 IY  Address of complex state data for colliding entity
  LD DE,13                ; Load DE with 13 (as entries in complex state data
                          ; are 13 bytes wide)
  LD IY,(34238)           ; Load start address of current level's complex state
                          ; data into IY
  LD A,(IY+0)             ; Load A with room index for current IY entity
  CP 255                  ; If this is not 255 (i.e. End Marker)...
  JR NZ,54682             ; ...then skip ahead to 54682
  SCF                     ; Set Carry Flag
  RET                     ; Return
  LD A,(IX+0)             ; If room of entity at IX is not the same as room of
                          ; entity at IY...
  CP (IY+0)               ; ...
  JR NZ,54760             ; ...then advance IY to next entity
  BIT 5,(IY+10)           ; If current entity at IY has its Is Being Carried
                          ; Flag set...
  JP NZ,54760             ; ...then advance IY to next entity
  LD A,(IY+8)             ; If current entity at IY has a class which is the
                          ; same as the entity at IX...
  CP (IX+8)               ; ...
  JP Z,54760              ; ...then advance IY to next entity
  BIT 7,A                 ; If entity at IY has its "Spans Full Depth" Flag is
                          ; set...
  JR NZ,54718             ; ...then skip over depth check to 54620
  LD A,(IY+1)             ; If entity at IY has a depth which is not the same
                          ; as the depth of the entity at IX...
  CP (IX+1)               ; ...
  JR NZ,54760             ; ...then advance IY to next entity
  LD A,(IY+11)            ; If entity at IY has its "Impassable / Pushable
                          ; Leftwards" Flag reset...
  AND 16                  ; ...
  JP Z,54760              ; ...then advance IY to next entity
  LD A,(IX+5)             ; If the left side of entity at IX...
  DEC A                   ; ...
  CP (IY+7)               ; ...is not immediately to the right of the right
                          ; side of the entity at IY...
  JR NZ,54760             ; ...then advance IY to next entity
  LD A,(IX+6)             ; If the bottom of the entity at IX...
  CP (IY+4)               ; ...is above the top of the entity at IY...
  JR C,54760              ; ...then advance IY to next entity
  LD A,(IY+6)             ; If the bottom of the entity at IY...
  CP (IX+4)               ; ...is above the top of the entity at IX...
  JR C,54760              ; ...then advance IY to next entity
  XOR A                   ; Set A to zero to reset Carry Flag
  LD (34258),IY           ; Store pointer to current entity at 34258
  LD A,(IY+8)             ; Load A with class of entity at IY
  RET                     ; Return
  ADD IY,DE               ; Advance IY pointer to next entity in complex state
                          ; data block
  JR 54673                ; Loop back to 54673

; Check Entity at IX for Collision With Another Entity at Next Depth Level Out
; Of Screen Whose Interaction (11,6) Flag is Set
;
; Used by the routines at 37639 and 52315. Input:  IX  Address of complex state
; data for an entity Output: F Carry Flag set if no entity found, reset
; otherwise A  Class of entity, if found, otherwise 255 IY  Address of complex
; state data for colliding entity
  LD C,1                  ; Set depth offset to 1 (i.e. check entities at next
                          ; depth level out of screen)
  JR 54770                ; Jump to collision detection routine

; Check Entity at IX for Collision With Another Entity at Same Depth Whose
; Interaction (11,6) Flag is Set
;
; Used by the routines at 36036, 36542, 37085, 38074, 38219, 38540, 38592,
; 41498, 41633, 41961, 42064, 42266, 42486, 48487, 51779, 53083, 55196 and
; 55525. Input:  IX  Address of complex state data for an entity C  (Entry at
; 54770 only) Depth offset Output: F  Carry Flag set if no entity found, reset
; otherwise A  Class of entity, if found, otherwise 255 IY  Address of complex
; state data for colliding entity
  LD C,0                  ; Set depth offset to 0 (i.e. check entities at same
                          ; depth)
; This entry point is used by the routine at 54764.
  LD IY,(34238)           ; Load start address of current level's complex state
                          ; data into IY
  LD DE,13                ; Load DE with 13 (as entries in complex state data
                          ; are 13 bytes wide)
  LD A,(IY+0)             ; Load A with room index for current IY entity
  CP 255                  ; If this is not 255 (i.e. End Marker)...
  JR NZ,54786             ; ...then skip ahead to 54786
  SCF                     ; Set Carry Flag
  RET                     ; Return
  LD A,(IX+0)             ; If room of entity at IX is not the same as room of
                          ; entity at IY...
  CP (IY+0)               ; ...
  JR NZ,54874             ; ...then advance IY to next entity
  BIT 5,(IY+10)           ; If current entity at IY has its Is Being Carried
                          ; Flag set...
  JP NZ,54874             ; ...then advance IY to next entity
  LD A,(IY+8)             ; If current entity at IY has a class which is the
                          ; same as the entity at IX...
  CP (IX+8)               ; ...
  JR Z,54874              ; ...then advance IY to next entity
  BIT 7,A                 ; If entity at IY has its "Spans Full Depth" Flag is
                          ; set...
  JR NZ,54822             ; ...then skip over depth check to 54822
  LD A,(IY+1)             ; If entity at IY has a depth which is not the same
                          ; as the depth of the entity at IX...
  ADD A,C                 ; ...plus depth offset...
  CP (IX+1)               ; ...
  JR NZ,54874             ; ...then advance IY to next entity
  LD A,(IY+11)            ; If entity at IY has its Interaction (11,6) Flag
                          ; reset...
  AND 64                  ; ...
  JP Z,54874              ; ...then advance IY to next entity
  LD A,(IX+6)             ; If the bottom of the entity at IX...
  CP (IY+4)               ; ...is above the top of the entity at IY...
  JR C,54874              ; ...then advance IY to next entity
  LD A,(IY+6)             ; If the bottom of the entity at IY...
  CP (IX+4)               ; ...is above the top of the entity at IX...
  JR C,54874              ; ...then advance IY to next entity
  LD A,(IX+7)             ; If the right side of entity IX...
  CP (IY+5)               ; ...is to the left of the left side of the entity at
                          ; IY...
  JR C,54874              ; ...then advance IY to next entity
  LD A,(IY+7)             ; If the right side of entity IY...
  CP (IX+5)               ; ...is to the left of the left side of the entity at
                          ; IX...
  JR C,54874              ; ...then advance IY to next entity
  XOR A                   ; Set A to zero to reset Carry Flag
  LD (34258),IY           ; Store pointer to current entity at 34258
  LD A,(IY+8)             ; Load A with class of entity at IY
  RET                     ; Return
; This entry point is used by the routines at 55196 and 55525.
  LD DE,13                ; Load DE with 13, as entries in complex state data
                          ; are 13 bytes wide
  ADD IY,DE               ; Advance IY pointer to next entity in complex state
                          ; data block
  JR 54777                ; Loop back to 54777

; Check Entity at IX for Collision With Another Entity (Only those Defined
; Before, and in Reverse Order) at Same Depth Level Whose Interaction (11,7)
; Flag is Set
;
; Used by the routine at 52315. Input:  IX  Address of complex state data for
; an entity Output: F  Carry Flag set if no entity found, reset otherwise A
; Class of entity, if found, otherwise 254 IY  Address of complex state data
; for colliding entity
  LD C,0                  ; Set depth offset to 0 (i.e. check entities at same
                          ; depth)
  PUSH IX                 ; Load IY with address in IX...
  POP IY                  ; ...
  LD DE,65523             ; Load DE with -13
  JP 54987                ; Move IY back to previous entity in complex state
                          ; data and jump into collision check routine

; Check Entity at IX for Collision With Another Entity (in Reverse Order) at
; Next Depth Level Into Screen Whose Interaction (11,7) Flag is Set
;
; The address stored at 34246 is the address of complex state data for the
; entity to start with when doing collision checks in reverse order. On levels
; 2, 3 and 4, the value stored here is the address of the complex state data of
; the last entity, which means that on these levels, all entities are checked.
; On Level 1, however, the value stored is the address of the complex state
; data of the sixth-last entity. The remaining five entities after this address
; on Level 1 are the three spiders, their webs and their arches. This means
; that on Level 1, these spiders, webs and arches are excluded from certain
; collision checks. Input:  IX  Address of complex state data for an entity C
; (Entry at 54899 only) Depth offset Output: F  Carry Flag set if no entity
; found, reset otherwise A Class of entity, if found, otherwise 254 IY  Address
; of complex state data for colliding entity
  LD C,1                  ; Set depth offset to 1 (i.e. check entities at next
                          ; depth level into screen)
  LD DE,65523             ; Load DE with -13 (as entries in complex state data
                          ; are 13 bytes wide)
  LD IY,(34246)           ; Load IY with current level's start address for
                          ; reverse-order collision checks
  LD A,(IX+0)             ; If room of entity at IX is not the same as room of
                          ; entity at IY...
  CP (IY+0)               ; ...
  JR NZ,54987             ; ...then move IY back to previous entity
  BIT 5,(IY+10)           ; If current entity at IY has its Is Being Carried
                          ; Flag set...
  JP NZ,54987             ; ...then move IY back to previous entity
  LD A,(IY+8)             ; If current entity at IY has a class which is the
                          ; same as the entity at IX...
  CP (IX+8)               ; ...
  JR Z,54987              ; ...then move IY back to previous entity
  BIT 7,A                 ; If entity at IY has its "Spans Full Depth" Flag is
                          ; set...
  JR NZ,54935             ; ...then skip over depth check to 54935
  LD A,(IY+1)             ; If entity at IY has a depth which is not the same
                          ; as the depth of the entity at IX...
  SUB C                   ; ...minus depth offset...
  CP (IX+1)               ; ...
  JR NZ,54987             ; ...then move IY back to previous entity
  LD A,(IY+11)            ; If entity at IY has its Interaction (11,7) Flag
                          ; reset...
  AND 128                 ; ...
  JP Z,54987              ; ...then move IY back to previous entity
  LD A,(IX+6)             ; If the bottom of the entity at IX...
  CP (IY+4)               ; ...is above the top of the entity at IY...
  JR C,54987              ; ...then move IY back to previous entity
  LD A,(IY+6)             ; If the bottom of the entity at IY...
  CP (IX+4)               ; ...is above the top of the entity at IX...
  JR C,54987              ; ...then move IY back to previous entity
  LD A,(IX+7)             ; If the right side of entity IX...
  CP (IY+5)               ; ...is to the left of the left side of the entity at
                          ; IY...
  JR C,54987              ; ...then move IY back to previous entity
  LD A,(IY+7)             ; If the right side of entity IY...
  CP (IX+5)               ; ...is to the left of the left side of the entity at
                          ; IX...
  JR C,54987              ; ...then move IY back to previous entity
  XOR A                   ; Set A to zero to reset Carry Flag
  LD (34258),IY           ; Store pointer to current entity at 34258
  LD A,(IY+8)             ; Load A with class of entity at IY
  RET                     ; Return
  LD DE,65523             ; Load DE with -13
; This entry point is used by the routine at 54878.
  LD A,(IY-1)             ; If byte before current IY position is 254 (i.e. end
                          ; marker for simple state data)...
  CP 254                  ; ...
  JP Z,55000              ; ...then skip ahead to 55000
  ADD IY,DE               ; Move IY back 13 bytes (i.e. to start of previous
                          ; entry)
  JP 54899                ; Jump to 54899
  SCF                     ; Set Carry Flag
  RET                     ; Return

; Unused routine
;
; This routine seems to be involved with the relative positioning of two
; different entities, assuming that IX contains a complex state data address.
  LD IY,(34258)           ; Load IY with address of complex state data for
                          ; entity involved in last collision check
  LD A,(IY+7)             ; Load A with width of this entity, minus one...
  SUB (IY+5)              ; ...
  SRL A                   ; Divide result by two, clearing remainder...
  DEC A                   ; ...and subtract one
  ADD A,(IY+5)            ; Add x-coordinate of entity's left edge
  CP (IX+5)
  RET                     ; Return

; Cached Control Input
;
; This value is set by the instruction at 55066. It holds a value read from
; control input when handling characters' jumps.
  DEFB 0

; Handle Drutt's Jump, and Load E with Jump State Index As Appropriate
;
; See description of routine at 55041 for details. Output: E  (via routine at
; 55041) Jump state index (see 55041)
  LD IX,(34242)           ; Load IX with address of current level's complex
                          ; state data for Drutt
  BIT 7,(IX+12)           ; If Drutt's Is Jumping Flag is reset...
  RET Z                   ; ...then return
; Drutt's Is Jumping Flag is set
  LD A,(34208)            ; If Drutt Mode Flag is reset (Berk Mode)...
  BIT 0,A                 ; ...
  JR Z,55065              ; ...then handle Drutt's jump, and load E with jump
                          ; state index as appropriate based upon no control
                          ; input
  JR 55060                ; Handle Drutt's jump, and load E with jump state
                          ; index as appropriate based upon current control
                          ; input

; Handle Berk's Jump, and Load E with Jump State Index As Appropriate
;
; This routine updates the position, direction and velocity of a jumping
; character (Berk if entry at 55041 or Drutt if entry via routine at 55023)
; based upon various conditions (control input, collisions with obstructions
; and the character's current position, direction and velocity). Register E is
; loaded (either by this routine, or the CALLed routine at 55196) with a value
; determined by these conditions. The value in E in turn determines how the
; character's jump will progress. A given numeric value may result from more
; than one set of conditions. Possible output values in E are: Input:  IX
; Address of complex state data (current level) for Berk (entry via 55041) or
; Drutt (entry via 55060 and 55065) Output: E  Jump state index (see table
; above)
  CALL 54283              ; Move Berk into new room (left or right) if he is at
                          ; the edge of his current room
  LD IX,(34240)           ; Load IX with address of current level's complex
                          ; state data for Berk
  BIT 7,(IX+12)           ; If Berk's Is Jumping Flag is reset...
  RET Z                   ; ...then return
; Berk's Is Jumping Flag is set
  LD A,(34208)            ; If Drutt Mode Flag is set...
  BIT 0,A                 ; ...
  JR NZ,55065             ; ...then skip ahead to 55065
; From this point onwards, IX points to either Berk's complex state data (entry
; via 55041) or Drutt's complex state data (entry via 55060 or 55065). This
; entry point is used by the routine at 55023.
  LD A,(34219)            ; Load A with control input
  JR 55066                ; Skip ahead to 55066
; This entry point is used by the routine at 55023.
  XOR A                   ; Load A with zero
  LD (55022),A            ; Store value in A at 55022
  BIT 0,(IX+11)           ; If jumper's Walking Right Flag is reset...
  JR Z,55128              ; ...then skip ahead to 55128
; Walking Right Flag is set
  LD B,2                  ; Load B with 2 (as Berk and Drutt jump right by two
                          ; characters)
  PUSH BC                 ; Store BC (B = remaining number of characters to
                          ; move)
  CALL 54569              ; Check jumper for collision with another impassable
                          ; / pushable entity immediately to the right...
  JR C,55108              ; ...and if a collision has not occurred, then skip
                          ; ahead to 55108
  CP 22                   ; If collision was with an entity of class less than
                          ; 22 (can be picked up)...
  JR C,55108              ; ...then skip ahead to 55108
  CP 129                  ; If collision was with entity of class 129 (causes
                          ; other entities to start falling)...
  JR Z,55108              ; ...then skip ahead to 55108
  CP 50                   ; If collision was with entity of class 50 (causes
                          ; Drutt to swap depth levels)...
  JR Z,55108              ; ...then skip ahead to 55108
  CP 159                  ; If collision was not with entity of class 159 (Berk
                          ; floating)...
  JR NZ,55124             ; ...then skip ahead to 55124
; Collision with Berk, floating
  LD (IY+11),241          ; Set Berk's Walking Right, Impassable Leftwards,
                          ; Impassable Rightwards, Interaction (11,6) and
                          ; Interaction (11,7) flags and reset his Walking
                          ; Left, Unused (11,2) and Unused (11,3) flags
  CALL 55187              ; Set Character Swap Pending Flag
  JR 55124                ; Skip ahead to 55124
; No collision, or collision with entity of class 50, 129 or less than 22
  CALL 54313              ; Move jumper into room to the right, if
                          ; appropriate...
  JR NC,55124             ; ...and if jumper can't enter new room then skip
                          ; ahead to 55124
  INC (IX+5)              ; Move jumper right by one character...
  INC (IX+7)              ; ...
  POP BC                  ; Restore BC (B = remaining number of characters to
                          ; move)
  DJNZ 55077              ; Decrease remaining number of characters to move,
                          ; and if not zero, loop back to 55077
  JR 55196                ; Handle vertical component of jumper's jump, load E
                          ; with Jump State Index and return
; Collision with other class of entity
  POP BC                  ; Restore BC (B = remaining number of characters to
                          ; move)
  LD E,4                  ; Load E with 4 (jumper has bounced off an
                          ; obstruction to the right while jumping right)
  RET                     ; Return
; Walking Right Flag is reset
  BIT 1,(IX+11)           ; If jumper's Walking Left Flag is reset...
  JR Z,55196              ; ...then skip ahead to 55196 (handle vertical
                          ; component of jumper's jump, load E with Jump State
                          ; Index and return)
; Walking Left Flag is set
  LD B,2                  ; Load B with 2 (as Berk and Drutt jump left by two
                          ; characters)
  PUSH BC                 ; Store BC (B = remaining number of characters to
                          ; move)
  CALL 54666              ; Check jumper for collision with another impassable
                          ; / pushable entity immediately to the left...
  JR C,55167              ; ...and if a collision has not occurred, then skip
                          ; ahead to 55167
  CP 22                   ; If collision was with an entity of class less than
                          ; 22 (can be picked up)...
  JR C,55167              ; ...then skip ahead to 55167
  CP 129                  ; If collision was with entity of class 129 (causes
                          ; other entities to start falling)...
  JR Z,55167              ; ...then skip ahead to 55167
  CP 50                   ; If collision was with entity of class 50 (causes
                          ; Drutt to swap depth levels)...
  JR Z,55167              ; ...then skip ahead to 55167
  CP 159                  ; If collision was not with entity of class 159 (Berk
                          ; floating)...
  JR NZ,55183             ; ...then skip ahead to 55183
; Collision with Berk, floating
  LD (IY+11),242          ; Set Berk's Walking Left, Impassable Leftwards,
                          ; Impassable Rightwards, Interaction (11,6) and
                          ; Interaction (11,7) flags and reset his Walking
                          ; Right and Unused (11,2) and Unused (11,3) flags
  CALL 55187              ; Set Character Swap Pending Flag
  JR 55183                ; Skip ahead to 55183
; No collision, or collision with entity of class 50, 129 or less than 22
  CALL 54348              ; Move jumper into room to the left, if
                          ; appropriate...
  JR NC,55183             ; ...and if jumper can't enter new room then skip
                          ; ahead to 55183
  DEC (IX+5)              ; Move jumper left by one character...
  DEC (IX+7)              ; ...
  POP BC                  ; Restore BC (B = remaining number of characters to
                          ; move)
  DJNZ 55136              ; Decrease remaining number of characters to move,
                          ; and if not zero, loop back to 55136
  JR 55196                ; Handle vertical component of jumper's jump, load E
                          ; with Jump State Index and return
; Collision with other class of entity
  POP BC                  ; Restore BC (B = remaining number of characters to
                          ; move)
  LD E,5                  ; Load E with 5 (jumper has bounced off an
                          ; obstruction to the left while jumping left)
  RET                     ; Return

; Set Character Swap Pending Flag
;
; Used by the routine at 55041.
  LD A,(34208)            ; Set Character Swap Pending Flag...
  SET 6,A                 ; ...
  LD (34208),A            ; ...
  RET                     ; Return

; Handle Vertical Component of Character's Jump, and Load E with Jump State
; Index As Appropriate
;
; This routine handles the vertical component of Berk's or Drutt's jumping,
; checking for collisions (e.g. Berk or Drutt hitting an obstruction above, or
; Drutt knocking down an entity such as a key). The routine also checks the
; cached control input value at 55022 to determine the outcome of the next
; "bounce" if the jumper is on the floor (for example, start a leftward jump if
; left was pressed). Input:  IX  Address of complex state data (current level)
; for Berk or Drutt Output: E  Jump state index (see table in description of
; routine at 55041)
  LD A,(IX+12)            ; Load A with current velocity of jumper's jump...
  AND 15                  ; ...
  BIT 6,(IX+12)           ; If Downward Jump Phase Flag is set...
  JR NZ,55281             ; ...then skip ahead to 55281
; Downward Jump Phase Flag is reset, i.e. in upward phase of jump
  OR A                    ; If current velocity of jumper's jump is at least
                          ; one...
  JR NZ,55234             ; ...then skip ahead to 55234
; Current velocity of jumper's jump is zero
  LD A,(55022)            ; Load A with Cached Control Input...
  BIT 3,A                 ; ...and if Back Bit is reset...
  JR Z,55223              ; ...then skip ahead to 55223
  DEC (IX+4)              ; Move jumper up one character...
  DEC (IX+6)              ; ...
  SET 6,(IX+12)           ; Set Downward Jump Phase Flag
  CALL 55421              ; Increase current velocity of jumper's jump if less
                          ; than 7
  LD A,1                  ; Prepare to set velocity of jumper's jump to one,
                          ; downwards
  JR 55284                ; Skip ahead to 55284 (handle downward phase of jump)
; Current velocity of jumper's jump is at least 1
  LD B,A                  ; Load B with current velocity of jumper's jump
  DEC (IX+4)              ; Move jumper up one character...
  DEC (IX+6)              ; ...
  CALL 54768              ; Check entity at IX for collision with another
                          ; entity at same depth whose Interaction (11,6) Flag
                          ; is set...
  JR C,55258              ; ...and if no collision occurred, then skip ahead to
                          ; 55258
  CP 130                  ; If collision was not with entity of class 130
                          ; (causes Berk and Drutt to bounce off or bang
                          ; head)...
  JR NZ,55258             ; ...then skip ahead to 55258
; Jumper has banged his head
  LD A,6                  ; Set pending sound index to 6 (banging head) if it
                          ; is currently zero, or lower priority...
  CALL 59613              ; ...
  LD E,6                  ; Load E with 6 (jumper has banged his head on
                          ; something above him)
  RET                     ; Return
; No collision, or collision with entity other than that of class 130
  CP 22                   ; If collision was with an entity of class of 22 or
                          ; greater (can't be picked up, or 255 for no
                          ; collision)...
  JR NC,55270             ; ...then skip ahead to 55270
; Drutt has knocked down an entity, e.g. Red Sweet on Level 1
  LD (IY+12),2            ; Set initial velocity factor of entity jumper
                          ; collided with to 2...
  SET 6,(IY+10)           ; ...and set its "Can Fall" flag
  CALL 55433              ; Change jumper's room up one if appropriate
  DJNZ 55235              ; Decrease B (remaining number of characters to move
                          ; up) and loop back to 55235 if not zero
  DEC (IX+12)             ; Decrease current velocity of jumper's jump, slowing
                          ; ascent
  LD E,0                  ; Load E with zero (jumper jumping upwards, no
                          ; collision)
  RET                     ; Return
; Downward Jump Phase Flag is set, i.e. in downward phase of jump
  CALL 55421              ; Increase current velocity of jumper's jump if less
                          ; than 7, speeding descent, and load into A
  LD B,A                  ; Load B with velocity of jumper's jump
  INC (IX+4)              ; Move jumper down one character...
  INC (IX+6)              ; ...
  CALL 54768              ; Check jumper for collision with another entity at
                          ; same depth whose Interaction (11,6) Flag is set...
  JR C,55300              ; ...and if no collision occurred, then skip ahead to
                          ; 55300
  CP 35                   ; If collision was with an entity of class 35
                          ; (platform, Level 1 or Level 3)...
  JR Z,55363              ; ...then skip ahead to 55363
; No collision, or collision with entity other than that of class 35
  LD A,(IX+6)             ; Load A with y-coordinate of jumper's bottom edge...
  ADD A,(IX+1)            ; ...and add jumper's depth
  CP 122                  ; If A is 122 (i.e. jumper is at bottom of screen)...
  JR Z,55320              ; ...then skip ahead to 55320
  DJNZ 55285              ; Decrease B (remaining number of characters to move
                          ; down) and loop back to 55285 if not zero
  PUSH HL                 ; Store HL
  CALL 55616              ; Change jumper's room down one if appropriate
  POP HL                  ; Restore HL
  LD E,0                  ; Load E with zero (jumper jumping downwards, no
                          ; collision)
  RET                     ; Return
; Jumper is at the bottom of the screen
  CALL 54768              ; Check jumper for collision with another entity at
                          ; same depth whose Interaction (11,6) Flag is set...
  JR C,55363              ; ...and if no collision occurred, then skip ahead to
                          ; 55363
  CP 129                  ; If collision was with entity of class 129 (causes
                          ; other entities to start falling)...
  JR Z,55334              ; ...then skip ahead to 55334
; Collision was not with entity of class 129, so need to resume collision check
; from current position in entities list, i.e. entity that jumper did collide
; with
  CALL 54871              ; Resume checking jumper for collision with another
                          ; entity at same depth whose Interaction (11,6) Flag
                          ; is set
  JR 55323                ; ...and jump back to 55323
; Collision with entity of class 129
  LD A,(IX+8)             ; If jumper is not Berk...
  CP 31                   ; ...(class = 31).....
  JR NZ,55285             ; ...then jump back to 55285 (continue moving
                          ; downwards)
  LD A,(IX+5)             ; If Berk's left edge...
  CP (IY+5)               ; ...is at or to the right of the colliding entity's
                          ; left edge...
  JR NC,55352             ; ...then skip ahead to 55352
; Berk's left edge is to the left of colliding entity's left edge
  LD E,7                  ; Load E with 7 (jumper is Berk, his left edge is to
                          ; the left of colliding, class=129, entity's left
                          ; edge)
  RET                     ; Return
; Berk's left edge is at, or to the right of, colliding entity's left edge
  LD A,(IY+7)             ; If Berk's right edge...
  CP (IX+7)               ; ...is at or to the right of the colliding entity's
                          ; right edge...
  JR NC,55285             ; ...then jump back to 55285 (continue moving
                          ; downwards)
; Berk's right edge is to the left of colliding entity's right edge
  LD E,8                  ; Load E with 8 (jumper is Berk, and he is between
                          ; left and right edges of colliding, class=129,
                          ; entity)
  RET                     ; Return
; Downward phase, and collision with entity of class 35 (platform, Level 1 or
; Level 3) or no collision at bottom of screen
  RES 6,(IX+12)           ; Reset Downward Jump Phase Flag (i.e. prepare to
                          ; jump up again)
  LD A,(55022)            ; Load A with Cached Control Input...
  BIT 3,A                 ; ...and if Back Bit is reset...
  JR Z,55377              ; ...then skip ahead to 55377
  LD E,1                  ; Load E with 1 (jumper landed on floor / platform
                          ; and Back Control Input Bit set)
  RET                     ; Return
; Back Bit is reset
  LD A,(IX+12)            ; If current velocity of jumper's jump is at least
                          ; 4...
  AND 15                  ; ...
  CP 4                    ; ...
  JR NC,55393             ; ...then skip ahead to 55393
  LD (IX+12),0            ; Reset jumper's Is Jumping Flag and set current
                          ; velocity of jump to zero
  LD E,3                  ; Load E with 3 (jumper's jump velocity less than 4,
                          ; and back not pressed, i.e. terminate jumping)
  RET                     ; Return
; Current velocity of jumper's jump is at least 4, and Back Bit is reset
  LD A,(55022)            ; Load A with Cached Control Input...
  BIT 1,A                 ; ...and if Left Bit is reset...
  JR Z,55404              ; ...then skip ahead to 55404
; Left Bit is set
  LD E,4                  ; Load E with 4 (jumper's jump velocity at least 4
                          ; and Left Control Input Bit set)
  JR 55410                ; Decrease current velocity of jumper's jump by two
                          ; and return
; Left Bit is reset
  BIT 0,A                 ; If Right Bit is reset...
  JR Z,55417              ; ...then skip ahead to 55417
; Right Bit is set
  LD E,5                  ; Load E with 5 (jumper's jump velocity at least 4
                          ; and Right Control Input Bit set)
  DEC (IX+12)             ; Decrease current velocity of jumper's jump by
                          ; two...
  DEC (IX+12)             ; ...
  RET                     ; Return
; Right Bit (and Left and Back bits) reset
  LD E,0                  ; Load E with zero (current velocity of jumper's jump
                          ; is at least 4 and Back, Left and Right Control
                          ; Input bits are reset)
  JR 55410                ; Decrease current velocity of jumper's jump by two
                          ; and return

; Increase Current Velocity of Character's Jump if Less Than 7
;
; See pokes Input:  IX  Address of complex state data (current level) for Berk
; or Drutt
  LD A,(IX+12)            ; Load A with current velocity of character's jump...
  AND 15                  ; ...
  CP 7                    ; ...and if this is 7 or more...
  RET NC                  ; ...then return
  INC (IX+12)             ; Increase velocity of character's jump
  RET                     ; Return

; Change Entity's Room Up One if Appropriate
;
; Used by the routines at 36542, 48487 and 55196. Input:  IX  Address of
; complex state data for an entity
  LD A,99                 ; If y-coordinate of top of entity is larger than 99
                          ; (i.e. top of entity is below top of room)...
  CP (IX+4)               ; ...
  RET C                   ; ...then return
  PUSH HL                 ; Store HL
  PUSH BC                 ; Store BC
  PUSH DE                 ; Store DE
  LD IY,(34254)           ; Load start address of current level's Vertical Room
                          ; Connectivity Data into IY
  INC IY                  ; Advance by one byte to second byte (lower room
                          ; index) of first entry
  LD D,(IX+0)             ; Load current room of entity into D
  LD A,(IY+0)             ; Load second byte (lower room index) of current
                          ; entry into A
  CP 255                  ; If byte is 255 (i.e. the End Marker)...
  JR Z,55512              ; ...then skip ahead to 55512
  CP D                    ; If byte is the same as the entity's current room...
  JR Z,55467              ; ...then skip ahead to 55467
  INC IY                  ; Advance by two bytes to the next entry...
  INC IY                  ; ...
  JR 55451                ; Loop back to 55451
  LD B,(IY-1)             ; Load first byte (upper room index) of current entry
                          ; into B
  LD A,(34231)            ; Load position (chars) of left side of current room
                          ; (old, that entity is leaving) into D...
  LD D,A                  ; ...
  CALL 54480              ; Set room of entity to B, store room size data for
                          ; new room and load E with entity's width minus one
  LD A,(34231)            ; Load position (chars) of left side of current room
                          ; (new, that entity has entered) into A
  SUB D                   ; Subtract x-coordinate of old room's left edge from
                          ; x-coordinate of new room's left edge...
  LD D,A                  ; ...and place result in D
  LD A,(IX+5)             ; Load A with x-coordinate of left of entity...
  SUB D                   ; ...subtract difference in positions of rooms' left
                          ; edges...
  LD (IX+5),A             ; ...and store
  ADD A,E                 ; Update x-coordinate of right of entity by adding
                          ; entity's (width - 1) value...
  LD (IX+7),A             ; ...
  LD A,(IX+4)             ; Add 22 to y-coordinate of top of entity...
  ADD A,22                ; ...
  LD (IX+4),A             ; ...
  LD A,(IX+6)             ; Add 22 to y-coordinate of bottom of entity...
  ADD A,22                ; ...
  LD (IX+6),A             ; ...
  CALL 54456              ; Paint red areas outside current character's room if
                          ; IX points to current character's complex state data
  POP DE                  ; Restore DE
  POP BC                  ; Restore BC
  POP HL                  ; Restore HL
  RET                     ; Return

; Set Can Fall Flag and Set Initial Velocity Factor of 2 for Entity Defined at
; Address in IX
;
; Used by the routines at 36638, 39760, 48417, 51779, 52098, 52193 and 52243.
; Input:  IX  Address of complex state data for an entity
  SET 6,(IX+10)           ; Set entity's "Can Fall" flag
  LD (IX+12),2            ; Set entity's initial velocity factor to 2
  RET                     ; Return

; Move All Falling Entities Down by Distances Appropriate to their Current
; Velocity Factors
;
; If an entity's "velocity factor" is equal to its height in characters plus 3
; (a proxy for its mass), then it has reached its terminal velocity.
  LD IX,(34238)           ; Load IX with start address of current level's
                          ; complex state data
  LD DE,13                ; Load DE with 13 (as entries in complex state data
                          ; are 13 bytes wide)
  LD A,(IX+0)             ; If first byte of entry is 255 (i.e. End Marker)...
  CP 255                  ; ...
  RET Z                   ; ...then return
  BIT 6,(IX+10)           ; If current entity's "Can Fall" flag is reset...
  JR Z,55592              ; ...then skip ahead to 55592 (advance to next
                          ; entity)
; Current entity's "Can Fall" Flag is set
  PUSH DE                 ; Store DE
  CALL 53848              ; Store room size data for current entity's current
                          ; room
  POP DE                  ; Restore DE
  LD A,(IX+6)             ; Load C with height (of entity defined by entry) +
                          ; 3...
  SUB (IX+4)              ; ...
  ADD A,4                 ; ...
  LD C,A                  ; ...
  LD A,(IX+12)            ; Load B with velocity factor...
  LD B,A                  ; ...
  CP C                    ; If C is less than or equal to this (i.e. "terminal
                          ; velocity" reached)...
  JR NC,55569             ; ...then skip ahead to 55569
  INC A                   ; Increase velocity factor by one and store for next
                          ; pass (i.e. acceleration)...
  LD (IX+12),A            ; ...
  SRL B                   ; Divide current (i.e. not increased) velocity factor
                          ; by 2
  LD A,(IX+6)             ; If sum of y-coordinate of entity's bottom and
                          ; entity's depth is 122...
  ADD A,(IX+1)            ; ...(i.e. entity is at ground-level)...
  CP 122                  ; ...
  JR Z,55596              ; ...then skip ahead to 55596
  INC (IX+4)              ; Move entity down by one character...
  INC (IX+6)              ; ...
  CALL 55616              ; Change entity's room down one if appropriate
  DJNZ 55571              ; Decrease B (current velocity factor, i.e. remaining
                          ; number of characters to drop entity) and if
                          ; non-zero, loop back to 55571
  ADD IX,DE               ; Advance IX by 13 bytes to next entry
  JR 55532                ; Loop back to 55532
; Entity's position is such that sum of y-coordinate of bottom + depth = 122
; (i.e. at ground-level)
  CALL 54768              ; Check entity at IX for collision with another
                          ; entity at same depth whose Interaction (11,6) Flag
                          ; is set...
  JR C,55610              ; ...and if no collision occurred, then skip ahead to
                          ; 55610
  CP 129                  ; If collision was with entity of class 129 (causes
                          ; other entities to start falling)...
  JR Z,55581              ; ...then jump to 55581 (entity may fall down into
                          ; next room)
; Collision was not with entity of class 129, so need to resume collision check
; from current position in entities list, i.e. entity that character did
; collide with
  CALL 54871              ; Resume checking entity for collision with another
                          ; entity at same depth whose Interaction (11,6) Flag
                          ; is set...
  JR 55599                ; ...
; Entity has landed (i.e. is at ground-level and has not collided with a marker
; of class 129)
  RES 6,(IX+10)           ; Reset entity's "Can Fall" flag as entity has landed
  JR 55592                ; Loop back for next entity

; Change Entity's Room Down One if Appropriate
;
; Used by the routines at 55196 and 55525. Input:  IX  Address of complex state
; data for an entity
  LD A,122                ; If y-coordinate of bottom of entity is smaller than
                          ; 122 (i.e. bottom of entity is above bottom of
                          ; room)...
  CP (IX+6)               ; ...
  RET NC                  ; ...then return
  PUSH BC                 ; Store BC
  PUSH DE                 ; Store DE
  LD IY,(34254)           ; Load start address of current level's Vertical Room
                          ; Connectivity Data into IY
  LD D,(IX+0)             ; Load current room of entity into D
  LD A,(IY+0)             ; Load first byte (upper room index) of current entry
                          ; into A
  CP 255                  ; If byte is 255 (i.e. the End Marker)...
  JR Z,55695              ; ...then skip ahead to 55695
  CP D                    ; If byte is the same as the entity's current room...
  JR Z,55647              ; ...then skip ahead to 55647
  INC IY                  ; Advance by two bytes to the next entry...
  INC IY                  ; ...
  JR 55631                ; Loop back to 55631
  LD B,(IY+1)             ; Load second byte (lower room index) of current
                          ; entry into B
  LD A,(34231)            ; Load position (chars) of left side of current room
                          ; (old, that entity is leaving) into D...
  LD D,A                  ; ...
  CALL 54480              ; Set room of entity to B, store room size data for
                          ; new room and load E with entity's width minus one
  LD A,(34231)            ; Load position (chars) of left side of current room
                          ; (new, that entity has entered) into A
  SUB D                   ; Subtract x-coordinate of old room's left edge from
                          ; x-coordinate of new room's left edge...
  LD D,A                  ; ...and place result in D
  LD A,(IX+5)             ; Load A with x-coordinate of left of entity...
  SUB D                   ; ...subtract difference in positions of rooms' left
                          ; edges...
  LD (IX+5),A             ; ...and store
  ADD A,E                 ; Update x-coordinate of right of entity by adding
                          ; entity's (width - 1) value...
  LD (IX+7),A             ; ...
  LD A,(IX+4)             ; Subtract 20 from y-coordinate of top of entity...
  SUB 20                  ; ...
  LD (IX+4),A             ; ...
  LD A,(IX+6)             ; Subtract 20 from y-coordinate of bottom of
                          ; entity...
  SUB 20                  ; ...
  LD (IX+6),A             ; ...
  CALL 54456              ; Paint red areas outside current character's room if
                          ; IX points to current character's complex state data
  POP DE                  ; Restore DE
  POP BC                  ; Restore BC
  RET                     ; Return
  POP DE                  ; Restore DE
  POP BC                  ; Restore BC
  RET                     ; Return

; Graphic Layout Data Berk Stepping right, right foot out and forward, arm and
; eye animated
  DEFB 251,232,217        ; Process graphic layout data at 55784 and upon
                          ; returning, move cursor to base coordinates
  DEFB 251,213,217        ; Process graphic layout data at 55765 and upon
                          ; returning, move cursor to base coordinates
  DEFB 250,4,254          ; Change cursor's x- and y-coordinates by -2 and +4
                          ; characters respectively
  DEFB 248,122,218        ; Jump to 55930 (Berk's feet, right foot raised and
                          ; forward, facing right)
; Stepping right, right foot out, arm and eye animated
  DEFB 251,232,217        ; Process graphic layout data at 55784 and upon
                          ; returning, move cursor to base coordinates
  DEFB 251,213,217        ; Process graphic layout data at 55765 and upon
                          ; returning, move cursor to base coordinates
  DEFB 250,4,254          ; Change cursor's x- and y-coordinates by -2 and +4
                          ; characters respectively
  DEFB 248,88,218         ; Jump to 55896 (Berk's feet, right foot raised and
                          ; to the side, facing right)
; Facing right, arm and eye animated
