                          ; characters respectively
  DEFB 251,245,218        ; Process graphic layout data at 56053 and upon
                          ; returning, move cursor to base coordinates
  DEFB 248,213,217        ; Jump to 55765 (Berk's hand, animated, right-facing)
; Walking right, animated
  DEFB 251,232,217        ; Process graphic layout data at 55784 and upon
                          ; returning, move cursor to base coordinates
  DEFB 251,191,217        ; Process graphic layout data at 55743 and upon
                          ; returning, move cursor to base coordinates
  DEFB 248,213,217        ; Jump to 55765 (Berk's hand, animated, right-facing)
; Lower half of body, walking right, animated
  DEFB 250,4,254          ; Change cursor's x- and y-coordinates by -2 and +4
                          ; characters respectively
  DEFB 243,0,7            ; Increase current state value n (initially 0), up to
                          ; maximum of 7, resetting to zero if maximum reached
                          ; and jump to n-th address in following list (see
                          ; trivia):
  DEFB 88,218             ; 55896 (Berk's feet, right foot raised and to the
                          ; side, facing right)
  DEFB 122,218            ; 55930 (Berk's feet, right foot raised and forward,
                          ; facing right)
  DEFB 159,218            ; 55967 (lower half of body and feet, facing right,
                          ; right foot forward)
  DEFB 199,218            ; 56007 (lower half of body and feet, facing right,
                          ; left foot behind)
  DEFB 245,218            ; 56053 (lower half of body and feet, facing right,
                          ; standing)
  DEFB 26,219             ; 56090 (lower half of body and feet, facing right,
                          ; left foot forward)
  DEFB 66,219             ; 56130 (lower half of body and feet, facing right,
                          ; left foot forward, right foot behind)
  DEFB 103,219            ; 56167 (lower half of body and feet, facing right,
                          ; left foot forward, right foot out and behind)
; Arm, facing right, animated
  DEFB 243,0,7            ; Increase current state value n (initially 0), up to
                          ; maximum of 7, resetting to zero if maximum reached
                          ; and jump to n-th address in following list (see
                          ; trivia):
  DEFB 17,218             ; 55825 (arm, facing right, up)
  DEFB 17,218             ; 55825 (arm, facing right, up)
  DEFB 17,218             ; 55825 (arm, facing right, up)
  DEFB 17,218             ; 55825 (arm, facing right, up)
  DEFB 51,218             ; 55859 (arm, facing right, down)
  DEFB 51,218             ; 55859 (arm, facing right, down)
  DEFB 51,218             ; 55859 (arm, facing right, down)
  DEFB 51,218             ; 55859 (arm, facing right, down)
; Upper body without arm, facing right, eye animated
  DEFB 244,2              ; Set current graphic set to 2
  DEFB 254,0,2            ; Change cursor's x- and y-coordinates by +2 and 0
                          ; characters respectively and store as new base
                          ; coordinates
  DEFB 236,6,1,1,1,1,2,3  ; Modify following instruction to display graphic of
