  DEFB 19,65,33,20,65,33
  DEFB 21,1,29,89,65,161
  DEFB 22,65,161,23,65,33
  DEFB 24,1,30,25,65,161
  DEFB 26,1,32
  DEFB 255                ; End Marker
; Lower half of body and feet, facing right, right foot out
  DEFB 27,65,33,28,33,33
  DEFB 29,33,33,30,65,29
  DEFB 31,65,33,32,33,33
  DEFB 33,33,33,34,65,30
  DEFB 35,1,33,36,1,33
  DEFB 37,1,32
