; Unused routine
;
; This routine appears to have been set up to load visual data into the Display
; and Attribute files and then to load the game code and data into RAM, from
; address 27000 onwards. This routine was probably used during development.
; Input:  A  New value for system variable DF SZ
  LD (23659),A            ; Set System Variable DF SZ to value in A
  LD DE,6912              ; Set data length to 6912
  LD IX,40000             ; Set base address for load to 40000
  LD A,255                ; Load A with 255 to denote a data block
  SCF                     ; Set Carry Flag as we are LOADing, not VERIFYing
  CALL 1366               ; Call ROM routine to load game data
  LD HL,40000             ; Copy data just loaded to Display File / Attribute
                          ; File...
  LD DE,16384             ; ...
  LD BC,6912              ; ...
  LDIR                    ; ...
  LD DE,32860             ; Set data length to 32860
  LD IX,27000             ; Set base address for load to 27000
  LD A,255                ; Load A with 255 to denote a data block
  SCF                     ; Set Carry Flag as we are LOADing, not VERIFYing
  CALL 1366               ; Call ROM routine to load game data
  JP 34200                ; Jump to code entry point

; Unused
  DEFB 0,0,0,0,0,0,0,0
  DEFB 0,0,0,0,0,0,0

; If Current Character is in Same Room as Target Entity at IX then Set Pending
; Sound to A
;
; If the requested sound has a lower index than the sound already pending then
; the requested sound overrides the pending sound (i.e. lower index has higher
; priority). Input:  A  Index of requested sound IX  Address of complex state
; data for target entity
  PUSH AF                 ; Store AF (A = index of requested sound)
  LD A,(34218)            ; If current character's current room is the same as
                          ; current room of target entity...
  CP (IX+0)               ; ...
  JR Z,59612              ; ...then skip ahead to 59612
  POP AF                  ; Restore AF (A = index of requested sound)
  RET                     ; Return
  POP AF                  ; Restore AF (A = index of requested sound)
; At this point, A will hold the index of a requested sound, and RAM address
; 34273 will contain the index of a pending sound. If the index of the
; requested sound is lower than the index of the pending sound, then the
; pending sound's index at 34273 will be overwritten by the index of the
; requested sound in A. Sounds with lower indices therefore take priority over
; sounds with higher indices. This entry point is used by the routines at
; 46284, 55196 and 59722.
  OR A                    ; If index of requested sound is zero...
  RET Z                   ; ...then return
  PUSH DE                 ; Store DE
  LD E,A                  ; Load E with index of requested sound
  LD A,(34273)            ; Load index of pending sound into A...
  OR A                    ; ...and if this is zero (i.e. no sound pending)...
  JR Z,59628              ; ...then skip ahead to 59628
  CP E                    ; If index of requested sound is less than or equal
                          ; to index of pending sound...
  JR NC,59628             ; ...then skip ahead to 59628
  POP DE                  ; Restore DE
  RET                     ; Return
  LD A,E                  ; Set requested sound to be new pending sound...
  LD (34273),A            ; ...
  POP DE                  ; Restore DE
  RET                     ; Return

; Table of Sound Parameters
;
; +--------+------------------------------------------------------------------+
; | Offset | Meaning                                                          |
; +--------+------------------------------------------------------------------+
; | 0      | Index (unused)                                                   |
; | 1      | Outer repeat counter                                             |
; | 2      | Inner repeat counter                                             |
; | 3      | Delay constant (controls speed, higher value is slower)          |
; | 4      | Delay constant (controls speed / pitch, higher value is slower / |
; |        | lower)                                                           |
; | 5      | Increment for delay constant D                                   |
; | 6      | Increment for delay constant E                                   |
; | 7      | Most significant byte of pseudo-random address plus No Pause     |
; |        | Flag                                                             |
; +--------+------------------------------------------------------------------+
  DEFB 1,4,168,29,167,254,3,1 ; (01) - Out of time
  DEFB 2,3,160,57,6,1,0,128 ; (02) - Main Menu sound (three blips)
  DEFB 3,15,141,214,46,1,253,128 ; (03) - Unused
  DEFB 4,1,40,82,59,253,1,6 ; (04) - Explosion
  DEFB 5,1,84,93,115,4,251,11 ; (05) - Berk landing
  DEFB 6,1,190,58,25,0,250,128 ; (06) - Berk/Drutt banging head on ceiling
  DEFB 7,1,30,180,12,0,252,128 ; (07) - Spider sound
  DEFB 8,1,134,55,58,251,4,128 ; (08) - Drutt eating a worm
  DEFB 9,1,10,60,187,253,247,128 ; (09) - Drutt hopping
  DEFB 10,1,68,160,79,254,254,128 ; (10) - Unused
  DEFB 11,1,122,123,102,205,0,128 ; (11) - Unused

; Set Sound of Index A as Pending if Appropriate, then Play and Clear Pending
; Sound
;
; The sound with index A will become the pending sound if the currently pending
; sound index is either zero, or of higher index than A (i.e. lower priority).
; Input:  A  Sound index L  Undefined, pseudo-random value
  CALL 59613              ; Set pending sound index to A if it is currently
                          ; zero, or lower priority
; This entry point is used by the routine at 34438.
  LD A,(34273)            ; Load index of pending sound into A...
  OR A                    ; ...and if this is zero...
  RET Z                   ; ...then return
  DEC A                   ; Decrease A to give zero-based sound index
  PUSH IX                 ; Store IX
  LD IX,59635             ; Point IX at second byte of first entry in Sound
                          ; Parameters Table
  ADD A,A                 ; Multiply sound index by eight...
  ADD A,A                 ; ...as sound data entries in table at 59634 are
                          ; eight bytes wide...
  ADD A,A                 ; ...
  LD C,A                  ; ...and load into BC...
  LD B,0                  ; ...
  ADD IX,BC               ; Add BC to IX as offset to point to sound data for
                          ; pending sound
  LD A,B                  ; Set index of pending sound to zero...
  LD (34273),A            ; ...
  LD C,(IX+0)             ; Load outer repeat count into C
  LD B,(IX+1)             ; Load inner repeat count into B
  LD E,(IX+2)             ; Load delay constant E into E
  LD D,(IX+3)             ; Load delay constant D into D
  LD H,(IX+6)             ; Load most significant byte of pseudo-random address
                          ; into H
  PUSH BC                 ; Store BC (B = inner repeat count, C = outer repeat
                          ; count)
  LD A,(34217)            ; Load current border colour into A
  SET 4,A                 ; Set Speaker Bit
  OUT (254),A             ; Write Speaker Bit and border colour to Port 254
  LD B,D                  ; Apply delay based upon delay constant D...
  NOP                     ; ...
  DJNZ 59773              ; ...
  BIT 7,H                 ; If No Pause Flag is set...
  JR NZ,59794             ; ...then skip ahead to 59794
  LD B,(HL)               ; Load B with value from pseudo-random address
  INC HL                  ; Advance HL
  BIT 0,(IX+0)            ; Do nothing (pause) for period B...
  NOP                     ; ...
  NOP                     ; ...
  NOP                     ; ...
  NOP                     ; ...
  NOP                     ; ...
  NOP                     ; ...
  DJNZ 59782              ; ...
  RES 4,A                 ; Reset Speaker Bit
  OUT (254),A             ; Write Speaker Bit and border colour to Port 254
  LD B,E                  ; Do nothing for E cycles...
  NOP                     ; ...
  DJNZ 59799              ; ...
  LD A,(IX+4)             ; Adjust value of delay constant D...
  ADD A,D                 ; ...
  LD D,A                  ; ...
  LD A,(IX+5)             ; Adjust value of delay constant E...
  ADD A,E                 ; ...
  LD E,A                  ; ...
  POP BC                  ; Restore BC (B = inner repeat count, C = outer
                          ; repeat count)
  DJNZ 59764              ; Loop back to 59764
  DEC C                   ; Decrease outer repeat count
  JR NZ,59752             ; If non-zero (i.e. more repeats to process) then
                          ; loop back to 59752
  POP IX                  ; Restore IX
  RET                     ; Return

; Table of Initial-State Data for Complex Entities
;
; This table is used to store the initial states of the various entities in the
; game, so that they can be reset when a new game is started.
  DEFB 49,50,51,52,53,54,55,56,57,48

; Do nothing
;
; Used by the routine at 34428
  RET                     ; Return

; Unused
  DEFS 1480

