; Load loading screen and main game code The following instructions set the
; system variable DF SZ to zero. This prevents a press of the break key
; returning us to basic while the game is loading.
  XOR A                   ; Set system variable DF SZ to zero
  LD (23659),A
  LD DE,6912              ; Load loading screen to 40000 and copy into Display
                          ; File
  LD IX,40000
  LD A,255
  SCF
  CALL 1366
  LD HL,40000
  LD DE,16384
  LD BC,6912
  LDIR
  LD DE,32860             ; Load 32860 bytes to 27000
  LD IX,27000
  LD A,255
  SCF
  CALL 1366
  JP 34200                ; Jump to start-up code

